// 2. GATE NAME CACHE - Cache normalized gate names to avoid recalculation
const gateNameCache = new Map();
function getCachedNormalizedGateName(gateName) {
    if (!gateName) return '';
    if (gateNameCache.has(gateName)) {
        return gateNameCache.get(gateName);
    }
    const normalized = normalizeGateName(gateName);
    gateNameCache.set(gateName, normalized);
    return normalized;
}

// 3. SCHEDULE INDEX - Pre-built lookup map for O(1) gate search
// Structure: scheduleIndex[airportName][normalizedGateName][day] = [schedule items]
let scheduleIndex = {};
let scheduleIndexDirty = true; // Flag to rebuild index when schedules change

// 3b. ROUTE BOARDING FLIGHTS INDEX - one rebuild scans all schedules; getScheduledFlightsForRoute is O(1)
let routeFlightsByPairKey = new Map();
let routeFlightsLookupDirty = true;

function markRouteFlightsLookupDirty() {
    routeFlightsLookupDirty = true;
    document.querySelectorAll('[id^="route-schedule-host-"]').forEach(el => {
        const m = el.id.match(/^route-schedule-host-(\d+)$/);
        const routeIndex = m ? parseInt(m[1], 10) : NaN;
        if (Number.isNaN(routeIndex)) return;
        const details = document.getElementById(`route-details-${routeIndex}`);
        const wasLoaded = el.getAttribute('data-loaded') === '1';
        el.removeAttribute('data-loaded');
        if (wasLoaded && details && details.style.display !== 'none') {
            el.innerHTML = '';
            ensureRouteScheduleGridIfNeeded(routeIndex);
        }
    });
}

function rebuildRouteFlightsLookup() {
    const map = new Map();
    Object.keys(aircraftSchedules).forEach(aircraftRegistration => {
        const schedule = aircraftSchedules[aircraftRegistration];
        if (!Array.isArray(schedule)) return;

        schedule.forEach(item => {
            if (item.type !== 'flight' || !item.route || item.phase !== 'boarding') return;
            const isPositioningFlight = item.flightNumber && item.flightNumber.endsWith('P');
            if (isPositioningFlight) return;

            const routeParts = item.route.split(' → ');
            if (routeParts.length !== 2) return;

            const itemDeparture = routeParts[0].trim();
            const itemArrival = routeParts[1].trim();
            const itemDepartureCode = getAirportCodeWithContext(itemDeparture, itemDeparture);
            const itemArrivalCode = getAirportCodeWithContext(itemArrival, itemArrival);
            const pairKey = `${itemDepartureCode}|${itemArrivalCode}`;
            const flightKey = `${aircraftRegistration}-${item.day}-${item.startTime}-${item.route}`;

            let bucket = map.get(pairKey);
            if (!bucket) {
                bucket = { flights: [], seen: new Set() };
                map.set(pairKey, bucket);
            }
            if (!bucket.seen.has(flightKey)) {
                bucket.seen.add(flightKey);
                const localDeparture = convertUTCDayTimeToLocal(item.day, item.startTime, itemDeparture);
                bucket.flights.push({
                    day: item.day,
                    localDepartureDay: localDeparture.day,
                    localDepartureTime: localDeparture.time,
                    startTime: item.startTime,
                    endTime: item.endTime,
                    aircraft: aircraftRegistration,
                    phase: item.phase,
                    route: item.route
                });
            }
        });
    });

    routeFlightsByPairKey = new Map();
    map.forEach((bucket, key) => {
        routeFlightsByPairKey.set(key, bucket.flights);
    });
    routeFlightsLookupDirty = false;
}

function ensureRouteFlightsLookup() {
    if (routeFlightsLookupDirty) {
        rebuildRouteFlightsLookup();
    }
}

let saveRoutesIdleHandle = null;
function scheduleSaveRoutes() {
    if (saveRoutesIdleHandle != null) {
        if (window.cancelIdleCallback) {
            cancelIdleCallback(saveRoutesIdleHandle);
        } else {
            clearTimeout(saveRoutesIdleHandle);
        }
        saveRoutesIdleHandle = null;
    }
    const run = () => {
        saveRoutesIdleHandle = null;
        saveRoutes();
    };
    if (window.requestIdleCallback) {
        saveRoutesIdleHandle = requestIdleCallback(run, { timeout: 1500 });
    } else {
        saveRoutesIdleHandle = setTimeout(run, 0);
    }
}

function applyRouteCompletionToDom(routeIndex) {
    const route = routesList[routeIndex];
    if (!route) return;
    const item = document.querySelector(`.route-item[data-route-index="${routeIndex}"]`);
    if (!item) return;
    item.classList.toggle('route-completed', !!route.completed);
    const circle = item.querySelector('.route-weekly-status .status-circle');
    if (circle) {
        circle.classList.toggle('completed', !!route.completed);
    }
    const completeBtn = item.querySelector('.route-actions .complete-btn, .route-actions .incomplete-btn');
    if (completeBtn) {
        completeBtn.textContent = route.completed ? 'Mark Incomplete' : 'Mark Complete';
        completeBtn.classList.toggle('complete-btn', !!route.completed);
        completeBtn.classList.toggle('incomplete-btn', !route.completed);
    }
}

function rebuildScheduleIndex() {
    if (!scheduleIndexDirty) return;
    
    scheduleIndex = {};
    
    Object.keys(aircraftSchedules).forEach(aircraftReg => {
        const schedule = aircraftSchedules[aircraftReg];
        if (!Array.isArray(schedule)) return;
        
        schedule.forEach((item, index) => {
            if (!item.airport || !item.gate) return;
            
            const airportName = item.airport;
            const normalizedGate = getCachedNormalizedGateName(item.gate);
            const day = item.day;
            
            if (!scheduleIndex[airportName]) {
                scheduleIndex[airportName] = {};
            }
            if (!scheduleIndex[airportName][normalizedGate]) {
                scheduleIndex[airportName][normalizedGate] = {};
            }
            if (!scheduleIndex[airportName][normalizedGate][day]) {
                scheduleIndex[airportName][normalizedGate][day] = [];
            }
            
            scheduleIndex[airportName][normalizedGate][day].push({
                aircraft: aircraftReg,
                index: index,
                item: item
            });
        });
    });
    
    scheduleIndexDirty = false;
    logger('📊 Schedule index rebuilt');
}

// 4. BATCH MARKER OPERATIONS - Batch add/remove markers
let markerBatchQueue = {
    toAdd: [],
    toRemove: []
};

function flushMarkerBatch() {
    if (markerBatchQueue.toAdd.length > 0) {
        markerBatchQueue.toAdd.forEach(marker => {
            if (markerClusterGroup) {
                markerClusterGroup.addLayer(marker);
            } else {
                marker.addTo(map);
            }
        });
        markerBatchQueue.toAdd = [];
    }
    
    if (markerBatchQueue.toRemove.length > 0) {
        markerBatchQueue.toRemove.forEach(marker => {
            if (markerClusterGroup) {
                markerClusterGroup.removeLayer(marker);
            } else {
                map.removeLayer(marker);
            }
        });
        markerBatchQueue.toRemove = [];
    }
}

// 5. DEBOUNCING - Prevent rapid clicking
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

// THROTTLING - Limit function execution frequency
function throttle(func, limit) {
    let inThrottle;
    return function executedFunction(...args) {
        if (!inThrottle) {
            func.apply(this, args);
            inThrottle = true;
            setTimeout(() => inThrottle = false, limit);
        }
    };
}

// CHUNKED PROCESSING - Process large arrays in chunks to prevent blocking
// OPTIMIZATION: Use setTimeout instead of requestAnimationFrame to reduce violations
// Use requestAnimationFrame only for visual updates, setTimeout for data processing
function processInChunks(array, processor, chunkSize = 100, onComplete = null, useRAF = false) {
    if (array.length === 0) {
        if (onComplete) onComplete();
        return;
    }
    
    let index = 0;
    
    function processChunk() {
        const startTime = performance.now();
        const end = Math.min(index + chunkSize, array.length);
        
        // Process chunk with time limit to prevent blocking
        for (let i = index; i < end; i++) {
            processor(array[i], i);
            
            // Yield every 50 items to prevent blocking
            if ((i - index) % 50 === 0 && i > index) {
                const elapsed = performance.now() - startTime;
                if (elapsed > 16) { // If we've taken more than one frame, yield
                    index = i + 1;
                    if (useRAF) {
                        requestAnimationFrame(processChunk);
                    } else {
                        setTimeout(processChunk, 0);
                    }
                    return;
                }
            }
        }
        
        index = end;
        
        if (index < array.length) {
            // Use setTimeout for non-visual operations to reduce RAF violations
            if (useRAF) {
                requestAnimationFrame(processChunk);
            } else {
                setTimeout(processChunk, 0);
            }
        } else if (onComplete) {
            onComplete();
        }
    }
    
    processChunk();
}

