function getDayOfYearUTC(date) {
    const start = Date.UTC(date.getUTCFullYear(), 0, 0);
    const now = Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate());
    return Math.floor((now - start) / 86400000);
}

function normalizeLongitude(lon) {
    let normalized = lon;
    while (normalized > 180) normalized -= 360;
    while (normalized < -180) normalized += 360;
    return normalized;
}

function getSolarDeclinationAndEquationOfTime(date) {
    const dayOfYear = getDayOfYearUTC(date);
    const utcHour = date.getUTCHours() + (date.getUTCMinutes() / 60) + (date.getUTCSeconds() / 3600);
    const gamma = (2 * Math.PI / 365) * (dayOfYear - 1 + ((utcHour - 12) / 24));

    const declination =
        0.006918
        - 0.399912 * Math.cos(gamma)
        + 0.070257 * Math.sin(gamma)
        - 0.006758 * Math.cos(2 * gamma)
        + 0.000907 * Math.sin(2 * gamma)
        - 0.002697 * Math.cos(3 * gamma)
        + 0.00148 * Math.sin(3 * gamma);

    const equationOfTimeMinutes = 229.18 * (
        0.000075
        + 0.001868 * Math.cos(gamma)
        - 0.032077 * Math.sin(gamma)
        - 0.014615 * Math.cos(2 * gamma)
        - 0.040849 * Math.sin(2 * gamma)
    );

    return { declination, equationOfTimeMinutes };
}

function generateTerminatorLatLngs(date) {
    const { declination, equationOfTimeMinutes } = getSolarDeclinationAndEquationOfTime(date);
    const utcMinutes = (date.getUTCHours() * 60) + date.getUTCMinutes() + (date.getUTCSeconds() / 60);
    const subsolarLongitude = normalizeLongitude((720 - utcMinutes - equationOfTimeMinutes) / 4);

    const latLngs = [];
    const tanDeclination = Math.tan(declination);
    const safeTanDeclination = Math.abs(tanDeclination) < 1e-6 ? (tanDeclination >= 0 ? 1e-6 : -1e-6) : tanDeclination;

    for (let lon = -180; lon <= 180; lon += 1) {
        const hourAngleRad = (Math.PI / 180) * normalizeLongitude(lon - subsolarLongitude);
        let latRad = Math.atan(-Math.cos(hourAngleRad) / safeTanDeclination);

        if (!Number.isFinite(latRad)) {
            latRad = 0;
        }

        let lat = latRad * (180 / Math.PI);
        lat = Math.max(-89.5, Math.min(89.5, lat));
        latLngs.push([lat, lon]);
    }

    return { latLngs, declination };
}

function generateNightPolygonLatLngs(terminatorLatLngs, declination) {
    const nightOverNorthPole = declination < 0;
    const polarLatitude = nightOverNorthPole ? 90 : -90;

    const polygon = [[polarLatitude, -180], [polarLatitude, 180]];
    for (let i = terminatorLatLngs.length - 1; i >= 0; i--) {
        polygon.push(terminatorLatLngs[i]);
    }
    polygon.push([polarLatitude, -180]);

    return polygon;
}

function shiftCurveTowardPole(latLngs, shiftDegrees, towardNorthPole) {
    const direction = towardNorthPole ? 1 : -1;
    return latLngs.map(([lat, lon]) => {
        const shiftedLat = Math.max(-89.8, Math.min(89.8, lat + (direction * shiftDegrees)));
        return [shiftedLat, lon];
    });
}

function buildBandPolygon(innerCurve, outerCurve) {
    const polygon = [];
    for (let i = 0; i < innerCurve.length; i++) {
        polygon.push(innerCurve[i]);
    }
    for (let i = outerCurve.length - 1; i >= 0; i--) {
        polygon.push(outerCurve[i]);
    }
    return polygon;
}

function ensureTwilightBandLayers(terminatorLatLngs, declination) {
    const nightOverNorthPole = declination < 0;

    const nightBandSteps = [2, 5, 9, 14];
    const nightBandOpacities = [0.08, 0.06, 0.045, 0.03];
    const dayBandSteps = [2, 5, 9];
    const dayBandOpacities = [0.04, 0.025, 0.015];

    while (dayNightTwilightNightBands.length < nightBandSteps.length) {
        const layer = L.polygon([], {
            pane: 'dayNightPane',
            stroke: false,
            fillColor: '#0b2d48',
            fillOpacity: 0.05
        }).addTo(map);
        dayNightTwilightNightBands.push(layer);
    }
    while (dayNightTwilightDayBands.length < dayBandSteps.length) {
        const layer = L.polygon([], {
            pane: 'dayNightPane',
            stroke: false,
            fillColor: '#f6ca7a',
            fillOpacity: 0.02
        }).addTo(map);
        dayNightTwilightDayBands.push(layer);
    }

    let previousNightCurve = terminatorLatLngs;
    for (let i = 0; i < nightBandSteps.length; i++) {
        const nextNightCurve = shiftCurveTowardPole(terminatorLatLngs, nightBandSteps[i], nightOverNorthPole);
        const bandPolygon = buildBandPolygon(previousNightCurve, nextNightCurve);
        dayNightTwilightNightBands[i].setStyle({ fillOpacity: nightBandOpacities[i] });
        dayNightTwilightNightBands[i].setLatLngs(bandPolygon);
        previousNightCurve = nextNightCurve;
    }

    let previousDayCurve = terminatorLatLngs;
    for (let i = 0; i < dayBandSteps.length; i++) {
        const nextDayCurve = shiftCurveTowardPole(terminatorLatLngs, dayBandSteps[i], !nightOverNorthPole);
        const bandPolygon = buildBandPolygon(previousDayCurve, nextDayCurve);
        dayNightTwilightDayBands[i].setStyle({ fillOpacity: dayBandOpacities[i] });
        dayNightTwilightDayBands[i].setLatLngs(bandPolygon);
        previousDayCurve = nextDayCurve;
    }
}

function updateDayNightOverlay() {
    if (!dayNightOverlayVisible) return;

    ensureDayNightPane();
    const now = new Date();
    const { latLngs: terminatorLatLngs, declination } = generateTerminatorLatLngs(now);
    const nightPolygonLatLngs = generateNightPolygonLatLngs(terminatorLatLngs, declination);

    if (!dayNightNightPolygon) {
        dayNightNightPolygon = L.polygon(nightPolygonLatLngs, {
            pane: 'dayNightPane',
            stroke: false,
            fillColor: '#00111f',
            fillOpacity: 0.28
        }).addTo(map);
    } else {
        dayNightNightPolygon.setLatLngs(nightPolygonLatLngs);
    }

    if (!dayNightTerminatorLine) {
        dayNightTerminatorLine = L.polyline(terminatorLatLngs, {
            pane: 'dayNightPane',
            color: '#f7d67a',
            weight: 2,
            opacity: 0.9,
            dashArray: '6, 6'
        }).addTo(map);
    } else {
        dayNightTerminatorLine.setLatLngs(terminatorLatLngs);
    }

    ensureTwilightBandLayers(terminatorLatLngs, declination);
}

function startDayNightOverlayUpdates() {
    updateDayNightOverlay();
    if (dayNightUpdateInterval) {
        clearInterval(dayNightUpdateInterval);
    }
    dayNightUpdateInterval = setInterval(updateDayNightOverlay, DAY_NIGHT_UPDATE_MS);
}

function stopDayNightOverlayUpdates() {
    if (dayNightUpdateInterval) {
        clearInterval(dayNightUpdateInterval);
        dayNightUpdateInterval = null;
    }
}

function updateDayNightToggleButtonText() {
    const toggleButton = document.getElementById('toggleDayNight');
    if (toggleButton) {
        toggleButton.textContent = dayNightOverlayVisible ? 'Hide Day/Night' : 'Show Day/Night';
    }
}

function toggleDayNightVisibility() {
    dayNightOverlayVisible = !dayNightOverlayVisible;

    if (dayNightOverlayVisible) {
        startDayNightOverlayUpdates();
    } else {
        stopDayNightOverlayUpdates();
        dayNightTwilightNightBands.forEach(layer => {
            if (layer && map.hasLayer(layer)) {
                map.removeLayer(layer);
            }
        });
        dayNightTwilightDayBands.forEach(layer => {
            if (layer && map.hasLayer(layer)) {
                map.removeLayer(layer);
            }
        });
        dayNightTwilightNightBands = [];
        dayNightTwilightDayBands = [];
        if (dayNightNightPolygon && map.hasLayer(dayNightNightPolygon)) {
            map.removeLayer(dayNightNightPolygon);
        }
        if (dayNightTerminatorLine && map.hasLayer(dayNightTerminatorLine)) {
            map.removeLayer(dayNightTerminatorLine);
        }
        dayNightNightPolygon = null;
        dayNightTerminatorLine = null;
    }

    updateDayNightToggleButtonText();
}

