// Function to get city name from airport name by looking up in saved airports
function extractCityName(airportName) {
    if (!airportName) return 'Unknown';
    
    console.log(`extractCityName called with: "${airportName}"`);
    
    // Get saved airports from localStorage
    const savedAirports = localStorage.getItem('savedAirports');
    if (savedAirports) {
        try {
            const airports = JSON.parse(savedAirports);
            console.log(`Found ${airports.length} saved airports`);
            
            // Find airport by name
            const airport = airports.find(ap => ap.name === airportName);
            if (airport) {
                console.log(`Found airport: ${airport.name}, city: ${airport.city}`);
                if (airport.city) {
                    return airport.city;
                }
            } else {
                console.log(`Airport "${airportName}" not found in saved airports`);
                // Try partial matching
                const partialMatch = airports.find(ap => 
                    ap.name.toLowerCase().includes(airportName.toLowerCase()) || 
                    airportName.toLowerCase().includes(ap.name.toLowerCase())
                );
                if (partialMatch) {
                    console.log(`Found partial match: ${partialMatch.name}, city: ${partialMatch.city}`);
                    if (partialMatch.city) {
                        return partialMatch.city;
                    }
                }
            }
        } catch (error) {
            console.error('Error parsing saved airports:', error);
        }
    } else {
        console.log('No saved airports found in localStorage');
    }
    
    // Fallback: try to extract city name from airport name using patterns
    const patterns = [
        // "City International Airport" -> "City"
        /^(.+?)\s+(International|Regional|National|Municipal)\s+Airport$/i,
        // "City Airport" -> "City"
        /^(.+?)\s+Airport$/i,
        // "City" -> "City" (already just city name)
        /^(.+)$/
    ];
    
    for (const pattern of patterns) {
        const match = airportName.match(pattern);
        if (match) {
            return match[1].trim();
        }
    }
    
    return airportName; // Fallback to original name
}

// Function to get all scheduled flights from the system
function getAllScheduledFlights() {
    const flights = [];

    function dayTimeToWeekMinutes(day, timeString) {
        if (day === null || day === undefined || !timeString) return null;
        const [hour, minute] = String(timeString).split(':').map(Number);
        if (Number.isNaN(hour) || Number.isNaN(minute)) return null;
        return (day * 1440) + (hour * 60) + minute;
    }

    function getForwardMinutesDiff(startDay, startTime, endDay, endTime) {
        const start = dayTimeToWeekMinutes(startDay, startTime);
        const end = dayTimeToWeekMinutes(endDay, endTime);
        if (start === null || end === null) return null;
        const weekMinutes = 7 * 1440;
        const normalizedEnd = end < start ? end + weekMinutes : end;
        return Math.max(0, normalizedEnd - start);
    }
    
    // Get flights from all registered aircraft schedules
    console.log('Checking aircraftSchedules:', Object.keys(aircraftSchedules).length, 'aircraft');
    console.log('aircraftSchedules content:', aircraftSchedules);
    Object.keys(aircraftSchedules).forEach(aircraftRegistration => {
        const schedule = aircraftSchedules[aircraftRegistration];
        console.log(`Processing schedule for ${aircraftRegistration}:`, schedule.length, 'items');
        
            schedule.forEach(scheduleItem => {
            console.log(`Processing schedule item:`, scheduleItem);
            // Note: Cancelled flights are included here so they show on airport boards
            // They are filtered out separately for map display and flight search
            if (scheduleItem.type === 'flight' && scheduleItem.route && scheduleItem.phase === 'flight') {
                console.log(`Found flight phase item:`, scheduleItem);
                console.log(`NEW CODE IS RUNNING - Route matching fix applied`);
                // Try multiple ways to match the route
                let route = routesList.find(r => r.id === scheduleItem.route || r.name === scheduleItem.route);
                
                // If not found, try matching by departure and arrival airports (unidirectional only)
                if (!route) {
                    const routeParts = scheduleItem.route.split(' → ');
                    if (routeParts.length === 2) {
                        const departureAirport = routeParts[0].trim();
                        const arrivalAirport = routeParts[1].trim();
                        // Use airport codes for accurate route matching
                        const departureCode = getAirportCodeWithContext(departureAirport, departureAirport);
                        const arrivalCode = getAirportCodeWithContext(arrivalAirport, arrivalAirport);
                        
                        route = routesList.find(r => 
                            getRouteAirportCode(r, 'departure') === departureCode &&
                            getRouteAirportCode(r, 'arrival') === arrivalCode
                        );
                    }
                }
                
                console.log(`Route found:`, route);
                console.log(`Looking for route: "${scheduleItem.route}"`);
                console.log(`Available routes:`, routesList.map(r => ({ name: r.name, departure: r.departure, arrival: r.arrival })));
                if (route) {
                    // Calculate flight times based on schedule
                    if (!scheduleItem.startTime || !scheduleItem.endTime) {
                        console.warn(`Missing time data for ${aircraftRegistration}:`, scheduleItem);
                        return;
                    }
                    
                    const [startHour, startMinute] = scheduleItem.startTime.split(':').map(Number);
                    const [endHour, endMinute] = scheduleItem.endTime.split(':').map(Number);
                    
                    // Calculate the date for this specific day of the week
                    const today = new Date();
                    const currentDay = today.getUTCDay(); // 0 = Sunday, 1 = Monday, etc. (UTC)
                    // Convert Sunday-based day to Monday-based day (0 = Monday, 6 = Sunday) - same as animated aircraft
                    const scheduleDay = currentDay === 0 ? 6 : currentDay - 1;
                    const targetDay = scheduleItem.day; // 0 = Monday, 1 = Tuesday, etc. (Monday-based)
                    
                    console.log(`Flight ${scheduleItem.flightNumber}: Current day is ${currentDay} (${['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][currentDay]}), Schedule day is ${scheduleDay} (Monday-based), Flight is on day ${targetDay} (Monday-based)`);
                    
                    // Calculate days until target day using Monday-based system
                    let daysUntilTarget = targetDay - scheduleDay;
                    if (daysUntilTarget < 0) {
                        daysUntilTarget += 7; // Next week
                    }
                    
                    console.log(`Days until target day: ${daysUntilTarget}`);
                    
                    const startTime = new Date(today);
                    startTime.setUTCDate(today.getUTCDate() + daysUntilTarget);
                    startTime.setUTCHours(startHour, startMinute, 0, 0);
                    
                    const endTime = new Date(today);
                    endTime.setUTCDate(today.getUTCDate() + daysUntilTarget);
                    endTime.setUTCHours(endHour, endMinute, 0, 0);
                    
                    // Handle overnight flights - if end time is earlier than start time, it's the next day
                    if (endHour < startHour || (endHour === startHour && endMinute < startMinute)) {
                        endTime.setUTCDate(endTime.getUTCDate() + 1);
                        console.log(`Overnight flight detected: ${scheduleItem.flightNumber} ends on next day`);
                    }
                    
                    console.log(`Calculated flight times for ${aircraftRegistration}: Start: ${startTime.toLocaleString()}, End: ${endTime.toLocaleString()}`);
                    
                    // Extract gate information from the schedule
                    const schedule = aircraftSchedules[aircraftRegistration];
                    let departureGate = 'TBD';
                    let arrivalGate = 'TBD';
                    
                    // Find boarding and disembarking phases for gate information
                    const boardingPhase = schedule.find(item =>
                        item.phase === 'boarding' &&
                        item.route === scheduleItem.route &&
                        item.flightNumber === scheduleItem.flightNumber
                    );
                    const disembarkingPhase = schedule.find(item =>
                        item.phase === 'disembarking' &&
                        item.route === scheduleItem.route &&
                        item.flightNumber === scheduleItem.flightNumber
                    );
                    
                    if (boardingPhase && boardingPhase.gate) {
                        departureGate = boardingPhase.gate.replace(/\([^)]*\)/g, '').trim();
                    }
                    if (disembarkingPhase && disembarkingPhase.gate) {
                        arrivalGate = disembarkingPhase.gate.replace(/\([^)]*\)/g, '').trim();
                    }
                    
                        // Extract city names from airport names
                        const departureCity = extractCityName(route.departure || route.departureAirport);
                        const arrivalCity = extractCityName(route.arrival || route.arrivalAirport);
                        
                        // Get airline name for this aircraft
                        const airlineName = getAirlineFromAircraft(aircraftRegistration);
                        
                        const boardingMinutesFromSchedule = boardingPhase
                            ? getForwardMinutesDiff(
                                boardingPhase.day,
                                boardingPhase.startTime,
                                scheduleItem.day,
                                scheduleItem.startTime
                            )
                            : null;
                        const disembarkingMinutesFromSchedule = disembarkingPhase
                            ? getForwardMinutesDiff(
                                scheduleItem.day,
                                scheduleItem.endTime,
                                disembarkingPhase.day,
                                disembarkingPhase.endTime
                            )
                            : null;

                        const effectiveBoardingMinutes = boardingMinutesFromSchedule !== null
                            ? boardingMinutesFromSchedule
                            : (scheduleItem.boardingTime || 30);
                        const effectiveDisembarkingMinutes = disembarkingMinutesFromSchedule !== null
                            ? disembarkingMinutesFromSchedule
                            : (scheduleItem.disembarkingTime || 15);

                        flights.push({
                            id: `${aircraftRegistration}-${scheduleItem.day}-${scheduleItem.startTime}`,
                            flightNumber: scheduleItem.flightNumber || `${aircraftRegistration}`,
                        cancelled: scheduleItem.cancelled || false,
                            departureAirport: route.departure || route.departureAirport,
                            arrivalAirport: route.arrival || route.arrivalAirport,
                            departureCity: departureCity,
                            arrivalCity: arrivalCity,
                            startTime: startTime.toISOString(),
                            endTime: endTime.toISOString(),
                            departureGate: departureGate,
                            arrivalGate: arrivalGate,
                            boardingTime: effectiveBoardingMinutes,
                            disembarkingTime: effectiveDisembarkingMinutes,
                            disembarkEndTime: new Date(endTime.getTime() + (effectiveDisembarkingMinutes * 60000)).toISOString(),
                            aircraft: aircraftRegistration,
                            airline: airlineName,
                            day: scheduleItem.day
                        });
                }
            }
        });
    });
    
    // Also get flights from currently animated aircraft (active flights)
    console.log(`Checking ${animatedAircraft.size} animated aircraft for airport board`);
    animatedAircraft.forEach((aircraft, aircraftId) => {
        console.log(`Processing animated aircraft ${aircraftId}:`, aircraft);
        const flightItem = aircraft.flightItem;
        const routeData = aircraft.routeData;
        
        if (flightItem && routeData) {
            if (!flightItem.startTime || !flightItem.endTime) {
                console.warn(`Missing time data for animated aircraft ${aircraftId}:`, flightItem);
                return;
            }
            
            const [startHour, startMinute] = flightItem.startTime.split(':').map(Number);
            const [endHour, endMinute] = flightItem.endTime.split(':').map(Number);
            
            // Calculate actual flight times for animated aircraft
            const today = new Date();
            const currentDay = today.getUTCDay();
            // Convert Sunday-based day to Monday-based day (0 = Monday, 6 = Sunday) - same as animated aircraft
            const scheduleDay = currentDay === 0 ? 6 : currentDay - 1;
            const targetDay = flightItem.day; // Monday-based
            
            // Calculate days until target day using Monday-based system
            let daysUntilTarget = targetDay - scheduleDay;
            if (daysUntilTarget < 0) {
                daysUntilTarget += 7;
            }
            
            console.log(`Animated aircraft: Current day is ${currentDay}, Schedule day is ${scheduleDay} (Monday-based), Flight is on day ${targetDay} (Monday-based), Days until target: ${daysUntilTarget}`);
            
            const startTime = new Date(today);
            startTime.setUTCDate(today.getUTCDate() + daysUntilTarget);
            startTime.setUTCHours(startHour, startMinute, 0, 0);
            
            const endTime = new Date(today);
            endTime.setUTCDate(today.getUTCDate() + daysUntilTarget);
            endTime.setUTCHours(endHour, endMinute, 0, 0);
            
            // Handle overnight flights - if end time is earlier than start time, it's the next day
            if (endHour < startHour || (endHour === startHour && endMinute < startMinute)) {
                endTime.setUTCDate(endTime.getUTCDate() + 1);
                console.log(`Overnight animated aircraft flight detected: ${aircraftId} ends on next day`);
            }
            
            console.log(`Adding animated aircraft flight: ${aircraftId}, Start: ${startTime.toLocaleString()}, End: ${endTime.toLocaleString()}`);
            
                // Extract city names from airport names
                const departureCity = extractCityName(routeData.departureAirport);
                const arrivalCity = extractCityName(routeData.arrivalAirport);
                
                // Get airline name for this aircraft
                const airlineName = getAirlineFromAircraft(aircraft.aircraftRegistration);
                
                const animatedDisembarkingMinutes = flightItem.disembarkingTime || 15;

                flights.push({
                    id: aircraftId,
                    flightNumber: flightItem.flightNumber || aircraft.aircraftRegistration,
                    departureAirport: routeData.departureAirport,
                    arrivalAirport: routeData.arrivalAirport,
                    cancelled: flightItem.cancelled || false,
                    departureCity: departureCity,
                    arrivalCity: arrivalCity,
                    startTime: startTime.toISOString(),
                    endTime: endTime.toISOString(),
                    departureGate: flightItem.departureGate || 'TBD',
                    arrivalGate: flightItem.arrivalGate || 'TBD',
                    boardingTime: flightItem.boardingTime || 30,
                    disembarkingTime: animatedDisembarkingMinutes,
                    disembarkEndTime: new Date(endTime.getTime() + (animatedDisembarkingMinutes * 60000)).toISOString(),
                    aircraft: aircraft.aircraftRegistration,
                    airline: airlineName,
                    day: flightItem.day,
                    isAnimated: true // Mark as animated for debugging
                });
        }
    });
    
    // Also check the savedSchedule data (alternative schedule format)
    const savedScheduleData = localStorage.getItem('savedSchedule');
    if (savedScheduleData) {
        try {
            const scheduleArray = JSON.parse(savedScheduleData);
            console.log('Checking savedSchedule data:', scheduleArray.length, 'items');
            
            scheduleArray.forEach(scheduleItem => {
                if (scheduleItem.type === 'flight' && scheduleItem.route) {
                    const route = routesList.find(r => r.id === scheduleItem.route);
                    if (route) {
                        // Calculate flight times based on schedule
                        if (!scheduleItem.startTime || !scheduleItem.duration) {
                            console.warn(`Missing time data in savedSchedule:`, scheduleItem);
                            return;
                        }
                        
                        const [startHour, startMinute] = scheduleItem.startTime.split(':').map(Number);
                        const [durationHour, durationMinute] = scheduleItem.duration.split(':').map(Number);
                        
                        // Calculate the date for this specific day of the week
                        const today = new Date();
                        const currentDay = today.getUTCDay(); // 0 = Sunday, 1 = Monday, etc. (UTC)
                        // Convert Sunday-based day to Monday-based day (0 = Monday, 6 = Sunday) - same as animated aircraft
                        const scheduleDay = currentDay === 0 ? 6 : currentDay - 1;
                        const targetDay = scheduleItem.day; // 0 = Monday, 1 = Tuesday, etc. (Monday-based)
                        
                        // Calculate days until target day using Monday-based system
                        let daysUntilTarget = targetDay - scheduleDay;
                        if (daysUntilTarget < 0) {
                            daysUntilTarget += 7; // Next week
                        }
                        
                        console.log(`Flight ${scheduleItem.flightNumber}: Current day is ${currentDay} (${['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][currentDay]}), Schedule day is ${scheduleDay} (Monday-based), Flight is on day ${targetDay} (Monday-based)`);
                        console.log(`Days until target day: ${daysUntilTarget}`);
                        
                        const startTime = new Date(today);
                        startTime.setUTCDate(today.getUTCDate() + daysUntilTarget);
                        startTime.setUTCHours(startHour, startMinute, 0, 0);
                        
                        const endTime = new Date(startTime.getTime() + (durationHour * 60 + durationMinute) * 60000);
                        
                        console.log(`Calculated flight times from savedSchedule: Start: ${startTime.toLocaleString()}, End: ${endTime.toLocaleString()}`);
                        
                            // Extract city names from airport names
                            const departureCity = extractCityName(route.departureAirport);
                            const arrivalCity = extractCityName(route.arrivalAirport);
                            
                            const savedDisembarkingMinutes = scheduleItem.disembarkingTime || 15;

                            flights.push({
                                id: `saved-${scheduleItem.aircraft || 'unknown'}-${scheduleItem.day}-${scheduleItem.startTime}`,
                                flightNumber: scheduleItem.flightNumber || scheduleItem.aircraft || 'Unknown',
                                departureAirport: route.departureAirport,
                                arrivalAirport: route.arrivalAirport,
                                departureCity: departureCity,
                                arrivalCity: arrivalCity,
                                startTime: startTime.toISOString(),
                                endTime: endTime.toISOString(),
                                departureGate: scheduleItem.departureGate || 'TBD',
                                arrivalGate: scheduleItem.arrivalGate || 'TBD',
                                boardingTime: scheduleItem.boardingTime || 30,
                                disembarkingTime: savedDisembarkingMinutes,
                                disembarkEndTime: new Date(endTime.getTime() + (savedDisembarkingMinutes * 60000)).toISOString(),
                                aircraft: scheduleItem.aircraft || 'Unknown',
                                day: scheduleItem.day,
                                source: 'savedSchedule'
                            });
                    }
                }
            });
        } catch (error) {
            console.error('Error parsing savedSchedule data:', error);
        }
    }
    
    return flights;
}

