    // Handle airport form submission
    const form = document.getElementById('airportFormElement');
    if (form) {
        form.addEventListener('submit', function(e) {
            e.preventDefault();
            console.log('Form submitted');
            console.log('Editing marker:', window.editingMarker);
            console.log('Editing coordinates:', window.editingCoordinates);
            
            const wasEditingAirport = Boolean(window.editingMarker);
            let previousAirportData = null;
            if (wasEditingAirport && window.editingMarker.airportData) {
                const previousLatLng = window.editingMarker.getLatLng();
                previousAirportData = {
                    ...window.editingMarker.airportData,
                    lat: previousLatLng.lat,
                    lng: previousLatLng.lng
                };
            }
            
            // Get coordinates - use stored coordinates if editing, otherwise get from form
            let coordinates;
            let coordResult;
            
            if (window.editingMarker && window.editingCoordinates) {
                // Editing mode - use stored coordinates
                coordinates = window.editingCoordinates;
                console.log('Using stored coordinates for edit:', coordinates);
                
                // Check if stored coordinates are in decimal format (from old data)
                if (coordinates.includes(',') && !coordinates.includes('°')) {
                    // Convert decimal format to lat/lng
                    const [lat, lng] = coordinates.split(',').map(coord => parseFloat(coord.trim()));
                    coordResult = { lat: lat, lng: lng };
                    console.log('Using decimal coordinates:', coordResult);
                } else if (coordinates.includes('°')) {
                    // Parse degrees/minutes/seconds format
                    coordResult = parseCoordinates(coordinates);
                    if (!coordResult) {
                        console.log('Failed to parse DMS coordinates:', coordinates);
                        alert('Invalid coordinates format! Please use format like: 8°30′00″N 77°16′28″W');
                        return;
                    }
                } else {
                    // If coordinates are just numbers (lat, lng), use them directly
                    console.log('Using direct lat/lng from marker');
                    const markerLatLng = window.editingMarker.getLatLng();
                    coordResult = { lat: markerLatLng.lat, lng: markerLatLng.lng };
                    console.log('Using marker coordinates:', coordResult);
                }
            } else if (window.editingMarker) {
                // Fallback: use marker coordinates directly if no stored coordinates
                console.log('No stored coordinates, using marker coordinates directly');
                const markerLatLng = window.editingMarker.getLatLng();
                coordResult = { lat: markerLatLng.lat, lng: markerLatLng.lng };
                console.log('Using marker coordinates:', coordResult);
            } else {
                // Adding new airport - get from form
                coordinates = document.getElementById('coordinates').value;
                console.log('Using form coordinates for new airport:', coordinates);
                
                // Parse coordinates from format like "8°30′00″N 77°16′28″W"
                coordResult = parseCoordinates(coordinates);
                if (!coordResult) {
                    alert('Invalid coordinates format! Please use format like: 8°30′00″N 77°16′28″W');
                    return;
                }
            }
            
            const country = document.getElementById('country').value;
            const city = document.getElementById('city').value;
            const airportName = document.getElementById('airportName').value;
            const airportCode = document.getElementById('airportCode').value;
            const isInternational = document.getElementById('isInternational').checked;
            const openingTime = document.getElementById('openingTime').value;
            const closingTime = document.getElementById('closingTime').value;
            const normalizedAirportCode = (airportCode || '').trim().toUpperCase();

            // Prevent duplicate airport codes (case-insensitive), excluding the airport being edited.
            const duplicateAirportCodeExists = userMarkers.some(marker => {
                if (!marker || marker === window.editingMarker) return false;
                return (marker.airportData?.code || '').trim().toUpperCase() === normalizedAirportCode;
            });

            if (duplicateAirportCodeExists) {
                alert(`Airport code "${normalizedAirportCode}" already exists. Please use a different code.`);
                return;
            }
            
            // Get timezone data
            const timeZone = document.getElementById('timeZone').value;
            const timeDifference = document.getElementById('timeDifference').value;
            const alternateTimeZone = document.getElementById('alternateTimeZone').value;
            const alternateTimeDifference = document.getElementById('alternateTimeDifference').value;
            
            // Get selected aircraft types
            const selectedAircraft = getSelectedAircraftTypes();
            
            const lat = coordResult.lat;
            const lng = coordResult.lng;
            
            // Get population data
            const population = parseInt(document.getElementById('population').value) || 0;
            
            // Get services checkboxes
            const waypointHotel = document.getElementById('waypointHotel').checked;
            const waypointLounge = document.getElementById('waypointLounge').checked;
            const cityBusTransfer = document.getElementById('cityBusTransfer').checked;
            
            // Get notes
            const notes = document.getElementById('airportNotes').value || '';
            
            // Create airport data object
            const airportData = {
                name: airportName,
                country: country,
                city: city,
                code: normalizedAirportCode,
                isInternational: isInternational,
                originalCoordinates: coordinates, // Store original format
                coordinates: `${lat.toFixed(4)}, ${lng.toFixed(4)}`,
                hours: `${openingTime} - ${closingTime}`,
                compatibleAircraft: selectedAircraft,
                population: population,
                timeZone: timeZone,
                timeDifference: timeDifference,
                alternateTimeZone: alternateTimeZone,
                alternateTimeDifference: alternateTimeDifference,
                waypointHotel: waypointHotel,
                waypointLounge: waypointLounge,
                cityBusTransfer: cityBusTransfer,
                notes: notes,
                runways: Array.isArray(window.editingMarker?.airportData?.runways)
                    ? window.editingMarker.airportData.runways.map(rwy => normalizeRunwayRecord(rwy)).filter(Boolean)
                    : [],
                lat: lat,
                lng: lng
            };
            
            // Check if we're editing an existing airport
            if (window.editingMarker) {
                // Remove the old marker
                map.removeLayer(window.editingMarker);
                const index = userMarkers.indexOf(window.editingMarker);
                if (index > -1) {
                    userMarkers.splice(index, 1);
                }
            }
            
            // Add airport marker
            const airportMarker = addAirportMarker(airportData);
            
            // Save to localStorage
            saveAirports();
            
            // If airport identity changed (e.g. code correction), update all linked routes
            if (wasEditingAirport) {
                syncRoutesForAirportUpdate(previousAirportData, airportData);
            }
            
            // Center map on the airport
            map.setView([lat, lng], 10);
            
            // Hide form (keep airports management menu visible)
            const formEl = document.getElementById('airportForm');
            
            if (formEl) formEl.style.display = 'none';
            safeResetForm('airportFormElement');
            resetFormToAddMode();
            
            // Update airports list
            updateAirportsList();
            updateRoutesList();
            
            // Show success message
            const message = window.editingMarker ? 'Airport updated successfully!' : 'Airport added successfully!';
            alert(message);
        });
    }

