// Aircraft management functions
/** Passenger seats for an aircraft type model, or null if unknown / legacy data. */
function getAircraftTypeCapacity(model) {
    if (!model) return null;
    const t = aircraftList.find(a => a.model === model);
    if (!t || t.capacity == null) return null;
    const n = Number(t.capacity);
    return Number.isFinite(n) && n > 0 ? n : null;
}

function formatAircraftSpecsLine(aircraft) {
    const cap = getAircraftTypeCapacity(aircraft.model);
    const capPart = cap != null ? ` | ${cap} pax` : '';
    return `${aircraft.speed} km/h | ${aircraft.range} km${capPart}`;
}

function loadSavedAircraft() {
    const savedAircraft = localStorage.getItem('savedAircraft');
    if (savedAircraft) {
        const aircraft = JSON.parse(savedAircraft);
        aircraftList.length = 0; // Clear array
        aircraftList.push(...aircraft);
    }
    populateAircraftTypeDropdown();
}

function saveAircraft() {
    localStorage.setItem('savedAircraft', JSON.stringify(aircraftList));
    populateAircraftTypeDropdown();
}

function updateAircraftList() {
    const aircraftListElement = document.getElementById('aircraftList');
    
    if (!aircraftListElement) {
        console.log('Aircraft list element not found');
        return;
    }
    
    if (aircraftList.length === 0) {
        aircraftListElement.innerHTML = '<div class="no-airports">No aircraft types added yet</div>';
        return;
    }
    
    let listHTML = '';
    aircraftList.forEach((aircraft, index) => {
        const cap = aircraft.capacity != null && Number.isFinite(Number(aircraft.capacity)) ? Number(aircraft.capacity) : null;
        listHTML += `
            <div class="aircraft-item" onclick="editAircraft(${index})">
                <h5>${aircraft.model}</h5>
                <p><span class="aircraft-specs">Speed: ${aircraft.speed} km/h</span></p>
                <p>Max Range: ${aircraft.range} km</p>
                <p>Capacity: ${cap != null ? `${cap} seats` : '—'}</p>
                <div style="margin-top: 8px; display: flex; gap: 5px;">
                    <button onclick="event.stopPropagation(); editAircraft(${index})" 
                            style="padding: 4px 8px; background: #19363c; color: #e6e6e9; border: none; border-radius: 3px; cursor: pointer; font-size: 10px;">
                        Edit
                    </button>
                    <button onclick="event.stopPropagation(); deleteAircraft(${index})" 
                            style="padding: 4px 8px; background: #e74c3c; color: white; border: none; border-radius: 3px; cursor: pointer; font-size: 10px;">
                        Delete
                    </button>
                </div>
        </div>
    `;
    });
    
    aircraftListElement.innerHTML = listHTML;
}

function editAircraft(index) {
    const aircraft = aircraftList[index];
    if (!aircraft) return;
    
    // Show the form and hide aircraft menu
    const form = document.getElementById('aircraftForm');
    const aircraftMenu = document.getElementById('aircraftMenuContent');
    
    if (aircraftMenu) aircraftMenu.style.display = 'none';
    if (form) form.style.display = 'block';
    
    // Fill the form with existing data
    document.getElementById('aircraftModel').value = aircraft.model;
    document.getElementById('aircraftSpeed').value = aircraft.speed;
    document.getElementById('aircraftRange').value = aircraft.range;
    const cap = aircraft.capacity != null && Number.isFinite(Number(aircraft.capacity)) ? Number(aircraft.capacity) : '';
    document.getElementById('aircraftCapacity').value = cap;
    
    // Store the index for updating
    window.editingAircraftIndex = index;
    
    // Change form title and button text
    const formTitle = form.querySelector('h4');
    const submitButton = form.querySelector('button[type="submit"]');
    if (formTitle) formTitle.textContent = 'Edit Aircraft Type';
    if (submitButton) submitButton.textContent = 'Update Aircraft Type';
}

function deleteAircraft(index) {
    if (confirm('Are you sure you want to delete this aircraft?')) {
        aircraftList.splice(index, 1);
        saveAircraft();
        updateAircraftList();
        alert('Aircraft type deleted successfully!');
    }
}

function resetAircraftFormToAddMode() {
    const form = document.getElementById('aircraftForm');
    const formTitle = form.querySelector('h4');
    const submitButton = form.querySelector('button[type="submit"]');
    
    if (formTitle) formTitle.textContent = 'Add New Aircraft Type';
    if (submitButton) submitButton.textContent = 'Add Aircraft Type';
    
    // Clear editing state
    window.editingAircraftIndex = null;
}

// Registered aircraft management functions
function loadSavedRegisteredAircraft() {
    const savedRegisteredAircraft = localStorage.getItem('savedRegisteredAircraft');
    console.log('Loading saved registered aircraft:', savedRegisteredAircraft);
    if (savedRegisteredAircraft) {
        const registeredAircraft = JSON.parse(savedRegisteredAircraft);
        console.log('Parsed registered aircraft:', registeredAircraft);
        
        // Clear array properly
        registeredAircraftList.length = 0;
        
        // Validate and filter out any invalid entries
        if (Array.isArray(registeredAircraft)) {
            const validAircraft = registeredAircraft.filter(aircraft => 
                aircraft && 
                typeof aircraft === 'object' && 
                aircraft.aircraftType && 
                aircraft.registration
            );
            registeredAircraftList.push(...validAircraft);
        } else {
            console.warn('Invalid registered aircraft data structure, clearing localStorage');
            localStorage.removeItem('savedRegisteredAircraft');
        }
        
        console.log('Loaded registered aircraft list:', registeredAircraftList);
    }
}

function saveRegisteredAircraft() {
    console.log('Saving registered aircraft list:', registeredAircraftList);
    localStorage.setItem('savedRegisteredAircraft', JSON.stringify(registeredAircraftList));
    console.log('Saved to localStorage');
}

