// Function to hide all menu content and show only the specified menu
function showOnlyMenu(menuIdToShow) {
    console.log('Showing only menu:', menuIdToShow);
    
    // List of all menu content elements to hide
    const allMenus = [
        'mainMenu',
        'airportsManagementMenuContent',
        'countryAirportsContent', 
        'airportGatesContent',
        'gateCalendarContent',
        'aircraftManagementMenuContent',
        'aircraftTypesSubMenuContent',
        'airlinesSubMenuContent',
        'individualAirlineSubMenuContent',
        'routesManagementMenuContent',
        'flightSearchMenuContent',
        'aircraftScheduleContent'
    ];
    
    // Hide all menus first
    allMenus.forEach(menuId => {
        const menu = document.getElementById(menuId);
        if (menu) {
            menu.style.display = 'none';
        }
    });
    
    // Show only the specified menu
    if (menuIdToShow) {
        const targetMenu = document.getElementById(menuIdToShow);
        if (targetMenu) {
            targetMenu.style.display = 'block';
        }
    }
    
    // Show/hide quick navigation tabs based on which menu is active
    const quickNavTabs = document.getElementById('quickNavTabs');
    const mainMenuIds = [
        'aircraftManagementMenuContent',
        'airportsManagementMenuContent',
        'routesManagementMenuContent',
        'flightSearchMenuContent'
    ];
    
    // Submenus that should also show tabs (they belong to a main menu)
    const subMenuToMainMenuMap = {
        'aircraftTypesSubMenuContent': 'aircraftManagementMenuContent',
        'airlinesSubMenuContent': 'aircraftManagementMenuContent',
        'individualAirlineSubMenuContent': 'aircraftManagementMenuContent',
        'aircraftScheduleContent': 'aircraftManagementMenuContent',
        'countryAirportsContent': 'airportsManagementMenuContent',
        'airportGatesContent': 'airportsManagementMenuContent',
        'gateCalendarContent': 'airportsManagementMenuContent'
    };
    
    if (quickNavTabs) {
        // Determine which main menu we're in (or parent menu if in submenu)
        let currentMainMenu = null;
        if (mainMenuIds.includes(menuIdToShow)) {
            currentMainMenu = menuIdToShow;
        } else if (subMenuToMainMenuMap[menuIdToShow]) {
            currentMainMenu = subMenuToMainMenuMap[menuIdToShow];
        }
        
        // Show tabs if we're in a main menu or a submenu
        if (currentMainMenu) {
            // Directly set style properties to override inline style
            quickNavTabs.style.display = 'flex';
            quickNavTabs.style.visibility = 'visible';
            // Set initial state for animation - start at sidebar edge
            quickNavTabs.style.opacity = '0';
            quickNavTabs.style.transform = 'translateX(0)';
            // Trigger fade in animation - tabs stay flush with sidebar edge
            setTimeout(() => {
                quickNavTabs.style.opacity = '1';
                quickNavTabs.style.transform = 'translateX(0)';
            }, 10);
            // Hide the tab for the current menu, show others
            updateTabVisibility(currentMainMenu);
            // Update active tab based on current menu
            updateActiveTab(currentMainMenu);
        } else if (menuIdToShow === 'mainMenu') {
            // Hide tabs when on main menu with fade out - slide back to sidebar edge
            quickNavTabs.style.opacity = '0';
            quickNavTabs.style.transform = 'translateX(0)';
            setTimeout(() => {
                quickNavTabs.style.display = 'none';
            }, 300);
        } else {
            // For any other menu, hide tabs with fade out - slide back to sidebar edge
            quickNavTabs.style.opacity = '0';
            quickNavTabs.style.transform = 'translateX(0)';
            setTimeout(() => {
                quickNavTabs.style.display = 'none';
            }, 300);
        }
    }
    
    // Also close all forms when switching menus
    closeAllFormsAndResetMenus();
    syncGateMapMarkersVisibility();
}

// Function to update the active tab
function updateActiveTab(activeMenuId) {
    const tabs = document.querySelectorAll('.nav-tab');
    tabs.forEach(tab => {
        const tabMenuId = tab.getAttribute('data-menu');
        if (tabMenuId === activeMenuId) {
            tab.classList.add('active');
        } else {
            tab.classList.remove('active');
        }
    });
}

// Function to show/hide tabs based on current menu (hide current menu's tab)
function updateTabVisibility(currentMenuId) {
    const tabs = document.querySelectorAll('.nav-tab');
    tabs.forEach(tab => {
        const tabMenuId = tab.getAttribute('data-menu');
        // Hide the tab for the current menu, show all others
        if (tabMenuId === currentMenuId) {
            tab.style.display = 'none';
        } else {
            tab.style.display = 'flex';
        }
    });
}

// Function to get airline name from aircraft registration
function getAirlineFromAircraft(aircraftRegistration) {
    // Search through all airlines to find which one owns this aircraft
    for (const airline of airlinesList) {
        if (airline.aircraft) {
            const aircraft = airline.aircraft.find(ac => ac.registration === aircraftRegistration);
            if (aircraft) {
                return airline.name;
            }
        }
    }
    return null;
}

// Function to get airline logo based on airline name or flight number
function getAirlineLogo(airlineName, flightNumber = '') {
    // Airline logo mapping
    const airlineLogos = {
        'Kohben Travel Airlines': 'KTA.png',
        'Kohben Travel Connect': 'KTC.png',
        'd.p air': 'DPA.png',
        'ALMAca': 'AlmaCa.png',
        'Argente': 'Argente.png',
        'NOAH': 'Noah.png',
        'NOAH Jr': 'Noah Jr.png'
    };
    
    // Check by airline name first
    if (airlineName && airlineLogos[airlineName]) {
        return airlineLogos[airlineName];
    }
    
    // Check by flight number prefixes
    if (flightNumber) {
        if (flightNumber.includes('KTA')) return 'KTA.png';
        if (flightNumber.includes('KTC')) return 'KTC.png';
        if (flightNumber.includes('DPA')) return 'DPA.png';
        if (flightNumber.includes('ALM')) return 'AlmaCa.png';
        if (flightNumber.includes('ARG')) return 'Argente.png';
        if (flightNumber.includes('NOA')) return 'Noah.png';
        if (flightNumber.includes('NOJ')) return 'Noah Jr.png';
    }
    
    // Default fallback
    return null;
}

// Function to generate airline logo HTML
function generateAirlineLogoHTML(airlineName, flightNumber = '', size = '40px') {
    const logoFile = getAirlineLogo(airlineName, flightNumber);
    
    if (logoFile) {
        return `<img src="Photos/${logoFile}" style="width: ${size}; height: ${size}; object-fit: contain;" alt="${airlineName || 'Airline'}">`;
    } else {
        // Fallback to generic airline icon
        const airlineCode = airlineName ? airlineName.charAt(0).toUpperCase() : 'AIR';
        return `<div style="width: ${size}; height: ${size}; background: #4e8ca0; border-radius: 4px; display: flex; align-items: center; justify-content: center; color: white; font-size: 12px; font-weight: bold;">${airlineCode}</div>`;
    }
}

// Helper function to safely reset forms
function safeResetForm(formId) {
    const form = document.getElementById(formId);
    if (form && typeof form.reset === 'function') {
        form.reset();
        return true;
    } else {
        console.warn(`Could not reset form: ${formId} (element not found or not a form)`);
        return false;
    }
}

