function getCurrentAircraftRegistrations() {
    const registrations = [];
    airlinesList.forEach(airline => {
        if (airline.aircraft) {
            airline.aircraft.forEach(aircraft => {
                registrations.push(aircraft.registration);
            });
        }
    });
    return registrations;
}

// Function to clean up schedules and gate blocks for aircraft that no longer exist
function cleanupOrphanedAircraftSchedules() {
    console.log('Cleaning up orphaned aircraft schedules and gate blocks...');
    
    // Get list of current aircraft registrations from all airlines
    const currentAircraftRegistrations = getCurrentAircraftRegistrations();
    console.log('Current aircraft registrations from all airlines:', currentAircraftRegistrations);
    
    // Find aircraft data for registrations that no longer exist
    const orphanedAircraft = new Set();
    Object.keys(aircraftSchedules).forEach(registration => {
        if (!currentAircraftRegistrations.includes(registration)) {
            orphanedAircraft.add(registration);
        }
    });
    Object.keys(gateBlocks).forEach(registration => {
        if (!currentAircraftRegistrations.includes(registration)) {
            orphanedAircraft.add(registration);
        }
    });
    
    if (orphanedAircraft.size > 0) {
        const orphanedRegistrations = Array.from(orphanedAircraft);
        console.log('Found orphaned aircraft data for:', orphanedRegistrations);
        
        // Remove orphaned schedules and gate blocks
        orphanedRegistrations.forEach(registration => {
            delete aircraftSchedules[registration];
            delete gateBlocks[registration];
            console.log(`Removed schedule/gate blocks for deleted aircraft: ${registration}`);
        });
        
        // Save the cleaned data
        saveAircraftSchedules();
        saveGateBlocks();
        console.log('Orphaned aircraft data cleaned up and saved');
    } else {
        console.log('No orphaned aircraft data found');
    }
}

