// Function to verify schedule isolation is maintained
function verifyScheduleIsolation() {
    console.log('=== VERIFYING SCHEDULE ISOLATION ===');
    
    let isolationMaintained = true;
    const issues = [];
    
    // Get current aircraft registrations from all airlines
    const currentAircraftRegistrations = [];
    airlinesList.forEach(airline => {
        if (airline.aircraft) {
            airline.aircraft.forEach(aircraft => {
                currentAircraftRegistrations.push(aircraft.registration);
            });
        }
    });
    
    // Check that each aircraft has its own schedule array
    currentAircraftRegistrations.forEach(registration => {
        const schedule = aircraftSchedules[registration];
        
        if (!schedule) {
            console.log(`✅ ${registration}: No schedule (will be created when needed)`);
            return;
        }
        
        if (!Array.isArray(schedule)) {
            issues.push(`${registration}: Schedule is not an array`);
            isolationMaintained = false;
            return;
        }
        
        // Check that schedule items don't reference other aircraft
        schedule.forEach((item, index) => {
            if (item.aircraft && item.aircraft !== registration) {
                issues.push(`${registration}: Item ${index} references different aircraft (${item.aircraft})`);
                isolationMaintained = false;
            }
        });
        
        console.log(`✅ ${registration}: Schedule isolation maintained (${schedule.length} items)`);
    });
    
    // Check for cross-references between schedules
    const allScheduleItems = [];
    Object.keys(aircraftSchedules).forEach(registration => {
        const schedule = aircraftSchedules[registration];
        if (Array.isArray(schedule)) {
            schedule.forEach((item, index) => {
                allScheduleItems.push({
                    registration,
                    index,
                    item
                });
            });
        }
    });
    
    // Check for duplicate items across aircraft
    for (let i = 0; i < allScheduleItems.length; i++) {
        for (let j = i + 1; j < allScheduleItems.length; j++) {
            const item1 = allScheduleItems[i];
            const item2 = allScheduleItems[j];
            
            if (item1.registration !== item2.registration && 
                JSON.stringify(item1.item) === JSON.stringify(item2.item)) {
                issues.push(`Duplicate item found between ${item1.registration} and ${item2.registration}`);
                isolationMaintained = false;
            }
        }
    }
    
    if (isolationMaintained) {
        console.log('✅ SCHEDULE ISOLATION VERIFIED: All aircraft have independent schedules');
    } else {
        console.log('❌ SCHEDULE ISOLATION ISSUES FOUND:');
        issues.forEach(issue => console.log(`  - ${issue}`));
    }
    
    console.log('=== SCHEDULE ISOLATION VERIFICATION COMPLETE ===');
    return isolationMaintained;
}

// Function to test gate conflict checking across aircraft
function testGateConflictChecking() {
    console.log('=== TESTING GATE CONFLICT CHECKING ===');
    
    // Create test aircraft if we don't have enough
    const testAircraft1 = { registration: 'TEST-GATE-001', aircraftType: 'Test Aircraft', airline: 'Test Airline' };
    const testAircraft2 = { registration: 'TEST-GATE-002', aircraftType: 'Test Aircraft', airline: 'Test Airline' };
    
    // Add test aircraft to registered list if not already there
    if (!registeredAircraftList.find(a => a.registration === 'TEST-GATE-001')) {
        registeredAircraftList.push(testAircraft1);
    }
    if (!registeredAircraftList.find(a => a.registration === 'TEST-GATE-002')) {
        registeredAircraftList.push(testAircraft2);
    }
    
    // Initialize schedules for test aircraft
    if (!aircraftSchedules['TEST-GATE-001']) {
        aircraftSchedules['TEST-GATE-001'] = [];
    }
    if (!aircraftSchedules['TEST-GATE-002']) {
        aircraftSchedules['TEST-GATE-002'] = [];
    }
    
    console.log('Test aircraft created: TEST-GATE-001, TEST-GATE-002');
    
    // Test 1: Add schedule item to first aircraft
    console.log('\n--- Test 1: Adding Schedule to First Aircraft ---');
    
    const item1 = {
        type: 'flight',
        day: 0, // Monday
        startTime: '08:00',
        endTime: '10:00',
        gate: 'Gate A1',
        airport: 'Test Airport',
        description: 'TEST-GATE-001 Flight 1'
    };
    
    aircraftSchedules['TEST-GATE-001'].push(item1);
    console.log('Added item to TEST-GATE-001:', item1.description);
    
    // Test 2: Try to add conflicting schedule to second aircraft
    console.log('\n--- Test 2: Testing Gate Conflict Detection ---');
    
    const conflictResult = checkGateConflicts('Test Airport', 'Gate A1', 0, '09:00', '11:00');
    console.log('Conflict check result:', conflictResult);
    
    if (conflictResult.conflict) {
        console.log('✅ Gate conflict correctly detected!');
        console.log(`  Conflict with: ${conflictResult.type} - ${conflictResult.aircraft || conflictResult.reason}`);
    } else {
        console.log('❌ Gate conflict NOT detected - this is a problem!');
    }
    
    // Test 3: Try to add non-conflicting schedule to second aircraft
    console.log('\n--- Test 3: Testing Non-Conflicting Schedule ---');
    
    const noConflictResult = checkGateConflicts('Test Airport', 'Gate A1', 0, '11:00', '13:00');
    console.log('Non-conflict check result:', noConflictResult);
    
    if (!noConflictResult.conflict) {
        console.log('✅ No conflict correctly detected for non-overlapping time!');
        
        // Add the non-conflicting item
        const item2 = {
            type: 'flight',
            day: 0, // Monday
            startTime: '11:00',
            endTime: '13:00',
            gate: 'Gate A1',
            airport: 'Test Airport',
            description: 'TEST-GATE-002 Flight 1'
        };
        
        aircraftSchedules['TEST-GATE-002'].push(item2);
        console.log('Added non-conflicting item to TEST-GATE-002:', item2.description);
    } else {
        console.log('❌ False conflict detected - this is a problem!');
    }
    
    // Test 4: Test gate block conflict
    console.log('\n--- Test 4: Testing Gate Block Conflict ---');
    
    // Add a gate block
    if (!gateBlocks['Test Airport']) {
        gateBlocks['Test Airport'] = [];
    }
    
    const gateBlock = {
        day: 0,
        gate: 'Gate A1',
        startTime: '14:00',
        endTime: '16:00',
        reason: 'Maintenance',
        type: 'gate-block'
    };
    
    gateBlocks['Test Airport'].push(gateBlock);
    console.log('Added gate block:', gateBlock.reason);
    
    // Test conflict with gate block
    const blockConflictResult = checkGateConflicts('Test Airport', 'Gate A1', 0, '15:00', '17:00');
    console.log('Gate block conflict check result:', blockConflictResult);
    
    if (blockConflictResult.conflict) {
        console.log('✅ Gate block conflict correctly detected!');
        console.log(`  Conflict with: ${blockConflictResult.type} - ${blockConflictResult.reason}`);
    } else {
        console.log('❌ Gate block conflict NOT detected - this is a problem!');
    }
    
    // Cleanup test aircraft
    console.log('\n--- Cleanup ---');
    registeredAircraftList.splice(registeredAircraftList.findIndex(a => a.registration === 'TEST-GATE-001'), 1);
    registeredAircraftList.splice(registeredAircraftList.findIndex(a => a.registration === 'TEST-GATE-002'), 1);
    delete aircraftSchedules['TEST-GATE-001'];
    delete aircraftSchedules['TEST-GATE-002'];
    gateBlocks['Test Airport'] = gateBlocks['Test Airport'].filter(block => block.reason !== 'Maintenance');
    
    console.log('Test aircraft and gate block removed');
    console.log('=== GATE CONFLICT CHECKING TEST COMPLETE ===');
}

