// Function to fix the existing gate conflict in the data
function fixExistingGateConflict() {
    console.log('=== FIXING EXISTING GATE CONFLICT ===');
    
    // Check if the conflict exists
    const hkKcbSchedule = aircraftSchedules['HK-KCB'];
    const hkKcaSchedule = aircraftSchedules['HK-KCA'];
    
    if (!hkKcbSchedule || !hkKcaSchedule) {
        console.log('❌ Aircraft schedules not found');
        return;
    }
    
    // Find the conflicting items
    const hkKcbDisembarking = hkKcbSchedule.find(item => 
        item.phase === 'disembarking' && 
        item.gate === 'F01 (Terminal 2)' && 
        item.airport === 'El Dorado International Airport'
    );
    
    const hkKcaBoarding = hkKcaSchedule.find(item => 
        item.phase === 'boarding' && 
        item.gate === 'F01 (Terminal 2)' && 
        item.airport === 'El Dorado International Airport'
    );
    
    if (!hkKcbDisembarking || !hkKcaBoarding) {
        console.log('❌ Conflicting items not found');
        return;
    }
    
    console.log('Found conflict:');
    console.log(`  HK-KCB disembarking: ${hkKcbDisembarking.startTime}-${hkKcbDisembarking.endTime}`);
    console.log(`  HK-KCA boarding: ${hkKcaBoarding.startTime}-${hkKcaBoarding.endTime}`);
    
    // Fix by changing HK-KCA boarding to use a different gate
    const originalGate = hkKcaBoarding.gate;
    hkKcaBoarding.gate = 'F02 (Terminal 2)'; // Use a different gate
    
    console.log(`✅ Fixed conflict: Changed HK-KCA boarding gate from ${originalGate} to ${hkKcaBoarding.gate}`);
    
    // Save the changes
    saveAircraftSchedules();
    
    // Verify the fix
    const conflictCheck = checkGateConflicts('El Dorado International Airport', 'F02 (Terminal 2)', 2, '13:05', '13:35');
    if (!conflictCheck.conflict) {
        console.log('✅ Conflict resolved - no more gate conflicts!');
    } else {
        console.log('❌ Conflict still exists');
    }
    
    console.log('=== GATE CONFLICT FIX COMPLETE ===');
}

// REMOVED: Duplicate comprehensiveGateConflictCheck function that lacked gate name normalization
// The correct function with gate name normalization is defined later in the file
function REMOVED_comprehensiveGateConflictCheck(airportName, gateName, day, startTime, endTime, excludeAircraft = null, excludeIndex = null) {
    // DISABLED: This function lacks gate name normalization and is overridden by the correct function later
    console.log('⚠️ WARNING: Using disabled function - this should not happen');
    return { conflict: false, conflicts: [], totalConflicts: 0 };
    
    console.log(`🔍 COMPREHENSIVE GATE CONFLICT CHECK`);
    console.log(`   Gate: ${gateName} at ${airportName}`);
    console.log(`   Day: ${day} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][day]})`);
    console.log(`   Time: ${startTime} - ${endTime}`);
    console.log(`   Exclude: ${excludeAircraft || 'none'}`);
    console.log(`   Total aircraft schedules: ${Object.keys(aircraftSchedules).length}`);
    
    const conflicts = [];
    
    // Convert times to minutes for easier comparison
    const checkStart = timeToMinutes(startTime);
    const checkEnd = timeToMinutes(endTime);
    
    // 1. Check ALL aircraft schedules for conflicts
    Object.keys(aircraftSchedules).forEach(aircraftReg => {
        const schedule = aircraftSchedules[aircraftReg];
        if (!Array.isArray(schedule)) return;
        
        schedule.forEach((item, index) => {
            // Skip if this is the item being edited
            if (excludeAircraft && aircraftReg === excludeAircraft && index === excludeIndex) {
                return;
            }
            
            // Check if this item uses the same gate at the same airport on the same day
            if (item.day === day && item.gate === gateName && item.airport === airportName) {
                const itemStart = timeToMinutes(item.startTime);
                const itemEnd = timeToMinutes(item.endTime);
                
                console.log(`   Found matching item: ${aircraftReg} - ${item.startTime}-${item.endTime} at ${item.airport} gate ${item.gate}`);
                console.log(`   Checking against ${aircraftReg}: ${item.startTime}-${item.endTime} (${itemStart}-${itemEnd} min)`);
                
                // Check for overlap (excluding zero-minute overlaps)
                if ((checkStart < itemEnd && checkEnd > itemStart)) {
                    const overlapStart = Math.max(checkStart, itemStart);
                    const overlapEnd = Math.min(checkEnd, itemEnd);
                    const overlapMinutes = overlapEnd - overlapStart;
                    
                    // Only report conflicts with actual time overlap (more than 0 minutes)
                    // Zero-minute overlaps are acceptable - flights can end exactly when another starts
                    if (overlapMinutes > 0) {
                        conflicts.push({
                            type: 'aircraft',
                            aircraft: aircraftReg,
                            description: item.description || item.type,
                            conflictingTime: `${item.startTime}-${item.endTime}`,
                            overlapMinutes: overlapMinutes,
                            phase: item.phase || 'unknown'
                        });
                        
                        console.log(`   ❌ CONFLICT: ${overlapMinutes} minute overlap with ${aircraftReg}`);
                    } else {
                        console.log(`   ✅ NO CONFLICT: Zero-minute overlap with ${aircraftReg} (acceptable - no actual conflict)`);
                    }
                }
            }
        });
    });
    
    // 2. Check gate blocks for conflicts (only for current aircraft)
    if (currentAircraftForSchedule && gateBlocks[currentAircraftForSchedule] && gateBlocks[currentAircraftForSchedule][airportName]) {
        const airportBlocks = gateBlocks[currentAircraftForSchedule][airportName];
        airportBlocks.forEach((block, index) => {
            if (block.day === day && block.gate === gateName) {
                const blockStart = timeToMinutes(block.startTime);
                const blockEnd = timeToMinutes(block.endTime);
                
                console.log(`   Checking against gate block: ${block.startTime}-${block.endTime} (${blockStart}-${blockEnd} min)`);
                
                // Check for overlap (excluding zero-minute overlaps)
                if ((checkStart < blockEnd && checkEnd > blockStart)) {
                    const overlapStart = Math.max(checkStart, blockStart);
                    const overlapEnd = Math.min(checkEnd, blockEnd);
                    const overlapMinutes = overlapEnd - overlapStart;
                    
                    // Only report conflicts with actual time overlap (more than 0 minutes)
                    if (overlapMinutes > 0) {
                        conflicts.push({
                            type: 'block',
                            reason: block.reason,
                            conflictingTime: `${block.startTime}-${block.endTime}`,
                            overlapMinutes: overlapMinutes
                        });
                        
                        console.log(`   ❌ CONFLICT: ${overlapMinutes} minute overlap with gate block`);
                    } else {
                        console.log(`   ✅ NO CONFLICT: Zero-minute overlap with gate block (acceptable)`);
                    }
                }
            }
        });
    }
    
    // 3. Check for edge cases
    if (conflicts.length === 0) {
        console.log(`   ✅ NO CONFLICTS FOUND`);
    } else {
        console.log(`   ❌ ${conflicts.length} CONFLICT(S) FOUND:`);
        conflicts.forEach((conflict, index) => {
            console.log(`      ${index + 1}. ${conflict.type}: ${conflict.aircraft || conflict.reason} (${conflict.overlapMinutes} min overlap)`);
        });
    }
    
    return {
        conflict: conflicts.length > 0,
        conflicts: conflicts,
        totalConflicts: conflicts.length
    };
}

