// Test gate name normalization
function testGateNameNormalization() {
    console.log('=== TESTING GATE NAME NORMALIZATION ===');
    
    const testCases = [
        { input: 'Remote Stand 1 (Remote)', expected: 'remotestand1remote' },
        { input: 'Remote Stand 1 (Remote )', expected: 'remotestand1remote' },
        { input: 'F01 (Terminal 2)', expected: 'f01terminal2' },
        { input: 'F01 ( Terminal 2 )', expected: 'f01terminal2' },
        { input: 'Stand (Main Terminal)', expected: 'standmainterminal' },
        { input: '  Stand (Main Terminal)  ', expected: 'standmainterminal' },
        { input: 'Gate A1', expected: 'gatea1' },
        { input: 'GATE A1', expected: 'gatea1' },
        { input: '', expected: '' },
        { input: null, expected: '' }
    ];
    
    console.log('Testing gate name normalization...');
    testCases.forEach((testCase, index) => {
        const result = normalizeGateName(testCase.input);
        const passed = result === testCase.expected;
        console.log(`Test ${index + 1}: "${testCase.input}" → "${result}" ${passed ? '✅' : '❌'} (expected: "${testCase.expected}")`);
        
        if (!passed) {
            console.error(`❌ FAILED: Expected "${testCase.expected}" but got "${result}"`);
        }
    });
    
    console.log('\n=== GATE NAME NORMALIZATION TEST COMPLETE ===');
}

