// Test function to verify conflict detection with real schedule data
function testRealScheduleConflictDetection() {
    console.log('=== TESTING REAL SCHEDULE CONFLICT DETECTION ===');
    
    // Run the conflict scan on the actual schedule data
    const conflictResults = quickConflictScan();
    
    console.log('\n=== CONFLICT DETECTION RESULTS ===');
    console.log(`Total conflicts found: ${conflictResults.totalConflicts}`);
    
    if (conflictResults.totalConflicts > 0) {
        console.log('\n📋 DETAILED CONFLICT REPORT:');
        conflictResults.allConflicts.forEach((conflict, index) => {
            console.log(`\n${index + 1}. Aircraft: ${conflict.aircraft}`);
            if (conflict.scheduleItem) {
                console.log(`   Schedule Item: ${conflict.scheduleItem.description || conflict.scheduleItem.type || 'Unknown'}`);
                console.log(`   Gate: ${conflict.scheduleItem.gate} at ${conflict.scheduleItem.airport}`);
                console.log(`   Time: ${conflict.scheduleItem.startTime}-${conflict.scheduleItem.endTime} (Day ${conflict.scheduleItem.day})`);
            }
            if (conflict.gateBlock) {
                console.log(`   Gate Block: ${conflict.gateBlock.reason}`);
                console.log(`   Gate: ${conflict.gateBlock.gate}`);
                console.log(`   Time: ${conflict.gateBlock.startTime}-${conflict.gateBlock.endTime} (Day ${conflict.gateBlock.day})`);
            }
            console.log(`   Conflicts: ${conflict.conflicts.length}`);
            conflict.conflicts.forEach((conflictDetail, detailIndex) => {
                console.log(`     ${detailIndex + 1}. ${conflictDetail.conflictType || 'Unknown conflict type'}`);
                console.log(`        Overlap: ${conflictDetail.overlapMinutes} minutes`);
                console.log(`        Conflicting: ${conflictDetail.conflictingTime}`);
            });
        });
    } else {
        console.log('✅ No conflicts found in the current schedule data');
    }
    
    console.log('\n=== REAL SCHEDULE CONFLICT DETECTION TEST COMPLETE ===');
    
    return conflictResults;
}

