    currentAircraftForSchedule = 'TEST-AIRCRAFT-2';
    
    // Test that Aircraft 2 doesn't see Aircraft 1's gate blocks
    const noConflict2 = checkGateConflicts('Test Airport', 'Gate A1', 0, '11:00', '13:00');
    console.log('Aircraft 2 conflict test (11:00-13:00 vs Aircraft 1 block 10:00-12:00):', !noConflict2.conflict ? 'NO CONFLICT ✅' : 'CONFLICT DETECTED ❌');
    
    // Test 3: Comprehensive conflict detection
    console.log('\nTest 3: Comprehensive conflict detection');
    
    // Set current aircraft back to Aircraft 1
    currentAircraftForSchedule = 'TEST-AIRCRAFT-1';
    
    // Test various overlap scenarios
