// Test function to verify overnight flight display fix
function testOvernightFlightDisplay() {
    console.log('=== TESTING OVERNIGHT FLIGHT DISPLAY FIX ===');
    
    // Test case: Flight departing Friday 22:45, arriving Saturday 00:25
    const testRoute = {
        departure: 'SOX',
        arrival: 'BOG'
    };
    
    const day = 4; // Friday
    const startTime = '22:45';
    const boardingTime = 15; // 15 minutes
    const flightDuration = '01:00'; // 1 hour
    const disembarkingTime = 25; // 25 minutes
    
    // Calculate times
    const boardingStartTime = startTime;
    const boardingEndTime = addMinutesToTime(startTime, boardingTime);
    const flightStartTime = boardingEndTime;
    const flightEndTime = addMinutesToTime(startTime, boardingTime + timeToMinutes(flightDuration));
    const disembarkingStartTime = flightEndTime;
    const disembarkingEndTime = addMinutesToTime(startTime, boardingTime + timeToMinutes(flightDuration) + disembarkingTime);
    
    console.log('Flight times:');
    console.log(`  Boarding: ${boardingStartTime} - ${boardingEndTime}`);
    console.log(`  Flight: ${flightStartTime} - ${flightEndTime}`);
    console.log(`  Disembarking: ${disembarkingStartTime} - ${disembarkingEndTime}`);
    
    // Calculate days
    const startDay = parseInt(day);
    let boardingDay = startDay;
    let flightDay = startDay;
    let disembarkingDay = startDay;
    
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        boardingDay = getNextDay(startDay);
    }
    if (timeToMinutes(flightEndTime) < timeToMinutes(flightStartTime)) {
        flightDay = getNextDay(startDay);
    }
    if (timeToMinutes(disembarkingStartTime) < timeToMinutes(startTime)) {
        disembarkingDay = getNextDay(startDay);
    }
    
    console.log('Calculated days:');
    console.log(`  Boarding day: ${boardingDay} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][boardingDay]})`);
    console.log(`  Flight day: ${flightDay} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][flightDay]})`);
    console.log(`  Disembarking day: ${disembarkingDay} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][disembarkingDay]})`);
    
    // Expected results
    console.log('Expected results:');
    console.log('  Boarding: Friday 22:45-23:00');
    console.log('  Flight: Friday 23:00-23:59 + Saturday 00:00-00:00');
    console.log('  Disembarking: Saturday 00:00-00:25');
    
    // Verify the fix
    if (boardingDay === 4 && flightDay === 4 && disembarkingDay === 5) {
        console.log('✅ OVERNIGHT FLIGHT DISPLAY FIX: PASSED');
        console.log('   Disembarking will now correctly show on Saturday only');
    } else {
        console.log('❌ OVERNIGHT FLIGHT DISPLAY FIX: FAILED');
        console.log('   Day calculations are incorrect');
    }
}

// Test function to verify overnight flight segment placement
function testOvernightFlightSegmentPlacement() {
    console.log('=== TESTING OVERNIGHT FLIGHT SEGMENT PLACEMENT ===');
    
    // Test case: Flight departing Friday 22:45, arriving Saturday 00:25
    const day = 4; // Friday
    const startTime = '22:45';
    const boardingTime = 15; // 15 minutes
    const flightDuration = '01:00'; // 1 hour
    const disembarkingTime = 25; // 25 minutes
    
    // Calculate times
    const boardingStartTime = startTime;
    const boardingEndTime = addMinutesToTime(startTime, boardingTime);
    const flightStartTime = boardingEndTime;
    const flightEndTime = addMinutesToTime(startTime, boardingTime + timeToMinutes(flightDuration));
    const disembarkingStartTime = flightEndTime;
    const disembarkingEndTime = addMinutesToTime(startTime, boardingTime + timeToMinutes(flightDuration) + disembarkingTime);
    
    console.log('Flight times:');
    console.log(`  Boarding: ${boardingStartTime} - ${boardingEndTime}`);
    console.log(`  Flight: ${flightStartTime} - ${flightEndTime}`);
    console.log(`  Disembarking: ${disembarkingStartTime} - ${disembarkingEndTime}`);
    
    // Test the day calculation logic (same as in the actual code)
    const startDay = parseInt(day);
    let boardingDay = startDay;
    let flightDay = startDay;
    let disembarkingDay = startDay;
    
    // Check if boarding spans to next day
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        boardingDay = getNextDay(startDay);
    }
    
    // Check if flight spans to next day
    if (timeToMinutes(flightEndTime) < timeToMinutes(flightStartTime)) {
        flightDay = getNextDay(startDay);
    }
    
    // Check if disembarking occurs on next day (if disembarking spans overnight)
    const disembarkingEndTimeMinutes = timeToMinutes(disembarkingStartTime) + disembarkingTime;
    if (disembarkingEndTimeMinutes >= 1440) { // 1440 minutes = 24:00
        disembarkingDay = getNextDay(startDay);
    }
    
    console.log('Day calculations:');
    console.log(`  Boarding day: ${boardingDay} (start day: ${startDay})`);
    console.log(`  Flight day: ${flightDay} (start day: ${startDay})`);
    console.log(`  Disembarking day: ${disembarkingDay} (start day: ${startDay})`);
    
    // Expected results for this test case:
    // Boarding: Friday (same day) - 22:45 to 23:00
    // Flight: Saturday (spans to next day) - 23:00 to 00:25
    // Disembarking: Saturday (next day) - 00:25 to 00:50
    
    const expectedBoardingDay = 4; // Friday
    const expectedFlightDay = 5; // Saturday
    const expectedDisembarkingDay = 5; // Saturday
    
    if (boardingDay === expectedBoardingDay && 
        flightDay === expectedFlightDay && 
        disembarkingDay === expectedDisembarkingDay) {
        console.log('✅ OVERNIGHT FLIGHT SEGMENT PLACEMENT: PASSED');
        console.log('   All segments are placed on the correct days');
        console.log('   Boarding: Friday 22:45-23:00');
        console.log('   Flight: Saturday 23:00-00:25 (spans from Friday)');
        console.log('   Disembarking: Saturday 00:25-00:50');
    } else {
        console.log('❌ OVERNIGHT FLIGHT SEGMENT PLACEMENT: FAILED');
        console.log(`   Expected: Boarding=${expectedBoardingDay}, Flight=${expectedFlightDay}, Disembarking=${expectedDisembarkingDay}`);
        console.log(`   Actual: Boarding=${boardingDay}, Flight=${flightDay}, Disembarking=${disembarkingDay}`);
    }
    
    console.log('=== OVERNIGHT FLIGHT SEGMENT PLACEMENT TEST COMPLETE ===');
}

