// Function to verify all data is being exported
function verifyExportData() {
    console.log('=== VERIFYING EXPORT DATA ===');
    
    const dataTypes = [
        'savedAirports',
        'savedRoutes', 
        'savedAircraft',
        'savedRegisteredAircraft',
        'savedAirlines',
        'savedGates',
        'savedGateBlocks',
        'savedSchedule',
        'savedAircraftSchedules'
    ];
    
    console.log('📊 LOCAL STORAGE DATA:');
    dataTypes.forEach(dataType => {
        const data = localStorage.getItem(dataType);
        if (data) {
            try {
                const parsed = JSON.parse(data);
                if (Array.isArray(parsed)) {
                    console.log(`  ✅ ${dataType}: ${parsed.length} items`);
                } else if (typeof parsed === 'object') {
                    const keys = Object.keys(parsed);
                    console.log(`  ✅ ${dataType}: ${keys.length} entries (${keys.slice(0, 3).join(', ')}${keys.length > 3 ? '...' : ''})`);
                } else {
                    console.log(`  ✅ ${dataType}: ${typeof parsed}`);
                }
            } catch (e) {
                console.log(`  ❌ ${dataType}: Invalid JSON`);
            }
        } else {
            console.log(`  ⚠️  ${dataType}: No data`);
        }
    });
    
    console.log('📋 EXPORT DATA STRUCTURE:');
    const exportData = {
        version: "1.0",
        exportDate: new Date().toISOString(),
        data: {
            airports: JSON.parse(localStorage.getItem('savedAirports') || '[]'),
            routes: JSON.parse(localStorage.getItem('savedRoutes') || '[]'),
            aircraftTypes: JSON.parse(localStorage.getItem('savedAircraft') || '[]'),
            registeredAircraft: JSON.parse(localStorage.getItem('savedRegisteredAircraft') || '[]'),
            airlines: JSON.parse(localStorage.getItem('savedAirlines') || '[]'),
            gates: JSON.parse(localStorage.getItem('savedGates') || '{}'),
            gateBlocks: JSON.parse(localStorage.getItem('savedGateBlocks') || '{}'),
            schedule: JSON.parse(localStorage.getItem('savedSchedule') || '[]'),
            aircraftSchedules: JSON.parse(localStorage.getItem('savedAircraftSchedules') || '{}')
        }
    };
    
    Object.keys(exportData.data).forEach(key => {
        const data = exportData.data[key];
        if (Array.isArray(data)) {
            console.log(`  ✅ ${key}: ${data.length} items`);
        } else if (typeof data === 'object') {
            const keys = Object.keys(data);
            console.log(`  ✅ ${key}: ${keys.length} entries`);
        }
    });
    
    console.log('=== EXPORT DATA VERIFICATION COMPLETE ===');
}

// Function to clean up duplicate route lines
function cleanupDuplicateRouteLines() {
    console.log('=== CLEANING UP DUPLICATE ROUTE LINES ===');
    
    // Remove all existing route lines from map
    routeLines.forEach(line => {
        if (line) {
            map.removeLayer(line);
        }
    });
    
    // Clear the route lines array
    routeLines.length = 0;
    
    // Redraw all routes with consistent styling
    routesList.forEach((route, index) => {
        drawRouteLine(route, index);
    });
    
    console.log(`✅ Cleaned up and redrew ${routesList.length} route lines`);
    console.log('=== ROUTE LINES CLEANUP COMPLETE ===');
}




function populateAircraftTypeDropdown() {
    const buildLabel = (a) => {
        const cap = a.capacity != null && Number.isFinite(Number(a.capacity)) ? Number(a.capacity) : null;
        const base = `${a.model} (${a.speed} km/h, ${a.range} km)`;
        return cap != null ? `${base}, ${cap} pax` : base;
    };

    const flightSelect = document.getElementById('aircraftType');
    if (flightSelect) {
        flightSelect.innerHTML = '<option value="">Select aircraft type</option>';
        aircraftList.forEach(aircraft => {
            const option = document.createElement('option');
            option.value = aircraft.model;
            option.textContent = buildLabel(aircraft);
            flightSelect.appendChild(option);
        });
    }

    const modalSelect = document.getElementById('aircraftTypeSelect');
    if (!modalSelect) return;

    modalSelect.innerHTML = '<option value="">Select Aircraft Type</option>';
    aircraftList.forEach(aircraft => {
        const option = document.createElement('option');
        option.value = aircraft.model;
        option.textContent = buildLabel(aircraft);
        modalSelect.appendChild(option);
    });

    if (aircraftList.length === 0) {
        const option = document.createElement('option');
        option.value = '';
        option.textContent = 'No aircraft types available - Add aircraft types first';
        option.disabled = true;
        modalSelect.appendChild(option);
    }
}

// Routes management functions
function loadSavedRoutes() {
    console.log('📂 Loading saved routes from localStorage...');
    const savedRoutes = localStorage.getItem('savedRoutes');
    if (savedRoutes) {
        try {
            const routes = JSON.parse(savedRoutes);
            console.log('✅ Loaded', routes.length, 'routes from localStorage');
            routesList.length = 0; // Clear array
            
            // Clear existing route lines from map and array
            routeLines.forEach(line => {
                if (line) {
                    map.removeLayer(line);
                }
            });
            routeLines.length = 0; // Clear route lines array
            
            routesList.push(...routes);
            console.log('✅ Routes loaded into routesList. Total routes:', routesList.length);
            
            // Update route data to match current airport names (in case airport names were updated)
            console.log('🔄 Updating route data for new airport names...');
            updateRouteDataForNewAirportNames();
            
            // Fix specific issue: CCS routes using wrong airport names
            console.log('🔧 Fixing CCS routes to use correct airport names...');
            routesList.forEach((route, index) => {
                const departureCode = getRouteAirportCode(route, 'departure');
                const arrivalCode = getRouteAirportCode(route, 'arrival');
                
                // Fix CCS routes that are using the wrong airport name
                if (arrivalCode === 'CCS' && route.arrival.includes('(CO)')) {
                    console.log(`Fixing CCS route: ${route.name}`);
                    route.arrival = 'Simón Bolívar International Airport (VZ)';
                    console.log(`  Updated arrival: ${route.arrival}`);
                }
                if (departureCode === 'CCS' && route.departure.includes('(CO)')) {
                    console.log(`Fixing CCS route: ${route.name}`);
                    route.departure = 'Simón Bolívar International Airport (VZ)';
                    console.log(`  Updated departure: ${route.departure}`);
                }
            });
            
            // Force-update route coordinates to ensure correct airport connections
            console.log('🔧 Force-updating route coordinates for correct airport connections...');
            routesList.forEach((route, index) => {
                // Get the correct airport codes
                const departureCode = getRouteAirportCode(route, 'departure');
                const arrivalCode = getRouteAirportCode(route, 'arrival');
                
                // Find the correct airport markers by code
                const departureMarker = userMarkers.find(marker => 
                    marker.airportData && marker.airportData.code === departureCode
                );
                const arrivalMarker = userMarkers.find(marker => 
                    marker.airportData && marker.airportData.code === arrivalCode
                );
                
                if (departureMarker && arrivalMarker) {
                    // Update the route coordinates to use the correct airport locations
                    route.departureCoords = {
                        lat: departureMarker.getLatLng().lat,
                        lng: departureMarker.getLatLng().lng
                    };
                    route.arrivalCoords = {
                        lat: arrivalMarker.getLatLng().lat,
                        lng: arrivalMarker.getLatLng().lng
                    };
                    console.log(`✅ Fixed coordinates for ${departureCode} → ${arrivalCode}`);
                }
            });
            console.log('✅ Route coordinates force-updated');
            
            routesList.forEach(route => applyDemandModelToDirectionalRoute(route));
            
            // Save the updated routes to localStorage
            saveRoutes();
            console.log('✅ Updated routes saved to localStorage');
            
            // Redraw all route lines (but don't show them if routes are hidden)
            routes.forEach((route, index) => {
                drawRouteLine(route, index);
            });
            console.log('✅ Route lines redrawn on map');
            
            // Auto-fix any route issues that may have occurred during loading
            setTimeout(() => {
                autoFixRouteIssues();
            }, 1000); // Small delay to ensure all routes are drawn first
            
        } catch (error) {
            console.error('❌ Error parsing saved routes:', error);
        }
    } else {
        console.log('ℹ️ No saved routes found in localStorage');
    }
}

