// Flight Search Functions
function populateFlightSearchAirports() {
    console.log('🔄 Setting up flight search airport inputs');
    
    const departureInput = document.getElementById('departureAirportSearch');
    const arrivalInput = document.getElementById('arrivalAirportSearch');
    
    if (!departureInput || !arrivalInput) {
        console.log('❌ Flight search airport inputs not found');
        return;
    }
    
    // Set up search functionality for departure airport
    departureInput.addEventListener('input', function() {
        const searchTerm = this.value.toLowerCase();
        if (searchTerm.length >= 1) {
            searchAirportsForFlight(searchTerm, 'departure');
        } else {
            hideSearchResults('departure');
        }
    });
    
    // Set up search functionality for arrival airport
    arrivalInput.addEventListener('input', function() {
        const searchTerm = this.value.toLowerCase();
        if (searchTerm.length >= 1) {
            searchAirportsForFlight(searchTerm, 'arrival');
        } else {
            hideSearchResults('arrival');
        }
    });
    
    // Hide search results when clicking outside
    document.addEventListener('click', function(e) {
        if (!e.target.closest('.search-container')) {
            hideSearchResults('departure');
            hideSearchResults('arrival');
        }
    });
    
    console.log('✅ Flight search airport inputs set up');
}

function searchAirportsForFlight(searchTerm, type) {
    console.log(`🔍 Searching airports for "${searchTerm}" (${type})`);
    
    const resultsContainer = document.getElementById(`${type}SearchResults`);
    if (!resultsContainer) {
        console.log('❌ Search results container not found');
        return;
    }
    
    // Create array of airport data for searching
    const airportData = userMarkers.map((marker, index) => {
        // Use airportData if available, otherwise fall back to marker properties
        let airportName, airportCode, city, country;
        
        if (marker.airportData) {
            airportName = marker.airportData.name || `Airport ${index + 1}`;
            airportCode = marker.airportData.code || `AP${index + 1}`;
            city = marker.airportData.city || 'Unknown City';
            country = marker.airportData.country || 'Unknown Country';
        } else {
            // Fallback to marker properties (for older data)
            airportName = marker.airportName || `Airport ${index + 1}`;
            airportCode = marker.airportCode || `AP${index + 1}`;
            city = marker.city || 'Unknown City';
            country = marker.country || 'Unknown Country';
        }
        
        return {
            index: index,
            airportName: airportName,
            airportCode: airportCode,
            city: city,
            country: country,
            searchText: `${airportName} ${airportCode} ${city} ${country}`.toLowerCase()
        };
    });
    
    // Filter airports based on search term
    const filteredAirports = airportData.filter(airport => {
        return airport.searchText.includes(searchTerm) ||
               airport.airportCode.toLowerCase().includes(searchTerm) ||
               airport.city.toLowerCase().includes(searchTerm) ||
               airport.airportName.toLowerCase().includes(searchTerm);
    });
    
    // Sort by relevance (exact matches first, then by airport code)
    filteredAirports.sort((a, b) => {
        // Exact airport code match gets highest priority
        if (a.airportCode.toLowerCase() === searchTerm) return -1;
        if (b.airportCode.toLowerCase() === searchTerm) return 1;
        
        // Then by airport code alphabetically
        return a.airportCode.localeCompare(b.airportCode);
    });
    
    // Display results
    if (filteredAirports.length === 0) {
        resultsContainer.innerHTML = '<div class="search-result-item">No airports found</div>';
    } else {
        let resultsHTML = '';
        filteredAirports.slice(0, 10).forEach(airport => { // Limit to 10 results
            resultsHTML += `
                <div class="search-result-item" onclick="selectAirport(${airport.index}, '${type}')">
                    <div class="search-result-info">
                        <div class="search-result-name">${airport.airportName}</div>
                        <div class="search-result-details">${airport.city}, ${airport.country}</div>
                    </div>
                    <div class="search-result-code">${airport.airportCode}</div>
                </div>
            `;
        });
        resultsContainer.innerHTML = resultsHTML;
    }
    
    resultsContainer.style.display = 'block';
}

function selectAirport(airportIndex, type) {
    console.log(`✈️ Selected airport ${airportIndex} for ${type}`);
    
    const marker = userMarkers[airportIndex];
    if (!marker) {
        console.log('❌ Airport marker not found');
        return;
    }
    
    // Get airport data
    let airportName, airportCode, city, country;
    
    if (marker.airportData) {
        airportName = marker.airportData.name || `Airport ${airportIndex + 1}`;
        airportCode = marker.airportData.code || `AP${airportIndex + 1}`;
        city = marker.airportData.city || 'Unknown City';
        country = marker.airportData.country || 'Unknown Country';
    } else {
        airportName = marker.airportName || `Airport ${airportIndex + 1}`;
        airportCode = marker.airportCode || `AP${airportIndex + 1}`;
        city = marker.city || 'Unknown City';
        country = marker.country || 'Unknown Country';
    }
    
    // Set the input value
    const input = document.getElementById(`${type}AirportSearch`);
    if (input) {
        input.value = `${airportName} (${airportCode}) - ${city}, ${country}`;
        input.setAttribute('data-airport-index', airportIndex);
    }
    
    // Hide search results
    hideSearchResults(type);
}

