function findFlightsForRoute(departureIndex, arrivalIndex) {
    const flights = [];
    
    console.log(`🔍 Searching for flights from airport ${departureIndex} to ${arrivalIndex} for all days`);
    console.log(`🔍 Available aircraft schedules:`, Object.keys(aircraftSchedules));
    
    // Get departure and arrival airport names for route matching
    const departureAirport = userMarkers[departureIndex];
    const arrivalAirport = userMarkers[arrivalIndex];
    
    let departureAirportName, arrivalAirportName;
    
    if (departureAirport.airportData) {
        departureAirportName = departureAirport.airportData.name;
    } else {
        departureAirportName = departureAirport.airportName || `Airport ${departureIndex + 1}`;
    }
    
    if (arrivalAirport.airportData) {
        arrivalAirportName = arrivalAirport.airportData.name;
    } else {
        arrivalAirportName = arrivalAirport.airportName || `Airport ${arrivalIndex + 1}`;
    }
    
    console.log(`🔍 Looking for flights from "${departureAirportName}" to "${arrivalAirportName}"`);
    
    // Search through all aircraft schedules
    Object.keys(aircraftSchedules).forEach(aircraftRegistration => {
        const schedule = aircraftSchedules[aircraftRegistration];
        console.log(`🔍 Checking schedule for aircraft ${aircraftRegistration}:`, schedule.length, 'items');
        
        schedule.forEach(scheduleItem => {
            // Include cancelled flights in search results (they will be filtered by the toggle if needed)
            // Check if this is a flight (any day) and it's the main flight phase (not boarding/disembarking)
            if (scheduleItem.type === 'flight' && scheduleItem.phase === 'flight') {
                console.log(`🔍 Found flight item:`, scheduleItem);
                
                // Check if the route matches
                const routeMatches = (scheduleItem.route && 
                    (scheduleItem.route.includes(`${departureAirportName} → ${arrivalAirportName}`) ||
                     scheduleItem.route.includes(`${departureAirportName} - ${arrivalAirportName}`) ||
                     scheduleItem.route.includes(`${departureAirportName} to ${arrivalAirportName}`)));
                
                if (routeMatches) {
                    console.log(`✅ Found matching flight:`, scheduleItem);
                    
                    // Find the aircraft in airlinesList to get airline info
                    let aircraft = null;
                    let airline = null;
                    
                    // Search through all airlines to find the aircraft
                    for (const airlineItem of airlinesList) {
                        if (airlineItem.aircraft) {
                            const foundAircraft = airlineItem.aircraft.find(ac => ac.registration === aircraftRegistration);
                            if (foundAircraft) {
                                aircraft = foundAircraft;
                                airline = airlineItem;
                                break;
                            }
                        }
                    }
                    
                    console.log(`🔍 Looking for aircraft ${aircraftRegistration} in airlinesList:`, aircraft);
                    console.log(`🔍 Found airline:`, airline);
                    console.log(`🔍 Available airlines:`, airlinesList.map(a => a.name));
                    
                    // Get airline info
                    const airlineName = airline?.name || 'Unknown Airline';
                    const airlineCode = airline?.code || 'UNK';
                    const aircraftType = aircraft?.aircraftType || 'Unknown Aircraft';
                    
                    console.log(`🔍 Extracted airline info:`, { airlineName, airlineCode, aircraftType });
                    
                    // Calculate flight duration and arrival time
                    const departureTime = scheduleItem.startTime;
                    const flightDuration = scheduleItem.duration || '02:00'; // Default 2 hours
                    const arrivalTime = calculateArrivalTime(departureTime, flightDuration);
                    
                    // Generate flight number
                    const flightNumber = scheduleItem.flightNumber || `${airlineCode}${Math.floor(Math.random() * 9000) + 1000}`;
                    
                    // Get airport codes for the route
                    let departureCode = '';
                    let arrivalCode = '';
                    
                    userMarkers.forEach(marker => {
                        if (marker.airportData) {
                            if (marker.airportData.name === departureAirportName) {
                                departureCode = marker.airportData.code;
                            }
                            if (marker.airportData.name === arrivalAirportName) {
                                arrivalCode = marker.airportData.code;
                            }
                        }
                    });
                    
                    flights.push({
                        flightNumber: flightNumber,
                        airline: airlineName,
                        airlineCode: airlineCode,
                        aircraftType: aircraftType,
                        departureTime: departureTime,
                        arrivalTime: arrivalTime,
                        duration: flightDuration,
                        departureGate: scheduleItem.departureGate || 'TBD',
                        arrivalGate: scheduleItem.arrivalGate || 'TBD',
                        aircraftRegistration: aircraftRegistration,
                        scheduleItem: scheduleItem,
                        cancelled: scheduleItem.cancelled || false,
                        day: scheduleItem.day, // Include day for grouping
                        departureAirport: departureAirportName,
                        arrivalAirport: arrivalAirportName,
                        departureCode: departureCode,
                        arrivalCode: arrivalCode
                    });
                }
            }
        });
    });
    
    console.log(`🔍 Found ${flights.length} flights for this route`);
    
    // No sample flights - only show real scheduled flights
    
    // Sort flights by departure time
    flights.sort((a, b) => a.departureTime.localeCompare(b.departureTime));
    
    return flights;
}

function calculateArrivalTime(departureTime, duration) {
    const [depHours, depMinutes] = departureTime.split(':').map(Number);
    const [durHours, durMinutes] = duration.split(':').map(Number);
    
    let arrivalMinutes = depMinutes + durMinutes;
    let arrivalHours = depHours + durHours;
    
    if (arrivalMinutes >= 60) {
        arrivalMinutes -= 60;
        arrivalHours += 1;
    }
    
    if (arrivalHours >= 24) {
        arrivalHours -= 24;
    }
    
    return `${arrivalHours.toString().padStart(2, '0')}:${arrivalMinutes.toString().padStart(2, '0')}`;
}

// Helper function to convert UTC time string (HH:MM) to local time string (HH:MM)
function convertUTCToLocalTime(utcTimeString, airportName) {
    if (!utcTimeString || !airportName) {
        return utcTimeString;
    }
    
    const timezoneData = getAirportTimezoneData(airportName);
    if (!timezoneData || !timezoneData.timeDifference) {
        return utcTimeString; // Return original if no timezone data
    }
    
    // Parse UTC time
    const [hours, minutes] = utcTimeString.split(':').map(Number);
    if (isNaN(hours) || isNaN(minutes)) {
        return utcTimeString; // Return original if invalid time format
    }
    
    // Get time difference (e.g., "+5", "-3", "5", "-3")
    const timeDiffStr = timezoneData.timeDifference.trim();
    if (!timeDiffStr) {
        return utcTimeString; // Return original if no time difference
    }
    
    // Parse the time difference
    let offsetHours = 0;
    if (timeDiffStr.startsWith('+')) {
        offsetHours = parseInt(timeDiffStr.substring(1)) || 0;
    } else if (timeDiffStr.startsWith('-')) {
        offsetHours = -parseInt(timeDiffStr.substring(1)) || 0;
    } else {
        // Assume positive if no sign
        offsetHours = parseInt(timeDiffStr) || 0;
    }
    
    // Calculate local time
    let localHours = hours + offsetHours;
    let localMinutes = minutes;
    
    // Handle day rollover
    if (localHours < 0) {
        localHours += 24;
    } else if (localHours >= 24) {
        localHours -= 24;
    }
    
    return `${localHours.toString().padStart(2, '0')}:${localMinutes.toString().padStart(2, '0')}`;
}

// Helper function to convert UTC day/time (Mon=0..Sun=6) to local day/time for an airport
function convertUTCDayTimeToLocal(day, utcTimeString, airportName) {
    const fallbackDay = Number.isInteger(day) ? day : 0;
    const fallback = { day: fallbackDay, time: utcTimeString };
    if (!utcTimeString || !airportName) return fallback;

    const timezoneData = getAirportTimezoneData(airportName);
    if (!timezoneData || !timezoneData.timeDifference) return fallback;

    const [hours, minutes] = String(utcTimeString).split(':').map(Number);
    if (isNaN(hours) || isNaN(minutes)) return fallback;

    const timeDiffStr = String(timezoneData.timeDifference).trim();
    if (!timeDiffStr) return fallback;

    let offsetHours = 0;
    if (timeDiffStr.startsWith('+')) {
        offsetHours = parseInt(timeDiffStr.substring(1), 10) || 0;
    } else if (timeDiffStr.startsWith('-')) {
        offsetHours = -(parseInt(timeDiffStr.substring(1), 10) || 0);
    } else {
        offsetHours = parseInt(timeDiffStr, 10) || 0;
    }

    let totalMinutes = (hours * 60) + minutes + (offsetHours * 60);
    let dayOffset = 0;

    while (totalMinutes < 0) {
        totalMinutes += 24 * 60;
        dayOffset -= 1;
    }
    while (totalMinutes >= 24 * 60) {
        totalMinutes -= 24 * 60;
        dayOffset += 1;
    }

    const localHours = Math.floor(totalMinutes / 60);
    const localMinutes = totalMinutes % 60;
    const localDay = (fallbackDay + dayOffset + 7) % 7;

    return {
        day: localDay,
        time: `${String(localHours).padStart(2, '0')}:${String(localMinutes).padStart(2, '0')}`
    };
}

// Function to refresh flight search results when toggle changes
function refreshFlightSearchResults() {
    const showCancelledCheckbox = document.getElementById('showCancelledFlights');
    const showCancelled = showCancelledCheckbox ? showCancelledCheckbox.checked : false;
    
    if (showCancelled) {
        // If showing cancelled flights, refresh that view
        showAllCancelledFlights();
    } else {
        // Otherwise, refresh regular search results if there's an active search
        const departureInput = document.getElementById('departureAirportSearch');
        const arrivalInput = document.getElementById('arrivalAirportSearch');
        
        if (departureInput && arrivalInput && departureInput.value && arrivalInput.value) {
            searchFlights();
        }
    }
}

function calculateFlightPrice(departureIndex, arrivalIndex, aircraftType) {
    // Simple price calculation based on distance and aircraft type
    const departureMarker = userMarkers[departureIndex];
    const arrivalMarker = userMarkers[arrivalIndex];
    
    // Calculate distance (simplified)
    const lat1 = departureMarker.getLatLng().lat;
    const lon1 = departureMarker.getLatLng().lng;
    const lat2 = arrivalMarker.getLatLng().lat;
    const lon2 = arrivalMarker.getLatLng().lng;
    
    const distance = Math.sqrt(Math.pow(lat2 - lat1, 2) + Math.pow(lon2 - lon1, 2)) * 111; // Rough km conversion
    
    // Base price per km
    let basePrice = 0.5;
    
    // Adjust for aircraft type
    switch (aircraftType) {
        case 'Boeing 737':
            basePrice = 0.4;
            break;
        case 'Airbus A320':
            basePrice = 0.45;
            break;
        case 'Boeing 777':
            basePrice = 0.6;
            break;
        case 'Airbus A350':
            basePrice = 0.65;
            break;
        default:
            basePrice = 0.5;
    }
    
    const price = Math.round(distance * basePrice);
    return Math.max(price, 50); // Minimum price of $50
}

function displayFlightResults(flights, departureAirport, arrivalAirport, showBothDirections = false) {
    console.log('📋 Displaying flight results:', flights.length, 'flights found');
    
    const resultsContainer = document.getElementById('flightSearchResults');
    const resultsList = document.getElementById('flightResultsList');
    
    if (!resultsContainer || !resultsList) {
        console.log('❌ Flight results elements not found');
        return;
    }
    
    // Show results container
    resultsContainer.style.display = 'block';
    
    if (flights.length === 0) {
        const routeText = showBothDirections 
            ? `between ${departureAirport.airportCode} and ${arrivalAirport.airportCode}`
            : `from ${departureAirport.airportCode} to ${arrivalAirport.airportCode}`;
        resultsList.innerHTML = `
            <div class="no-flights-found">
                <h5>No flights found</h5>
                <p>No flights available ${routeText}.</p>
                <p>Try selecting a different route.</p>
            </div>
        `;
        return;
    }
    
    // Get the show local times checkbox state
    const showLocalTimesCheckbox = document.getElementById('showLocalTimes');
    const showLocalTimes = showLocalTimesCheckbox ? showLocalTimesCheckbox.checked : false;

    // Prepare flights with display day/time context
    const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    const preparedFlights = flights.map(flight => {
        let flightDepartureAirportName;
        let flightArrivalAirportName;

        if (showBothDirections && flight.departureAirport && flight.arrivalAirport) {
            flightDepartureAirportName = flight.departureAirport;
            flightArrivalAirportName = flight.arrivalAirport;
        } else {
            flightDepartureAirportName = departureAirport.airportName;
            flightArrivalAirportName = arrivalAirport.airportName;
        }

        const utcDay = flight.day !== undefined ? flight.day : 0;
        const localDeparture = convertUTCDayTimeToLocal(utcDay, flight.departureTime, flightDepartureAirportName);

        return {
            ...flight,
            _departureAirportName: flightDepartureAirportName,
            _arrivalAirportName: flightArrivalAirportName,
            _displayDay: showLocalTimes ? localDeparture.day : utcDay,
            _displaySortTime: showLocalTimes ? localDeparture.time : flight.departureTime
        };
    });

    // Group flights by display day (UTC day or local departure day based on toggle)
    const flightsByDay = {};
    
    preparedFlights.forEach(flight => {
        const day = flight._displayDay;
        if (!flightsByDay[day]) {
            flightsByDay[day] = [];
        }
        flightsByDay[day].push(flight);
    });
    
    // Sort flights within each day by departure time
    Object.keys(flightsByDay).forEach(day => {
        flightsByDay[day].sort((a, b) => {
            const timeA = (a._displaySortTime || a.departureTime).split(':').map(Number);
            const timeB = (b._displaySortTime || b.departureTime).split(':').map(Number);
            return (timeA[0] * 60 + timeA[1]) - (timeB[0] * 60 + timeB[1]);
        });
    });
    
    let resultsHTML = '';
    
    // Get the show cancelled checkbox state
    const showCancelledCheckbox = document.getElementById('showCancelledFlights');
    const showCancelled = showCancelledCheckbox ? showCancelledCheckbox.checked : false;
    
    // Display flights grouped by day
    Object.keys(flightsByDay).sort((a, b) => parseInt(a) - parseInt(b)).forEach(day => {
        const dayFlights = flightsByDay[day];
        const dayName = dayNames[parseInt(day)];
        
        resultsHTML += `
            <div class="flight-results-day">
                <div class="flight-results-day-label">${dayName}</div>
                <div class="flight-results-head" aria-hidden="true">
                    <span>Flight</span>
                    <span>Route</span>
                    <span>Depart</span>
                    <span>Arrive</span>
                    <span>Aircraft</span>
                    <span class="flight-results-h-act"></span>
                </div>
        `;
        
        dayFlights.forEach((flight) => {
            // Get airline logo using the existing function
            const airlineLogo = generateAirlineLogoHTML(flight.airline, flight.flightNumber, '26px');
            const isCancelled = flight.cancelled || false;
            
            // Always show flights in search results (cancelled or not)
            // The toggle only affects the "Show All Cancelled Flights" view, not regular search results
            
            const cancelledStyle = isCancelled ? 'opacity: 0.5; text-decoration: line-through;' : '';
            
            // Determine route display - check if this is a return flight
            let routeDisplay;
            let flightDepartureAirportName = flight._departureAirportName;
            let flightArrivalAirportName = flight._arrivalAirportName;
            
            if (showBothDirections && flight.departureAirport && flight.arrivalAirport) {
                // Get airport codes for this flight
                let flightDepartureCode = flight.departureCode || '';
                let flightArrivalCode = flight.arrivalCode || '';
                
                // If codes not available, try to find them from airport names
                if (!flightDepartureCode || !flightArrivalCode) {
                    userMarkers.forEach(marker => {
                        if (marker.airportData) {
                            if (marker.airportData.name === flight.departureAirport && !flightDepartureCode) {
                                flightDepartureCode = marker.airportData.code;
                            }
                            if (marker.airportData.name === flight.arrivalAirport && !flightArrivalCode) {
                                flightArrivalCode = marker.airportData.code;
                            }
                        }
                    });
                }
                
                // Display the route with the actual codes
                routeDisplay = `${flightDepartureCode || flight.departureAirport} → ${flightArrivalCode || flight.arrivalAirport}`;
                flightDepartureAirportName = flightDepartureAirportName || flight.departureAirport;
                flightArrivalAirportName = flightArrivalAirportName || flight.arrivalAirport;
            } else {
                routeDisplay = `${departureAirport.airportCode} → ${arrivalAirport.airportCode}`;
                flightDepartureAirportName = flightDepartureAirportName || departureAirport.airportName;
                flightArrivalAirportName = flightArrivalAirportName || arrivalAirport.airportName;
            }
            
            // Convert times to local if toggle is enabled
            let displayDepartureTime = flight.departureTime;
            let displayArrivalTime = flight.arrivalTime;
            
            if (showLocalTimes) {
                displayDepartureTime = convertUTCToLocalTime(flight.departureTime, flightDepartureAirportName);
                displayArrivalTime = convertUTCToLocalTime(flight.arrivalTime, flightArrivalAirportName);
            }
            
            resultsHTML += `
                <div class="flight-result-row" data-cancelled="${isCancelled}" style="${cancelledStyle}" onclick="selectFlight('${flight.flightNumber}')">
                    <div class="flight-result-cell flight-result-cell--flight">
                        <span class="flight-result-logo">${airlineLogo}</span>
                        <span class="flight-result-num">${flight.flightNumber}</span>
                    </div>
                    <div class="flight-result-cell flight-result-cell--route" title="${routeDisplay}">${routeDisplay}</div>
                    <div class="flight-result-cell flight-result-cell--time">${displayDepartureTime}</div>
                    <div class="flight-result-cell flight-result-cell--time">${displayArrivalTime}</div>
                    <div class="flight-result-cell flight-result-cell--meta">
                        <span class="flight-result-aircraft">${flight.aircraftType}</span>
                        <span class="flight-result-airline">${flight.airline}</span>
                        ${isCancelled ? '<span class="flight-result-status">Cancelled</span>' : ''}
                    </div>
                    <div class="flight-result-cell flight-result-cell--act">
                        <button type="button" class="flight-result-btn ${isCancelled ? 'flight-result-btn--restore' : 'flight-result-btn--cancel'}" onclick="event.stopPropagation(); toggleFlightCancellation('${flight.flightNumber}', '${flight.aircraftRegistration}');">
                            ${isCancelled ? 'Restore' : 'Cancel'}
                        </button>
                    </div>
                </div>
            `;
        });
        
        resultsHTML += `</div>`;
    });
    
    resultsList.innerHTML = resultsHTML;
}

function selectFlight(flightNumber) {
    console.log('✈️ Flight selected:', flightNumber);
    alert(`Flight ${flightNumber} selected! This would typically redirect to booking or show more details.`);
}

// Toggle flight cancellation status
function toggleFlightCancellation(flightNumber, aircraftRegistration) {
    console.log(`🔄 Toggling cancellation for flight ${flightNumber} on aircraft ${aircraftRegistration}`);
    
    // Find the schedule item for this flight
    const schedule = aircraftSchedules[aircraftRegistration];
    if (!schedule) {
        console.error(`Schedule not found for aircraft ${aircraftRegistration}`);
        return;
    }
    
    // Find all schedule items for this flight (boarding, flight, disembarking)
    const flightItems = schedule.filter(item => item.flightNumber === flightNumber);
    
    if (flightItems.length === 0) {
        console.error(`Flight ${flightNumber} not found in schedule`);
        showNonBlockingNotification('❌ Flight not found in schedule', 'error');
        return;
    }
    
    // Toggle cancelled status on all items for this flight
    const isCurrentlyCancelled = flightItems[0].cancelled || false;
    const newCancelledStatus = !isCurrentlyCancelled;
    
    flightItems.forEach(item => {
        item.cancelled = newCancelledStatus;
    });
    
    // Save to localStorage
    saveAircraftSchedules();
    
    // Refresh display based on current view
    const showCancelledCheckbox = document.getElementById('showCancelledFlights');
    const showCancelled = showCancelledCheckbox ? showCancelledCheckbox.checked : false;
    
    if (showCancelled) {
        // If showing all cancelled flights, refresh that view
        showAllCancelledFlights();
    } else {
        // Otherwise, refresh the regular search results
        const departureInput = document.getElementById('departureAirportSearch');
        const arrivalInput = document.getElementById('arrivalAirportSearch');
        
        if (departureInput && arrivalInput && departureInput.value && arrivalInput.value) {
            // Re-run the search to refresh results with updated cancellation status
            searchFlights();
        }
    }
    
    // Update airport boards if they're open
    if (currentAirportBoard) {
        updateAirportBoard();
    }
    
    showNonBlockingNotification(
        newCancelledStatus ? `✅ Flight ${flightNumber} marked as cancelled` : `✅ Flight ${flightNumber} restored`,
        'success'
    );
}

// Toggle display of cancelled flights - show all cancelled flights when checked
function toggleCancelledFlightsDisplay() {
    const showCancelled = document.getElementById('showCancelledFlights').checked;
    
    if (showCancelled) {
        // Show all cancelled flights across all routes
        showAllCancelledFlights();
    } else {
        // If there's an active search, re-run it to show only non-cancelled flights
        const departureInput = document.getElementById('departureAirportSearch');
        const arrivalInput = document.getElementById('arrivalAirportSearch');
        
        if (departureInput && arrivalInput && departureInput.value && arrivalInput.value) {
            searchFlights();
        } else {
            // Hide the cancelled flights list
            const resultsContainer = document.getElementById('flightSearchResults');
            if (resultsContainer) {
                resultsContainer.style.display = 'none';
            }
        }
    }
}

// Function to show all cancelled flights across all routes
function showAllCancelledFlights() {
    console.log('📋 Showing all cancelled flights');
    
    const resultsContainer = document.getElementById('flightSearchResults');
    const resultsList = document.getElementById('flightResultsList');
    
    if (!resultsContainer || !resultsList) {
        console.log('❌ Flight results elements not found');
        return;
    }
    
    // Show results container
    resultsContainer.style.display = 'block';
    
    // Collect all cancelled flights from all aircraft schedules
    const cancelledFlights = [];
    const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    
    Object.keys(aircraftSchedules).forEach(aircraftRegistration => {
        const schedule = aircraftSchedules[aircraftRegistration];
        
        schedule.forEach(scheduleItem => {
            // Only get cancelled flight items
            if (scheduleItem.cancelled && scheduleItem.type === 'flight' && scheduleItem.phase === 'flight') {
                // Find the aircraft in airlinesList to get airline info
                let aircraft = null;
                let airline = null;
                
                for (const airlineItem of airlinesList) {
                    if (airlineItem.aircraft) {
                        const foundAircraft = airlineItem.aircraft.find(ac => ac.registration === aircraftRegistration);
                        if (foundAircraft) {
                            aircraft = foundAircraft;
                            airline = airlineItem;
                            break;
                        }
                    }
                }
                
                const airlineName = airline?.name || 'Unknown Airline';
                const airlineCode = airline?.code || 'UNK';
                const aircraftType = aircraft?.aircraftType || 'Unknown Aircraft';
                
                // Parse route to get airports
                const routeParts = scheduleItem.route.split(' → ');
                const departureAirportName = routeParts[0]?.trim() || '';
                const arrivalAirportName = routeParts[1]?.trim() || '';
                
                // Find airport codes
                let departureCode = '';
                let arrivalCode = '';
                
                userMarkers.forEach(marker => {
                    if (marker.airportData) {
                        if (marker.airportData.name === departureAirportName) {
                            departureCode = marker.airportData.code;
                        }
                        if (marker.airportData.name === arrivalAirportName) {
                            arrivalCode = marker.airportData.code;
                        }
                    }
                });
                
                const departureTime = scheduleItem.startTime;
                const flightDuration = scheduleItem.duration || '02:00';
                const arrivalTime = calculateArrivalTime(departureTime, flightDuration);
                const flightNumber = scheduleItem.flightNumber || `${airlineCode}${Math.floor(Math.random() * 9000) + 1000}`;
                
                cancelledFlights.push({
                    flightNumber: flightNumber,
                    airline: airlineName,
                    airlineCode: airlineCode,
                    aircraftType: aircraftType,
                    departureTime: departureTime,
                    arrivalTime: arrivalTime,
                    duration: flightDuration,
                    departureGate: scheduleItem.departureGate || 'TBD',
                    arrivalGate: scheduleItem.arrivalGate || 'TBD',
                    aircraftRegistration: aircraftRegistration,
                    scheduleItem: scheduleItem,
                    cancelled: true,
                    day: scheduleItem.day,
                    departureAirport: departureAirportName,
                    arrivalAirport: arrivalAirportName,
                    departureCode: departureCode,
                    arrivalCode: arrivalCode
                });
            }
        });
    });
    
    if (cancelledFlights.length === 0) {
        resultsList.innerHTML = `
            <div class="no-flights-found">
                <h5>No Cancelled Flights</h5>
                <p>There are currently no cancelled flights in the system.</p>
            </div>
        `;
        return;
    }
    
    // Get the show local times checkbox state
    const showLocalTimesCheckbox = document.getElementById('showLocalTimes');
    const showLocalTimes = showLocalTimesCheckbox ? showLocalTimesCheckbox.checked : false;

    // Group cancelled flights by display day (UTC day or local departure day based on toggle)
    const flightsByDay = {};
    
    cancelledFlights.forEach(flight => {
        const utcDay = flight.day !== undefined ? flight.day : 0;
        const localDeparture = convertUTCDayTimeToLocal(utcDay, flight.departureTime, flight.departureAirport);
        const day = showLocalTimes ? localDeparture.day : utcDay;
        if (!flightsByDay[day]) {
            flightsByDay[day] = [];
        }
        flightsByDay[day].push({
            ...flight,
            _displaySortTime: showLocalTimes ? localDeparture.time : flight.departureTime
        });
    });
    
    // Sort flights within each day by departure time
    Object.keys(flightsByDay).forEach(day => {
        flightsByDay[day].sort((a, b) => {
            const timeA = (a._displaySortTime || a.departureTime).split(':').map(Number);
            const timeB = (b._displaySortTime || b.departureTime).split(':').map(Number);
            return (timeA[0] * 60 + timeA[1]) - (timeB[0] * 60 + timeB[1]);
        });
    });
    
    let resultsHTML = '<div class="flight-results-banner-cancelled">All cancelled flights</div>';
    
    // Display flights grouped by day
    Object.keys(flightsByDay).sort((a, b) => parseInt(a) - parseInt(b)).forEach(day => {
        const dayFlights = flightsByDay[day];
        const dayName = dayNames[parseInt(day)];
        
        resultsHTML += `
            <div class="flight-results-day">
                <div class="flight-results-day-label">${dayName}</div>
                <div class="flight-results-head" aria-hidden="true">
                    <span>Flight</span>
                    <span>Route</span>
                    <span>Depart</span>
                    <span>Arrive</span>
                    <span>Aircraft</span>
                    <span class="flight-results-h-act"></span>
                </div>
        `;
        
        dayFlights.forEach((flight) => {
            // Get airline logo using the existing function
            const airlineLogo = generateAirlineLogoHTML(flight.airline, flight.flightNumber, '26px');
            const cancelledStyle = 'opacity: 0.5; text-decoration: line-through;';
            
            // Convert times to local if toggle is enabled
            let displayDepartureTime = flight.departureTime;
            let displayArrivalTime = flight.arrivalTime;
            
            if (showLocalTimes) {
                displayDepartureTime = convertUTCToLocalTime(flight.departureTime, flight.departureAirport);
                displayArrivalTime = convertUTCToLocalTime(flight.arrivalTime, flight.arrivalAirport);
            }
            
            const routeDisplayCancelled = `${flight.departureCode || flight.departureAirport} → ${flight.arrivalCode || flight.arrivalAirport}`;
            resultsHTML += `
                <div class="flight-result-row" data-cancelled="true" style="${cancelledStyle}" onclick="selectFlight('${flight.flightNumber}')">
                    <div class="flight-result-cell flight-result-cell--flight">
                        <span class="flight-result-logo">${airlineLogo}</span>
                        <span class="flight-result-num">${flight.flightNumber}</span>
                    </div>
                    <div class="flight-result-cell flight-result-cell--route" title="${routeDisplayCancelled}">${routeDisplayCancelled}</div>
                    <div class="flight-result-cell flight-result-cell--time">${displayDepartureTime}</div>
                    <div class="flight-result-cell flight-result-cell--time">${displayArrivalTime}</div>
                    <div class="flight-result-cell flight-result-cell--meta">
                        <span class="flight-result-aircraft">${flight.aircraftType}</span>
                        <span class="flight-result-airline">${flight.airline}</span>
                        <span class="flight-result-status">Cancelled</span>
                    </div>
                    <div class="flight-result-cell flight-result-cell--act">
                        <button type="button" class="flight-result-btn flight-result-btn--restore" onclick="event.stopPropagation(); toggleFlightCancellation('${flight.flightNumber}', '${flight.aircraftRegistration}');">
                            Restore
                        </button>
                    </div>
                </div>
            `;
        });
        
        resultsHTML += `</div>`;
    });
    
    resultsList.innerHTML = resultsHTML;
}

function clearFlightSearch() {
    console.log('🗑️ Clearing flight search');
    
    const departureInput = document.getElementById('departureAirportSearch');
    const arrivalInput = document.getElementById('arrivalAirportSearch');
    
    if (departureInput) {
        departureInput.value = '';
        departureInput.removeAttribute('data-airport-index');
    }
    
    if (arrivalInput) {
        arrivalInput.value = '';
        arrivalInput.removeAttribute('data-airport-index');
    }
    
    // Hide search results
    hideSearchResults('departure');
    hideSearchResults('arrival');
    
    const resultsContainer = document.getElementById('flightSearchResults');
    if (resultsContainer) {
        resultsContainer.style.display = 'none';
    }
}

// Function to focus on a specific route
function focusOnRoute(routeIndex) {
    console.log('🎯 Focusing on route:', routeIndex);
    
    const route = routesList[routeIndex];
    if (!route) {
        console.error('Route not found at index:', routeIndex);
        return;
    }
    
    // Clear any previous focus without restoring all routes
    clearRouteFocus(false);
    
    // Set the focused route
    focusedRouteIndex = routeIndex;
    
    // Hide all airports and routes first
    hideAllAirportsAndRoutes();
    
    // Show only the airports for this route
    showRouteAirports(route);
    
    // Show only this route line
    showFocusedRoute(route, routeIndex);
    
    // Fit map to show the route
    fitMapToRoute(route);
    
    // Update routes list display to show focus indicator
    updateRoutesList();
    
    console.log(`✅ Focused on route: ${route.departureCode || getAirportCode(route.departure)} → ${route.arrivalCode || getAirportCode(route.arrival)}`);
}

// Function to clear route focus
function clearRouteFocus(restoreAll = true) {
    if (focusedRouteIndex !== null) {
        console.log('🔄 Clearing route focus');
        
        // Only restore all airports and routes if requested (default true)
        if (restoreAll) {
            // Ensure airports are visible when clearing route focus
            airportsVisible = true;
            restoreAllAirportsAndRoutes();
        }
        
        // Clear focused route
        focusedRouteIndex = null;
        
        // Update routes list display to remove focus indicator
        updateRoutesList();
        
        console.log('✅ Route focus cleared');
    }
}

// Function to hide all airports and routes
function hideAllAirportsAndRoutes() {
    console.log('👁️ Hiding all airports and routes');
    
    // Hide all airports
    if (userMarkers) {
        userMarkers.forEach(function(marker, index) {
            marker.setOpacity(0);
            // Remove from map to ensure they're properly hidden
            if (markerClusterGroup) {
                if (markerClusterGroup.hasLayer(marker)) {
                    markerClusterGroup.removeLayer(marker);
                    console.log(`🚫 Removed marker ${index} from cluster group`);
                }
            } else {
                if (map.hasLayer(marker)) {
                    map.removeLayer(marker);
                    console.log(`🚫 Removed marker ${index} from map`);
                }
            }
        });
    }
    
    // Hide all route lines
    routeLines.forEach((line, index) => {
        if (line && typeof line.setOpacity === 'function') {
            line.setOpacity(0);
        }
    });
}

