// Keep route airport references in sync after editing an airport
function syncRoutesForAirportUpdate(previousAirportData, updatedAirportData) {
    if (!previousAirportData || !updatedAirportData || !Array.isArray(routesList) || routesList.length === 0) {
        return;
    }

    const previousCode = (previousAirportData.code || '').toUpperCase();
    const updatedCode = (updatedAirportData.code || '').toUpperCase();
    const previousName = previousAirportData.name || '';
    const updatedName = updatedAirportData.name || '';

    const updatedCoords = {
        lat: Number(updatedAirportData.lat),
        lng: Number(updatedAirportData.lng)
    };
    const hasValidUpdatedCoords = Number.isFinite(updatedCoords.lat) && Number.isFinite(updatedCoords.lng);

    let updatedRoutesCount = 0;

    routesList.forEach((route, index) => {
        if (!route) return;

        const departureCode = (getRouteAirportCode(route, 'departure') || '').toUpperCase();
        const arrivalCode = (getRouteAirportCode(route, 'arrival') || '').toUpperCase();

        const matchesDeparture =
            (previousCode && departureCode === previousCode) ||
            (previousName && route.departure === previousName);
        const matchesArrival =
            (previousCode && arrivalCode === previousCode) ||
            (previousName && route.arrival === previousName);

        if (!matchesDeparture && !matchesArrival) {
            return;
        }

        if (matchesDeparture) {
            route.departureCode = updatedCode;
            route.departure = updatedName;
            if (hasValidUpdatedCoords) {
                route.departureCoords = { ...updatedCoords };
            }
            if (Number.isFinite(updatedAirportData.population)) {
                route.departurePopulation = updatedAirportData.population;
            }
        }

        if (matchesArrival) {
            route.arrivalCode = updatedCode;
            route.arrival = updatedName;
            if (hasValidUpdatedCoords) {
                route.arrivalCoords = { ...updatedCoords };
            }
            if (Number.isFinite(updatedAirportData.population)) {
                route.arrivalPopulation = updatedAirportData.population;
            }
        }

        const resolvedDepartureCode = getRouteAirportCode(route, 'departure') || route.departureCode || '';
        const resolvedArrivalCode = getRouteAirportCode(route, 'arrival') || route.arrivalCode || '';
        route.name = `${resolvedDepartureCode} → ${resolvedArrivalCode}`;

        drawRouteLine(route, index);
        updatedRoutesCount++;
    });

    if (updatedRoutesCount > 0) {
        console.log(`✅ Updated ${updatedRoutesCount} routes after airport edit: ${previousCode || previousName} → ${updatedCode || updatedName}`);
        saveRoutes();
    }
}

// Function to force-update route coordinates using airport codes (more aggressive approach)
function forceUpdateRouteCoordinates() {
    console.log('🔧 Force-updating route coordinates using airport codes...');
    
    routesList.forEach((route, index) => {
        console.log(`Processing route ${index}: ${route.name || 'Unknown'}`);
        
        // Get the correct airport codes
        const departureCode = getRouteAirportCode(route, 'departure');
        const arrivalCode = getRouteAirportCode(route, 'arrival');
        
        console.log(`Route codes: ${departureCode} → ${arrivalCode}`);
        
        // Find the correct airport markers by code
        const departureMarker = userMarkers.find(marker => 
            marker.airportData && marker.airportData.code === departureCode
        );
        const arrivalMarker = userMarkers.find(marker => 
            marker.airportData && marker.airportData.code === arrivalCode
        );
        
        if (departureMarker && arrivalMarker) {
            const newDepartureCoords = {
                lat: departureMarker.getLatLng().lat,
                lng: departureMarker.getLatLng().lng
            };
            const newArrivalCoords = {
                lat: arrivalMarker.getLatLng().lat,
                lng: arrivalMarker.getLatLng().lng
            };
            
            console.log(`Updating coordinates for ${departureCode} → ${arrivalCode}:`);
            console.log(`  Departure: ${route.departureCoords?.lat}, ${route.departureCoords?.lng} → ${newDepartureCoords.lat}, ${newDepartureCoords.lng}`);
            console.log(`  Arrival: ${route.arrivalCoords?.lat}, ${route.arrivalCoords?.lng} → ${newArrivalCoords.lat}, ${newArrivalCoords.lng}`);
            
            // Update the route coordinates
            route.departureCoords = newDepartureCoords;
            route.arrivalCoords = newArrivalCoords;
            
            // Redraw the route line
            drawRouteLine(route, index);
        } else {
            console.warn(`Could not find markers for route ${departureCode} → ${arrivalCode}`);
            if (!departureMarker) console.warn(`  Missing departure marker for ${departureCode}`);
            if (!arrivalMarker) console.warn(`  Missing arrival marker for ${arrivalCode}`);
        }
    });
    
    // Save the updated routes
    saveRoutes();
    console.log('✅ Force-update complete');
}

