function drawRouteLine(route, index) {
    // Enhanced validation of route data
    if (!route) {
        console.error('Route is null or undefined at index:', index);
        return;
    }
    
    if (!route.departureCoords || !route.arrivalCoords) {
        console.error('Route missing coordinates at index:', index, 'Route:', route);
        return;
    }
    
    const departure = route.departureCoords;
    const arrival = route.arrivalCoords;
    
    // Enhanced coordinate validation
    if (typeof departure.lat !== 'number' || typeof departure.lng !== 'number' ||
        typeof arrival.lat !== 'number' || typeof arrival.lng !== 'number') {
        console.error('Invalid coordinate types for route at index:', index, 'Departure:', departure, 'Arrival:', arrival);
        return;
    }
    
    // Check for valid coordinate ranges
    if (departure.lat < -90 || departure.lat > 90 || departure.lng < -180 || departure.lng > 180 ||
        arrival.lat < -90 || arrival.lat > 90 || arrival.lng < -180 || arrival.lng > 180) {
        console.error('Coordinates out of valid range for route at index:', index, 'Departure:', departure, 'Arrival:', arrival);
        return;
    }
    
    // Check for identical coordinates (same airport)
    if (departure.lat === arrival.lat && departure.lng === arrival.lng) {
        console.warn('Route at index', index, 'has identical departure and arrival coordinates - skipping');
        return;
    }
    
    // Remove existing route line if it exists to prevent duplicates
    if (routeLines[index]) {
        try {
            map.removeLayer(routeLines[index]);
        } catch (error) {
            console.warn('Error removing existing route line:', error);
        }
        routeLines[index] = null;
    }
    
    const polylineLatLngs = getRoutePolylineLatLngs(route);
    if (polylineLatLngs.length < 2) {
        console.error('Could not build polyline for route at index:', index);
        return;
    }

    // Create polyline with consistent styling and error handling
    let polyline;
    try {
        polyline = L.polyline(polylineLatLngs, {
            color: '#4e8ca0',
            weight: 3,
            opacity: 0.8,
            dashArray: '8, 4', // Slightly longer dashes for better visibility
            lineCap: 'round',
            lineJoin: 'round'
        });
        
        // Validate the created polyline
        if (!polyline || typeof polyline.addTo !== 'function' || typeof polyline.setStyle !== 'function') {
            console.error('Failed to create valid polyline for route at index:', index);
            return;
        }
        
        console.log(`✅ Created valid polyline for route ${index}: ${getRouteAirportCode(route, 'departure')} → ${getRouteAirportCode(route, 'arrival')}`);
    } catch (error) {
        console.error('Error creating polyline for route at index:', index, 'Error:', error);
        return;
    }
    
    const isOnSchedulePage = isOnScheduleFlightPage();
    const previewSeats = isOnSchedulePage ? getScheduleFormPreviewAdditionalSeats(route) : null;
    polyline.bindPopup(`
        <div style="text-align: center; font-family: Arial, sans-serif;">
            ${buildRouteMapPopupHtml(route, isOnSchedulePage, previewSeats)}
        </div>
    `);
    
    const isRouteLineInteractable = () => {
        const lineIsVisibleOnMap = map.hasLayer(polyline) && Number(polyline.options?.opacity || 0) > 0;
        return polyline._isClickable !== false && lineIsVisibleOnMap;
    };

    // Add click event handler to prevent clicks when routes are hidden
    polyline.on('click', function(e) {
        if (!isRouteLineInteractable()) {
            console.log('🚫 Route click blocked - route line is not visible on map');
            e.originalEvent.stopPropagation();
            e.originalEvent.preventDefault();
            return false;
        }

        // Check if this specific route is clickable (for airport filtering)
        if (polyline._isClickable === false) {
            console.log('🚫 Route click blocked - route is filtered out');
            e.originalEvent.stopPropagation();
            e.originalEvent.preventDefault();
            return false;
        }
        
        console.log('✅ Route click allowed - focusing on route:', index);
        
        // Focus on the clicked route (same behavior as clicking Focus button in routes list)
        focusOnRoute(index);
        
        // Prevent event bubbling
        e.originalEvent.stopPropagation();
        e.originalEvent.preventDefault();
        return false;
    });

    // Prevent Leaflet popup auto-open for hidden/non-interactable route lines.
    polyline.on('popupopen', function() {
        if (!isRouteLineInteractable()) {
            polyline.closePopup();
        }
    });
    
    // Add to map and set visibility based on current state
    try {
        polyline.addTo(map);
        
        // Set initial visibility state with proper error handling
        if (!routesVisible) {
            polyline.setStyle({ opacity: 0 });
            polyline._isClickable = false;
            console.log(`Route ${index} added to map and hidden (routesVisible: false)`);
        } else {
            polyline._isClickable = true;
            console.log(`Route ${index} added to map and visible (routesVisible: true)`);
        }
        
        // Store reference to polyline only after successful addition to map
        routeLines[index] = polyline;
        
    } catch (error) {
        console.error('Error adding route line to map at index:', index, 'Error:', error);
        // Don't store the reference if adding to map failed
        routeLines[index] = null;
    }
}

function removeRouteLine(index) {
    if (routeLines[index]) {
        try {
            map.removeLayer(routeLines[index]);
            console.log(`Route line ${index} removed from map`);
        } catch (error) {
            console.warn(`Error removing route line ${index}:`, error);
        }
        routeLines[index] = null;
    }
}

// Function to clean up and validate all route lines
function cleanupRouteLines() {
    console.log('🧹 Cleaning up route lines...');
    let cleanedCount = 0;
    let validCount = 0;
    
    routeLines.forEach((polyline, index) => {
        if (polyline) {
            // Check if the polyline is still valid
            try {
                // Check if polyline has required methods and properties
                if (typeof polyline.setStyle === 'function' && 
                    typeof polyline.addTo === 'function' &&
                    polyline._latlngs && 
                    polyline._latlngs.length > 0) {
                    
                    // Additional check: verify the polyline has valid coordinates
                    const coords = polyline._latlngs[0];
                    if (coords && coords.length >= 2 && 
                        typeof coords[0].lat === 'number' && 
                        typeof coords[0].lng === 'number' &&
                        typeof coords[1].lat === 'number' && 
                        typeof coords[1].lng === 'number') {
                        validCount++;
                    } else {
                        // Polyline has invalid coordinates
                        routeLines[index] = null;
                        cleanedCount++;
                        console.log(`Cleaned up route line ${index} with invalid coordinates`);
                    }
                } else {
                    // Polyline is missing required methods or properties
                    routeLines[index] = null;
                    cleanedCount++;
                    console.log(`Cleaned up invalid route line ${index} - missing methods or properties`);
                }
            } catch (error) {
                // Polyline is completely invalid - clean it up
                routeLines[index] = null;
                cleanedCount++;
                console.log(`Cleaned up invalid route line ${index}:`, error);
            }
        }
    });
    
    console.log(`✅ Route cleanup complete: ${validCount} valid, ${cleanedCount} cleaned up`);
    return { valid: validCount, cleaned: cleanedCount };
}

// Function to refresh all routes and fix display issues
function refreshAllRoutes() {
    console.log('🔄 Refreshing all routes...');
    
    // First, clean up any invalid route lines
    cleanupRouteLines();
    
    // Store current visibility state
    const wasRoutesVisible = routesVisible;
    const wasFiltered = window.airportsFilteredForRoutes;
    const filteredAirport = window.filteredAirportName;
    
    // Remove all existing route lines from map
    routeLines.forEach((line, index) => {
        if (line) {
            try {
                map.removeLayer(line);
            } catch (error) {
                console.warn(`Error removing route line ${index} during refresh:`, error);
            }
        }
    });
    
    // Clear the route lines array
    routeLines.length = 0;
    
    // Redraw all routes
    routesList.forEach((route, index) => {
        drawRouteLine(route, index);
    });
    
    // Restore previous state
    if (wasFiltered && filteredAirport) {
        // Restore airport filtering
        showRoutesForAirport(filteredAirport, 0, 0); // Coordinates will be recalculated
    } else {
        // Apply the correct global visibility state
        routeLines.forEach((polyline, index) => {
            if (polyline && typeof polyline.setStyle === 'function') {
                try {
                    if (wasRoutesVisible) {
                        polyline.setStyle({
                            color: '#4e8ca0',
                            weight: 3,
                            opacity: 0.8,
                            dashArray: '8, 4',
                            lineCap: 'round',
                            lineJoin: 'round'
                        });
                        polyline._isClickable = true;
                    } else {
                        polyline.setStyle({ opacity: 0 });
                        polyline._isClickable = false;
                    }
                } catch (error) {
                    console.warn(`Error updating route line ${index} during refresh:`, error);
                }
            }
        });
    }
    
    // Update the routes button to reflect current state
    const toggleRoutesBtn = document.getElementById('toggleRoutes');
    if (toggleRoutesBtn) {
        if (routesVisible) {
            toggleRoutesBtn.textContent = '🗺️ Hide Routes';
            toggleRoutesBtn.disabled = false;
        } else {
            toggleRoutesBtn.textContent = '🗺️ Show Routes';
            toggleRoutesBtn.disabled = false;
        }
    }
    
    console.log(`✅ Refreshed ${routesList.length} routes with visibility state: ${routesVisible ? 'visible' : 'hidden'}`);
}

// Function to automatically fix route issues on startup
function autoFixRouteIssues() {
    console.log('🔧 Auto-fixing route issues...');
    
    // First, clean up any invalid routes
    const cleanupResult = cleanupRouteLines();
    
    if (cleanupResult.cleaned > 0) {
        console.log(`🧹 Cleaned up ${cleanupResult.cleaned} invalid routes, rebuilding...`);
        
        // Remove all existing route lines from map
        routeLines.forEach((line, index) => {
            if (line) {
                try {
                    map.removeLayer(line);
                } catch (error) {
                    console.warn(`Error removing route line ${index} during auto-fix:`, error);
                }
            }
        });
        
        // Clear the route lines array
        routeLines.length = 0;
        
        // Redraw all valid routes
        routesList.forEach((route, index) => {
            drawRouteLine(route, index);
        });
        
        // Apply correct visibility state
        routeLines.forEach((polyline, index) => {
            if (polyline && typeof polyline.setStyle === 'function') {
                try {
                    if (routesVisible) {
                        polyline.setStyle({
                            color: '#4e8ca0',
                            weight: 3,
                            opacity: 0.8,
                            dashArray: '8, 4',
                            lineCap: 'round',
                            lineJoin: 'round'
                        });
                        polyline._isClickable = true;
                    } else {
                        polyline.setStyle({ opacity: 0 });
                        polyline._isClickable = false;
                    }
                } catch (error) {
                    console.warn(`Error setting style for route line ${index} during auto-fix:`, error);
                }
            }
        });
        
        // Update the routes button
        const toggleRoutesBtn = document.getElementById('toggleRoutes');
        if (toggleRoutesBtn) {
            if (routesVisible) {
                toggleRoutesBtn.textContent = '🗺️ Hide Routes';
                toggleRoutesBtn.disabled = false;
            } else {
                toggleRoutesBtn.textContent = '🗺️ Show Routes';
                toggleRoutesBtn.disabled = false;
            }
        }
        
        console.log(`✅ Auto-fix complete: ${routesList.length} routes rebuilt, ${cleanupResult.cleaned} invalid routes removed`);
    } else {
        console.log('✅ No route issues found - all routes are valid');
    }
}

