function editRoute(index) {
    const route = routesList[index];
    if (!route) return;
    
    // Show the form and hide routes menu
    const form = document.getElementById('routeForm');
    const routesMenu = document.getElementById('routesMenuContent');
    
    if (routesMenu) routesMenu.style.display = 'none';
    if (form) {
        form.style.display = 'block';
        populateAirportDropdowns();
    }
    
    // Route name is now auto-generated from airport codes, no need to fill it
    
    // Find the full airport data for the dropdowns
    const departureFullData = findAirportFullData(route.departure);
    const arrivalFullData = findAirportFullData(route.arrival);
    
    document.getElementById('departureAirport').value = departureFullData || '';
    document.getElementById('arrivalAirport').value = arrivalFullData || '';
    
    // Set positioning route checkbox
    const positioningRouteCheckbox = document.getElementById('isPositioningRoute');
    if (positioningRouteCheckbox) {
        positioningRouteCheckbox.checked = route.isPositioningRoute || false;
    }
    
    // Update population display
    updateRoutePopulationDisplay();
    
    // Store the index for updating
    window.editingRouteIndex = index;
    
    // Change form title and button text
    const formTitle = form.querySelector('h4');
    const submitButton = form.querySelector('button[type="submit"]');
    if (formTitle) formTitle.textContent = 'Edit Route';
    if (submitButton) submitButton.textContent = 'Update Route';
}

function deleteRoute(index) {
    const routeToDelete = routesList[index];
    if (!routeToDelete) return;
    
    // Find the opposite direction route
    const oppositeRouteIndex = routesList.findIndex((route, i) => 
        i !== index && 
        route.departure === routeToDelete.arrival && 
        route.arrival === routeToDelete.departure
    );
    
    const hasOppositeRoute = oppositeRouteIndex !== -1;
    const confirmMessage = hasOppositeRoute 
        ? `Are you sure you want to delete this route? This will also delete the opposite direction route (${routeToDelete.arrivalCode || getAirportCode(routeToDelete.arrival)} → ${routeToDelete.departureCode || getAirportCode(routeToDelete.departure)}).`
        : 'Are you sure you want to delete this route?';
    
    if (confirm(confirmMessage)) {
        // Remove route line from map
        removeRouteLine(index);
        
        // Remove from array
        routesList.splice(index, 1);
        
        // If there's an opposite route, remove it too
        if (hasOppositeRoute) {
            // Adjust index if the opposite route comes before the deleted route
            const adjustedOppositeIndex = oppositeRouteIndex > index ? oppositeRouteIndex - 1 : oppositeRouteIndex;
            removeRouteLine(adjustedOppositeIndex);
            routesList.splice(adjustedOppositeIndex, 1);
        }
        
        // Reindex route lines array
        const newRouteLines = [];
        routesList.forEach((route, newIndex) => {
            if (routeLines[newIndex]) {
                newRouteLines[newIndex] = routeLines[newIndex];
            }
        });
        routeLines.length = 0;
        routeLines.push(...newRouteLines);
        
        saveRoutes();
        updateRoutesList();
        const successMessage = hasOppositeRoute 
            ? 'Route and opposite direction deleted successfully!'
            : 'Route deleted successfully!';
        alert(successMessage);
    }
}

function resetRouteFormToAddMode(preservedDepartureAirport = null) {
    const form = document.getElementById('routeForm');
    const formTitle = form.querySelector('h4');
    const submitButton = form.querySelector('button[type="submit"]');
    
    if (formTitle) formTitle.textContent = 'Add New Route';
    if (submitButton) submitButton.textContent = 'Add Route';
    
    // Clear airport selections and reset population display
    // If preservedDepartureAirport is provided, keep it selected for quick route creation
    if (preservedDepartureAirport) {
        document.getElementById('departureAirport').value = preservedDepartureAirport;
        // Filter arrival airports based on the preserved departure airport
        filterArrivalAirports(allAirportsForRoutes);
    } else {
        document.getElementById('departureAirport').value = '';
    }
    document.getElementById('arrivalAirport').value = '';
    updateRoutePopulationDisplay();
    
    // Reset positioning route checkbox
    const positioningRouteCheckbox = document.getElementById('isPositioningRoute');
    if (positioningRouteCheckbox) {
        positioningRouteCheckbox.checked = false;
    }
    
    // Clear editing state
    window.editingRouteIndex = null;
}

// Helper function to find full airport data by name
function findAirportFullData(airportName) {
    for (let i = 0; i < userMarkers.length; i++) {
        const marker = userMarkers[i];
        const popup = marker.getPopup();
        const content = popup.getContent();
        const parser = new DOMParser();
        const doc = parser.parseFromString(content, 'text/html');
        
        const name = doc.querySelector('h3').textContent;
        if (name === airportName) {
            const code = doc.querySelector('p:nth-child(4)').textContent.replace('Code: ', '');
            const latLng = marker.getLatLng();
            return `${name}|${code}|${latLng.lat}|${latLng.lng}`;
        }
    }
    return null;
}

// Calculate distance between two coordinates using Haversine formula
function calculateDistance(lat1, lon1, lat2, lon2) {
    const R = 6371; // Earth's radius in kilometers
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = 
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
        Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    const distance = R * c; // Distance in kilometers
    return distance;
}

function kmToStatuteMiles(km) {
    return km * KM_TO_STATUTE_MILES;
}

/** Lat/lng pairs for map polyline from airport SID/STAR procedures (or great-circle fallback). */
function getRoutePolylineLatLngs(route) {
    if (route?._polylineLatLngs?.length >= 2) {
        return route._polylineLatLngs;
    }
    if (!route?.departureCoords || !route?.arrivalCoords) {
        return [];
    }
    const resolved = resolveFlightPathForRoute(route);
    if (resolved.length >= 2) {
        return resolved.map(p => [p.lat, p.lng]);
    }
    return [
        [route.departureCoords.lat, route.departureCoords.lng],
        [route.arrivalCoords.lat, route.arrivalCoords.lng]
    ];
}

/** Total path length along drawn segments (km). */
function getRoutePathDistanceKm(route) {
    const latlngs = getRoutePolylineLatLngs(route);
    if (latlngs.length < 2) {
        return 0;
    }
    let total = 0;
    for (let i = 1; i < latlngs.length; i++) {
        total += calculateDistance(
            latlngs[i - 1][0], latlngs[i - 1][1],
            latlngs[i][0], latlngs[i][1]
        );
    }
    return total;
}

function formatRouteDistanceLabel(route) {
    const km = getRoutePathDistanceKm(route);
    const mi = kmToStatuteMiles(km);
    return `${mi.toFixed(0)} mi (${km.toFixed(0)} km)`;
}

function routeHasCustomPath(route) {
    const points = resolveFlightPathForRoute(route);
    return points.length > 2;
}

function coordsNearlyEqual(a, b, toleranceKm = 2) {
    if (!a || !b) return false;
    return calculateDistance(a.lat, a.lng, b.lat, b.lng) <= toleranceKm;
}

function startRoutePathDrawing(routeIndex) {
    const route = routesList[routeIndex];
    if (!route?.departureCoords || !route.arrivalCoords) {
        alert('This route is missing airport coordinates.');
        return;
    }

    cancelRoutePathDrawing(false);
    cancelRunwayDrawing(false);
    cancelGatePinning(true);

    const initialWaypoints = Array.isArray(route.pathWaypoints)
        ? route.pathWaypoints.filter(wp => wp && typeof wp.lat === 'number' && typeof wp.lng === 'number')
        : [];
    const points = [
        { lat: route.departureCoords.lat, lng: route.departureCoords.lng },
        ...initialWaypoints.map(wp => ({ lat: wp.lat, lng: wp.lng }))
    ];

    routeDrawingState = {
        active: true,
        routeIndex,
        route,
        points,
        cursorLatLng: null,
        committedLine: null,
        rubberLine: null,
        waypointMarkers: [],
        arrivalHitTarget: null,
        arrivalMarker: null,
        arrivalMarkerClickHandler: null
    };

    const depCode = route.departureCode || getAirportCode(route.departure);
    const arrCode = route.arrivalCode || getAirportCode(route.arrival);
    const toolbar = document.getElementById('routeDrawToolbar');
    const toolbarTitle = document.getElementById('routeDrawToolbarTitle');
    const codesEl = document.getElementById('routeDrawToolbarCodes');
    const editingExistingPath = routeHasCustomPath(route);
    if (toolbar) toolbar.style.display = 'block';
    if (toolbarTitle) {
        toolbarTitle.textContent = editingExistingPath ? 'Edit route path' : 'Draw route path';
    }
    if (codesEl) codesEl.textContent = `${depCode} → ${arrCode}`;

    map.getContainer().classList.add('route-drawing-active');

    focusedRouteIndex = null;
    showingSpecificAirports = true;
    airportsVisible = true;
    routesVisible = false;

    hideAllRoutesAndReset();
    showRouteAirports(route);
    setupRouteDrawArrivalTarget(route);
    setupRouteDrawMapHandlers();
    enableRouteDrawRightButtonPan();
    refreshRouteDrawLayers();
    updateRouteDrawDistanceDisplay();

    fitMapToRoute(route);

    const toggleAirportsButton = document.getElementById('toggleAirports');
    if (toggleAirportsButton) toggleAirportsButton.textContent = 'Hide Airports';
}

function setupRouteDrawMapHandlers() {
    if (!routeDrawingState) return;

    routeDrawingState.mapClickHandler = onRouteDrawMapClick;
    routeDrawingState.mapMoveHandler = onRouteDrawMapMove;
    map.on('click', routeDrawingState.mapClickHandler);
    map.on('mousemove', routeDrawingState.mapMoveHandler);
}

function teardownRouteDrawMapHandlers() {
    if (!routeDrawingState) return;
    disableRouteDrawRightButtonPan();
    if (routeDrawingState.mapClickHandler) {
        map.off('click', routeDrawingState.mapClickHandler);
    }
    if (routeDrawingState.mapMoveHandler) {
        map.off('mousemove', routeDrawingState.mapMoveHandler);
    }
}

/** Left click adds waypoints; right-click drag pans the map while drawing. */
function enableRouteDrawRightButtonPan() {
    if (!routeDrawingState) return;

    const container = map.getContainer();
    const rightPan = {
        active: false,
        lastPoint: null,
        contextMenuHandler: (e) => {
            if (!routeDrawingState?.active) return;
            e.preventDefault();
        },
        mouseDownHandler: (e) => {
            if (!routeDrawingState?.active || e.button !== 2) return;
            e.preventDefault();
            e.stopPropagation();
            rightPan.active = true;
            rightPan.lastPoint = { x: e.clientX, y: e.clientY };
            container.classList.add('route-drawing-panning');
            document.addEventListener('mousemove', rightPan.mouseMoveHandler);
            document.addEventListener('mouseup', rightPan.mouseUpHandler);
        },
        mouseMoveHandler: (e) => {
            if (!routeDrawingState?.active || !rightPan.active || !rightPan.lastPoint) return;
            const dx = e.clientX - rightPan.lastPoint.x;
            const dy = e.clientY - rightPan.lastPoint.y;
            map.panBy(L.point(-dx, -dy), { animate: false });
            rightPan.lastPoint = { x: e.clientX, y: e.clientY };
        },
        mouseUpHandler: () => {
            if (!rightPan.active) return;
            rightPan.active = false;
            rightPan.lastPoint = null;
            container.classList.remove('route-drawing-panning');
            document.removeEventListener('mousemove', rightPan.mouseMoveHandler);
            document.removeEventListener('mouseup', rightPan.mouseUpHandler);
        }
    };

    routeDrawingState.rightPan = rightPan;
    container.addEventListener('contextmenu', rightPan.contextMenuHandler);
    container.addEventListener('mousedown', rightPan.mouseDownHandler);
    map.dragging.disable();
}

function disableRouteDrawRightButtonPan() {
    const container = map.getContainer();
    const rightPan = routeDrawingState?.rightPan;
    if (rightPan) {
        if (rightPan.active) {
            rightPan.mouseUpHandler();
        }
        container.removeEventListener('contextmenu', rightPan.contextMenuHandler);
        container.removeEventListener('mousedown', rightPan.mouseDownHandler);
        container.classList.remove('route-drawing-panning');
    }
    if (map.dragging && !map.dragging.enabled()) {
        map.dragging.enable();
    }
}

function setupRouteDrawArrivalTarget(route) {
    if (!routeDrawingState) return;

    const arrivalCode = route.arrivalCode || getAirportCode(route.arrival);
    const arrivalMarker = userMarkers.find(m => m.airportData?.code === arrivalCode);
    routeDrawingState.arrivalMarker = arrivalMarker || null;

    if (arrivalMarker) {
        routeDrawingState.arrivalMarkerClickHandler = onRouteDrawArrivalTargetClick;
        arrivalMarker.on('click', routeDrawingState.arrivalMarkerClickHandler);
    }
}

function onRouteDrawArrivalTargetClick(e) {
    if (!routeDrawingState?.active) return;
    if (e?.originalEvent) {
        L.DomEvent.stopPropagation(e);
    }
    finishRouteDrawAtArrival();
}

function onRouteDrawMapClick(e) {
    if (!routeDrawingState?.active) return;

    const clickLatLng = e.latlng;
    routeDrawingState.points.push({ lat: clickLatLng.lat, lng: clickLatLng.lng });
    refreshRouteDrawLayers();
    updateRouteDrawDistanceDisplay();
}

function onRouteDrawMapMove(e) {
    if (!routeDrawingState?.active) return;
    routeDrawingState.cursorLatLng = { lat: e.latlng.lat, lng: e.latlng.lng };
    updateRouteDrawRubberLine();
    updateRouteDrawDistanceDisplay();
}

function refreshRouteDrawLayers() {
    if (!routeDrawingState) return;

    routeDrawingState.waypointMarkers.forEach(marker => {
        try { map.removeLayer(marker); } catch (_) { /* ignore */ }
    });
    routeDrawingState.waypointMarkers = [];

    const pointLatLngs = routeDrawingState.points.map(p => [p.lat, p.lng]);
    if (!routeDrawingState.committedLine) {
        routeDrawingState.committedLine = L.polyline(pointLatLngs, {
            color: '#8e44ad',
            weight: 4,
            opacity: 0.95,
            lineCap: 'round',
            lineJoin: 'round'
        }).addTo(map);
    } else {
        routeDrawingState.committedLine.setLatLngs(pointLatLngs);
        if (!map.hasLayer(routeDrawingState.committedLine)) {
            routeDrawingState.committedLine.addTo(map);
        }
    }

    routeDrawingState.points.slice(1).forEach((p, idx) => {
        const marker = L.marker([p.lat, p.lng], {
            interactive: false,
            icon: L.divIcon({
                className: 'route-draw-waypoint-marker-wrap',
                html: '<div class="route-draw-waypoint-marker"></div>',
                iconSize: [10, 10],
                iconAnchor: [5, 5]
            })
        }).addTo(map);
        marker._routeDrawWaypointIndex = idx + 1;
        routeDrawingState.waypointMarkers.push(marker);
    });

    updateRouteDrawRubberLine();
}

function updateRouteDrawRubberLine() {
    if (!routeDrawingState) return;

    const last = routeDrawingState.points[routeDrawingState.points.length - 1];
    const cursor = routeDrawingState.cursorLatLng;
    if (!last || !cursor) {
        if (routeDrawingState.rubberLine) {
            routeDrawingState.rubberLine.remove();
            routeDrawingState.rubberLine = null;
        }
        return;
    }

    const rubberLatLngs = [[last.lat, last.lng], [cursor.lat, cursor.lng]];
    if (!routeDrawingState.rubberLine) {
        routeDrawingState.rubberLine = L.polyline(rubberLatLngs, {
            color: '#8e44ad',
            weight: 3,
            opacity: 0.55,
            dashArray: '6, 8',
            lineCap: 'round',
            lineJoin: 'round'
        }).addTo(map);
    } else {
        routeDrawingState.rubberLine.setLatLngs(rubberLatLngs);
        if (!map.hasLayer(routeDrawingState.rubberLine)) {
            routeDrawingState.rubberLine.addTo(map);
        }
    }
}

function getRouteDrawPointsDistanceKm(points, includeCursor = false, cursorLatLng = null) {
    if (!points || points.length < 1) return 0;
    let total = 0;
    for (let i = 1; i < points.length; i++) {
        total += calculateDistance(points[i - 1].lat, points[i - 1].lng, points[i].lat, points[i].lng);
    }
    if (includeCursor && cursorLatLng && points.length >= 1) {
        const last = points[points.length - 1];
        total += calculateDistance(last.lat, last.lng, cursorLatLng.lat, cursorLatLng.lng);
    }
    return total;
}

function updateRouteDrawDistanceDisplay() {
    if (!routeDrawingState) return;

    const km = getRouteDrawPointsDistanceKm(
        routeDrawingState.points,
        true,
        routeDrawingState.cursorLatLng
    );
    const mi = kmToStatuteMiles(km);
    const waypointCount = Math.max(0, routeDrawingState.points.length - 1);

    const miEl = document.getElementById('routeDrawDistanceMi');
    const countEl = document.getElementById('routeDrawWaypointCount');
    if (miEl) miEl.textContent = mi.toFixed(0);
    if (countEl) {
        countEl.textContent = waypointCount === 1 ? '1 waypoint' : `${waypointCount} waypoints`;
    }
}

function finishRouteDrawAtArrival() {
    if (!routeDrawingState?.active) return;

    const arrival = routeDrawingState.route.arrivalCoords;
    const last = routeDrawingState.points[routeDrawingState.points.length - 1];
    if (!coordsNearlyEqual(last, arrival, 2)) {
        routeDrawingState.points.push({ lat: arrival.lat, lng: arrival.lng });
    }
    routeDrawingState.cursorLatLng = null;
    refreshRouteDrawLayers();
    updateRouteDrawDistanceDisplay();
}

function undoRouteDrawWaypoint() {
    if (!routeDrawingState?.active) return;
    if (routeDrawingState.points.length <= 1) return;

    routeDrawingState.points.pop();
    routeDrawingState.cursorLatLng = null;
    refreshRouteDrawLayers();
    updateRouteDrawDistanceDisplay();
}

function saveRoutePathDrawing() {
    if (!routeDrawingState?.active) return;

    const routeIndex = routeDrawingState.routeIndex;
    const route = routesList[routeIndex];
    if (!route) {
        cancelRoutePathDrawing();
        return;
    }

    finishRouteDrawAtArrival();

    const arrival = route.arrivalCoords;
    const middlePoints = routeDrawingState.points.slice(1).filter(p => !coordsNearlyEqual(p, arrival, 2));
    const pathWaypoints = middlePoints.map(p => ({ lat: p.lat, lng: p.lng }));

    if (pathWaypoints.length) {
        route.pathWaypoints = pathWaypoints;
    } else {
        delete route.pathWaypoints;
    }

    removeRouteLine(routeIndex);
    drawRouteLine(route, routeIndex);
    saveRoutes();
    updateRoutesList();

    cancelRoutePathDrawing(true);
    alert('Route path saved.');
}

function cancelRoutePathDrawing(restoreMapView = true) {
    if (!routeDrawingState) {
        const toolbar = document.getElementById('routeDrawToolbar');
        if (toolbar) toolbar.style.display = 'none';
        map.getContainer().classList.remove('route-drawing-active');
        map.getContainer().classList.remove('route-drawing-panning');
        if (map.dragging && !map.dragging.enabled()) {
            map.dragging.enable();
        }
        return;
    }

    teardownRouteDrawMapHandlers();

    if (routeDrawingState.committedLine) {
        routeDrawingState.committedLine.remove();
    }
    if (routeDrawingState.rubberLine) {
        routeDrawingState.rubberLine.remove();
    }
    routeDrawingState.waypointMarkers.forEach(marker => {
        try { map.removeLayer(marker); } catch (_) { /* ignore */ }
    });
    if (routeDrawingState.arrivalHitTarget) {
        routeDrawingState.arrivalHitTarget.off('click', onRouteDrawArrivalTargetClick);
        routeDrawingState.arrivalHitTarget.remove();
    }
    if (routeDrawingState.arrivalMarker && routeDrawingState.arrivalMarkerClickHandler) {
        routeDrawingState.arrivalMarker.off('click', routeDrawingState.arrivalMarkerClickHandler);
    }

    routeDrawingState = null;

    const toolbar = document.getElementById('routeDrawToolbar');
    if (toolbar) toolbar.style.display = 'none';
    map.getContainer().classList.remove('route-drawing-active');

    showingSpecificAirports = false;

    if (restoreMapView) {
        hideAllRoutesAndAirportsOnClickAway();
    }
}

function findAirportMarkerByLatLng(lat, lng) {
    return userMarkers.find(m => {
        const ll = m.getLatLng();
        return Math.abs(ll.lat - lat) < 0.000001 && Math.abs(ll.lng - lng) < 0.000001;
    });
}

function setRunwayDrawToolbarVisible(visible) {
    const toolbar = document.getElementById('runwayDrawToolbar');
    if (!toolbar) return;
    toolbar.style.display = visible ? 'flex' : 'none';
}

function ensureSidebarVisibleForRunwayEditing() {
    const sidebar = document.querySelector('.sidebar');
    const toggleSidebarIcon = document.getElementById('toggleSidebarIcon');
    if (!sidebar || !sidebar.classList.contains('hidden')) return;

    sidebar.classList.remove('hidden');
    if (toggleSidebarIcon) toggleSidebarIcon.textContent = '✕';
    localStorage.setItem('sidebarHidden', 'false');
    setTimeout(() => {
        if (map) map.invalidateSize();
    }, 300);
}

function beginRunwayDrawingSession(marker, mode = 'runway') {
    if (routeDrawingState?.active) {
        cancelRoutePathDrawing(false);
    }
    cancelRunwayDrawing(false);
    cancelGatePinning(true);

    const existingRunways = Array.isArray(marker.airportData.runways)
        ? marker.airportData.runways.map(rwy => normalizeRunwayRecord(rwy)).filter(Boolean)
        : [];

    if (mode === 'path' && !existingRunways.length) {
        alert('Draw at least one runway before editing arrival or departure paths.');
        return false;
    }

    const firstPair = existingRunways.length ? getRunwayDesignatorPair(existingRunways[0]) : null;

    runwayDrawingState = {
        active: true,
        mode,
        marker,
        runways: existingRunways,
        pendingStart: null,
        cursorLatLng: null,
        sessionLayers: [],
        rubberLine: null,
        mapClickHandler: null,
        mapMoveHandler: null,
        rightPan: null,
        pathRunwayIndex: 0,
        pathDesignator: firstPair?.primary || null,
        pathKind: 'arrival',
        pathVariantId: null,
        pathPoints: [],
        pathDrawingFollowCursor: true
    };

    map.closePopup();
    ensureSidebarVisibleForRunwayEditing();

    const code = marker.airportData.code || '';
    const titleEl = document.getElementById('runwayDrawToolbarTitle');
    const codesEl = document.getElementById('runwayDrawToolbarCodes');
    setRunwayDrawToolbarVisible(true);
    if (titleEl) {
        titleEl.textContent = mode === 'path' ? 'Edit runway paths' : 'Draw airport runways';
    }
    if (codesEl) codesEl.textContent = code;

    map.getContainer().classList.add('route-drawing-active');
    airportsVisible = true;
    showingSpecificAirports = true;
    routesVisible = false;
    hideAllRoutesAndReset();

    userMarkers.forEach(m => {
        if (m === marker) {
            if (markerClusterGroup) {
                if (!markerClusterGroup.hasLayer(m)) markerClusterGroup.addLayer(m);
            } else if (!map.hasLayer(m)) {
                m.addTo(map);
            }
        } else if (markerClusterGroup) {
            if (markerClusterGroup.hasLayer(m)) markerClusterGroup.removeLayer(m);
        } else if (map.hasLayer(m)) {
            map.removeLayer(m);
        }
    });

    clearAirportRunwayMapLayers(marker);
    setupRunwayDrawMapHandlers();
    enableRunwayDrawRightButtonPan();

    setRunwayDrawMode(mode, { skipCommit: true });

    if (mode === 'path') {
        loadPathEditingStateFromRunway();
    }

    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();

    const latLng = marker.getLatLng();
    map.setView([latLng.lat, latLng.lng], Math.max(map.getZoom(), 15));

    const toggleAirportsButton = document.getElementById('toggleAirports');
    if (toggleAirportsButton) toggleAirportsButton.textContent = 'Hide Airports';
    return true;
}

function startRunwayDrawing(lat, lng) {
    const marker = findAirportMarkerByLatLng(lat, lng);
    if (!marker?.airportData) {
        alert('Airport not found.');
        return;
    }
    beginRunwayDrawingSession(marker, 'runway');
}

function startRunwayPathEditing(lat, lng) {
    const marker = findAirportMarkerByLatLng(lat, lng);
    if (!marker?.airportData) {
        alert('Airport not found.');
        return;
    }
    beginRunwayDrawingSession(marker, 'path');
}

function setRunwayDrawMode(mode, options = {}) {
    if (!runwayDrawingState?.active) return;

    if (mode === 'path' && !runwayDrawingState.runways.length) {
        alert('Draw at least one runway before editing paths.');
        return;
    }

    if (!options.skipCommit && runwayDrawingState.mode === 'path' && mode !== 'path') {
        commitPathEditingStateToRunway();
    }

    runwayDrawingState.mode = mode;
    runwayDrawingState.pendingStart = null;
    runwayDrawingState.cursorLatLng = null;

    const runwaysBtn = document.getElementById('runwayDrawModeRunwaysBtn');
    const pathsBtn = document.getElementById('runwayDrawModePathsBtn');
    const runwaysPanel = document.getElementById('runwayDrawRunwaysPanel');
    const pathsPanel = document.getElementById('runwayDrawPathsPanel');
    const finishBtn = document.getElementById('runwayPathFinishThresholdBtn');
    const clearBtn = document.getElementById('runwayPathClearBtn');

    if (runwaysBtn) runwaysBtn.classList.toggle('active', mode === 'runway');
    if (pathsBtn) pathsBtn.classList.toggle('active', mode === 'path');
    if (runwaysPanel) runwaysPanel.style.display = mode === 'runway' ? 'block' : 'none';
    if (pathsPanel) pathsPanel.style.display = mode === 'path' ? 'block' : 'none';
    if (finishBtn) finishBtn.style.display = mode === 'path' ? 'inline-block' : 'none';
    if (clearBtn) clearBtn.style.display = mode === 'path' ? 'inline-block' : 'none';

    if (mode === 'path') {
        populateRunwayPathSelectors();
        loadPathEditingStateFromRunway();
    }

    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();
}

function getRunwayPathDirectionFromSelect() {
    const select = document.getElementById('runwayPathDirectionSelect');
    return normalizeRunwayPathDirectionCode(select?.value) || 'N';
}

function syncRunwayPathDirectionSelect(variant, rwy, designator, pathKind) {
    const select = document.getElementById('runwayPathDirectionSelect');
    if (!select) return;

    if (!rwy || !designator) {
        select.innerHTML = '<option value="">—</option>';
        return;
    }

    const usedByOthers = new Set(
        getUsedRunwayPathDirections(rwy, designator, pathKind, variant?.id || null)
    );

    select.innerHTML = RUNWAY_PATH_DIRECTIONS.map(d => {
        const selected = variant && variant.direction === d.code ? ' selected' : '';
        const disabled = usedByOthers.has(d.code) ? ' disabled' : '';
        return `<option value="${d.code}"${selected}${disabled}>${d.label}</option>`;
    }).join('');

    if (!variant) {
        const firstUnused = getFirstUnusedRunwayPathDirection(rwy, designator, pathKind) || 'N';
        select.value = firstUnused;
    }
}

function ensureActiveRunwayPathVariant(rwy) {
    if (!runwayDrawingState || !rwy || !runwayDrawingState.pathVariantId) return null;

    const des = runwayDrawingState.pathDesignator;
    const kindKey = getRunwayPathKindKey(runwayDrawingState.pathKind);
    ensureRunwayHasPaths(rwy);
    return rwy.paths[des][kindKey].find(v => v.id === runwayDrawingState.pathVariantId) || null;
}

function populateRunwayPathSelectors() {
    if (!runwayDrawingState) return;

    const runwaySelect = document.getElementById('runwayPathRunwaySelect');
    const designatorSelect = document.getElementById('runwayPathDesignatorSelect');
    const variantSelect = document.getElementById('runwayPathVariantSelect');
    if (!runwaySelect || !designatorSelect) return;

    runwaySelect.innerHTML = runwayDrawingState.runways
        .map((rwy, idx) => `<option value="${idx}"${idx === runwayDrawingState.pathRunwayIndex ? ' selected' : ''}>${escapeHtml(rwy.name)}</option>`)
        .join('');

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    const pair = rwy ? getRunwayDesignatorPair(rwy) : null;
    if (pair) {
        if (!runwayDrawingState.pathDesignator ||
            ![pair.primary, pair.reciprocal].includes(runwayDrawingState.pathDesignator)) {
            runwayDrawingState.pathDesignator = pair.primary;
        }
        designatorSelect.innerHTML = `
            <option value="${pair.primary}"${runwayDrawingState.pathDesignator === pair.primary ? ' selected' : ''}>Runway ${pair.primary}</option>
            <option value="${pair.reciprocal}"${runwayDrawingState.pathDesignator === pair.reciprocal ? ' selected' : ''}>Runway ${pair.reciprocal}</option>
        `;
    } else {
        designatorSelect.innerHTML = '';
    }

    const kindSelect = document.getElementById('runwayPathKindSelect');
    if (kindSelect) {
        kindSelect.value = runwayDrawingState.pathKind || 'arrival';
    }

    if (variantSelect && rwy && runwayDrawingState.pathDesignator) {
        const des = runwayDrawingState.pathDesignator;
        const kind = runwayDrawingState.pathKind;
        const variants = getRunwayPathVariants(rwy, des, kind);
        let options = `<option value=""${!runwayDrawingState.pathVariantId ? ' selected' : ''}>Default (no direction)</option>`;
        options += variants
            .map(v => `<option value="${v.id}"${v.id === runwayDrawingState.pathVariantId ? ' selected' : ''}>${escapeHtml(getRunwayPathDirectionLabel(v.direction))}</option>`)
            .join('');
        variantSelect.innerHTML = options;
    }

    const activeVariant = ensureActiveRunwayPathVariant(rwy);
    syncRunwayPathDirectionSelect(
        activeVariant,
        rwy,
        runwayDrawingState.pathDesignator,
        runwayDrawingState.pathKind
    );
}

function resetRunwayPathPreviewCursor() {
    if (!runwayDrawingState) return;
    runwayDrawingState.cursorLatLng = null;
    if (runwayDrawingState.rubberLine) {
        try { runwayDrawingState.rubberLine.remove(); } catch (_) { /* ignore */ }
        runwayDrawingState.rubberLine = null;
    }
}

function onRunwayPathTargetChange() {
    if (!runwayDrawingState || runwayDrawingState.mode !== 'path') return;

    commitPathEditingStateToRunway();

    const runwaySelect = document.getElementById('runwayPathRunwaySelect');
    const designatorSelect = document.getElementById('runwayPathDesignatorSelect');
    const kindSelect = document.getElementById('runwayPathKindSelect');

    runwayDrawingState.pathRunwayIndex = parseInt(runwaySelect?.value || '0', 10) || 0;
    runwayDrawingState.pathDesignator = designatorSelect?.value || runwayDrawingState.pathDesignator;
    runwayDrawingState.pathKind = kindSelect?.value === 'departure' ? 'departure' : 'arrival';
    runwayDrawingState.pathVariantId = null;
    runwayDrawingState.pathDrawingFollowCursor = true;
    resetRunwayPathPreviewCursor();

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    ensureRunwayPathEditingSelection(rwy);

    populateRunwayPathSelectors();
    loadPathEditingStateFromRunway();
    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();
}

function onRunwayPathVariantChange() {
    if (!runwayDrawingState || runwayDrawingState.mode !== 'path') return;

    commitPathEditingStateToRunway();

    const variantSelect = document.getElementById('runwayPathVariantSelect');
    const selected = variantSelect?.value || '';
    runwayDrawingState.pathVariantId = selected || null;
    runwayDrawingState.pathDrawingFollowCursor = true;
    resetRunwayPathPreviewCursor();

    loadPathEditingStateFromRunway();
    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();
}

function onRunwayPathDirectionChange() {
    if (!runwayDrawingState || runwayDrawingState.mode !== 'path') return;
    if (!isEditingDirectionalRunwayPathVariant()) return;

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    if (!rwy || !runwayDrawingState.pathDesignator) return;

    commitPathEditingStateToRunway();

    const newDirection = getRunwayPathDirectionFromSelect();
    const kindKey = getRunwayPathKindKey(runwayDrawingState.pathKind);
    ensureRunwayHasPaths(rwy);
    const variants = rwy.paths[runwayDrawingState.pathDesignator][kindKey];
    let variant = variants.find(v => v.id === runwayDrawingState.pathVariantId);

    if (!variant) return;

    const conflict = variants.find(v => v.id !== variant.id && v.direction === newDirection);
    if (conflict) {
        alert(`${getRunwayPathDirectionLabel(newDirection)} already has a path. Select it from Variant or delete it first.`);
        populateRunwayPathSelectors();
        return;
    }

    variant.direction = newDirection;

    populateRunwayPathSelectors();
    loadPathEditingStateFromRunway();
    updateRunwayDrawUi();
}

function addNewRunwayPathVariant() {
    if (!runwayDrawingState?.active || runwayDrawingState.mode !== 'path') return;

    commitPathEditingStateToRunway();

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    if (!rwy || !runwayDrawingState.pathDesignator) return;

    const direction = getFirstUnusedRunwayPathDirection(
        rwy,
        runwayDrawingState.pathDesignator,
        runwayDrawingState.pathKind
    );
    if (!direction) {
        alert('All compass directions already have a path for this runway and path type.');
        return;
    }

    const kindKey = getRunwayPathKindKey(runwayDrawingState.pathKind);
    ensureRunwayHasPaths(rwy);

    const depStart = getDepartureStartForDesignator(rwy, runwayDrawingState.pathDesignator);
    const waypoints = runwayDrawingState.pathKind === 'departure' && depStart
        ? [{ lat: depStart.lat, lng: depStart.lng }]
        : [];

    const variant = { id: generateRunwayPathId(), direction, waypoints };
    rwy.paths[runwayDrawingState.pathDesignator][kindKey].push(variant);
    runwayDrawingState.pathVariantId = variant.id;
    runwayDrawingState.pathDrawingFollowCursor = true;
    resetRunwayPathPreviewCursor();

    populateRunwayPathSelectors();
    loadPathEditingStateFromRunway();
    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();
}

function deleteCurrentRunwayPathVariant() {
    if (!runwayDrawingState?.active || runwayDrawingState.mode !== 'path') return;
    if (!isEditingDirectionalRunwayPathVariant()) {
        alert('Use Clear path to reset the default route. Directional variants can be deleted when one is selected.');
        return;
    }

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    if (!rwy || !runwayDrawingState.pathDesignator) return;

    const kindKey = getRunwayPathKindKey(runwayDrawingState.pathKind);
    ensureRunwayHasPaths(rwy);
    const variants = rwy.paths[runwayDrawingState.pathDesignator][kindKey];
    const idx = variants.findIndex(v => v.id === runwayDrawingState.pathVariantId);
    if (idx < 0) return;

    const directionLabel = getRunwayPathDirectionLabel(variants[idx].direction);
    if (!confirm(`Delete the ${directionLabel} path?`)) return;

    variants.splice(idx, 1);
    runwayDrawingState.pathVariantId = variants.length
        ? (variants[Math.min(idx, variants.length - 1)]?.id || variants[0].id)
        : null;
    ensureRunwayPathEditingSelection(rwy);
    runwayDrawingState.pathDrawingFollowCursor = true;
    resetRunwayPathPreviewCursor();

    populateRunwayPathSelectors();
    loadPathEditingStateFromRunway();
    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();
}

function ensurePathPointsReadyForDrawing() {
    if (!runwayDrawingState?.active || runwayDrawingState.mode !== 'path') return;
    if (isEditingDirectionalRunwayPathVariant()) return;
    if (runwayDrawingState.pathPoints.length) return;
    loadPathEditingStateFromRunway();
}

function updateRunwayPathVariantControlsVisibility() {
    if (!runwayDrawingState || runwayDrawingState.mode !== 'path') return;

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    const variants = rwy && runwayDrawingState.pathDesignator
        ? getRunwayPathVariants(rwy, runwayDrawingState.pathDesignator, runwayDrawingState.pathKind)
        : [];
    const showVariantPicker = variants.length > 0;
    const showDirectionPicker = isEditingDirectionalRunwayPathVariant();

    document.querySelectorAll('.runway-path-variant-controls').forEach(el => {
        if (el.classList.contains('runway-path-direction-controls')) {
            el.style.display = showDirectionPicker ? '' : 'none';
            return;
        }
        if (el.classList.contains('delete-btn')) {
            el.style.display = showDirectionPicker ? '' : 'none';
            return;
        }
        el.style.display = showVariantPicker ? '' : 'none';
    });
}

function loadPathEditingStateFromRunway() {
    if (!runwayDrawingState || runwayDrawingState.mode !== 'path') return;

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    if (!rwy) {
        runwayDrawingState.pathPoints = [];
        return;
    }

    ensureRunwayHasPaths(rwy);
    const pair = getRunwayDesignatorPair(rwy);
    if (pair && !runwayDrawingState.pathDesignator) {
        runwayDrawingState.pathDesignator = pair.primary;
    }

    const des = runwayDrawingState.pathDesignator;
    const kind = runwayDrawingState.pathKind;
    const kindKey = getRunwayPathKindKey(kind);

    ensureRunwayPathEditingSelection(rwy);

    if (!isEditingDirectionalRunwayPathVariant()) {
        const saved = getDefaultRunwayPathWaypoints(rwy, des, kind);
        if (kind === 'departure') {
            const depStart = getDepartureStartForDesignator(rwy, des);
            runwayDrawingState.pathPoints = saved.length
                ? saved.map(p => ({ lat: p.lat, lng: p.lng }))
                : (depStart ? [{ lat: depStart.lat, lng: depStart.lng }] : []);
        } else {
            runwayDrawingState.pathPoints = saved.map(p => ({ lat: p.lat, lng: p.lng }));
        }
        syncRunwayPathDirectionSelect(null, rwy, des, kind);
        updateRunwayPathVariantControlsVisibility();
        return;
    }

    const variants = rwy.paths?.[des]?.[kindKey] || [];
    const variant = variants.find(v => v.id === runwayDrawingState.pathVariantId);
    if (!variant) {
        runwayDrawingState.pathVariantId = null;
        loadPathEditingStateFromRunway();
        return;
    }

    const saved = variant.waypoints || [];
    if (kind === 'departure') {
        const depStart = getDepartureStartForDesignator(rwy, des);
        runwayDrawingState.pathPoints = saved.length
            ? saved.map(p => ({ lat: p.lat, lng: p.lng }))
            : (depStart ? [{ lat: depStart.lat, lng: depStart.lng }] : []);
    } else {
        runwayDrawingState.pathPoints = saved.map(p => ({ lat: p.lat, lng: p.lng }));
    }

    syncRunwayPathDirectionSelect(variant, rwy, des, kind);
    updateRunwayPathVariantControlsVisibility();
}

function commitPathEditingStateToRunway() {
    if (!runwayDrawingState || runwayDrawingState.mode !== 'path') return;

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    if (!rwy || !runwayDrawingState.pathDesignator) return;

    ensureRunwayHasPaths(rwy);
    const des = runwayDrawingState.pathDesignator;
    const kind = runwayDrawingState.pathKind;
    const points = runwayDrawingState.pathPoints.map(p => ({ lat: p.lat, lng: p.lng }));

    if (!isEditingDirectionalRunwayPathVariant()) {
        setDefaultRunwayPathWaypoints(rwy, des, kind, points);
        return;
    }

    const kindKey = getRunwayPathKindKey(kind);
    const variant = rwy.paths[des][kindKey].find(v => v.id === runwayDrawingState.pathVariantId);
    if (!variant) return;

    variant.direction = getRunwayPathDirectionFromSelect();
    variant.waypoints = points;
}

function finishRunwayPathAtThreshold() {
    if (!runwayDrawingState?.active || runwayDrawingState.mode !== 'path') return;
    if (runwayDrawingState.pathKind !== 'arrival') return;

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    const threshold = rwy ? getThresholdForDesignator(rwy, runwayDrawingState.pathDesignator) : null;
    if (!threshold) return;

    const last = runwayDrawingState.pathPoints[runwayDrawingState.pathPoints.length - 1];
    if (!last || calculateDistance(last.lat, last.lng, threshold.lat, threshold.lng) > 0.02) {
        runwayDrawingState.pathPoints.push({ lat: threshold.lat, lng: threshold.lng });
    }
    runwayDrawingState.pathDrawingFollowCursor = false;
    resetRunwayPathPreviewCursor();
    commitPathEditingStateToRunway();
    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();
}

function clearCurrentRunwayPath() {
    if (!runwayDrawingState?.active || runwayDrawingState.mode !== 'path') return;

    const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
    if (!rwy || !runwayDrawingState.pathDesignator) return;

    const des = runwayDrawingState.pathDesignator;
    const kind = runwayDrawingState.pathKind;

    if (!isEditingDirectionalRunwayPathVariant()) {
        if (kind === 'departure') {
            const depStart = getDepartureStartForDesignator(rwy, des);
            setDefaultRunwayPathWaypoints(
                rwy,
                des,
                kind,
                depStart ? [{ lat: depStart.lat, lng: depStart.lng }] : []
            );
        } else {
            setDefaultRunwayPathWaypoints(rwy, des, kind, []);
        }
    } else {
        const variant = ensureActiveRunwayPathVariant(rwy);
        if (!variant) return;
        const depStart = getDepartureStartForDesignator(rwy, des);
        variant.waypoints = kind === 'departure' && depStart
            ? [{ lat: depStart.lat, lng: depStart.lng }]
            : [];
    }

    runwayDrawingState.pathDrawingFollowCursor = true;
    resetRunwayPathPreviewCursor();
    loadPathEditingStateFromRunway();
    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();
}

function setupRunwayDrawMapHandlers() {
    if (!runwayDrawingState) return;
    runwayDrawingState.mapClickHandler = onRunwayDrawMapClick;
    runwayDrawingState.mapMoveHandler = onRunwayDrawMapMove;
    map.on('click', runwayDrawingState.mapClickHandler);
    map.on('mousemove', runwayDrawingState.mapMoveHandler);
}

function teardownRunwayDrawMapHandlers() {
    if (!runwayDrawingState) return;
    disableRunwayDrawRightButtonPan();
    if (runwayDrawingState.mapClickHandler) {
        map.off('click', runwayDrawingState.mapClickHandler);
    }
    if (runwayDrawingState.mapMoveHandler) {
        map.off('mousemove', runwayDrawingState.mapMoveHandler);
    }
}

function enableRunwayDrawRightButtonPan() {
    if (!runwayDrawingState) return;

    const container = map.getContainer();
    const rightPan = {
        active: false,
        lastPoint: null,
        contextMenuHandler: (e) => {
            if (!runwayDrawingState?.active) return;
            e.preventDefault();
        },
        mouseDownHandler: (e) => {
            if (!runwayDrawingState?.active || e.button !== 2) return;
            e.preventDefault();
            e.stopPropagation();
            rightPan.active = true;
            rightPan.lastPoint = { x: e.clientX, y: e.clientY };
            container.classList.add('route-drawing-panning');
            document.addEventListener('mousemove', rightPan.mouseMoveHandler);
            document.addEventListener('mouseup', rightPan.mouseUpHandler);
        },
        mouseMoveHandler: (e) => {
            if (!runwayDrawingState?.active || !rightPan.active || !rightPan.lastPoint) return;
            const dx = e.clientX - rightPan.lastPoint.x;
            const dy = e.clientY - rightPan.lastPoint.y;
            map.panBy(L.point(-dx, -dy), { animate: false });
            rightPan.lastPoint = { x: e.clientX, y: e.clientY };
        },
        mouseUpHandler: () => {
            if (!rightPan.active) return;
            rightPan.active = false;
            rightPan.lastPoint = null;
            container.classList.remove('route-drawing-panning');
            document.removeEventListener('mousemove', rightPan.mouseMoveHandler);
            document.removeEventListener('mouseup', rightPan.mouseUpHandler);
        }
    };

    runwayDrawingState.rightPan = rightPan;
    container.addEventListener('contextmenu', rightPan.contextMenuHandler);
    container.addEventListener('mousedown', rightPan.mouseDownHandler);
    map.dragging.disable();
}

function disableRunwayDrawRightButtonPan() {
    const container = map.getContainer();
    const rightPan = runwayDrawingState?.rightPan;
    if (rightPan) {
        if (rightPan.active) {
            rightPan.mouseUpHandler();
        }
        container.removeEventListener('contextmenu', rightPan.contextMenuHandler);
        container.removeEventListener('mousedown', rightPan.mouseDownHandler);
        container.classList.remove('route-drawing-panning');
    }
    if (map.dragging && !map.dragging.enabled()) {
        map.dragging.enable();
    }
}

function onRunwayDrawMapClick(e) {
    if (!runwayDrawingState?.active) return;

    const click = { lat: e.latlng.lat, lng: e.latlng.lng };

    if (runwayDrawingState.mode === 'path') {
        if (!runwayDrawingState.pathDrawingFollowCursor) return;
        ensurePathPointsReadyForDrawing();
        runwayDrawingState.pathPoints.push(click);
        resetRunwayPathPreviewCursor();
        refreshRunwayDrawingLayers();
        updateRunwayDrawUi();
        return;
    }

    if (!runwayDrawingState.pendingStart) {
        runwayDrawingState.pendingStart = click;
        runwayDrawingState.cursorLatLng = click;
        updateRunwayDrawUi();
        refreshRunwayDrawingLayers();
        return;
    }

    const end1 = runwayDrawingState.pendingStart;
    const end2 = click;
    if (calculateDistance(end1.lat, end1.lng, end2.lat, end2.lng) < 0.05) {
        alert('Runway is too short. Click a point farther away for the opposite end.');
        return;
    }

    const designators = getRunwayNameFromEndpoints(end1, end2);
    const newRunway = {
        name: designators.name,
        end1,
        end2,
        heading: designators.heading,
        reciprocalHeading: designators.reciprocalHeading
    };
    ensureRunwayHasPaths(newRunway);
    runwayDrawingState.runways.push(newRunway);
    runwayDrawingState.pendingStart = null;
    runwayDrawingState.cursorLatLng = null;
    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();
}

function onRunwayDrawMapMove(e) {
    if (!runwayDrawingState?.active) return;

    if (runwayDrawingState.mode === 'path') {
        if (!runwayDrawingState.pathDrawingFollowCursor) return;
        ensurePathPointsReadyForDrawing();
        if (!runwayDrawingState.pathPoints.length) return;
        runwayDrawingState.cursorLatLng = { lat: e.latlng.lat, lng: e.latlng.lng };
        updateRunwayDrawRubberLine();
        return;
    }

    if (!runwayDrawingState.pendingStart) return;
    runwayDrawingState.cursorLatLng = { lat: e.latlng.lat, lng: e.latlng.lng };
    updateRunwayDrawRubberLine();
}

function clearRunwayDrawingSessionLayers() {
    if (!runwayDrawingState?.sessionLayers?.length) {
        if (runwayDrawingState) runwayDrawingState.sessionLayers = [];
        return;
    }
    runwayDrawingState.sessionLayers.forEach(layer => {
        try { map.removeLayer(layer); } catch (_) { /* ignore */ }
    });
    runwayDrawingState.sessionLayers = [];
    if (runwayDrawingState.rubberLine) {
        try { runwayDrawingState.rubberLine.remove(); } catch (_) { /* ignore */ }
        runwayDrawingState.rubberLine = null;
    }
}

function refreshRunwayDrawingLayers() {
    if (!runwayDrawingState) return;

    clearRunwayDrawingSessionLayers();

    runwayDrawingState.runways.forEach(rwy => {
        const line = L.polyline(
            [[rwy.end1.lat, rwy.end1.lng], [rwy.end2.lat, rwy.end2.lng]],
            {
                color: '#f1c40f',
                weight: 7,
                opacity: 0.95,
                lineCap: 'butt'
            }
        ).addTo(map);
        runwayDrawingState.sessionLayers.push(line);

        [rwy.end1, rwy.end2].forEach(end => {
            const endpoint = L.marker([end.lat, end.lng], {
                interactive: false,
                icon: L.divIcon({
                    className: 'runway-end-marker-wrap',
                    html: '<div class="runway-end-marker"></div>',
                    iconSize: [10, 10],
                    iconAnchor: [5, 5]
                })
            }).addTo(map);
            runwayDrawingState.sessionLayers.push(endpoint);
        });

        const midLat = (rwy.end1.lat + rwy.end2.lat) / 2;
        const midLng = (rwy.end1.lng + rwy.end2.lng) / 2;
        const label = L.marker([midLat, midLng], {
            interactive: false,
            icon: L.divIcon({
                className: 'runway-label-marker-wrap',
                html: `<div class="runway-label-marker">${escapeHtml(rwy.name)}</div>`,
                iconSize: [52, 22],
                iconAnchor: [26, 11]
            })
        }).addTo(map);
        runwayDrawingState.sessionLayers.push(label);

        if (runwayDrawingState.mode !== 'path') {
            return;
        }

        ensureRunwayHasPaths(rwy);
        Object.keys(rwy.paths).forEach(des => {
            [
                { defaultKey: 'defaultArrival', key: 'arrivals', kind: 'arrival' },
                { defaultKey: 'defaultDeparture', key: 'departures', kind: 'departure' }
            ].forEach(({ defaultKey, key, kind }) => {
                const rwyIndex = runwayDrawingState.runways.indexOf(rwy);
                const drawInactivePath = (pts, isDirectional, variantId = null) => {
                    if (!pts || pts.length < 2) return;
                    const isActivePath = rwyIndex === runwayDrawingState.pathRunwayIndex &&
                        des === runwayDrawingState.pathDesignator &&
                        kind === runwayDrawingState.pathKind &&
                        (isDirectional
                            ? variantId === runwayDrawingState.pathVariantId
                            : !runwayDrawingState.pathVariantId);
                    if (isActivePath) return;

                    const pathLine = L.polyline(
                        pts.map(p => [p.lat, p.lng]),
                        {
                            color: kind === 'arrival' ? '#2ecc71' : '#3498db',
                            weight: 3,
                            opacity: 0.4,
                            dashArray: kind === 'arrival' ? '5, 6' : '9, 5',
                            lineCap: 'round',
                            lineJoin: 'round'
                        }
                    ).addTo(map);
                    runwayDrawingState.sessionLayers.push(pathLine);
                };

                drawInactivePath(rwy.paths[des][defaultKey], false);
                rwy.paths[des][key].forEach(variant => {
                    drawInactivePath(variant.waypoints, true, variant.id);
                });
            });
        });
    });

    if (runwayDrawingState.mode === 'path' && runwayDrawingState.pathPoints.length) {
        const kind = runwayDrawingState.pathKind;
        const activeLine = L.polyline(
            runwayDrawingState.pathPoints.map(p => [p.lat, p.lng]),
            {
                color: kind === 'arrival' ? '#27ae60' : '#2980b9',
                weight: 5,
                opacity: 0.9,
                dashArray: kind === 'arrival' ? '4, 5' : '8, 4',
                lineCap: 'round',
                lineJoin: 'round'
            }
        ).addTo(map);
        runwayDrawingState.sessionLayers.push(activeLine);

        runwayDrawingState.pathPoints.forEach((p, idx) => {
            const isDepartureStart = kind === 'departure' && idx === 0;
            const waypoint = L.marker([p.lat, p.lng], {
                interactive: false,
                icon: L.divIcon({
                    className: 'runway-end-marker-wrap',
                    html: `<div class="runway-end-marker${isDepartureStart ? ' runway-path-threshold-marker' : ''}"></div>`,
                    iconSize: [10, 10],
                    iconAnchor: [5, 5]
                })
            }).addTo(map);
            runwayDrawingState.sessionLayers.push(waypoint);
        });
    }

    if (runwayDrawingState.pendingStart) {
        const startMarker = L.marker(
            [runwayDrawingState.pendingStart.lat, runwayDrawingState.pendingStart.lng],
            {
                interactive: false,
                icon: L.divIcon({
                    className: 'runway-end-marker-wrap',
                    html: '<div class="runway-end-marker runway-end-marker-pending"></div>',
                    iconSize: [12, 12],
                    iconAnchor: [6, 6]
                })
            }
        ).addTo(map);
        runwayDrawingState.sessionLayers.push(startMarker);
    }

    updateRunwayDrawRubberLine();
}

function updateRunwayDrawRubberLine() {
    if (!runwayDrawingState) return;

    let start = null;
    if (runwayDrawingState.mode === 'path') {
        const pts = runwayDrawingState.pathPoints;
        start = pts.length ? pts[pts.length - 1] : null;
    } else {
        start = runwayDrawingState.pendingStart;
    }

    const cursor = runwayDrawingState.cursorLatLng;
    if (!start || !cursor) {
        if (runwayDrawingState.rubberLine) {
            runwayDrawingState.rubberLine.remove();
            runwayDrawingState.rubberLine = null;
        }
        return;
    }

    const rubberColor = runwayDrawingState.mode === 'path'
        ? (runwayDrawingState.pathKind === 'arrival' ? '#27ae60' : '#2980b9')
        : '#f39c12';

    const rubberLatLngs = [[start.lat, start.lng], [cursor.lat, cursor.lng]];
    if (!runwayDrawingState.rubberLine) {
        runwayDrawingState.rubberLine = L.polyline(rubberLatLngs, {
            color: rubberColor,
            weight: 4,
            opacity: 0.65,
            dashArray: '8, 8',
            lineCap: runwayDrawingState.mode === 'path' ? 'round' : 'butt'
        }).addTo(map);
    } else {
        runwayDrawingState.rubberLine.setStyle({ color: rubberColor });
        runwayDrawingState.rubberLine.setLatLngs(rubberLatLngs);
        if (!map.hasLayer(runwayDrawingState.rubberLine)) {
            runwayDrawingState.rubberLine.addTo(map);
        }
    }
}

function updateRunwayDrawUi() {
    if (!runwayDrawingState) return;

    const statusEl = document.getElementById('runwayDrawStatus');
    const listEl = document.getElementById('runwayDrawList');
    const countEl = document.getElementById('runwayDrawCount');
    const pathHintEl = document.getElementById('runwayPathDrawHint');
    const pathCountEl = document.getElementById('runwayPathWaypointCount');
    const finishBtn = document.getElementById('runwayPathFinishThresholdBtn');

    if (runwayDrawingState.mode === 'path') {
        if (statusEl) statusEl.style.display = 'none';
        const rwy = runwayDrawingState.runways[runwayDrawingState.pathRunwayIndex];
        const des = runwayDrawingState.pathDesignator || '';
        const kind = runwayDrawingState.pathKind;

        if (pathHintEl) {
            if (kind === 'arrival') {
                if (!isEditingDirectionalRunwayPathVariant()) {
                    pathHintEl.innerHTML = `Optional default <strong>arrival</strong> for runway <strong>${escapeHtml(des)}</strong>, or use <strong>+ Add directional variant</strong> to define only compass-specific approaches (no default required).`;
                } else {
                    pathHintEl.innerHTML = `Draw a directional <strong>arrival</strong> to runway <strong>${escapeHtml(des)}</strong>. Set traffic direction, click waypoints, and use <strong>Finish at threshold</strong>.`;
                }
            } else if (!isEditingDirectionalRunwayPathVariant()) {
                pathHintEl.innerHTML = `Optional default <strong>departure</strong> for runway <strong>${escapeHtml(des)}</strong>, or use <strong>+ Add directional variant</strong> to define only compass-specific routes (no default required).`;
            } else {
                pathHintEl.innerHTML = `Draw a directional <strong>departure</strong> for runway <strong>${escapeHtml(des)}</strong>. Choose variant and traffic direction, then click on the map.`;
            }
        }

        updateRunwayPathVariantControlsVisibility();

        const waypointCount = Math.max(
            0,
            kind === 'departure'
                ? runwayDrawingState.pathPoints.length - 1
                : runwayDrawingState.pathPoints.length
        );
        if (pathCountEl) {
            pathCountEl.textContent = waypointCount === 1 ? '1 waypoint' : `${waypointCount} waypoints`;
        }
        if (finishBtn) {
            const showFinish = kind === 'arrival' && runwayDrawingState.pathDrawingFollowCursor;
            finishBtn.style.display = showFinish ? 'inline-block' : 'none';
        }
        return;
    }

    if (statusEl) {
        statusEl.style.display = 'block';
        statusEl.textContent = runwayDrawingState.pendingStart
            ? 'Click the opposite end of the runway (second point).'
            : 'Click the first end of a runway, then click the opposite end.';
    }

    if (countEl) {
        const n = runwayDrawingState.runways.length;
        countEl.textContent = n === 1 ? '1 runway' : `${n} runways`;
    }

    if (listEl) {
        if (!runwayDrawingState.runways.length) {
            listEl.innerHTML = '<li style="color:#666;font-style:italic;">No runways yet</li>';
        } else {
            listEl.innerHTML = runwayDrawingState.runways
                .map((rwy, idx) => {
                    ensureRunwayHasPaths(rwy);
                    const counts = countRunwayPathVariants(rwy);
                    const pathSummary = `${counts.arrivals} arr / ${counts.departures} dep`;
                    return `<li><strong>${escapeHtml(rwy.name)}</strong> (${Math.round(rwy.heading)}°) — ${pathSummary}</li>`;
                })
                .join('');
        }
    }
}

function undoRunwayDrawAction() {
    if (!runwayDrawingState?.active) return;

    if (runwayDrawingState.mode === 'path') {
        if (runwayDrawingState.pathKind === 'departure') {
            if (runwayDrawingState.pathPoints.length > 1) {
                runwayDrawingState.pathPoints.pop();
            }
        } else if (runwayDrawingState.pathPoints.length) {
            runwayDrawingState.pathPoints.pop();
        }
        runwayDrawingState.pathDrawingFollowCursor = true;
        resetRunwayPathPreviewCursor();
        refreshRunwayDrawingLayers();
        updateRunwayDrawUi();
        return;
    }

    if (runwayDrawingState.pendingStart) {
        runwayDrawingState.pendingStart = null;
        runwayDrawingState.cursorLatLng = null;
    } else if (runwayDrawingState.runways.length) {
        runwayDrawingState.runways.pop();
    }

    refreshRunwayDrawingLayers();
    updateRunwayDrawUi();
}

function saveRunwayDrawing() {
    if (!runwayDrawingState?.active) return;

    if (runwayDrawingState.mode === 'runway' && runwayDrawingState.pendingStart) {
        alert('Finish the runway you started (second click) or use Undo to cancel that end.');
        return;
    }

    if (runwayDrawingState.mode === 'path') {
        commitPathEditingStateToRunway();
    }

    const marker = runwayDrawingState.marker;
    if (!marker?.airportData) {
        cancelRunwayDrawing(false);
        return;
    }

    marker.airportData.runways = runwayDrawingState.runways.map(rwy => normalizeRunwayRecord(rwy)).filter(Boolean);
    saveAirports();
    marker.setPopupContent(generateAirportPopupContent(marker.airportData, marker.getLatLng().lat, marker.getLatLng().lng));

    cancelRunwayDrawing(true);
    refreshCountryAirportsListIfVisible();
    alert('Runway data saved.');
}

function cancelRunwayDrawing(restoreMapView = true) {
    if (!runwayDrawingState) {
        setRunwayDrawToolbarVisible(false);
        map.getContainer().classList.remove('route-drawing-active');
        map.getContainer().classList.remove('route-drawing-panning');
        if (map.dragging && !map.dragging.enabled()) {
            map.dragging.enable();
        }
        return;
    }

    teardownRunwayDrawMapHandlers();
    clearRunwayDrawingSessionLayers();

    const marker = runwayDrawingState.marker;
    runwayDrawingState = null;

    setRunwayDrawToolbarVisible(false);
    map.getContainer().classList.remove('route-drawing-active');

    const statusEl = document.getElementById('runwayDrawStatus');
    if (statusEl) statusEl.style.display = 'block';

    showingSpecificAirports = false;

    if (marker) {
        syncAirportRunwayMapLayers(marker);
    }
    refreshAllAirportRunwayMapLayers();

    if (restoreMapView) {
        hideAllRoutesAndAirportsOnClickAway();
    }
}

/** Country name for an airport code (from loaded markers). */
function getAirportCountryByCode(code) {
    if (!code) return '';
    const marker = userMarkers.find(m => m.airportData && m.airportData.code === code);
    return marker?.airportData?.country || '';
}

/** Base (fixed) population for an airport code from marker data. */
function getAirportBasePopulationByCode(code) {
    if (!code) return 0;
    const marker = userMarkers.find(m => m.airportData && m.airportData.code === code);
    return Math.max(0, Number(marker?.airportData?.population || 0));
}

/**
 * Sliding-scale connection boost contributed to the connected airport.
 * Small airports add only a few people; large hubs add more.
 */
function calculateConnectionPopulationBoost(otherAirportBasePopulation, airportBasePopulation) {
    const otherPop = Math.max(0, Number(otherAirportBasePopulation || 0));
    const ownPop = Math.max(0, Number(airportBasePopulation || 0));
    if (otherPop <= 0) return 0;

    // Stronger network pull so large connected hubs materially shift demand.
    const BOOST_MULTIPLIER = 0.8;
    const BOOST_EXPONENT = 0.55;
    const rawBoost = Math.round(BOOST_MULTIPLIER * Math.pow(otherPop, BOOST_EXPONENT));
    const maxBoostPerConnection = Math.max(10, Math.round(ownPop * 0.02));
    return Math.max(1, Math.min(rawBoost, maxBoostPerConnection));
}

/**
 * Effective population = fixed base + network boost from all connected airports.
 * Uses unique neighboring airport codes so bidirectional route entries are not double-counted.
 */
function getEffectiveAirportPopulationByCode(code) {
    const airportCode = (code || '').toUpperCase();
    if (!airportCode) return 0;

    const basePopulation = getAirportBasePopulationByCode(airportCode);
    const connectedAirportCodes = new Set();

    routesList.forEach(route => {
        const departureCode = (getRouteAirportCode(route, 'departure') || '').toUpperCase();
        const arrivalCode = (getRouteAirportCode(route, 'arrival') || '').toUpperCase();
        if (!departureCode || !arrivalCode) return;

        if (departureCode === airportCode && arrivalCode !== airportCode) {
            connectedAirportCodes.add(arrivalCode);
        } else if (arrivalCode === airportCode && departureCode !== airportCode) {
            connectedAirportCodes.add(departureCode);
        }
    });

    let networkBoost = 0;
    connectedAirportCodes.forEach(otherCode => {
        const otherBasePopulation = getAirportBasePopulationByCode(otherCode);
        networkBoost += calculateConnectionPopulationBoost(otherBasePopulation, basePopulation);
    });

    return Math.round(basePopulation + networkBoost);
}

/** Format values as "value (+x%)" based on base vs effective. */
function formatValueWithBonus(baseValue, effectiveValue, options = {}) {
    const { suffix = '', minBonusToShow = 1, showZeroBonus = false } = options;
    const base = Math.max(0, Number(baseValue || 0));
    const effective = Math.max(0, Number(effectiveValue || 0));
    const formattedEffective = `${Math.round(effective).toLocaleString()}${suffix}`;

    if (base <= 0) return formattedEffective;

    const bonus = Math.max(0, Math.round(effective - base));
    if (bonus <= 0) {
        return showZeroBonus ? `${formattedEffective} (+0)` : formattedEffective;
    }
    if (bonus < minBonusToShow) return formattedEffective;
    return `${formattedEffective} (+${bonus.toLocaleString()})`;
}

/** Base/effective demand comparison for one directional route. */
function getRouteDemandComparison(route) {
    const departureCode = getRouteAirportCode(route, 'departure');
    const arrivalCode = getRouteAirportCode(route, 'arrival');
    const departureCountry = getAirportCountryByCode(departureCode);
    const arrivalCountry = getAirportCountryByCode(arrivalCode);

    const depBasePop = getAirportBasePopulationByCode(departureCode);
    const arrBasePop = getAirportBasePopulationByCode(arrivalCode);
    const depEffectivePop = getEffectiveAirportPopulationByCode(departureCode) || depBasePop;
    const arrEffectivePop = getEffectiveAirportPopulationByCode(arrivalCode) || arrBasePop;

    const baseLow = Math.min(depBasePop, arrBasePop);
    const baseHigh = Math.max(depBasePop, arrBasePop);
    const effectiveLow = Math.min(depEffectivePop, arrEffectivePop);
    const effectiveHigh = Math.max(depEffectivePop, arrEffectivePop);

    return {
        baseMetrics: deriveRouteDemandMetrics(baseLow, baseHigh, departureCountry, arrivalCountry),
        effectiveMetrics: deriveRouteDemandMetrics(effectiveLow, effectiveHigh, departureCountry, arrivalCountry)
    };
}

/**
 * Weekly directional O&D passenger pool: gravity-style weighted population × base rate × demand multiplier.
 * Connecting / multi-leg demand is not included (direct only).
 */
function calculatePassengerPool(popLow, popHigh, departureCountry, arrivalCountry) {
    const weightedPop = Math.round(Math.pow(popLow, 0.7) * Math.pow(popHigh, 0.3));
    const baseTravelRate = 0.0005;
    let demandFactor = 1.0;

    if (popHigh > 5000000) {
        demandFactor *= 1.5;
    } else if (popHigh > 1000000) {
        demandFactor *= 1.2;
    } else if (popHigh < 500000) {
        demandFactor *= 0.6;
    }

    if (departureCountry === arrivalCountry) {
        demandFactor *= 1.3;
    } else {
        if (popHigh > 5000000 && popLow > 1000000) {
            demandFactor *= 1.1;
        } else {
            demandFactor *= 0.7;
        }
    }

    const passengerPool = Math.round(weightedPop * baseTravelRate * demandFactor);

    return {
        passengerPool: Math.max(0, passengerPool),
        weightedPopulation: weightedPop,
        demandFactor
    };
}

/** Route list fields + human-readable weekly demand label (replaces former frequency-band recommendation). */
function deriveRouteDemandMetrics(popLow, popHigh, departureCountry, arrivalCountry) {
    const poolResult = calculatePassengerPool(popLow, popHigh, departureCountry, arrivalCountry);
    return {
        weightedPopulation: poolResult.weightedPopulation,
        passengerPool: poolResult.passengerPool,
        demandFactor: poolResult.demandFactor,
        recommendedFrequency: `${poolResult.passengerPool.toLocaleString()} pax/wk`,
        weeklyFlights: 0
    };
}

/** Recompute demand fields from endpoint populations and countries (e.g. after load or airport data change). */
function applyDemandModelToDirectionalRoute(route) {
    const depCode = getRouteAirportCode(route, 'departure');
    const arrCode = getRouteAirportCode(route, 'arrival');
    const depBasePop = getAirportBasePopulationByCode(depCode) || route.departurePopulation;
    const arrBasePop = getAirportBasePopulationByCode(arrCode) || route.arrivalPopulation;
    const depPop = getEffectiveAirportPopulationByCode(depCode) || depBasePop;
    const arrPop = getEffectiveAirportPopulationByCode(arrCode) || arrBasePop;
    if (depPop <= 0 || arrPop <= 0) return;

    route.departurePopulation = depPop;
    route.arrivalPopulation = arrPop;
    route.departureBasePopulation = depBasePop;
    route.arrivalBasePopulation = arrBasePop;

    const popLow = Math.min(depPop, arrPop);
    const popHigh = Math.max(depPop, arrPop);
    const depCountry = getAirportCountryByCode(depCode);
    const arrCountry = getAirportCountryByCode(arrCode);

    const metrics = deriveRouteDemandMetrics(popLow, popHigh, depCountry, arrCountry);
    route.weightedPopulation = metrics.weightedPopulation;
    route.passengerPool = metrics.passengerPool;
    route.demandFactor = metrics.demandFactor;
    route.recommendedFrequency = metrics.recommendedFrequency;
    route.weeklyFlights = metrics.weeklyFlights;
}

// Helper function to get airport code by airport name (handles both old names and new names with country codes)
function getAirportCode(airportName) {
    const marker = findAirportMarkerByName(airportName);
    if (marker && marker.airportData) {
        return marker.airportData.code;
    }
    
    // Fallback to parsing popup content
    for (let i = 0; i < userMarkers.length; i++) {
        const marker = userMarkers[i];
        const popup = marker.getPopup();
        const content = popup.getContent();
        const parser = new DOMParser();
        const doc = parser.parseFromString(content, 'text/html');
        
        const name = doc.querySelector('h3').textContent;
        if (name === airportName) {
            const code = doc.querySelector('p:nth-child(4)').textContent.replace('Code: ', '');
            return code;
        }
    }
    
    // Final fallback to hardcoded mappings
    const airportMappings = {
        'El Dorado International Airport': 'BOG',
        'Gustavo Rojas Pinilla International Airport': 'ADZ',
        'Alcides Fernández Airport': 'ACD',
        'José María Córdova International Airport': 'MDE',
        'Rafael Núñez International Airport': 'CTG',
        'Alfonso Bonilla Aragón International Airport': 'CLO',
        'Ernesto Cortissoz International Airport': 'BAQ',
        'Palonegro International Airport': 'BGA',
        'Simón Bolívar International Airport': 'CCS',
        'Camilo Daza International Airport': 'CUC',
        'La Florida Airport': 'TME',
        'Yariguíes Airport': 'EJA',
        'Gustavo Artunduaga Paredes Airport': 'FLA',
        'Gerardo Tobar López Airport': 'BUN',
        'Juan H. White Airport': 'CAQ',
        'Los Garzones Airport': 'MTR',
        'Almirante Padilla Airport': 'RCH',
        'Gonzalo Mejía Airport': 'MZL',
        'Jorge Isaacs Airport': 'LET',
        'Alberto Lleras Camargo Airport': 'SOX',
        'El Carano Airport': 'UIB',
        'Gustavo Rojas Pinilla Airport': 'ADZ',
        'El Embrujo Airport': 'PVA'
    };
    
    return airportMappings[airportName] || 'N/A'; // Return N/A if airport not found
}

// Enhanced function to get airport code with context (handles duplicate names)
function getAirportCodeWithContext(airportName, context = null) {
    // Handle the specific case of Simón Bolívar International Airport
    if (airportName === 'Simón Bolívar International Airport') {
        // If we have context (like coordinates or country), use it to determine the correct code
        if (context) {
            // Check if context contains coordinates or other identifying info
            if (typeof context === 'string' && context.includes('|')) {
                const parts = context.split('|');
                if (parts.length >= 4) {
                    const lat = parseFloat(parts[2]);
                    const lng = parseFloat(parts[3]);
                    
                    // SMR (Santa Marta) coordinates: approximately 11.1197°N, 74.2306°W
                    // CCS (Caracas) coordinates: approximately 10.6031°N, 66.9910°W
                    if (lat > 11.0 && lng < -74.0) {
                        return 'SMR'; // Santa Marta
                    } else if (lat < 11.0 && lng > -67.0) {
                        return 'CCS'; // Caracas
                    }
                }
            }
        }
        // Default to CCS if no context or unclear
        return 'CCS';
    }
    
    // For all other airports, use the standard lookup
    return getAirportCode(airportName);
}

// Function to get airport code from route data (handles stored codes and fallback)
function getRouteAirportCode(route, field) {
    if (field === 'departure') {
        return route.departureCode || getAirportCodeWithContext(route.departure, route.departure);
    } else if (field === 'arrival') {
        return route.arrivalCode || getAirportCodeWithContext(route.arrival, route.arrival);
    }
    return null;
}

// Function to check if a route involves a specific airport by code (more reliable than name matching)
function routeInvolvesAirport(route, airportCode) {
    const departureCode = getRouteAirportCode(route, 'departure');
    const arrivalCode = getRouteAirportCode(route, 'arrival');
    return departureCode === airportCode || arrivalCode === airportCode;
}

// Populate aircraft checkboxes in airport form
function populateAircraftCheckboxes() {
    const checkboxesContainer = document.getElementById('aircraftCheckboxes');
    if (!checkboxesContainer) return;
    
    if (aircraftList.length === 0) {
        checkboxesContainer.innerHTML = '<div style="text-align: center; color: #A68A64; font-style: italic; padding: 10px;">No aircraft types available. Add aircraft types first.</div>';
        return;
    }
    
    let checkboxesHTML = '';
    aircraftList.forEach((aircraft, index) => {
        checkboxesHTML += `
            <div class="aircraft-checkbox-item">
                <label>
                    <input type="checkbox" value="${aircraft.model}" data-index="${index}">
                    <div class="aircraft-info">
                        <span>${aircraft.model}</span>
                        <span class="aircraft-specs">${formatAircraftSpecsLine(aircraft)}</span>
                    </div>
                </label>
            </div>
        `;
    });
    
    checkboxesContainer.innerHTML = checkboxesHTML;
}

// Get selected aircraft types from checkboxes
function getSelectedAircraftTypes() {
    const checkboxes = document.querySelectorAll('#aircraftCheckboxes input[type="checkbox"]:checked');
    const selectedAircraft = [];
    
    checkboxes.forEach(checkbox => {
        const index = parseInt(checkbox.getAttribute('data-index'));
        if (aircraftList[index]) {
            selectedAircraft.push(aircraftList[index].model);
        }
    });
    
    return selectedAircraft;
}

// Set selected aircraft types in checkboxes (for editing)
function setSelectedAircraftTypes(selectedAircraft) {
    const checkboxes = document.querySelectorAll('#aircraftCheckboxes input[type="checkbox"]');
    
    checkboxes.forEach(checkbox => {
        const aircraftModel = checkbox.value;
        checkbox.checked = selectedAircraft && selectedAircraft.includes(aircraftModel);
    });
}

// Show routes for a specific airport
function showRoutesForAirport(airportName, lat, lng, airportCode = null) {
    console.log(`🛫 Showing routes for airport: ${airportName} (NEW BEHAVIOR)`);
    
    // Clear any existing route focus to ensure consistent behavior
    clearRouteFocus(false);
    
    // Get the airport code - use provided code or try to find it
    let resolvedAirportCode = airportCode;
    if (!resolvedAirportCode) {
        // Try to find the airport code from the marker data
        for (let i = 0; i < userMarkers.length; i++) {
            const marker = userMarkers[i];
            if (marker.airportData && marker.airportData.name === airportName) {
                resolvedAirportCode = marker.airportData.code;
                break;
            }
        }
        
        // Fallback to context-based resolution
        if (!resolvedAirportCode) {
            resolvedAirportCode = getAirportCodeWithContext(airportName, airportName);
        }
    }
    
    console.log(`🛫 Airport code for ${airportName}: ${resolvedAirportCode}`);
    
    // Find routes that involve this airport (both departing from and arriving at)
    // Exclude positioning routes from airport route networks
    const relevantRoutes = [];
    routesList.forEach((route, index) => {
        // Use airport code matching instead of name matching to avoid conflicts with duplicate names
        if (routeInvolvesAirport(route, resolvedAirportCode) && !route.isPositioningRoute) {
            relevantRoutes.push({ route, index });
        }
    });
    
    if (relevantRoutes.length === 0) {
        console.log(`No routes found involving ${airportName}`);
        return;
    }
    
    console.log(`🛫 Showing ${relevantRoutes.length} routes involving ${airportName}`);
    
    // Set the filtered airport for routes display
    filteredAirportForRoutes = airportName;
    
    // Update the routes list to show only routes involving this airport
    updateRoutesList();
    
    // Filter airports to show only the selected airport and connected airports
    filterAirportsForRoutes(airportName, relevantRoutes);
    
    // Hide all route lines first, then show only relevant ones
    routeLines.forEach((polyline, index) => {
        if (polyline && typeof polyline.setStyle === 'function') {
            try {
                // Check if this route involves the selected airport using airport code matching
                const route = routesList[index];
                const isRelevantRoute = route && routeInvolvesAirport(route, resolvedAirportCode);
                
                if (isRelevantRoute) {
                    // Show and style relevant routes
                    polyline.setStyle({
                        color: '#4e8ca0',
                        weight: 3,
                        opacity: 0.8,
                        dashArray: '5, 5'
                    });
                    // Store that this route is clickable
                    polyline._isClickable = true;
                    const departureCode = getRouteAirportCode(route, 'departure');
                    const arrivalCode = getRouteAirportCode(route, 'arrival');
                    console.log(`✅ Showing route: ${departureCode} → ${arrivalCode}`);
                } else {
                    // Hide irrelevant routes using opacity instead of removing
                    polyline.setStyle({ opacity: 0 });
                    // Store that this route is not clickable
                    polyline._isClickable = false;
                    if (route) {
                        const departureCode = getRouteAirportCode(route, 'departure');
                        const arrivalCode = getRouteAirportCode(route, 'arrival');
                        console.log(`🚫 Hiding route: ${departureCode} → ${arrivalCode}`);
                    } else {
                        console.log(`🚫 Hiding route: unknown`);
                    }
                }
            } catch (error) {
                console.warn(`Error updating route line ${index} visibility:`, error);
            }
        } else {
            console.warn(`Invalid route line ${index} for airport filtering:`, polyline);
        }
    });
    
    // Create bounds to show all relevant routes
    const bounds = L.latLngBounds([[lat, lng]]);
    
    relevantRoutes.forEach(({ route }) => {
        bounds.extend([route.departureCoords.lat, route.departureCoords.lng]);
        bounds.extend([route.arrivalCoords.lat, route.arrivalCoords.lng]);
    });
    
    // Fit map to show all relevant routes with padding
    map.fitBounds(bounds, { padding: [100, 100] });
    
    // Update all airport popup buttons to reflect current state
    updateAirportPopupButtons();
    
    // Update the routes button text to indicate filtering is active
    const toggleRoutesBtn = document.getElementById('toggleRoutes');
    if (toggleRoutesBtn) {
        toggleRoutesBtn.textContent = 'Hide Routes';
        toggleRoutesBtn.disabled = false; // Re-enable the button
        console.log('✅ Updated routes button text to indicate filtering is active');
    }
}

// Hide routes when departures/arrivals board is closed
function hideRoutesForAirport() {
    console.log('🛫 Hiding routes (departures/arrivals board closed)');
    
    // Hide all routes - ensure they're properly removed from map to prevent them staying visible
    routeLines.forEach((polyline, index) => {
        if (polyline) {
            try {
                // Remove from map to ensure they don't stay visible
                if (map.hasLayer(polyline)) {
                    map.removeLayer(polyline);
                }
                // Also set opacity to 0 and mark as not clickable for safety
                if (typeof polyline.setStyle === 'function') {
                    polyline.setStyle({ opacity: 0 });
                }
                polyline._isClickable = false;
                console.log(`  Hidden and removed route line ${index}`);
            } catch (error) {
                console.warn(`Error hiding route line ${index}:`, error);
            }
        }
    });
    
    // Reset filtering state
    window.airportsFilteredForRoutes = false;
    window.filteredAirportName = null;
    filteredAirportForRoutes = null;
    
    // Hide all airports (airports are hidden by default, shown only on interaction)
    // BUT: Only hide if airportsVisible is false, otherwise respect the visibility state
    if (!airportsVisible) {
        userMarkers.forEach(marker => {
            if (marker.airportData) {
                if (markerClusterGroup) {
                    if (markerClusterGroup.hasLayer(marker)) {
                        markerClusterGroup.removeLayer(marker);
                    }
                } else {
                    if (map.hasLayer(marker)) {
                        map.removeLayer(marker);
                    }
                }
            }
        });
    }
    
    // Update all airport popup buttons
    updateAirportPopupButtons();
    
    // Hide any active airport city tooltip
    hideAirportCityTooltip();
    
    console.log('✅ All routes hidden and removed from map');
}

// Show airport city tooltip on hover
function showAirportCityTooltip(airportData, lat, lng) {
    // Remove existing tooltip if any
    hideAirportCityTooltip();
    
    // Create tooltip element
    const tooltip = L.tooltip({
        direction: 'top',
        offset: [0, -10],
        opacity: 0.9,
        className: 'airport-city-tooltip'
    })
    .setContent(`
        <div style="
            background: #19363c;
            color: white;
            padding: 6px 10px;
            border-radius: 4px;
            font-size: 12px;
            font-weight: 500;
            font-family: 'League Spartan', Arial, sans-serif;
            box-shadow: 0 2px 8px rgba(0,0,0,0.3);
            border: 1px solid #4e8ca0;
        ">
            ${airportData.city}
        </div>
    `)
    .setLatLng([lat, lng])
    .addTo(map);
    
    // Store reference for removal
    window.currentAirportTooltip = tooltip;
}

// Hide airport city tooltip
function hideAirportCityTooltip() {
    if (window.currentAirportTooltip) {
        map.removeLayer(window.currentAirportTooltip);
        window.currentAirportTooltip = null;
    }
}

// Helper function to get relevant routes for an airport
function getRelevantRoutesForAirport(airportName, airportCode = null) {
    const relevantRoutes = [];
    
    // Get the airport code - use provided code or try to find it
    let resolvedAirportCode = airportCode;
    if (!resolvedAirportCode) {
        // Try to find the airport code from the marker data
        for (let i = 0; i < userMarkers.length; i++) {
            const marker = userMarkers[i];
            if (marker.airportData && marker.airportData.name === airportName) {
                resolvedAirportCode = marker.airportData.code;
                break;
            }
        }
        
        // Fallback to context-based resolution
        if (!resolvedAirportCode) {
            resolvedAirportCode = getAirportCodeWithContext(airportName, airportName);
        }
    }
    
    routesList.forEach((route, index) => {
        if (routeInvolvesAirport(route, resolvedAirportCode) && !route.isPositioningRoute) {
            relevantRoutes.push({ route, index });
        }
    });
    return relevantRoutes;
}

// Filter airports to show only the selected airport and connected airports
function filterAirportsForRoutes(selectedAirportName, relevantRoutes) {
    // Collect all connected airport names
    const connectedAirportNames = new Set();
    connectedAirportNames.add(selectedAirportName); // Always include the selected airport
    
    relevantRoutes.forEach(({ route }) => {
        connectedAirportNames.add(route.departure);
        connectedAirportNames.add(route.arrival);
    });
    
    console.log(`🔍 Filtering airports. Showing only: ${Array.from(connectedAirportNames).join(', ')}`);
    
    // Hide all airports first
    userMarkers.forEach(marker => {
        if (marker.airportData) {
            if (markerClusterGroup) {
                markerClusterGroup.removeLayer(marker);
            } else {
                map.removeLayer(marker);
            }
        }
    });
    
    // Show only connected airports
    userMarkers.forEach(marker => {
        if (marker.airportData) {
            const airportName = marker.airportData.name;
            if (connectedAirportNames.has(airportName)) {
                console.log(`✅ Showing connected airport: ${airportName}`);
                if (markerClusterGroup) {
                    markerClusterGroup.addLayer(marker);
                } else {
                    marker.addTo(map);
                }
            }
        }
    });
    
    // Set a flag to indicate we're in filtered mode
    window.airportsFilteredForRoutes = true;
    window.filteredAirportName = selectedAirportName;
}

// Reset airport filtering to show all airports
function resetAirportFiltering() {
    if (!window.airportsFilteredForRoutes) {
        console.log('Not in filtered mode - no reset needed');
        return; // Not in filtered mode
    }
    
    console.log('🔄 Resetting airport filtering - showing all airports');
    console.log('Current routesVisible before reset:', routesVisible);
    
    // Show all airports - ensure they're properly added to map
    userMarkers.forEach(marker => {
        if (marker.airportData) {
            // Check if marker is already in the map/cluster group to avoid duplicates
            if (markerClusterGroup) {
                if (!markerClusterGroup.hasLayer(marker)) {
                    markerClusterGroup.addLayer(marker);
                }
            } else {
                if (!map.hasLayer(marker)) {
                    marker.addTo(map);
                }
            }
        }
    });
    
    // Restore routes to their global visibility state
    routeLines.forEach((polyline, index) => {
        if (polyline && typeof polyline.setStyle === 'function') {
            try {
                if (routesVisible) {
                    // Show routes with standard styling if they should be visible globally
                    polyline.setStyle({
                        color: '#4e8ca0',
                        weight: 3,
                        opacity: 0.8,
                        dashArray: '8, 4',
                        lineCap: 'round',
                        lineJoin: 'round'
                    });
                    polyline._isClickable = true;
                    console.log(`  Restored route line ${index} to visible state`);
                } else {
                    // Hide routes if they should be hidden globally
                    polyline.setStyle({ opacity: 0 });
                    polyline._isClickable = false;
                    console.log(`  Restored route line ${index} to hidden state`);
                }
            } catch (error) {
                console.warn(`Error updating route line ${index} during reset:`, error);
            }
        }
    });
    
    // Update routes button to reflect current global state
    const toggleRoutesBtn = document.getElementById('toggleRoutes');
    if (toggleRoutesBtn) {
        if (routesVisible) {
            toggleRoutesBtn.textContent = '🗺️ Hide Routes';
            toggleRoutesBtn.disabled = false;
        } else {
            toggleRoutesBtn.textContent = '🗺️ Show Routes';
            toggleRoutesBtn.disabled = false;
        }
    }
    
    // Clear filtering flags
    window.airportsFilteredForRoutes = false;
    window.filteredAirportName = null;
    filteredAirportForRoutes = null;
    
    // Update all airport popup buttons
    updateAirportPopupButtons();
    
    // Hide any active airport city tooltip
    hideAirportCityTooltip();
    
    console.log('✅ Airport filtering reset - all airports shown, routes restored to global state');
}

// Update all airport popup buttons to show correct text
function updateAirportPopupButtons() {
    userMarkers.forEach(marker => {
        if (marker.airportData) {
            // Update the popup content to reflect current filtering state
            updateAirportPopupContent(marker);
        }
    });
}

// Global variable to store current range circle
let currentRangeCircle = null;

// Show range from airport function
function showRangeFromAirport(airportName, lat, lng) {
    // Store the selected airport data
    window.selectedAirportForRange = { name: airportName, lat: lat, lng: lng };
    
    // Show the aircraft selection modal
    showAircraftSelectionModal();
}

// Show aircraft selection modal
function showAircraftSelectionModal() {
    const modal = document.getElementById('aircraftSelectionModal');
    const airportNameSpan = document.getElementById('selectedAirportName');
    
    if (window.selectedAirportForRange) {
        airportNameSpan.textContent = window.selectedAirportForRange.name;
    }
    
    // Populate aircraft list
    populateAircraftSelectionList();
    
    // Show the modal
    modal.style.display = 'block';
}

// Populate aircraft selection list
function populateAircraftSelectionList() {
    const aircraftListElement = document.getElementById('aircraftSelectionList');
    
    if (aircraftList.length === 0) {
        aircraftListElement.innerHTML = '<div class="no-airports">No aircraft types available. Add aircraft types first.</div>';
        return;
    }
    
    let listHTML = '';
    aircraftList.forEach((aircraft, index) => {
        listHTML += `
            <div class="aircraft-selection-item" onclick="selectAircraftForRange(${index})">
                <div>
                    <h5>${aircraft.model}</h5>
                    <p>Speed: ${aircraft.speed} km/h${aircraft.capacity != null && Number.isFinite(Number(aircraft.capacity)) ? ` · ${Number(aircraft.capacity)} pax` : ''}</p>
                </div>
                <div class="aircraft-range">${aircraft.range} km</div>
            </div>
        `;
    });
    
    aircraftListElement.innerHTML = listHTML;
}

// Select aircraft for range display
function selectAircraftForRange(aircraftIndex) {
    const aircraft = aircraftList[aircraftIndex];
    const airport = window.selectedAirportForRange;
    
    if (!aircraft || !airport) return;
    
    // Clear any existing range circle
    clearRangeCircle();
    
    // Create range circle
    currentRangeCircle = L.circle([airport.lat, airport.lng], {
        radius: aircraft.range * 1000, // Convert km to meters
        color: '#27ae60',
        fillColor: '#27ae60',
        fillOpacity: 0.1,
        weight: 3,
        opacity: 0.8
    }).addTo(map);
    
    // Add popup to range circle
    currentRangeCircle.bindPopup(`
        <div style="text-align: center;">
            <h4 style="margin: 0 0 8px 0; color: #19363c;">${aircraft.model} Range</h4>
            <p style="margin: 4px 0; color: #19363c;"><strong>From:</strong> ${airport.name}</p>
            <p style="margin: 4px 0; color: #19363c;"><strong>Range:</strong> ${aircraft.range} km</p>
            <p style="margin: 4px 0; color: #19363c;"><strong>Speed:</strong> ${aircraft.speed} km/h</p>
            ${aircraft.capacity != null && Number.isFinite(Number(aircraft.capacity)) ? `<p style="margin: 4px 0; color: #19363c;"><strong>Capacity:</strong> ${Number(aircraft.capacity)} passengers</p>` : ''}
            <div style="margin-top: 10px;">
                <button onclick="clearRangeCircle()" 
                        style="padding: 6px 12px; background: #e74c3c; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 11px;">
                    Clear Range
                </button>
            </div>
        </div>
    `);
    
    // Fit map to show the range circle
    map.fitBounds(currentRangeCircle.getBounds(), { padding: [50, 50] });
    
    // Hide the modal
    hideAircraftSelectionModal();
}

// Clear range circle
function clearRangeCircle() {
    if (currentRangeCircle) {
        map.removeLayer(currentRangeCircle);
        currentRangeCircle = null;
    }
}

// Hide aircraft selection modal
function hideAircraftSelectionModal() {
    const modal = document.getElementById('aircraftSelectionModal');
    modal.style.display = 'none';
    window.selectedAirportForRange = null;
}

// Population gathering functions
let currentPopulationData = null;

// Show/hide population form elements based on selection
function handlePopulationRadiusChange() {
    const radiusSelect = document.getElementById('populationRadius');
    const manualGroup = document.getElementById('manualPopulationGroup');
    const autoGroup = document.getElementById('autoPopulationGroup');
    
    if (!radiusSelect || !manualGroup || !autoGroup) return;
    
    const selectedValue = radiusSelect.value;
    
    if (selectedValue === 'manual') {
        manualGroup.style.display = 'block';
        autoGroup.style.display = 'none';
    } else if (selectedValue && selectedValue !== '') {
        manualGroup.style.display = 'none';
        autoGroup.style.display = 'block';
        // Trigger population gathering if coordinates are available
        gatherPopulationData();
    } else {
        manualGroup.style.display = 'none';
        autoGroup.style.display = 'none';
    }
}

// Gather population data for the selected radius
async function gatherPopulationData() {
    const radiusSelect = document.getElementById('populationRadius');
    
    if (!radiusSelect.value || radiusSelect.value === 'manual') {
        return;
    }
    
    // Get coordinates - either from editing marker or form input
    let coordResult = null;
    let coordinates = '';
    
    if (window.editingMarker) {
        // Editing existing airport - use marker coordinates
        const markerLatLng = window.editingMarker.getLatLng();
        coordResult = { lat: markerLatLng.lat, lng: markerLatLng.lng };
        coordinates = `${markerLatLng.lat.toFixed(6)}, ${markerLatLng.lng.toFixed(6)}`;
        console.log('Using marker coordinates for population:', coordResult);
    } else {
        // Adding new airport - get from form
        coordinates = document.getElementById('coordinates').value;
        if (!coordinates) {
            showPopulationError('Please enter coordinates first');
            return;
        }
        
        // Parse coordinates from format like "8°30′00″N 77°16′28″W"
        coordResult = parseCoordinates(coordinates);
        if (!coordResult) {
            showPopulationError('Invalid coordinates format');
            return;
        }
        console.log('Using form coordinates for population:', coordResult);
    }
    
    const radius = parseInt(radiusSelect.value);
    showPopulationLoading();
    
    try {
        // Use a population estimation service
        const population = await estimatePopulationInRadius(coordResult.lat, coordResult.lng, radius);
        showPopulationResult(population, radius);
        currentPopulationData = population;
    } catch (error) {
        console.error('Error gathering population data:', error);
        showPopulationError('Failed to gather population data');
    }
}

// Population data cache to avoid repeated API calls
const populationCache = new Map();

// Function to clear population cache (useful for testing)
function clearPopulationCache() {
    populationCache.clear();
    console.log('🗑️ Population cache cleared');
}

// Make clearPopulationCache available globally for testing
window.clearPopulationCache = clearPopulationCache;

// Get population data from coordinate-based API using multiple reliable sources
async function getCoordinateBasedPopulation(lat, lng, radiusKm) {
    try {
        console.log(`🌍 Getting population data for ${lat.toFixed(6)}, ${lng.toFixed(6)} with ${radiusKm}km radius`);
        
        // Method 1: Try OpenCage Geocoding API (free tier available)
        try {
            const openCageResult = await getOpenCagePopulationData(lat, lng, radiusKm);
            if (openCageResult) {
                console.log(`✅ OpenCage API success: ${openCageResult.total} people`);
                return openCageResult;
            }
        } catch (error) {
            console.log('❌ OpenCage API failed:', error.message);
        }
        
        // Method 2: Try GeoNames API (free, reliable)
        try {
            const geoNameResult = await getGeoNamesPopulationData(lat, lng, radiusKm);
            if (geoNameResult) {
                console.log(`✅ GeoNames API success: ${geoNameResult.total} people`);
                return geoNameResult;
            }
        } catch (error) {
            console.log('❌ GeoNames API failed:', error.message);
        }
        
        // Method 3: Try BigDataCloud with enhanced population estimation
        try {
            const bigDataResult = await getBigDataCloudPopulationData(lat, lng, radiusKm);
            if (bigDataResult) {
                console.log(`✅ BigDataCloud API success: ${bigDataResult.total} people`);
                return bigDataResult;
            }
        } catch (error) {
            console.log('❌ BigDataCloud API failed:', error.message);
        }
        
        throw new Error('All coordinate-based APIs failed');
        
    } catch (error) {
        throw new Error(`Coordinate-based API failed: ${error.message}`);
    }
}

// Get country information from coordinates using reverse geocoding
async function getCountryFromCoordinates(lat, lng) {
    try {
        // Use a free reverse geocoding service
        const response = await fetch(
            `https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=${lat}&longitude=${lng}&localityLanguage=en`,
            {
                headers: {
                    'Accept': 'application/json'
                }
            }
        );
        
        if (!response.ok) {
            throw new Error('Reverse geocoding failed');
        }
        
        const data = await response.json();
        
        if (data && data.countryCode && data.countryName) {
            return {
                countryCode: data.countryCode,
                countryName: data.countryName,
                city: data.city || data.locality || 'Unknown'
            };
        }
        
        throw new Error('No country data found');
        
    } catch (error) {
        // Fallback to our internal country detection
        const countryCode = getCountryCode(lat, lng);
        const countryName = getCountryName(countryCode);
        return {
            countryCode: countryCode,
            countryName: countryName,
            city: 'Unknown'
        };
    }
}

// Get country population density from API
async function getCountryPopulationDensityFromAPI(countryCode) {
    try {
        // Use REST Countries API to get population and area data
        const response = await fetch(`https://restcountries.com/v3.1/alpha/${countryCode.toLowerCase()}`);
        
        if (!response.ok) {
            throw new Error('Country API request failed');
        }
        
        const data = await response.json();
        
        if (data && data[0]) {
            const country = data[0];
            const population = country.population || 0;
            const area = country.area || 1; // Avoid division by zero
            
            // Calculate density (people per km²)
            const density = population / area;
            return density;
        }
        
        throw new Error('No country data found');
        
    } catch (error) {
        // Fallback to our internal density data
        const countryData = getCountryPopulationDensity(0, 0); // Will use countryCode
        return countryData.density;
    }
}

// Get country name from country code
function getCountryName(countryCode) {
    const countryNames = {
        'USA': 'United States',
        'CAN': 'Canada',
        'MEX': 'Mexico',
        'DEU': 'Germany',
        'GBR': 'United Kingdom',
        'FRA': 'France',
        'CHN': 'China',
        'JPN': 'Japan',
        'IND': 'India',
        'COL': 'Colombia',
        'BRA': 'Brazil',
        'ARG': 'Argentina',
        'PER': 'Peru',
        'CHL': 'Chile',
        'ECU': 'Ecuador',
        'VEN': 'Venezuela',
        'BOL': 'Bolivia',
        'URY': 'Uruguay',
        'PRY': 'Paraguay'
    };
    
    return countryNames[countryCode] || 'Unknown Country';
}

// Get population data from OpenCage Geocoding API
async function getOpenCagePopulationData(lat, lng, radiusKm) {
    try {
        // OpenCage provides detailed location information including population data
        const response = await fetch(
            `https://api.opencagedata.com/geocode/v1/json?q=${lat}+${lng}&key=YOUR_API_KEY&no_annotations=0&limit=1`,
            {
                headers: {
                    'Accept': 'application/json'
                }
            }
        );
        
        if (!response.ok) {
            throw new Error('OpenCage API request failed');
        }
        
        const data = await response.json();
        
        if (data && data.results && data.results[0]) {
            const result = data.results[0];
            const components = result.components || {};
            
            // Try to get population from various fields
            let population = 0;
            if (components.population) {
                population = parseInt(components.population);
            } else if (components.city && components.population_city) {
                population = parseInt(components.population_city);
            } else if (components.town && components.population_town) {
                population = parseInt(components.population_town);
            }
            
            // If no direct population, estimate based on location type and coordinates
            if (population === 0) {
                population = estimatePopulationFromLocationData(result, lat, lng, radiusKm);
            }
            
            return {
                total: population,
                radius: radiusKm,
                center: { lat, lng },
                source: `OpenCage: ${components.city || components.town || components.country || 'Unknown'}`
            };
        }
        
        throw new Error('No data from OpenCage API');
        
    } catch (error) {
        throw new Error(`OpenCage API failed: ${error.message}`);
    }
}

// Get population data from GeoNames API
async function getGeoNamesPopulationData(lat, lng, radiusKm) {
    try {
        // GeoNames provides population data for cities and administrative areas
        const response = await fetch(
            `http://api.geonames.org/findNearbyPlaceNameJSON?lat=${lat}&lng=${lng}&radius=${radiusKm}&maxRows=10&username=demo`,
            {
                headers: {
                    'Accept': 'application/json'
                }
            }
        );
        
        if (!response.ok) {
            throw new Error('GeoNames API request failed');
        }
        
        const data = await response.json();
        
        if (data && data.geonames && data.geonames.length > 0) {
            // Sum population from all nearby places
            let totalPopulation = 0;
            let sourceInfo = [];
            
            data.geonames.forEach(place => {
                if (place.population) {
                    totalPopulation += parseInt(place.population);
                    sourceInfo.push(place.name);
                }
            });
            
            // If no population data, estimate based on location
            if (totalPopulation === 0) {
                totalPopulation = estimatePopulationFromGeoNamesData(data.geonames, lat, lng, radiusKm);
            }
            
            return {
                total: totalPopulation,
                radius: radiusKm,
                center: { lat, lng },
                source: `GeoNames: ${sourceInfo.slice(0, 3).join(', ')}`
            };
        }
        
        throw new Error('No data from GeoNames API');
        
    } catch (error) {
        throw new Error(`GeoNames API failed: ${error.message}`);
    }
}

// Get population data from BigDataCloud with enhanced estimation
async function getBigDataCloudPopulationData(lat, lng, radiusKm) {
    try {
        // BigDataCloud provides detailed location information
        const response = await fetch(
            `https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=${lat}&longitude=${lng}&localityLanguage=en`,
            {
                headers: {
                    'Accept': 'application/json'
                }
            }
        );
        
        if (!response.ok) {
            throw new Error('BigDataCloud API request failed');
        }
        
        const data = await response.json();
        
        if (data) {
            // Get country-specific population density
            const countryCode = data.countryCode;
            const countryDensity = await getCountryPopulationDensityFromAPI(countryCode);
            
            // Calculate area
            const area = Math.PI * radiusKm * radiusKm;
            
            // Apply location-specific factors
            let densityMultiplier = 1.0;
            
            // Urban areas have higher density
            if (data.city || data.locality) {
                densityMultiplier = 3.0;
            } else if (data.principalSubdivision) {
                densityMultiplier = 1.5;
            }
            
            // Apply coordinate-based urbanization factor
            const urbanFactor = getUrbanizationFactor(lat, lng);
            densityMultiplier *= urbanFactor;
            
            const population = Math.round(countryDensity * area * densityMultiplier);
            
            return {
                total: population,
                radius: radiusKm,
                center: { lat, lng },
                source: `BigDataCloud: ${data.city || data.locality || data.countryName || 'Unknown'}`
            };
        }
        
        throw new Error('No data from BigDataCloud API');
        
    } catch (error) {
        throw new Error(`BigDataCloud API failed: ${error.message}`);
    }
}

// Estimate population from OpenCage location data
function estimatePopulationFromLocationData(result, lat, lng, radiusKm) {
    const components = result.components || {};
    const area = Math.PI * radiusKm * radiusKm;
    
    // Get base density from coordinates
    const countryInfo = getCountryPopulationDensity(lat, lng);
    let density = countryInfo.density;
    
    // Adjust based on location type
    if (components.city) {
        density *= 4.0; // Cities are dense
    } else if (components.town) {
        density *= 2.0; // Towns are moderately dense
    } else if (components.village) {
        density *= 0.5; // Villages are less dense
    }
    
    // Apply urbanization factor
    const urbanFactor = getUrbanizationFactor(lat, lng);
    density *= urbanFactor;
    
    return Math.round(density * area);
}

// Estimate population from GeoNames data
function estimatePopulationFromGeoNamesData(places, lat, lng, radiusKm) {
    const area = Math.PI * radiusKm * radiusKm;
    
    // Get base density from coordinates
    const countryInfo = getCountryPopulationDensity(lat, lng);
    let density = countryInfo.density;
    
    // Adjust based on place types
    let hasUrbanArea = false;
    places.forEach(place => {
        if (place.fcode && (place.fcode.includes('PPLA') || place.fcode.includes('PPLC'))) {
            hasUrbanArea = true;
        }
    });
    
    if (hasUrbanArea) {
        density *= 3.0; // Administrative centers are dense
    }
    
    // Apply urbanization factor
    const urbanFactor = getUrbanizationFactor(lat, lng);
    density *= urbanFactor;
    
    return Math.round(density * area);
}

// Estimate population within radius using real APIs
async function estimatePopulationInRadius(lat, lng, radiusKm) {
    console.log(`🔍 Estimating population for coordinates: ${lat.toFixed(6)}, ${lng.toFixed(6)} with radius: ${radiusKm}km`);
    
    // Create cache key with more precision to avoid conflicts between nearby airports
    const cacheKey = `${lat.toFixed(4)},${lng.toFixed(4)},${radiusKm}`;
    
    // Check cache first
    if (populationCache.has(cacheKey)) {
        const cached = populationCache.get(cacheKey);
        console.log(`📋 Using cached result for ${cacheKey}: ${cached.total} people`);
        return {
            ...cached,
            details: `Cached population data within ${radiusKm}km radius of ${lat.toFixed(4)}, ${lng.toFixed(4)}`
        };
    }
    
    try {
        // Try multiple population data sources
        let population = null;
        
        // Method 1: Try coordinate-based population API
        try {
            console.log(`🌍 Trying coordinate-based API for ${lat.toFixed(6)}, ${lng.toFixed(6)}`);
            population = await getCoordinateBasedPopulation(lat, lng, radiusKm);
            console.log(`✅ Coordinate-based API success: ${population.total} people from ${population.source}`);
        } catch (error) {
            console.log('❌ Coordinate-based API failed, trying WorldPop:', error);
        }
        
        // Method 2: Try WorldPop API (free, no API key required)
        if (!population) {
            try {
                console.log(`🌍 Trying WorldPop API for ${lat.toFixed(6)}, ${lng.toFixed(6)}`);
                population = await getWorldPopData(lat, lng, radiusKm);
                console.log(`✅ WorldPop API success: ${population.total} people from ${population.source}`);
            } catch (error) {
                console.log('❌ WorldPop API failed, trying OSM:', error);
            }
        }
        
        // Method 3: Try OpenStreetMap Nominatim for location data + estimation
        if (!population) {
            try {
                console.log(`🌍 Trying OSM API for ${lat.toFixed(6)}, ${lng.toFixed(6)}`);
                population = await getOSMPopulationData(lat, lng, radiusKm);
                console.log(`✅ OSM API success: ${population.total} people from ${population.source}`);
            } catch (error) {
                console.log('❌ OSM API failed, using fallback estimation:', error);
            }
        }
        
        // Method 4: Fallback to improved estimation
        if (!population) {
            console.log(`🌍 Using fallback estimation for ${lat.toFixed(6)}, ${lng.toFixed(6)}`);
            population = await getImprovedPopulationEstimate(lat, lng, radiusKm);
            console.log(`✅ Fallback estimation success: ${population.total} people from ${population.source}`);
        }
        
        // Cache the result
        populationCache.set(cacheKey, population);
        console.log(`💾 Cached result for ${cacheKey}: ${population.total} people`);
        
        return {
            ...population,
            details: `Population data within ${radiusKm}km radius of ${lat.toFixed(4)}, ${lng.toFixed(4)}`
        };
        
    } catch (error) {
        console.error('All population estimation methods failed:', error);
        throw new Error('Unable to retrieve population data');
    }
}

// Get population data from WorldPop API
async function getWorldPopData(lat, lng, radiusKm) {
    try {
        // Use WorldPop's point-based population estimation
        // This is a simplified approach - in production you'd use their raster API
        const countryCode = getCountryCode(lat, lng);
        
        // Try to get population data from WorldPop's point service
        const response = await fetch(
            `https://www.worldpop.org/rest/data/pop/point?lat=${lat}&lon=${lng}&radius=${radiusKm}`,
            {
                method: 'GET',
                headers: {
                    'Accept': 'application/json',
                }
            }
        );
        
        if (response.ok) {
            const data = await response.json();
            if (data && data.population) {
                return {
                    total: Math.round(data.population),
                    radius: radiusKm,
                    center: { lat, lng },
                    source: 'WorldPop API'
                };
            }
        }
        
        // Fallback to density-based calculation
        const baseDensity = await getWorldPopDensity(lat, lng);
        const area = Math.PI * radiusKm * radiusKm; // Area in km²
        const population = Math.round(baseDensity * area);
        
        return {
            total: population,
            radius: radiusKm,
            center: { lat, lng },
            source: 'WorldPop Density'
        };
        
    } catch (error) {
        throw new Error(`WorldPop API failed: ${error.message}`);
    }
}

// Get population data from OpenStreetMap
async function getOSMPopulationData(lat, lng, radiusKm) {
    try {
        // Use Nominatim to get location information with coordinates
        const response = await fetch(
            `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&zoom=10&addressdetails=1&extratags=1`,
            {
                headers: {
                    'User-Agent': 'AirportMapApp/1.0'
                }
            }
        );
        
        if (!response.ok) {
            throw new Error('OSM API request failed');
        }
        
        const data = await response.json();
        
        // Extract population from OSM data if available
        let population = 0;
        if (data.address) {
            // Try to get population from various OSM tags
            const pop = data.address.population || data.address.population_city || 
                       data.address.population_town || data.address.population_village;
            if (pop) {
                population = parseInt(pop);
            }
        }
        
        // Check extratags for population data
        if (population === 0 && data.extratags) {
            const pop = data.extratags.population || data.extratags['population:city'] || 
                       data.extratags['population:town'] || data.extratags['population:village'];
            if (pop) {
                population = parseInt(pop);
            }
        }
        
        // If no direct population, estimate based on location type and coordinates
        if (population === 0) {
            population = estimatePopulationFromOSMData(data, radiusKm, lat, lng);
        }
        
        return {
            total: population,
            radius: radiusKm,
            center: { lat, lng },
            source: 'OpenStreetMap'
        };
        
    } catch (error) {
        throw new Error(`OSM API failed: ${error.message}`);
    }
}

// Improved population estimation with better algorithms
async function getImprovedPopulationEstimate(lat, lng, radiusKm) {
    // Simulate API call delay
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    // Get country and region information
    const countryInfo = getCountryPopulationDensity(lat, lng);
    const urbanFactor = getUrbanizationFactor(lat, lng);
    
    // Calculate area in km²
    const area = Math.PI * radiusKm * radiusKm;
    
    // Base density from country data
    const baseDensity = countryInfo.density;
    
    // Apply urbanization factor
    const adjustedDensity = baseDensity * urbanFactor;
    
    // Calculate population
    const population = Math.round(adjustedDensity * area);
    
    return {
        total: population,
        radius: radiusKm,
        center: { lat, lng },
        source: 'Improved Estimation'
    };
}

// Get country code from coordinates (simplified)
function getCountryCode(lat, lng) {
    // This is a simplified country code lookup
    // In a real implementation, you'd use a proper geocoding service
    
    // North America
    if (lat > 25 && lat < 70 && lng > -170 && lng < -50) return 'USA';
    if (lat > 45 && lat < 70 && lng > -140 && lng < -50) return 'CAN';
    if (lat > 15 && lat < 32 && lng > -120 && lng < -85) return 'MEX';
    
    // Europe
    if (lat > 35 && lat < 70 && lng > -25 && lng < 40) return 'DEU';
    if (lat > 50 && lat < 60 && lng > -10 && lng < 2) return 'GBR';
    if (lat > 42 && lat < 51 && lng > -5 && lng < 8) return 'FRA';
    
    // Asia
    if (lat > 20 && lat < 50 && lng > 70 && lng < 140) return 'CHN';
    if (lat > 30 && lat < 45 && lng > 130 && lng < 145) return 'JPN';
    if (lat > 6 && lat < 35 && lng > 68 && lng < 97) return 'IND';
    
    // South America
    if (lat > -5 && lat < 15 && lng > -82 && lng < -66) return 'COL'; // Colombia
    if (lat > -35 && lat < 5 && lng > -75 && lng < -35) return 'BRA'; // Brazil
    if (lat > -55 && lat < -22 && lng > -75 && lng < -53) return 'ARG'; // Argentina
    if (lat > -18 && lat < 0 && lng > -85 && lng < -68) return 'PER'; // Peru
    if (lat > -56 && lat < -17 && lng > -76 && lng < -66) return 'CHL'; // Chile
    if (lat > -5 && lat < 2 && lng > -92 && lng < -75) return 'ECU'; // Ecuador
    if (lat > 0 && lat < 15 && lng > -74 && lng < -59) return 'VEN'; // Venezuela
    if (lat > -23 && lat < -9 && lng > -70 && lng < -57) return 'BOL'; // Bolivia
    if (lat > -35 && lat < -30 && lng > -58 && lng < -53) return 'URY'; // Uruguay
    if (lat > -27 && lat < -19 && lng > -63 && lng < -54) return 'PRY'; // Paraguay
    
    // Default
    return 'USA';
}

// Get WorldPop density data (simplified)
async function getWorldPopDensity(lat, lng) {
    // This would normally fetch from WorldPop raster data
    // For now, we'll use realistic density estimates by region
    
    const countryCode = getCountryCode(lat, lng);
    const densities = {
        'USA': 35, 'CAN': 4, 'MEX': 65,
        'DEU': 240, 'GBR': 280, 'FRA': 120,
        'CHN': 150, 'JPN': 340, 'IND': 450,
        'COL': 45, 'BRA': 25, 'ARG': 16, 'PER': 25,
        'CHL': 24, 'ECU': 70, 'VEN': 32, 'BOL': 10,
        'URY': 20, 'PRY': 17,
        'default': 50
    };
    
    return densities[countryCode] || densities.default;
}

// Estimate population from OSM data using coordinates
function estimatePopulationFromOSMData(osmData, radiusKm, lat, lng) {
    const address = osmData.address || {};
    const area = Math.PI * radiusKm * radiusKm;
    
    // Get base density from coordinates
    const countryInfo = getCountryPopulationDensity(lat, lng);
    const urbanFactor = getUrbanizationFactor(lat, lng);
    
    // Start with country-based density
    let density = countryInfo.density;
    
    // Adjust based on OSM location type
    if (address.city || address.town) {
        density *= 3.0; // Urban areas are denser
    } else if (address.village || address.hamlet) {
        density *= 0.5; // Rural areas are less dense
    } else if (address.suburb || address.neighbourhood) {
        density *= 4.0; // Suburban areas can be very dense
    }
    
    // Apply urbanization factor from coordinates
    density *= urbanFactor;
    
    return Math.round(density * area);
}

// Get country population density data
function getCountryPopulationDensity(lat, lng) {
    const countryCode = getCountryCode(lat, lng);
    
    const countryData = {
        'USA': { density: 35, name: 'United States' },
        'CAN': { density: 4, name: 'Canada' },
        'MEX': { density: 65, name: 'Mexico' },
        'DEU': { density: 240, name: 'Germany' },
        'GBR': { density: 280, name: 'United Kingdom' },
        'FRA': { density: 120, name: 'France' },
        'CHN': { density: 150, name: 'China' },
        'JPN': { density: 340, name: 'Japan' },
        'IND': { density: 450, name: 'India' },
        'COL': { density: 45, name: 'Colombia' },
        'BRA': { density: 25, name: 'Brazil' },
        'ARG': { density: 16, name: 'Argentina' },
        'PER': { density: 25, name: 'Peru' },
        'CHL': { density: 24, name: 'Chile' },
        'ECU': { density: 70, name: 'Ecuador' },
        'VEN': { density: 32, name: 'Venezuela' },
        'BOL': { density: 10, name: 'Bolivia' },
        'URY': { density: 20, name: 'Uruguay' },
        'PRY': { density: 17, name: 'Paraguay' },
        'default': { density: 50, name: 'Unknown' }
    };
    
    return countryData[countryCode] || countryData.default;
}

// Get urbanization factor based on coordinates
function getUrbanizationFactor(lat, lng) {
    // Major urban areas get higher factors
    const majorCities = [
        { lat: 40.7128, lng: -74.0060, factor: 5.0 }, // New York
        { lat: 34.0522, lng: -118.2437, factor: 4.5 }, // Los Angeles
        { lat: 51.5074, lng: -0.1278, factor: 4.0 }, // London
        { lat: 48.8566, lng: 2.3522, factor: 3.5 }, // Paris
        { lat: 35.6762, lng: 139.6503, factor: 4.5 }, // Tokyo
        { lat: 39.9042, lng: 116.4074, factor: 3.0 }, // Beijing
        { lat: 19.0760, lng: 72.8777, factor: 4.0 }, // Mumbai
        // Colombian cities
        { lat: 4.7110, lng: -74.0721, factor: 4.5 }, // Bogotá
        { lat: 6.2442, lng: -75.5812, factor: 4.0 }, // Medellín
        { lat: 3.4516, lng: -76.5320, factor: 3.5 }, // Cali
        { lat: 11.2408, lng: -74.2110, factor: 3.0 }, // Barranquilla
        { lat: 7.1193, lng: -73.1227, factor: 2.5 }, // Bucaramanga
        // Other South American cities
        { lat: -23.5505, lng: -46.6333, factor: 4.0 }, // São Paulo
        { lat: -34.6118, lng: -58.3960, factor: 3.5 }, // Buenos Aires
        { lat: -12.0464, lng: -77.0428, factor: 3.0 }, // Lima
        { lat: -33.4489, lng: -70.6693, factor: 3.0 }, // Santiago
    ];
    
    // Check if coordinates are near major cities
    for (const city of majorCities) {
        const distance = Math.sqrt(
            Math.pow(lat - city.lat, 2) + Math.pow(lng - city.lng, 2)
        );
        if (distance < 0.5) { // Within ~50km
            return city.factor;
        }
    }
    
    // Default urbanization factor based on latitude (urban areas tend to be in certain ranges)
    if (lat > 25 && lat < 60 && lng > -130 && lng < 180) {
        return 2.0; // Higher urbanization in temperate zones
    } else if (lat > -40 && lat < 25) {
        return 1.5; // Medium urbanization in tropical/subtropical zones
    } else {
        return 1.0; // Lower urbanization in polar zones
    }
}

// Get base population estimate based on location (legacy function)
function getBasePopulationEstimate(lat, lng) {
    // This is now a legacy function - kept for backward compatibility
    const countryInfo = getCountryPopulationDensity(lat, lng);
    const urbanFactor = getUrbanizationFactor(lat, lng);
    return Math.round(countryInfo.density * urbanFactor * 1000); // Convert to base population
}

// Get radius multiplier for population estimation
function getRadiusMultiplier(radiusKm) {
    // Population typically grows with the square of radius, but with diminishing returns
    if (radiusKm === 40) return 1.0;
    if (radiusKm === 70) return 2.5;
    if (radiusKm === 100) return 4.0;
    return 1.0;
}

