// Handle population radius change for update modal
function handleUpdatePopulationRadiusChange() {
    const radiusSelect = document.getElementById('updatePopulationRadius');
    const manualGroup = document.getElementById('updateManualPopulationGroup');
    const autoGroup = document.getElementById('updateAutoPopulationGroup');
    
    if (!radiusSelect || !manualGroup || !autoGroup) return;
    
    const selectedValue = radiusSelect.value;
    
    if (selectedValue === 'manual') {
        manualGroup.style.display = 'block';
        autoGroup.style.display = 'none';
    } else if (selectedValue && selectedValue !== '') {
        manualGroup.style.display = 'none';
        autoGroup.style.display = 'block';
        // Trigger population gathering if coordinates are available
        gatherUpdatePopulationData();
    } else {
        manualGroup.style.display = 'none';
        autoGroup.style.display = 'none';
    }
}

// Gather population data for the update modal
async function gatherUpdatePopulationData() {
    const radiusSelect = document.getElementById('updatePopulationRadius');
    
    if (!radiusSelect.value || radiusSelect.value === 'manual' || !currentUpdateMarker) {
        return;
    }
    
    const latLng = currentUpdateMarker.getLatLng();
    const radius = parseInt(radiusSelect.value);
    showUpdatePopulationLoading();
    
    try {
        // Use the same population estimation service
        const population = await estimatePopulationInRadius(latLng.lat, latLng.lng, radius);
        showUpdatePopulationResult(population, radius);
        currentUpdatePopulationData = population;
    } catch (error) {
        console.error('Error gathering population data:', error);
        showUpdatePopulationError('Failed to gather population data');
    }
}

