// Save population update to existing airport
function savePopulationUpdate() {
    if (!currentUpdateMarker) {
        alert('No airport selected for update!');
        return;
    }
    
    const population = parseInt(document.getElementById('updatePopulation').value) || 0;
    
    if (population <= 0) {
        alert('Please enter a valid population value!');
        return;
    }
    
    // Update the marker's airport data
    if (currentUpdateMarker.airportData) {
        currentUpdateMarker.airportData.population = population;
    }
    
    // Update the popup content
    updateAirportPopupContent(currentUpdateMarker);
    
    // Save to localStorage
    saveAirports();
    
    routesList.forEach(route => applyDemandModelToDirectionalRoute(route));
    saveRoutes();
    updateRoutesList();
    updateRoutePopupsForSchedulePage();
    
    // Hide the modal
    hidePopulationUpdateModal();
    
    alert(`Population data updated successfully! Population: ${population.toLocaleString()}`);
}

