// Get population data from airport selection
function getAirportPopulation(airportSelection) {
    if (!airportSelection) return 0;
    
    const parts = airportSelection.split('|');
    if (parts.length < 4) return 0;
    
    const airportCode = (parts[1] || '').toUpperCase();
    if (!airportCode) return 0;

    // Demand uses network-adjusted population (base + connected-airport boost).
    return getEffectiveAirportPopulationByCode(airportCode);
}

