function populateGateAircraftCheckboxes() {
    const checkboxesContainer = document.getElementById('gateAircraftCheckboxes');
    if (!checkboxesContainer) return;
    
    if (!currentAirportForGates) {
        checkboxesContainer.innerHTML = '<div style="text-align: center; color: #A68A64; font-style: italic; padding: 10px;">No airport selected</div>';
        return;
    }
    
    // Get the current airport's compatible aircraft
    const currentAirport = userMarkers.find(marker => {
        const popup = marker.getPopup();
        const content = popup.getContent();
        const parser = new DOMParser();
        const doc = parser.parseFromString(content, 'text/html');
        const name = doc.querySelector('h3').textContent;
        return name === currentAirportForGates;
    });
    
    let compatibleAircraft = [];
    if (currentAirport && currentAirport.airportData) {
        compatibleAircraft = currentAirport.airportData.compatibleAircraft || [];
    }
    
    if (compatibleAircraft.length === 0) {
        checkboxesContainer.innerHTML = '<div style="text-align: center; color: #A68A64; font-style: italic; padding: 10px;">No compatible aircraft types available for this airport. Add compatible aircraft to the airport first.</div>';
        return;
    }
    
    let checkboxesHTML = '';
    compatibleAircraft.forEach((aircraftModel, index) => {
        // Find the aircraft details from aircraftList
        const aircraftDetails = aircraftList.find(aircraft => aircraft.model === aircraftModel);
        if (aircraftDetails) {
            checkboxesHTML += `
                <div class="aircraft-checkbox-item">
                    <label>
                        <input type="checkbox" value="${aircraftModel}" data-index="${index}">
                        <div class="aircraft-info">
                            <span>${aircraftModel}</span>
                            <span class="aircraft-specs">${formatAircraftSpecsLine(aircraftDetails)}</span>
                        </div>
                    </label>
                </div>
            `;
        }
    });
    
    checkboxesContainer.innerHTML = checkboxesHTML;
}

function getSelectedGateAircraftTypes() {
    const checkboxes = document.querySelectorAll('#gateAircraftCheckboxes input[type="checkbox"]:checked');
    const selectedAircraft = [];
    
    checkboxes.forEach(checkbox => {
        selectedAircraft.push(checkbox.value);
    });
    
    return selectedAircraft;
}

function setSelectedGateAircraftTypes(selectedAircraft) {
    const checkboxes = document.querySelectorAll('#gateAircraftCheckboxes input[type="checkbox"]');
    
    checkboxes.forEach(checkbox => {
        const aircraftModel = checkbox.value;
        checkbox.checked = selectedAircraft && selectedAircraft.includes(aircraftModel);
    });
}

// Airline management functions
function loadSavedAirlines() {
    const savedAirlines = localStorage.getItem('savedAirlines');
    if (savedAirlines) {
        const airlines = JSON.parse(savedAirlines);
        airlinesList.length = 0; // Clear array
        airlinesList.push(...airlines);
        airlinesList.forEach(a => {
            if (a && Object.prototype.hasOwnProperty.call(a, 'mapColor')) {
                delete a.mapColor;
            }
        });
    }
}

function saveAirlines() {
    airlinesList.forEach(a => {
        if (a && Object.prototype.hasOwnProperty.call(a, 'mapColor')) {
            delete a.mapColor;
        }
    });
    localStorage.setItem('savedAirlines', JSON.stringify(airlinesList));
}

// Migration function to move registered aircraft to airlines
function migrateRegisteredAircraftToAirlines() {
    console.log('🔄 Migrating registered aircraft to airlines...');
    
    // First, ensure all airlines have an aircraft array
    airlinesList.forEach(airline => {
        if (!airline.aircraft) {
            airline.aircraft = [];
        }
    });
    
    // Migrate each registered aircraft to its airline
    registeredAircraftList.forEach(aircraft => {
        const airlineName = aircraft.airline;
        
        if (airlineName) {
            // Find the airline
            const airline = airlinesList.find(a => a.name === airlineName);
            if (airline) {
                // Add aircraft to airline
                airline.aircraft.push({
                    registration: aircraft.registration,
                    aircraftType: aircraft.aircraftType
                });
                console.log(`✅ Migrated ${aircraft.registration} to ${airlineName}`);
            } else {
                // Create new airline if it doesn't exist
                const newAirline = {
                    name: airlineName,
                    code: airlineName.substring(0, 3).toUpperCase(), // Generate code from name
                    aircraft: [{
                        registration: aircraft.registration,
                        aircraftType: aircraft.aircraftType
                    }]
                };
                airlinesList.push(newAirline);
                console.log(`✅ Created new airline ${airlineName} with aircraft ${aircraft.registration}`);
            }
        } else {
            // Create "No Airline Assigned" group
            let noAirlineGroup = airlinesList.find(a => a.name === 'No Airline Assigned');
            if (!noAirlineGroup) {
                noAirlineGroup = {
                    name: 'No Airline Assigned',
                    code: 'N/A',
                    aircraft: []
                };
                airlinesList.push(noAirlineGroup);
            }
            noAirlineGroup.aircraft.push({
                registration: aircraft.registration,
                aircraftType: aircraft.aircraftType
            });
            console.log(`✅ Migrated ${aircraft.registration} to "No Airline Assigned"`);
        }
    });
    
    // Clear registered aircraft list
    registeredAircraftList.length = 0;
    
    // Save updated data
    saveAirlines();
    saveRegisteredAircraft(); // Save empty array
    
    console.log('✅ Migration complete! Registered aircraft moved to airlines.');
}

