// Function to extract prefix from registration (handles XX-XXX and XXXXX formats)
function extractPrefix(registration) {
    if (!registration) return '';
    
    const reg = registration.trim().toUpperCase();
    
    // Check for XX-XXX format (e.g., HK-1234, HK-ABC)
    // Match pattern: 1-3 alphanumeric chars followed by a dash
    const dashMatch = reg.match(/^([A-Z0-9]{1,3})-/);
    if (dashMatch) {
        return dashMatch[1] + '-';
    }
    
    // Check for XXXXX format (no dash) - take first 1-2 characters as prefix
    // Common formats: N123AB (US - single char), GABCD (UK - single char), FABCD (France - single char)
    // Some countries use 2 chars: VH-ABC (Australia), but without dash it would be VHABC
    // For now, we'll use first 1-2 characters, prioritizing single char for common cases
    if (reg.length > 0) {
        // If it starts with a single letter followed by numbers, use just the letter (e.g., N123AB -> N)
        const singleLetterMatch = reg.match(/^([A-Z])(\d)/);
        if (singleLetterMatch) {
            return singleLetterMatch[1];
        }
        // Otherwise, use first 2 characters
        return reg.substring(0, Math.min(2, reg.length));
    }
    
    return '';
}

// Function to normalize prefix for comparison (handles dash variations)
function normalizePrefixForComparison(prefix) {
    if (!prefix) return '';
    // Remove trailing dash for comparison, convert to uppercase
    return prefix.replace(/-$/, '').toUpperCase();
}

// Function to get prefix name from airline prefixes
function getPrefixName(airline, prefix) {
    if (!airline.prefixes || !Array.isArray(airline.prefixes)) return '';
    const normalizedPrefix = normalizePrefixForComparison(prefix);
    const prefixEntry = airline.prefixes.find(p => normalizePrefixForComparison(p.prefix) === normalizedPrefix);
    return prefixEntry ? prefixEntry.name : '';
}

// Function to update individual airline display
function updateIndividualAirlineDisplay(airlineIndex) {
    const airline = airlinesList[airlineIndex];
    if (!airline) return;
    
    // Update title
    const titleElement = document.getElementById('individualAirlineTitle');
    if (titleElement) {
        titleElement.textContent = airline.name;
    }
    
    // Update airline info
    const infoElement = document.getElementById('individualAirlineInfo');
    if (infoElement) {
        const airlineLogo = generateAirlineLogoHTML(airline.name, airline.code, '48px');
        const aircraftCount = airline.aircraft ? airline.aircraft.length : 0;
        
        infoElement.innerHTML = `
            <div style="display: flex; align-items: center; gap: 20px; padding: 20px; background: #e6e6e9; border: 1px solid #A68A64; border-radius: 8px; margin-bottom: 20px;">
                <div style="flex-shrink: 0;">
                    ${airlineLogo}
                </div>
                <div style="flex: 1;">
                    <h3 style="margin: 0; font-size: 24px; color: #19363c;">
                        <span class="airline-code" style="color: #4e8ca0; font-weight: bold;">${airline.code}</span> ${airline.name}
                    </h3>
                    <p style="margin: 10px 0 0 0; color: #666; font-size: 16px;">
                        Fleet Size: ${aircraftCount} aircraft
                    </p>
                </div>
            </div>
        `;
    }
    
    // Initialize prefixes array if it doesn't exist
    if (!airline.prefixes) {
        airline.prefixes = [];
    }
    
    // Group aircraft by prefix (normalized for consistent grouping)
    const aircraftByPrefix = {};
    const prefixDisplayMap = {}; // Map normalized prefix to display prefix
    if (airline.aircraft && airline.aircraft.length > 0) {
        airline.aircraft.forEach(aircraft => {
            const extractedPrefix = extractPrefix(aircraft.registration);
            const normalizedPrefix = normalizePrefixForComparison(extractedPrefix);
            
            // Use normalized prefix for grouping, but keep track of display format
            if (!aircraftByPrefix[normalizedPrefix]) {
                aircraftByPrefix[normalizedPrefix] = [];
                prefixDisplayMap[normalizedPrefix] = extractedPrefix; // Store original format for display
            }
            aircraftByPrefix[normalizedPrefix].push(aircraft);
        });
    }
    
    // Update prefix filter dropdown
    const prefixFilterContainer = document.getElementById('prefixFilterContainer');
    const prefixFilter = document.getElementById('prefixFilter');
    const selectedPrefix = prefixFilter ? normalizePrefixForComparison(prefixFilter.value) : '';
    
    if (prefixFilterContainer && prefixFilter) {
        if (Object.keys(aircraftByPrefix).length > 0) {
            prefixFilterContainer.style.display = 'block';
            
            // Build prefix options using display format
            let prefixOptions = '<option value="">All Prefixes</option>';
            Object.keys(aircraftByPrefix).sort().forEach(normalizedPrefix => {
                const displayPrefix = prefixDisplayMap[normalizedPrefix] || normalizedPrefix;
                const prefixName = getPrefixName(airline, normalizedPrefix);
                const displayText = prefixName ? `${displayPrefix} (${prefixName})` : displayPrefix;
                prefixOptions += `<option value="${normalizedPrefix}" ${selectedPrefix === normalizedPrefix ? 'selected' : ''}>${displayText}</option>`;
            });
            prefixFilter.innerHTML = prefixOptions;
        } else {
            prefixFilterContainer.style.display = 'none';
        }
    }
    
    // Update aircraft list
    const aircraftListElement = document.getElementById('individualAirlineAircraftList');
    if (aircraftListElement) {
        if (airline.aircraft && airline.aircraft.length > 0) {
            let aircraftHTML = '';
            
            // Filter by selected prefix if one is selected
            const prefixesToShow = selectedPrefix ? [selectedPrefix] : Object.keys(aircraftByPrefix).sort();
            
            prefixesToShow.forEach(normalizedPrefix => {
                const aircraftInPrefix = aircraftByPrefix[normalizedPrefix];
                if (!aircraftInPrefix || aircraftInPrefix.length === 0) return;
                
                // Sort aircraft alphabetically by registration within prefix
                const sortedAircraft = [...aircraftInPrefix].sort((a, b) => a.registration.localeCompare(b.registration));
                
                // Add prefix header if showing all prefixes
                if (!selectedPrefix) {
                    const displayPrefix = prefixDisplayMap[normalizedPrefix] || normalizedPrefix;
                    const prefixName = getPrefixName(airline, normalizedPrefix);
                    const headerText = prefixName ? `${displayPrefix} - ${prefixName}` : displayPrefix;
                    aircraftHTML += `
                        <div style="margin: 20px 0 10px 0; padding: 8px 12px; background: #4e8ca0; color: white; border-radius: 4px; font-weight: bold; font-size: 16px;">
                            ${headerText} (${sortedAircraft.length} aircraft)
                        </div>
                    `;
                }
                
                sortedAircraft.forEach((aircraft) => {
                    // Find the original index for the onclick handlers
                    const originalIndex = airline.aircraft.findIndex(ac => ac.registration === aircraft.registration);
                    // Initialize completed property if it doesn't exist
                    if (aircraft.completed === undefined) {
                        aircraft.completed = false;
                    }
                    const fleetCap = getAircraftTypeCapacity(aircraft.aircraftType);
                    const fleetCapSuffix = fleetCap != null ? ` · ${fleetCap} pax` : '';
                    aircraftHTML += `
                        <div class="registered-aircraft-item ${aircraft.completed ? 'aircraft-completed' : ''}" onclick="showAircraftSchedule('${aircraft.registration}')" style="cursor: pointer;">
                            <div class="registered-aircraft-info">
                                <div class="registered-aircraft-registration">${aircraft.registration}</div>
                                <div class="registered-aircraft-type">${aircraft.aircraftType}${fleetCapSuffix}</div>
                            </div>
                            <div class="registered-aircraft-status">
                                <div class="status-circle ${aircraft.completed ? 'completed' : ''}"></div>
                            </div>
                            <div class="registered-aircraft-actions" onclick="event.stopPropagation();">
                                <button onclick="toggleAircraftComplete(${airlineIndex}, ${originalIndex}, event)" class="action-btn ${aircraft.completed ? 'complete-btn' : 'incomplete-btn'}">
                                    ${aircraft.completed ? 'Mark Incomplete' : 'Mark Complete'}
                                </button>
                                <button class="edit-btn" onclick="editAircraftInAirline(${airlineIndex}, ${originalIndex})">Edit</button>
                                <button class="delete-btn" onclick="deleteAircraftFromAirline(${airlineIndex}, ${originalIndex})">Delete</button>
                            </div>
                        </div>
                    `;
                });
            });
            
            aircraftListElement.innerHTML = aircraftHTML;
        } else {
            aircraftListElement.innerHTML = `
                <div style="padding: 40px; text-align: center; color: #666; font-style: italic; background: #f9f9f9; border: 1px solid #ddd; border-radius: 8px;">
                    <h4 style="margin: 0 0 10px 0; color: #999;">No Aircraft in Fleet</h4>
                    <p style="margin: 0;">Click "Add Aircraft" to add aircraft to this airline.</p>
                </div>
            `;
        }
    }
    
    // Save airlines to persist prefixes
    saveAirlines();
}

