// Function to setup aircraft form event listeners
function setupAircraftFormEventListeners(airlineIndex) {
    const form = document.getElementById('aircraftFormModalForm');
    const cancelBtn = document.getElementById('cancelAircraftForm');
    const registrationInput = document.getElementById('aircraftRegistration');
    const errorDiv = document.getElementById('registrationError');
    
    // Cancel button
    if (cancelBtn) {
        cancelBtn.addEventListener('click', function() {
            closeAircraftFormModal();
        });
    }
    
    // Real-time registration validation
    if (registrationInput) {
        registrationInput.addEventListener('input', function() {
            validateAircraftRegistration(this.value, errorDiv);
        });
    }
    
    // Form submission
    if (form) {
        form.addEventListener('submit', function(e) {
            e.preventDefault();
            
            const registration = document.getElementById('aircraftRegistration').value.trim();
            const aircraftType = document.getElementById('aircraftTypeSelect').value;
            
            // Validate inputs
            if (!registration) {
                alert('Please enter aircraft registration');
                return;
            }
            
            if (!aircraftType) {
                alert('Please select an aircraft type');
                return;
            }
            
            // Check if registration already exists
            if (!validateAircraftRegistration(registration, errorDiv)) {
                return;
            }
            
            // Add aircraft to airline
            addAircraftToAirlineWithData(airlineIndex, registration, aircraftType);
        });
    }
}

// Function to validate aircraft registration
function validateAircraftRegistration(registration, errorDiv) {
    if (!registration) {
        if (errorDiv) {
            errorDiv.style.display = 'none';
        }
        return true;
    }
    
    // Check if registration already exists across all airlines
    const existingAircraft = airlinesList.find(airline => 
        airline.aircraft && airline.aircraft.some(ac => 
            ac.registration.toLowerCase() === registration.toLowerCase()
        )
    );
    
    if (existingAircraft) {
        if (errorDiv) {
            errorDiv.textContent = 'Aircraft with this registration already exists!';
            errorDiv.style.display = 'block';
        }
        return false;
    }
    
    // Clear error if validation passes
    if (errorDiv) {
        errorDiv.style.display = 'none';
    }
    
    return true;
}

// Function to add aircraft with validated data
function addAircraftToAirlineWithData(airlineIndex, registration, aircraftType) {
    const airline = airlinesList[airlineIndex];
    if (!airline) return;
    
    // Ensure airline has aircraft array
    if (!airline.aircraft) {
        airline.aircraft = [];
    }
    
    // Add aircraft (initialize completed as false)
    airline.aircraft.push({
        registration: registration,
        aircraftType: aircraftType,
        completed: false
    });
    
    // Save and update display
    saveAirlines();
    
    // Update both displays
    updateAirlinesList();
    if (window.currentAirlineIndex !== undefined) {
        updateIndividualAirlineDisplay(window.currentAirlineIndex);
    }
    
    // Close modal and show success message
    closeAircraftFormModal();
    alert(`✅ Aircraft ${registration} (${aircraftType}) added to ${airline.name} successfully!`);
    
    console.log(`✅ Added ${registration} to ${airline.name}`);
}

// Function to close aircraft form modal
function closeAircraftFormModal() {
    const modal = document.getElementById('aircraftFormModal');
    if (modal) {
        modal.remove();
    }
}

// Function to edit aircraft in airline
function editAircraftInAirline(airlineIndex, aircraftIndex) {
    const airline = airlinesList[airlineIndex];
    const aircraft = airline.aircraft[aircraftIndex];
    
    if (!airline || !aircraft) {
        console.error('editAircraftInAirline: Invalid airline or aircraft');
        return;
    }
    
    const oldRegistration = aircraft.registration;
    if (!oldRegistration) {
        alert('Error: Aircraft registration is missing!');
        return;
    }
    
    const newRegistration = prompt(`Enter new registration for ${oldRegistration}:`, oldRegistration);
    if (!newRegistration) {
        console.log('Registration update cancelled by user');
        return;
    }
    
    // Trim whitespace from input
    const trimmedNewRegistration = newRegistration.trim();
    if (!trimmedNewRegistration) {
        alert('Registration cannot be empty!');
        return;
    }
    
    const newAircraftType = prompt(`Enter new aircraft type:`, aircraft.aircraftType);
    if (!newAircraftType) {
        console.log('Aircraft type update cancelled by user');
        return;
    }
    
    // Trim whitespace from aircraft type
    const trimmedNewAircraftType = newAircraftType.trim();
    if (!trimmedNewAircraftType) {
        alert('Aircraft type cannot be empty!');
        return;
    }
    
    // Check if registration actually changed (case-insensitive, trimmed)
    const registrationChanged = oldRegistration.toLowerCase().trim() !== trimmedNewRegistration.toLowerCase();
    
    if (registrationChanged) {
        // Check if new registration already exists (excluding current aircraft)
        const existingAircraft = airlinesList.find(a => 
            a.aircraft && a.aircraft.some(ac => 
                ac.registration.toLowerCase().trim() === trimmedNewRegistration.toLowerCase() && 
                !(a === airline && a.aircraft[aircraftIndex] === ac)
            )
        );
        
        if (existingAircraft) {
            alert('Aircraft with this registration already exists!');
            return;
        }
        
        // Migrate schedule data from old registration to new registration
        if (aircraftSchedules[oldRegistration]) {
            aircraftSchedules[trimmedNewRegistration] = aircraftSchedules[oldRegistration];
            delete aircraftSchedules[oldRegistration];
            console.log(`✅ Migrated schedule data from ${oldRegistration} to ${trimmedNewRegistration}`);
        } else {
            console.log(`ℹ️ No schedule data found for ${oldRegistration}`);
        }
        
        // Migrate gate blocks from old registration to new registration
        if (gateBlocks[oldRegistration]) {
            gateBlocks[trimmedNewRegistration] = gateBlocks[oldRegistration];
            delete gateBlocks[oldRegistration];
            console.log(`✅ Migrated gate blocks from ${oldRegistration} to ${trimmedNewRegistration}`);
        } else {
            console.log(`ℹ️ No gate blocks found for ${oldRegistration}`);
        }
        
        // Update current aircraft for schedule if it matches
        if (currentAircraftForSchedule === oldRegistration) {
            currentAircraftForSchedule = trimmedNewRegistration;
            console.log(`✅ Updated currentAircraftForSchedule from ${oldRegistration} to ${trimmedNewRegistration}`);
        }
    }
    
    // Update aircraft (preserve completed status)
    const wasCompleted = aircraft.completed || false;
    const oldRegValue = aircraft.registration;
    aircraft.registration = trimmedNewRegistration;
    aircraft.aircraftType = trimmedNewAircraftType;
    aircraft.completed = wasCompleted;
    
    console.log(`✅ Updated aircraft registration from "${oldRegValue}" to "${trimmedNewRegistration}"`);
    console.log(`✅ Updated aircraft type to "${trimmedNewAircraftType}"`);
    
    // Save all data
    saveAirlines();
    if (registrationChanged) {
        saveAircraftSchedules();
        saveGateBlocks();
    }
    
    // Update display
    updateAirlinesList();
    if (window.currentAirlineIndex !== undefined) {
        updateIndividualAirlineDisplay(window.currentAirlineIndex);
    }
    
    // If schedule view is open, refresh it
    if (currentAircraftForSchedule === trimmedNewRegistration) {
        showAircraftSchedule(trimmedNewRegistration);
    }
    
    console.log(`✅ Successfully updated aircraft ${trimmedNewRegistration} in ${airline.name}${registrationChanged ? ' (migrated schedule and gate blocks)' : ''}`);
}

// Function to toggle aircraft completion status
function toggleAircraftComplete(airlineIndex, aircraftIndex, event) {
    // Prevent the click from triggering parent click handlers
    event.stopPropagation();
    
    const airline = airlinesList[airlineIndex];
    const aircraft = airline.aircraft[aircraftIndex];
    
    if (!airline || !aircraft) return;
    
    // Initialize completed property if it doesn't exist
    if (aircraft.completed === undefined) {
        aircraft.completed = false;
    }
    
    // Toggle the completed status
    aircraft.completed = !aircraft.completed;
    
    // Save and update display
    saveAirlines();
    if (window.currentAirlineIndex !== undefined) {
        updateIndividualAirlineDisplay(window.currentAirlineIndex);
    }
    
    // Show notification
    if (typeof showNonBlockingNotification === 'function') {
        showNonBlockingNotification(
            aircraft.completed ? 
                `✅ Aircraft ${aircraft.registration} marked as complete` :
                `🔄 Aircraft ${aircraft.registration} marked as incomplete`, 
            'success'
        );
    } else {
        console.log(aircraft.completed ? 
            `✅ Aircraft ${aircraft.registration} marked as complete` :
            `🔄 Aircraft ${aircraft.registration} marked as incomplete`);
    }
}

// Function to delete aircraft from airline
function deleteAircraftFromAirline(airlineIndex, aircraftIndex) {
    const airline = airlinesList[airlineIndex];
    const aircraft = airline.aircraft[aircraftIndex];
    
    if (!airline || !aircraft) return;
    
    if (confirm(`Are you sure you want to delete aircraft ${aircraft.registration} from ${airline.name}?`)) {
        const registration = aircraft.registration;
        
        // Remove aircraft
        airline.aircraft.splice(aircraftIndex, 1);
        
        // Remove related schedules and gate blocks for this aircraft
        delete aircraftSchedules[registration];
        delete gateBlocks[registration];
        
        // Save and update display
        saveAirlines();
        saveAircraftSchedules();
        saveGateBlocks();
        updateAirlinesList();
        if (window.currentAirlineIndex !== undefined) {
            updateIndividualAirlineDisplay(window.currentAirlineIndex);
        }
        
        console.log(`✅ Deleted ${registration} from ${airline.name} and cleared its schedules/gate blocks`);
    }
}

