// Function to setup prefix form event listeners
function setupPrefixFormEventListeners(airlineIndex) {
    const form = document.getElementById('prefixFormModalForm');
    const cancelBtn = document.getElementById('cancelPrefixForm');
    
    // Cancel button
    if (cancelBtn) {
        cancelBtn.addEventListener('click', function() {
            closeAddPrefixModal();
        });
    }
    
    // Form submission
    if (form) {
        form.addEventListener('submit', function(e) {
            e.preventDefault();
            
            const prefix = document.getElementById('prefixInput').value.trim().toUpperCase();
            const prefixName = document.getElementById('prefixNameInput').value.trim();
            
            // Validate inputs
            if (!prefix) {
                alert('Please enter a prefix');
                return;
            }
            
            if (!prefixName) {
                alert('Please enter a name/country for the prefix');
                return;
            }
            
            // Ensure prefix ends with dash if it doesn't already
            const normalizedPrefix = prefix.endsWith('-') ? prefix : prefix + '-';
            
            // Add prefix to airline
            addPrefixToAirline(airlineIndex, normalizedPrefix, prefixName);
        });
    }
}

// Function to add prefix to airline
function addPrefixToAirline(airlineIndex, prefix, name) {
    const airline = airlinesList[airlineIndex];
    if (!airline) return;
    
    // Initialize prefixes array if it doesn't exist
    if (!airline.prefixes) {
        airline.prefixes = [];
    }
    
    // Check if prefix already exists
    const existingPrefix = airline.prefixes.find(p => p.prefix === prefix);
    if (existingPrefix) {
        // Update existing prefix name
        existingPrefix.name = name;
        alert(`Prefix ${prefix} updated to "${name}"`);
    } else {
        // Add new prefix
        airline.prefixes.push({ prefix: prefix, name: name });
        alert(`Prefix ${prefix} added as "${name}"`);
    }
    
    // Save and update display
    saveAirlines();
    updateIndividualAirlineDisplay(airlineIndex);
    
    // Close modal
    closeAddPrefixModal();
    
    console.log(`✅ Added prefix ${prefix} (${name}) to ${airline.name}`);
}

// Function to close Add Prefix modal
function closeAddPrefixModal() {
    const modal = document.getElementById('addPrefixModal');
    if (modal) {
        modal.remove();
    }
}

function editAirline(index) {
    const airline = airlinesList[index];
    if (!airline) return;

    // Ensure airlines submenu is visible (e.g. when opening edit from airline detail view)
    showOnlyMenu('airlinesSubMenuContent');
    
    // Show the form and hide airlines menu
    const form = document.getElementById('airlineForm');
    const airlinesMenu = document.getElementById('airlinesMenuContent');
    
    if (airlinesMenu) airlinesMenu.style.display = 'none';
    if (form) form.style.display = 'block';
    
    // Fill the form with existing data
    document.getElementById('airlineName').value = airline.name;
    document.getElementById('airlineCode').value = airline.code;
    
    // Store the index for updating
    window.editingAirlineIndex = index;
    
    // Change form title and button text
    const formTitle = form.querySelector('h4');
    const submitButton = form.querySelector('button[type="submit"]');
    if (formTitle) formTitle.textContent = 'Edit Airline';
    if (submitButton) submitButton.textContent = 'Update Airline';
}

function deleteAirline(index) {
    if (confirm('Are you sure you want to delete this airline?')) {
        airlinesList.splice(index, 1);
        saveAirlines();
        updateAirlinesList();
        
        // If we're in the individual airline view, go back to airlines list
        if (window.currentAirlineIndex !== undefined) {
            const airlinesSubMenu = document.getElementById('airlinesSubMenuContent');
            const individualAirlineSubMenu = document.getElementById('individualAirlineSubMenuContent');
            
            if (airlinesSubMenu) airlinesSubMenu.style.display = 'block';
            if (individualAirlineSubMenu) individualAirlineSubMenu.style.display = 'none';
            
            // Clear current airline index
            window.currentAirlineIndex = undefined;
        }
        
        alert('Airline deleted successfully!');
    }
}

function resetAirlineFormToAddMode() {
    const form = document.getElementById('airlineForm');
    const formTitle = form.querySelector('h4');
    const submitButton = form.querySelector('button[type="submit"]');
    
    if (formTitle) formTitle.textContent = 'Add New Airline';
    if (submitButton) submitButton.textContent = 'Add Airline';
    
    // Clear editing state
    window.editingAirlineIndex = null;
}

function populateAirlineDropdown() {
    const airlineSelect = document.getElementById('airline');
    
    if (!airlineSelect) {
        console.log('Airline dropdown not found');
        return;
    }
    
    // Clear existing options except the first one
    airlineSelect.innerHTML = '<option value="">Select airline (optional)</option>';
    
    // Add airlines from airlinesList
    airlinesList.forEach(airline => {
        const option = document.createElement('option');
        option.value = airline.name;
        option.textContent = `${airline.name} (${airline.code})`;
        airlineSelect.appendChild(option);
    });
}

function populateGateAirlinesCheckboxes() {
    const checkboxesContainer = document.getElementById('gateAirlinesCheckboxes');
    if (!checkboxesContainer) return;
    
    if (airlinesList.length === 0) {
        checkboxesContainer.innerHTML = '<div style="text-align: center; color: #A68A64; font-style: italic; padding: 10px;">No airlines available. Add airlines first.</div>';
        return;
    }
    
    let checkboxesHTML = '';
    airlinesList.forEach((airline, index) => {
        checkboxesHTML += `
            <div class="aircraft-checkbox-item">
                <label>
                    <input type="checkbox" value="${airline.name}" data-index="${index}">
                    <div class="aircraft-info">
                        <span>${airline.name}</span>
                        <span class="aircraft-specs">${airline.code}</span>
                    </div>
                </label>
            </div>
        `;
    });
    
    checkboxesContainer.innerHTML = checkboxesHTML;
}

function getSelectedGateAirlines() {
    const checkboxes = document.querySelectorAll('#gateAirlinesCheckboxes input[type="checkbox"]:checked');
    const selectedAirlines = [];
    
    checkboxes.forEach(checkbox => {
        selectedAirlines.push(checkbox.value);
    });
    
    return selectedAirlines;
}

function setSelectedGateAirlines(selectedAirlines) {
    const checkboxes = document.querySelectorAll('#gateAirlinesCheckboxes input[type="checkbox"]');
    
    checkboxes.forEach(checkbox => {
        const airlineName = checkbox.value;
        checkbox.checked = selectedAirlines && selectedAirlines.includes(airlineName);
    });
}

// Aircraft Schedule management functions
function loadSavedAircraftSchedules() {
    console.log('📂 LOADING: Loading aircraft schedules from localStorage...');
    const savedSchedules = localStorage.getItem('savedAircraftSchedules');
    if (savedSchedules) {
        const schedules = JSON.parse(savedSchedules);
        console.log('📂 LOADING: Found saved schedules:', schedules);
        Object.keys(schedules).forEach(aircraftRegistration => {
            aircraftSchedules[aircraftRegistration] = schedules[aircraftRegistration];
        });
        console.log('📂 LOADING: Successfully loaded aircraft schedules');
    } else {
        console.log('📂 LOADING: No saved schedules found in localStorage');
    }
    markRouteFlightsLookupDirty();
}

function saveAircraftSchedules() {
    markRouteFlightsLookupDirty();
    console.log('💾 SAVING: Saving aircraft schedules to localStorage...');
    console.log('💾 SAVING: aircraftSchedules object:', aircraftSchedules);
    localStorage.setItem('savedAircraftSchedules', JSON.stringify(aircraftSchedules));
    console.log('💾 SAVING: Successfully saved to localStorage');
}

function showAircraftSchedule(aircraftRegistration) {
    console.log(`=== VIEWING SCHEDULE FOR AIRCRAFT: ${aircraftRegistration} ===`);
    currentAircraftForSchedule = aircraftRegistration;
    
    // Check if this aircraft has a schedule
    const schedule = aircraftSchedules[aircraftRegistration];
    console.log('Aircraft schedule exists:', !!schedule);
    console.log('Schedule length:', schedule ? schedule.length : 0);
    
    if (schedule && schedule.length > 0) {
        console.log('Schedule items:');
        schedule.forEach((item, index) => {
            console.log(`  ${index + 1}. ${item.type} - ${item.startTime} to ${item.endTime} (Day ${item.day})`);
        });
    } else {
        console.log('No schedule items found for this aircraft');
    }
    
    // Show aircraft schedule in the existing menu system
    showAircraftScheduleInMenu(aircraftRegistration);
    
    console.log(`=== SCHEDULE VIEW SETUP COMPLETE FOR ${aircraftRegistration} ===`);
}

// Function to show aircraft schedule in the menu system
function showAircraftScheduleInMenu(aircraftRegistration) {
    // Hide current menu and show aircraft schedule menu
    const individualAirlineSubMenu = document.getElementById('individualAirlineSubMenuContent');
    const aircraftScheduleMenu = document.getElementById('aircraftScheduleContent');
    const aircraftScheduleTitle = document.getElementById('aircraftScheduleTitle');
    
    if (individualAirlineSubMenu) individualAirlineSubMenu.style.display = 'none';
    if (aircraftScheduleMenu) aircraftScheduleMenu.style.display = 'block';
    if (aircraftScheduleTitle) aircraftScheduleTitle.textContent = `${aircraftRegistration} Schedule`;
    
    // Generate and display calendar
    generateCalendar();
}

function generateCalendar() {
    const calendarBody = document.getElementById('calendarBody');
    if (!calendarBody) return;
    
    console.log('🗓️ GENERATING CALENDAR GRID');
    console.log('   Day 0 = Monday, Day 1 = Tuesday, Day 2 = Wednesday, Day 3 = Thursday, Day 4 = Friday, Day 5 = Saturday, Day 6 = Sunday');
    
    // Generate time slots from 00:00 to 23:55 in 5-minute increments
    let calendarHTML = '';
    
    for (let hour = 0; hour < 24; hour++) {
        for (let minute = 0; minute < 60; minute += 5) {
            const timeString = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
            
            calendarHTML += `
                <div class="time-slot" data-time="${timeString}">
                    <div class="time-label">${timeString}</div>
                    <div class="day-cell" data-day="0" data-time="${timeString}"></div>
                    <div class="day-cell" data-day="1" data-time="${timeString}"></div>
                    <div class="day-cell" data-day="2" data-time="${timeString}"></div>
                    <div class="day-cell" data-day="3" data-time="${timeString}"></div>
                    <div class="day-cell" data-day="4" data-time="${timeString}"></div>
                    <div class="day-cell" data-day="5" data-time="${timeString}"></div>
                    <div class="day-cell" data-day="6" data-time="${timeString}"></div>
                </div>
            `;
        }
    }
    
    calendarBody.innerHTML = calendarHTML;
    
    // Populate existing schedule items
    populateScheduleItems();
    
    // Add click event listeners to day cells
    addDayCellClickListeners();
}

// Helper function to get all time slots between start and end time
function getTimeSlotsBetween(startTime, endTime) {
    const slots = [];
    const startMinutes = timeToMinutes(startTime);
    const endMinutes = timeToMinutes(endTime);
    
    console.log(`   🕐 getTimeSlotsBetween: ${startTime} (${startMinutes} min) to ${endTime} (${endMinutes} min)`);
    
    // Check if this is a true overnight flight (end time is earlier than start time, indicating next day)
    const isOvernight = endMinutes < startMinutes;
    
    console.log(`   🔍 Debug: startMinutes=${startMinutes}, endMinutes=${endMinutes}, isOvernight=${isOvernight}`);
    
    if (isOvernight) {
        console.log(`   🌙 Overnight flight detected: ${startTime} to ${endTime} (spans midnight)`);
        
        // Generate slots from start time to end of current day (23:55)
        for (let minutes = startMinutes; minutes <= 1435; minutes += 5) { // 1435 = 23:55
            const hours = Math.floor(minutes / 60) % 24;
            const mins = minutes % 60;
            const timeString = `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
            slots.push(timeString);
            if (timeString === '23:55') {
                console.log(`   ✅ Found 23:55 slot at minutes=${minutes}`);
            }
        }
        
        // Generate slots from start of next day (00:00) to the end time
        for (let minutes = 0; minutes < endMinutes; minutes += 5) {
            const hours = Math.floor(minutes / 60) % 24;
            const mins = minutes % 60;
            const timeString = `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
            slots.push(timeString);
        }
    } else {
        // Normal case - same day
        console.log(`   ☀️ Same-day flight: ${startTime} to ${endTime}`);
        // Special cases: if endTime is 23:55 or 23:59, we want to include 23:55
        const includeEndTime = (endTime === '23:55' || endTime === '23:59');
        const loopEnd = includeEndTime ? 1435 : endMinutes - 5; // 1435 = 23:55
        
        for (let minutes = startMinutes; minutes <= loopEnd; minutes += 5) {
            const hours = Math.floor(minutes / 60) % 24;
            const mins = minutes % 60;
            const timeString = `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
            slots.push(timeString);
        }
    }
    
    console.log(`   🕐 Generated ${slots.length} time slots: ${slots[0] || 'none'} to ${slots[slots.length-1] || 'none'}`);
    if (slots.length > 0) {
        console.log(`   📋 All slots: ${slots.join(', ')}`);
    }
    return slots;
}

let scheduleHoverTooltipEl = null;
let scheduleContextMenuEl = null;

function ensureScheduleHoverTooltip() {
    if (scheduleHoverTooltipEl && document.body.contains(scheduleHoverTooltipEl)) {
        return scheduleHoverTooltipEl;
    }

    scheduleHoverTooltipEl = document.createElement('div');
    scheduleHoverTooltipEl.className = 'schedule-item-tooltip';
    document.body.appendChild(scheduleHoverTooltipEl);
    return scheduleHoverTooltipEl;
}

function hideScheduleHoverTooltip() {
    if (!scheduleHoverTooltipEl) return;
    scheduleHoverTooltipEl.classList.remove('show');
}

function ensureScheduleContextMenu() {
    if (scheduleContextMenuEl && document.body.contains(scheduleContextMenuEl)) {
        return scheduleContextMenuEl;
    }

    scheduleContextMenuEl = document.createElement('div');
    scheduleContextMenuEl.className = 'schedule-context-menu';
    scheduleContextMenuEl.innerHTML = '<div class="schedule-context-menu-actions"></div>';
    document.body.appendChild(scheduleContextMenuEl);

    document.addEventListener('click', hideScheduleContextMenu);
    document.addEventListener('contextmenu', (event) => {
        const clickedInsideMenu = scheduleContextMenuEl && scheduleContextMenuEl.contains(event.target);
        if (!clickedInsideMenu) hideScheduleContextMenu();
    });
    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') hideScheduleContextMenu();
    });
    window.addEventListener('scroll', hideScheduleContextMenu, true);

    return scheduleContextMenuEl;
}

function hideScheduleContextMenu() {
    if (!scheduleContextMenuEl) return;
    scheduleContextMenuEl.classList.remove('show');
    scheduleContextMenuEl._actions = null;
}

function showScheduleContextMenu(clientX, clientY, actions = []) {
    const menu = ensureScheduleContextMenu();
    const actionsHost = menu.querySelector('.schedule-context-menu-actions');
    if (!actionsHost) return;

    const validActions = Array.isArray(actions)
        ? actions.filter(action => action && typeof action.label === 'string' && typeof action.onClick === 'function')
        : [];

    if (validActions.length === 0) return;

    actionsHost.innerHTML = validActions.map((action) => {
        const classes = ['schedule-context-menu-item'];
        if (action.variant) classes.push(`schedule-context-menu-item--${action.variant}`);
        return `<button type="button" class="${classes.join(' ')}">${escapeHtml(action.label)}</button>`;
    }).join('');

    const actionButtons = actionsHost.querySelectorAll('.schedule-context-menu-item');
    actionButtons.forEach((button, index) => {
        button.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();
            validActions[index].onClick();
            hideScheduleContextMenu();
        });
    });

    menu._actions = validActions;
    menu.classList.add('show');

    const margin = 8;
    const menuRect = menu.getBoundingClientRect();
    let left = clientX;
    let top = clientY;

    if (left + menuRect.width > window.innerWidth - margin) {
        left = window.innerWidth - menuRect.width - margin;
    }
    if (top + menuRect.height > window.innerHeight - margin) {
        top = window.innerHeight - menuRect.height - margin;
    }

    menu.style.left = `${Math.max(margin, left)}px`;
    menu.style.top = `${Math.max(margin, top)}px`;
}

function positionScheduleHoverTooltip(event) {
    if (!scheduleHoverTooltipEl) return;

    const margin = 12;
    const tooltipRect = scheduleHoverTooltipEl.getBoundingClientRect();
    let left = event.clientX + margin;
    let top = event.clientY + margin;

    if (left + tooltipRect.width > window.innerWidth - margin) {
        left = event.clientX - tooltipRect.width - margin;
    }
    if (top + tooltipRect.height > window.innerHeight - margin) {
        top = event.clientY - tooltipRect.height - margin;
    }

    scheduleHoverTooltipEl.style.left = `${Math.max(margin, left)}px`;
    scheduleHoverTooltipEl.style.top = `${Math.max(margin, top)}px`;
}

function getScheduleItemHoverHTML(item) {
    const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    const title = item.type === 'flight'
        ? (item.flightNumber ? `Flight ${escapeHtml(item.flightNumber)}` : 'Flight')
        : escapeHtml((item.type || 'Scheduled').toUpperCase());

    let html = `<div class="schedule-tooltip-title">${title}</div>`;
    html += `<div><strong>Day:</strong> ${escapeHtml(dayNames[item.day] || 'Unknown')}</div>`;
    html += `<div><strong>Time:</strong> ${escapeHtml(item.startTime || '--:--')} - ${escapeHtml(item.endTime || '--:--')}</div>`;

    if (item.route) html += `<div><strong>Route:</strong> ${escapeHtml(item.route)}</div>`;
    if (item.airport) html += `<div><strong>Airport:</strong> ${escapeHtml(item.airport)}</div>`;
    if (item.gate) html += `<div><strong>Gate:</strong> ${escapeHtml(item.gate)}</div>`;
    if (item.phase) html += `<div><strong>Phase:</strong> ${escapeHtml(item.phase)}</div>`;
    if (item.description) html += `<div><strong>Info:</strong> ${escapeHtml(item.description)}</div>`;

    return html;
}

function getGateBlockHoverHTML(block, airportName) {
    const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    let html = '<div class="schedule-tooltip-title">Gate Block</div>';
    html += `<div><strong>Airport:</strong> ${escapeHtml(airportName || 'Unknown')}</div>`;
    html += `<div><strong>Gate:</strong> ${escapeHtml(block.gate || 'Unknown')}</div>`;
    html += `<div><strong>Day:</strong> ${escapeHtml(dayNames[block.day] || 'Unknown')}</div>`;
    html += `<div><strong>Time:</strong> ${escapeHtml(block.startTime || '--:--')} - ${escapeHtml(block.endTime || '--:--')}</div>`;
    if (block.reason) html += `<div><strong>Reason:</strong> ${escapeHtml(block.reason)}</div>`;
    return html;
}

function attachScheduleHoverTooltip(element, getTooltipHTML) {
    if (!element || typeof getTooltipHTML !== 'function') return;

    element.addEventListener('mouseenter', (event) => {
        const tooltip = ensureScheduleHoverTooltip();
        tooltip.innerHTML = getTooltipHTML();
        tooltip.classList.add('show');
        positionScheduleHoverTooltip(event);
    });

    element.addEventListener('mousemove', (event) => {
        positionScheduleHoverTooltip(event);
    });

    element.addEventListener('mouseleave', hideScheduleHoverTooltip);
}

function attachScheduleContextMenu(element, getActions) {
    if (!element || typeof getActions !== 'function') return;

    element.addEventListener('contextmenu', (event) => {
        event.preventDefault();
        event.stopPropagation();
        hideScheduleHoverTooltip();
        showScheduleContextMenu(event.clientX, event.clientY, getActions());
    });
}

// OPTIMIZATION: Function to add specific schedule items to calendar incrementally
// This avoids rebuilding the entire calendar when adding a new flight
function addScheduleItemsToCalendar(items, startIndex) {
    if (!currentAircraftForSchedule || !items || items.length === 0) return;
    
    const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    
    items.forEach((item, relativeIndex) => {
        const index = startIndex + relativeIndex;
        const dayName = dayNames[item.day] || 'Unknown';
        logger(`   Adding item ${index}: ${item.phase || item.type} - Day ${item.day} (${dayName}) ${item.startTime}-${item.endTime}`);
        
        // Check if this is an overnight item
        const startMinutes = timeToMinutes(item.startTime);
        const endMinutes = timeToMinutes(item.endTime);
        const isOvernight = endMinutes < startMinutes;
        
        if (isOvernight) {
            // Handle overnight item - split across two days
            const nextDay = getNextDay(item.day);
            
            // First part: current day from start time to 23:55
            const currentDaySlots = getTimeSlotsBetween(item.startTime, '23:55');
            currentDaySlots.forEach((timeSlot, slotIndex) => {
                const dayCell = document.querySelector(`[data-day="${item.day}"][data-time="${timeSlot}"]`);
                if (dayCell && !dayCell.querySelector('.schedule-item')) { // Only add if cell is empty
                    const scheduleItem = document.createElement('div');
                    let className = `schedule-item ${item.type}`;
                    if (item.phase) className += ` ${item.phase}`;
                    if (slotIndex > 0) className += ' continuation';
                    
                    scheduleItem.textContent = '';
                    scheduleItem.className = className;
                    scheduleItem.onclick = (e) => {
                        e.stopPropagation();
                        showScheduleItemDetails(item, index);
                    };
                    attachScheduleHoverTooltip(scheduleItem, () => getScheduleItemHoverHTML(item));
                    attachScheduleContextMenu(scheduleItem, () => {
                        const actions = [];
                        if (item.type === 'flight' && item.flightNumber) {
                            actions.push({
                                label: 'Edit Flight Number',
                                onClick: () => editFlightNumber(index)
                            });
                        }
                        if (item.gate && item.airport && item.phase && item.flightNumber) {
                            actions.push({
                                label: 'Change Gate',
                                onClick: () => changeGateAssignment(currentAircraftForSchedule, index, item.gate, item.airport, item.day, item.startTime, item.endTime, item.phase, item.flightNumber)
                            });
                        }
                        actions.push({ label: 'Delete', variant: 'delete', onClick: () => deleteScheduleItem(index) });
                        return actions;
                    });
                    
                    dayCell.appendChild(scheduleItem);
                }
            });
            
            // Second part: next day from 00:00 to end time
            const nextDaySlots = getTimeSlotsBetween('00:00', item.endTime);
            nextDaySlots.forEach((timeSlot, slotIndex) => {
                const dayCell = document.querySelector(`[data-day="${nextDay}"][data-time="${timeSlot}"]`);
                if (dayCell && !dayCell.querySelector('.schedule-item')) { // Only add if cell is empty
                    const scheduleItem = document.createElement('div');
                    let className = `schedule-item ${item.type}`;
                    if (item.phase) className += ` ${item.phase}`;
                    className += ' continuation';
                    
                    scheduleItem.textContent = '';
                    scheduleItem.className = className;
                    scheduleItem.onclick = (e) => {
                        e.stopPropagation();
                        showScheduleItemDetails(item, index);
                    };
                    attachScheduleHoverTooltip(scheduleItem, () => getScheduleItemHoverHTML(item));
                    attachScheduleContextMenu(scheduleItem, () => {
                        const actions = [];
                        if (item.type === 'flight' && item.flightNumber) {
                            actions.push({
                                label: 'Edit Flight Number',
                                onClick: () => editFlightNumber(index)
                            });
                        }
                        if (item.gate && item.airport && item.phase && item.flightNumber) {
                            actions.push({
                                label: 'Change Gate',
                                onClick: () => changeGateAssignment(currentAircraftForSchedule, index, item.gate, item.airport, item.day, item.startTime, item.endTime, item.phase, item.flightNumber)
                            });
                        }
                        actions.push({ label: 'Delete', variant: 'delete', onClick: () => deleteScheduleItem(index) });
                        return actions;
                    });
                    
                    dayCell.appendChild(scheduleItem);
                }
            });
        } else {
            // Normal same-day item
            const timeSlots = getTimeSlotsBetween(item.startTime, item.endTime);
            
            timeSlots.forEach((timeSlot, slotIndex) => {
                const dayCell = document.querySelector(`[data-day="${item.day}"][data-time="${timeSlot}"]`);
                if (dayCell && !dayCell.querySelector('.schedule-item')) { // Only add if cell is empty
                    const scheduleItem = document.createElement('div');
                    let className = `schedule-item ${item.type}`;
                    if (item.phase) className += ` ${item.phase}`;
                    if (slotIndex > 0) className += ' continuation';
                    
                    scheduleItem.textContent = '';
                    scheduleItem.className = className;
                    scheduleItem.onclick = (e) => {
                        e.stopPropagation();
                        showScheduleItemDetails(item, index);
                    };
                    
                    dayCell.appendChild(scheduleItem);
                }
            });
        }
    });
}

