// Edit flight number for a specific schedule item
function editFlightNumber(index) {
    if (!currentAircraftForSchedule || !aircraftSchedules[currentAircraftForSchedule]) {
        showNonBlockingNotification('❌ No aircraft selected for scheduling', 'error');
        return;
    }
    
    const schedule = aircraftSchedules[currentAircraftForSchedule];
    const item = schedule[index];
    
    if (!item || item.type !== 'flight') {
        alert('This item cannot be edited');
        return;
    }
    
    // Store the current item index for editing
    window.currentScheduleItemIndex = index;
    
    // Create edit form HTML
    const editFormHTML = `
        <div style="background: #f8f9fa; padding: 20px; border-radius: 8px; margin-bottom: 15px; border-left: 4px solid #4e8ca0;">
            <h5 style="margin: 0 0 15px 0; color: #19363c;">Edit Flight Number</h5>
            <div class="form-group">
                <label for="editFlightNumberInput" style="display: block; margin-bottom: 5px; color: #19363c; font-weight: 500;">Flight Number:</label>
                <input type="text" id="editFlightNumberInput" value="${item.flightNumber || ''}" 
                       style="width: 100%; padding: 10px; border: 2px solid #A68A64; border-radius: 6px; font-size: 14px; background: #e6e6e9; color: #19363c; box-sizing: border-box;"
                       placeholder="Enter flight number (e.g., AA1234, DL5678)">
                <small style="display: block; margin-top: 3px; color: #A68A64; font-size: 12px;">Enter the flight number for this flight</small>
            </div>
            <div style="margin-top: 15px; display: flex; gap: 10px;">
                <button type="button" class="option-btn" onclick="saveFlightNumberEdit()" style="background: #27ae60; flex: 1;">
                    💾 Save Changes
                </button>
                <button type="button" class="option-btn cancel-btn" onclick="cancelFlightNumberEdit()" style="flex: 1;">
                    ❌ Cancel
                </button>
            </div>
        </div>
    `;
    
    // Populate modal content with edit form
    document.getElementById('scheduleItemDetailsContent').innerHTML = editFormHTML;
    
    // Focus on the input field and add keyboard support
    setTimeout(() => {
        const input = document.getElementById('editFlightNumberInput');
        if (input) {
            input.focus();
            input.select();
            
            // Add keyboard event listeners
            input.addEventListener('keydown', function(e) {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    saveFlightNumberEdit();
                } else if (e.key === 'Escape') {
                    e.preventDefault();
                    cancelFlightNumberEdit();
                }
            });
        }
    }, 100);
}

// Save flight number edit
function saveFlightNumberEdit() {
    const newFlightNumber = document.getElementById('editFlightNumberInput').value.trim();
    
    if (!newFlightNumber) {
        showNonBlockingNotification('❌ Please enter a flight number', 'error');
        return;
    }
    
    // Basic validation for flight number format
    if (newFlightNumber.length < 2 || newFlightNumber.length > 10) {
        showNonBlockingNotification('❌ Flight number must be between 2 and 10 characters long', 'error');
        return;
    }
    
    // Check for invalid characters (only allow letters, numbers, and common flight number characters)
    if (!/^[A-Za-z0-9\-]+$/.test(newFlightNumber)) {
        showNonBlockingNotification('❌ Flight number can only contain letters, numbers, and hyphens', 'error');
        return;
    }
    
    if (!currentAircraftForSchedule || !aircraftSchedules[currentAircraftForSchedule]) {
        showNonBlockingNotification('❌ No aircraft selected for scheduling', 'error');
        return;
    }
    
    const schedule = aircraftSchedules[currentAircraftForSchedule];
    const itemIndex = window.currentScheduleItemIndex;
    const item = schedule[itemIndex];
    
    if (!item || item.type !== 'flight') {
        alert('This item cannot be edited');
        return;
    }
    
    // Update the flight number for all related items (boarding, flight, disembarking)
    const flightNumber = item.flightNumber;
    const route = item.route;
    const day = item.day;
    const startTime = item.startTime;
    
    // Find all items that are part of the same flight
    let updatedCount = 0;
    schedule.forEach((scheduleItem, index) => {
        if (scheduleItem.type === 'flight' && 
            scheduleItem.route === route && 
            scheduleItem.day === day && 
            scheduleItem.startTime === startTime &&
            scheduleItem.flightNumber === flightNumber) {
            scheduleItem.flightNumber = newFlightNumber;
            updatedCount++;
        }
    });
    
    // Save the updated schedule
    saveAircraftSchedules();
    
    // Update route utilization from schedules
    updateRouteUtilizationFromSchedules();
    
    // Regenerate calendar to reflect changes
    generateCalendar();
    
    // Show success message
    showNonBlockingNotification(`✅ Flight number updated successfully! Updated ${updatedCount} schedule item(s).`, 'success');
    
    // Close the modal
    document.getElementById('scheduleItemDetailsModal').style.display = 'none';
    
    // Briefly highlight the updated flight in the calendar
    highlightUpdatedFlight(route, day, startTime);
}

// Cancel flight number edit
function cancelFlightNumberEdit() {
    // Close the modal
    document.getElementById('scheduleItemDetailsModal').style.display = 'none';
}

// Highlight updated flight in calendar
function highlightUpdatedFlight(route, day, startTime) {
    // Find all schedule items for this flight and add a temporary highlight class
    const scheduleItems = document.querySelectorAll('.schedule-item');
    scheduleItems.forEach(item => {
        // This is a simple approach - in a real implementation, you'd need to match
        // the specific flight based on route, day, and start time
        if (item.classList.contains('flight')) {
            item.style.boxShadow = '0 0 10px rgba(78, 140, 160, 0.8)';
            item.style.border = '2px solid #4e8ca0';
            
            // Remove highlight after 2 seconds
            setTimeout(() => {
                item.style.boxShadow = '';
                item.style.border = '';
            }, 2000);
        }
    });
}

// Delete schedule item
function deleteScheduleItem(index) {
    // Ensure schedule isolation - only delete from current aircraft's schedule
    if (!currentAircraftForSchedule) {
        alert('Error: No aircraft selected for deletion operation');
        return;
    }
    
    const schedule = aircraftSchedules[currentAircraftForSchedule];
    if (!schedule || !schedule[index]) {
        showNonBlockingNotification('❌ Error: Schedule item not found', 'error');
        return;
    }
    
    const itemToDelete = schedule[index];
    
    // If it's a flight item, we need to delete all related phases (boarding, flight, disembarking)
    if (itemToDelete.type === 'flight' && itemToDelete.route) {
        const route = itemToDelete.route;
        const flightNumber = itemToDelete.flightNumber;
        
        // Find all items that are part of the same flight
        const relatedItems = [];
        schedule.forEach((item, i) => {
            if (item.type === 'flight' && 
                item.route === route && 
                item.flightNumber === flightNumber) {
                relatedItems.push(i);
            }
        });
        
        // Sort indices in descending order to avoid index shifting issues
        relatedItems.sort((a, b) => b - a);
        
        if (confirm(`Are you sure you want to delete flight ${flightNumber}? This will remove ${relatedItems.length} schedule item(s) (boarding, flight, and disembarking).`)) {
            // Delete all related items
            relatedItems.forEach(itemIndex => {
                schedule.splice(itemIndex, 1);
            });
            
            saveAircraftSchedules();
            
            // Update route utilization from schedules
            updateRouteUtilizationFromSchedules();
            
            // Regenerate calendar to clear conflicts and reflect changes
            generateCalendar();
            
            console.log(`Deleted flight ${flightNumber} from aircraft: ${currentAircraftForSchedule}`, relatedItems.length, 'items removed');
            showNonBlockingNotification(`✅ Flight ${flightNumber} deleted successfully! Removed ${relatedItems.length} schedule item(s).`, 'success');
        }
    } else {
        // For non-flight items, delete just the single item
        if (confirm('Are you sure you want to delete this schedule item?')) {
            schedule.splice(index, 1);
            saveAircraftSchedules();
            
            // Update route utilization from schedules
            updateRouteUtilizationFromSchedules();
            
            // Regenerate calendar to clear conflicts and reflect changes
            generateCalendar();
            
            console.log(`Deleted schedule item from aircraft: ${currentAircraftForSchedule}`, itemToDelete);
            showNonBlockingNotification('✅ Schedule item deleted successfully!', 'success');
        }
    }
}

// Delete gate block
function deleteGateBlock(airportName, index) {
    if (confirm('Are you sure you want to delete this gate block?')) {
        if (currentAircraftForSchedule && gateBlocks[currentAircraftForSchedule] && gateBlocks[currentAircraftForSchedule][airportName]) {
            const airportBlocks = gateBlocks[currentAircraftForSchedule][airportName];
            if (airportBlocks && airportBlocks[index]) {
                airportBlocks.splice(index, 1);
                saveGateBlocks();
                generateCalendar(); // Regenerate calendar to reflect changes
                showNonBlockingNotification('✅ Gate block deleted successfully!', 'success');
            }
        }
    }
}

