// Display validation errors in a user-friendly popup
function showValidationError(errors) {
    let errorMessage = "Flight scheduling validation failed:\n\n";
    
    errors.forEach((error, index) => {
        errorMessage += `${index + 1}. ${error.message}\n`;
        if (error.details) {
            errorMessage += `   Details: ${error.details}\n`;
        }
        errorMessage += "\n";
    });
    
    errorMessage += "Please correct these issues and try again.";
    
    alert(errorMessage);
}

function checkGateConflicts(airportName, gateName, day, startTime, endTime, excludeIndex = null, excludeAircraft = null, excludeGateBlock = null, autoGateBlocksEnabled = true) {
    console.log(`🔍 Checking gate conflicts for ${gateName} at ${airportName} on day ${day} from ${startTime} to ${endTime}`);
    console.log(`🔍 Auto gate blocks enabled: ${autoGateBlocksEnabled}`);
    
    // Use the comprehensive gate conflict check system
    const result = comprehensiveGateConflictCheck(airportName, gateName, day, startTime, endTime, excludeAircraft, excludeIndex, excludeGateBlock, autoGateBlocksEnabled);
    
    if (result.conflict && result.conflicts.length > 0) {
        // Return the first conflict in the old format for backward compatibility
        const firstConflict = result.conflicts[0];
        return {
            conflict: true,
            type: firstConflict.type,
            aircraft: firstConflict.aircraft,
            reason: firstConflict.reason,
            conflictingTime: firstConflict.conflictingTime,
            overlapMinutes: firstConflict.overlapMinutes
        };
    }
    
    return { conflict: false };
    
    // Legacy code below (kept for reference but not used)
    console.log(`🔍 Total aircraft schedules to check: ${Object.keys(aircraftSchedules).length}`);
    
    // Check aircraft schedules for conflicts across ALL aircraft
    for (const aircraftReg of Object.keys(aircraftSchedules)) {
        const schedule = aircraftSchedules[aircraftReg];
        if (!Array.isArray(schedule)) {
            console.log(`  ⚠️ Schedule for ${aircraftReg} is not an array:`, schedule);
            continue;
        }
        
        console.log(`  🔍 Checking ${aircraftReg} schedule (${schedule.length} items)`);
        
        for (let index = 0; index < schedule.length; index++) {
            const item = schedule[index];
            
            // Skip if this is the item being edited
            if (excludeIndex !== null && aircraftReg === excludeAircraft && index === excludeIndex) {
                console.log(`  ⏭️ Skipping item ${index} (being edited)`);
                continue;
            }
            
            // Debug: Log all items being checked
            console.log(`    📋 Item ${index}: day=${item.day}, gate="${item.gate}", airport="${item.airport}", time=${item.startTime}-${item.endTime}`);
            
            // Check if this item uses the same gate at the same airport on the same day
            // Handle gate name format differences
            const itemGateNumber = item.gate ? item.gate.split(' (')[0] : '';
            const checkGateNumber = gateName ? gateName.split(' (')[0] : '';
            
            if (item.day === day && itemGateNumber === checkGateNumber && item.airport === airportName) {
                const itemStart = timeToMinutes(item.startTime);
                const itemEnd = timeToMinutes(item.endTime);
                const checkStart = timeToMinutes(startTime);
                const checkEnd = timeToMinutes(endTime);
                
                console.log(`  🎯 MATCH FOUND! Checking ${aircraftReg} item: ${item.startTime}-${item.endTime} (${itemStart}-${itemEnd} min)`);
                console.log(`  🎯 Requested time: ${startTime}-${endTime} (${checkStart}-${checkEnd} min)`);
                console.log(`  🎯 Overlap check: ${checkStart} <= ${itemEnd} && ${checkEnd} >= ${itemStart} = ${(checkStart <= itemEnd && checkEnd >= itemStart)}`);
                
                // Check for overlap (excluding zero-minute overlaps)
                if ((checkStart < itemEnd && checkEnd > itemStart)) {
                    console.log(`  ❌ CONFLICT FOUND with ${aircraftReg}: ${item.description || item.type}`);
                    return {
                        conflict: true,
                        type: 'aircraft',
                        aircraft: aircraftReg,
                        description: item.description || item.type,
                        conflictingTime: `${item.startTime}-${item.endTime}`
                    };
                } else {
                    console.log(`  ✅ No overlap with ${aircraftReg} item`);
                }
            }
        }
    }
    
    // Check gate blocks for conflicts (only for current aircraft)
    if (currentAircraftForSchedule && gateBlocks[currentAircraftForSchedule] && gateBlocks[currentAircraftForSchedule][airportName]) {
        const airportBlocks = gateBlocks[currentAircraftForSchedule][airportName];
        for (const block of airportBlocks) {
            if (block.day === day && block.gate === gateName) {
                const blockStart = timeToMinutes(block.startTime);
                const blockEnd = timeToMinutes(block.endTime);
                const checkStart = timeToMinutes(startTime);
                const checkEnd = timeToMinutes(endTime);
                
                console.log(`  Checking against gate block: ${block.startTime}-${block.endTime} (${blockStart}-${blockEnd} min)`);
                
                // Check for overlap
                if ((checkStart < blockEnd && checkEnd > blockStart)) {
                    console.log(`  ❌ CONFLICT FOUND with gate block: ${block.reason}`);
                    return {
                        conflict: true,
                        type: 'block',
                        reason: block.reason,
                        conflictingTime: `${block.startTime}-${block.endTime}`
                    };
                }
            }
        }
    }
    
    console.log(`  ✅ No conflicts found for ${gateName} at ${airportName}`);
    return { conflict: false };
}

