function startFollowingAircraft(aircraftId) {
    // Clear any existing follow interval
    if (window.followInterval) {
        clearInterval(window.followInterval);
    }
    
    // Start following interval
    window.followInterval = setInterval(() => {
        const aircraft = animatedAircraft.get(aircraftId);
        if (aircraft && aircraft.marker) {
            // Center map on aircraft
            map.setView(aircraft.marker.getLatLng(), map.getZoom());
        } else {
            // Aircraft no longer exists, stop following
            clearInterval(window.followInterval);
            followedAircraft = null;
        }
    }, 1000); // Update every second
}

function stopFollowingAircraft() {
    if (window.followInterval) {
        clearInterval(window.followInterval);
        window.followInterval = null;
    }
    followedAircraft = null;
}

// Export all data function
function exportAllData() {
    try {
        // Collect all data from localStorage and current state
        const exportData = {
            version: "1.0",
            exportDate: new Date().toISOString(),
            data: {
                airports: JSON.parse(localStorage.getItem('savedAirports') || '[]'),
                routes: JSON.parse(localStorage.getItem('savedRoutes') || '[]'),
                aircraftTypes: JSON.parse(localStorage.getItem('savedAircraft') || '[]'),
                registeredAircraft: JSON.parse(localStorage.getItem('savedRegisteredAircraft') || '[]'),
                airlines: JSON.parse(localStorage.getItem('savedAirlines') || '[]'),
                gates: JSON.parse(localStorage.getItem('savedGates') || '{}'),
                gateBlocks: JSON.parse(localStorage.getItem('savedGateBlocks') || '{}'),
                schedule: JSON.parse(localStorage.getItem('savedSchedule') || '[]'),
                aircraftSchedules: JSON.parse(localStorage.getItem('savedAircraftSchedules') || '{}'),
                routeScheduleTemplates: JSON.parse(localStorage.getItem('routeScheduleTemplates') || '{}'),
                airlineRouteFlightNumberRegistry: JSON.parse(localStorage.getItem('airlineRouteFlightNumberRegistry') || '{}')
            }
        };

        // Create and download the file
        const dataStr = JSON.stringify(exportData, null, 2);
        const dataBlob = new Blob([dataStr], { type: 'application/json' });
        const url = URL.createObjectURL(dataBlob);
        
        const link = document.createElement('a');
        link.href = url;
        link.download = `kohben-travel-data-${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);

        // Show success message
        alert('Data exported successfully!');
        console.log('Data exported successfully');
    } catch (error) {
        console.error('Error exporting data:', error);
        alert('Error exporting data. Please try again.');
    }
}

// Import data function
function handleFileImport(event) {
    const file = event.target.files[0];
    if (!file) return;

    if (file.type !== 'application/json') {
        alert('Please select a valid JSON file.');
        return;
    }

    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const importData = JSON.parse(e.target.result);
            
            // Validate the import data structure
            if (!importData.data || !importData.version) {
                throw new Error('Invalid file format');
            }

            // Confirm import
            const confirmMessage = `This will replace all current data with the imported data.\n\n` +
                                 `Import contains:\n` +
                                 `- ${importData.data.airports?.length || 0} airports\n` +
                                 `- ${importData.data.routes?.length || 0} routes\n` +
                                 `- ${importData.data.aircraftTypes?.length || 0} aircraft types\n` +
                                 `- ${importData.data.registeredAircraft?.length || 0} registered aircraft\n` +
                                 `- ${importData.data.airlines?.length || 0} airlines\n` +
                                 `- ${importData.data.schedule?.length || 0} schedule items\n\n` +
                                 `Are you sure you want to continue?`;
            
            if (confirm(confirmMessage)) {
                importAllData(importData);
            }
        } catch (error) {
            console.error('Error parsing import file:', error);
            alert('Error reading file. Please check the file format.');
        }
    };
    
    reader.readAsText(file);
    
    // Reset the file input
    event.target.value = '';
}

// Import all data function
function importAllData(importData) {
    try {
        // Clear current data
        localStorage.removeItem('savedAirports');
        localStorage.removeItem('savedRoutes');
        localStorage.removeItem('savedAircraft');
        localStorage.removeItem('savedRegisteredAircraft');
        localStorage.removeItem('savedAirlines');
        localStorage.removeItem('savedGates');
        localStorage.removeItem('savedGateBlocks');
        localStorage.removeItem('savedSchedule');
        localStorage.removeItem('savedAircraftSchedules');
        localStorage.removeItem('routeScheduleTemplates');
        localStorage.removeItem('airlineRouteFlightNumberRegistry');

        // Import new data
        if (importData.data.airports) {
            localStorage.setItem('savedAirports', JSON.stringify(importData.data.airports));
        }
        if (importData.data.routes) {
            localStorage.setItem('savedRoutes', JSON.stringify(importData.data.routes));
        }
        if (importData.data.aircraftTypes) {
            localStorage.setItem('savedAircraft', JSON.stringify(importData.data.aircraftTypes));
        }
        if (importData.data.registeredAircraft) {
            localStorage.setItem('savedRegisteredAircraft', JSON.stringify(importData.data.registeredAircraft));
        }
        if (importData.data.airlines) {
            localStorage.setItem('savedAirlines', JSON.stringify(importData.data.airlines));
        }
        if (importData.data.schedule) {
            localStorage.setItem('savedSchedule', JSON.stringify(importData.data.schedule));
        }
        if (importData.data.gates) {
            localStorage.setItem('savedGates', JSON.stringify(importData.data.gates));
        }
        if (importData.data.gateBlocks) {
            localStorage.setItem('savedGateBlocks', JSON.stringify(importData.data.gateBlocks));
        }
        if (importData.data.aircraftSchedules) {
            localStorage.setItem('savedAircraftSchedules', JSON.stringify(importData.data.aircraftSchedules));
        }
        if (importData.data.routeScheduleTemplates) {
            localStorage.setItem('routeScheduleTemplates', JSON.stringify(importData.data.routeScheduleTemplates));
        }
        if (importData.data.airlineRouteFlightNumberRegistry) {
            localStorage.setItem('airlineRouteFlightNumberRegistry', JSON.stringify(importData.data.airlineRouteFlightNumberRegistry));
        }

        // Reload the application
        location.reload();
        
        alert('Data imported successfully!');
        console.log('Data imported successfully');
    } catch (error) {
        console.error('Error importing data:', error);
        alert('Error importing data. Please try again.');
    }
}

