// Enhanced Gate Conflict Detection System
// ======================================

// Helper function to normalize gate names for comparison
function normalizeGateName(gateName) {
    if (!gateName) return '';
    
    // Remove extra spaces, normalize case, and handle common variations
    return gateName
        .trim()                    // Remove leading/trailing spaces
        .replace(/\s+/g, ' ')      // Replace multiple spaces with single space
        .toLowerCase()             // Convert to lowercase for case-insensitive comparison
        .replace(/[()]/g, '')      // Remove parentheses for comparison
        .replace(/\s+/g, '');      // Remove all spaces for final comparison
}

// Function to update all aircraft schedules and gate blocks when a gate name is renamed
function updateAircraftForGateRename(airportName, oldGateName, newGateName) {
    if (!airportName || !oldGateName || !newGateName || oldGateName === newGateName) {
        return;
    }
    
    console.log(`🔄 Updating all aircraft for gate rename: "${oldGateName}" → "${newGateName}" at ${airportName}`);
    
    let updatedScheduleCount = 0;
    let updatedGateBlockCount = 0;
    
    // Normalize gate names for comparison (using the same normalization as in gate calendar)
    // This removes parentheses and normalizes spaces to handle both formats:
    // "A12 Terminal A" and "A12 (Terminal A)" both normalize to the same value
    const normalizeGateNameForComparison = (name) => {
        if (!name) return '';
        return name.replace(/[()]/g, '').replace(/\s+/g, ' ').trim();
    };
    
    const normalizedOldGate = normalizeGateNameForComparison(oldGateName);
    
    // Also create the old gate name with parentheses format (as it might be stored that way)
    // Extract gate number and terminal from old gate name
    const oldGateMatch = oldGateName.match(/^(.+?)\s+(.+)$/);
    const oldGateWithParentheses = oldGateMatch ? `${oldGateMatch[1]} (${oldGateMatch[2]})` : oldGateName;
    
    // Create new gate name with parentheses format (as schedule items store it this way)
    const newGateMatch = newGateName.match(/^(.+?)\s+(.+)$/);
    const newGateWithParentheses = newGateMatch ? `${newGateMatch[1]} (${newGateMatch[2]})` : newGateName;
    
    // Update all schedule items in aircraftSchedules
    Object.keys(aircraftSchedules).forEach(aircraftReg => {
        const schedule = aircraftSchedules[aircraftReg];
        if (!Array.isArray(schedule)) return;
        
        schedule.forEach(item => {
            if (item.airport === airportName && item.gate) {
                const normalizedItemGate = normalizeGateNameForComparison(item.gate);
                if (normalizedItemGate === normalizedOldGate) {
                    // Update to new gate name, preserving the format (with or without parentheses)
                    // If the old gate was stored with parentheses, use the new one with parentheses
                    const oldItemGate = item.gate;
                    const currentFormatHasParentheses = item.gate.includes('(');
                    item.gate = currentFormatHasParentheses ? newGateWithParentheses : newGateName;
                    updatedScheduleCount++;
                    console.log(`  ✅ Updated schedule item for aircraft ${aircraftReg}: "${oldItemGate}" → "${item.gate}"`);
                }
            }
        });
    });
    
    // Update all gate blocks
    Object.keys(gateBlocks).forEach(aircraftReg => {
        if (!gateBlocks[aircraftReg] || !gateBlocks[aircraftReg][airportName]) {
            return;
        }
        
        const airportBlocks = gateBlocks[aircraftReg][airportName];
        airportBlocks.forEach(block => {
            if (block.gate) {
                const normalizedBlockGate = normalizeGateNameForComparison(block.gate);
                if (normalizedBlockGate === normalizedOldGate) {
                    // Update to new gate name, preserving the format
                    const oldBlockGate = block.gate;
                    const currentFormatHasParentheses = block.gate.includes('(');
                    block.gate = currentFormatHasParentheses ? newGateWithParentheses : newGateName;
                    updatedGateBlockCount++;
                    console.log(`  ✅ Updated gate block for aircraft ${aircraftReg}: "${oldBlockGate}" → "${block.gate}"`);
                }
            }
        });
    });
    
    // Clear gate name cache for both old and new gate names (all formats)
    gateNameCache.delete(oldGateName);
    gateNameCache.delete(oldGateWithParentheses);
    gateNameCache.delete(newGateName);
    gateNameCache.delete(newGateWithParentheses);
    
    // Mark schedule index as dirty so it gets rebuilt
    scheduleIndexDirty = true;
    
    // Rebuild the schedule index
    rebuildScheduleIndex();
    
    // Save updated schedules and gate blocks
    saveAircraftSchedules();
    saveGateBlocks();
    
    console.log(`✅ Gate rename complete: Updated ${updatedScheduleCount} schedule items and ${updatedGateBlockCount} gate blocks`);
    
    if (updatedScheduleCount > 0 || updatedGateBlockCount > 0) {
        showNonBlockingNotification(`✅ Gate renamed! Updated ${updatedScheduleCount} schedule items and ${updatedGateBlockCount} gate blocks.`, 'success');
    }
}

// Function to check for gate conflicts across all aircraft and gate blocks
// IMPORTANT: This function IGNORES zero-minute overlaps (where flights end exactly when another starts)
// Zero-minute overlaps are considered acceptable since there's no actual time conflict
function comprehensiveGateConflictCheck(airportName, gateName, day, startTime, endTime, excludeAircraft = null, excludeIndex = null, excludeGateBlock = null, autoGateBlocksEnabled = true) {
    console.log(`🔍 COMPREHENSIVE GATE CONFLICT CHECK`);
    console.log(`   Gate: ${gateName} at ${airportName}`);
    console.log(`   Day: ${day} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][day]})`);
    console.log(`   Time: ${startTime} - ${endTime}`);
    console.log(`   Exclude: ${excludeAircraft || 'none'}`);
    console.log(`   Exclude gate block: ${excludeGateBlock ? 'yes' : 'no'}`);
    console.log(`   📝 NOTE: Zero-minute overlaps are ignored (acceptable - no actual conflict)`);

    const conflicts = [];

    // Convert times to minutes for easier comparison
    const checkStart = timeToMinutes(startTime);
    const checkEnd = timeToMinutes(endTime);
    
    // Check if this is an overnight request (spans past midnight)
    const isOvernightRequest = checkEnd < checkStart;
    console.log(`   🌙 Overnight request: ${isOvernightRequest ? 'YES' : 'NO'}`);
    
    if (isOvernightRequest) {
        console.log(`   📅 Overnight request spans from day ${day} to day ${(day + 1) % 7}`);
    }

    // 1. Check ALL aircraft schedules for conflicts (including multi-day flights)
    Object.keys(aircraftSchedules).forEach(aircraftReg => {
        const schedule = aircraftSchedules[aircraftReg];
        if (!Array.isArray(schedule)) return;

        schedule.forEach((item, index) => {
            // Skip excluded aircraft rows: single index match, OR entire aircraft (-1 — e.g. auto gate segments already reserve gate for this operator)
            if (excludeAircraft && aircraftReg === excludeAircraft) {
                if (excludeIndex === -1) return;
                if (excludeIndex != null && index === excludeIndex) return;
            }

            // Early exit: Skip if airport doesn't match
            if (item.airport !== airportName) {
                return;
            }

            // Early exit: Skip if gate is null (flight phases)
            if (!item.gate) {
                return;
            }

            // Check if this item uses the same gate at the same airport
            // Use normalized gate names for comparison to handle variations
            const normalizedItemGate = normalizeGateName(item.gate);
            const normalizedCheckGate = normalizeGateName(gateName);
            
            // Only log gate comparisons when debugging is enabled
            if (window.debugGateConflicts) {
                console.log(`   🔍 Comparing gates: "${item.gate}" (normalized: "${normalizedItemGate}") vs "${gateName}" (normalized: "${normalizedCheckGate}")`);
            }
            
            if (normalizedItemGate === normalizedCheckGate) {
                const itemStart = timeToMinutes(item.startTime);
                const itemEnd = timeToMinutes(item.endTime);
                const isItemOvernight = itemEnd < itemStart;

                // Handle multi-day flights - check if the requested time overlaps with this item
                let hasConflict = false;
                let conflictDetails = '';

                if (isOvernightRequest && isItemOvernight) {
                    // Both request and item are overnight - check for overlap across midnight
                    // Request: day X (startTime to 23:59) + day Y (00:00 to endTime)
                    // Item: item.day (item.startTime to 23:59) + next day (00:00 to item.endTime)
                    
                    if (item.day === day) {
                        // Item starts on same day as request
                        // Check if request's first part (startTime to 23:59) overlaps with item's first part (item.startTime to 23:59)
                        hasConflict = (checkStart < 1440 && itemStart < 1440 && checkStart < 1440 && itemStart < 1440);
                        if (hasConflict) {
                            const overlapStart = Math.max(checkStart, itemStart);
                            const overlapEnd = Math.min(1440, 1440); // Both go to end of day
                            const overlapMinutes = overlapEnd - overlapStart;
                            hasConflict = overlapMinutes > 0;
                            conflictDetails = `overnight overlap on day ${day}`;
                        }
                    } else if (item.day === (day + 1) % 7) {
                        // Item starts on next day after request
                        // Check if request's second part (00:00 to endTime) overlaps with item's first part (item.startTime to 23:59)
                        hasConflict = (checkEnd > 0 && itemStart < 1440 && checkEnd > itemStart);
                        if (hasConflict) {
                            const overlapStart = Math.max(0, itemStart);
                            const overlapEnd = Math.min(checkEnd, 1440);
                            const overlapMinutes = overlapEnd - overlapStart;
                            hasConflict = overlapMinutes > 0;
                            conflictDetails = `overnight overlap on day ${(day + 1) % 7}`;
                        }
                    }
                } else if (isOvernightRequest && !isItemOvernight) {
                    // Request is overnight, item is not
                    if (item.day === day) {
                        // Check if request's first part (startTime to 23:59) overlaps with item
                        hasConflict = (checkStart < itemEnd && 1440 > itemStart);
                        conflictDetails = `overnight request overlaps with same-day item`;
                    } else if (item.day === (day + 1) % 7) {
                        // Check if request's second part (00:00 to endTime) overlaps with item
                        hasConflict = (checkEnd > itemStart && 0 < itemEnd);
                        conflictDetails = `overnight request overlaps with next-day item`;
                    }
                } else if (!isOvernightRequest && isItemOvernight) {
                    // Request is not overnight, item is overnight
                    if (item.day === day) {
                        // Check if request overlaps with item's first part (item.startTime to 23:59)
                        hasConflict = (checkStart < 1440 && checkEnd > itemStart);
                        conflictDetails = `request overlaps with overnight item's first part`;
                    } else if (item.day === (day - 1 + 7) % 7) {
                        // Check if request overlaps with item's second part (00:00 to item.endTime)
                        hasConflict = (checkStart < itemEnd && checkEnd > 0);
                        conflictDetails = `request overlaps with overnight item's second part`;
                    }
                } else {
                    // Neither is overnight - standard same-day check
                    if (item.day === day) {
                        hasConflict = (checkStart < itemEnd && checkEnd > itemStart);
                        conflictDetails = `same-day overlap`;
                    }
                }

                if (hasConflict) {
                    // Compute accurate overlap minutes across day boundaries
                    let overlapStart;
                    let overlapEnd;
                    if (isOvernightRequest && isItemOvernight) {
                        if (item.day === day) {
                            // Overlap on day X: [checkStart, 1440] vs [itemStart, 1440]
                            overlapStart = Math.max(checkStart, itemStart);
                            overlapEnd = 1440;
                        } else if (item.day === (day + 1) % 7) {
                            // Overlap on day Y: [0, checkEnd] vs [itemStart, 1440]
                            overlapStart = Math.max(0, itemStart);
                            overlapEnd = Math.min(checkEnd, 1440);
                        }
                    } else if (isOvernightRequest && !isItemOvernight) {
                        if (item.day === day) {
                            // Request first part vs same-day item: [checkStart, 1440] vs [itemStart, itemEnd]
                            overlapStart = Math.max(checkStart, itemStart);
                            overlapEnd = Math.min(1440, itemEnd);
                        } else if (item.day === (day + 1) % 7) {
                            // Request second part vs next-day item: [0, checkEnd] vs [itemStart, itemEnd]
                            overlapStart = Math.max(0, itemStart);
                            overlapEnd = Math.min(checkEnd, itemEnd);
                        }
                    } else if (!isOvernightRequest && isItemOvernight) {
                        if (item.day === day) {
                            // Same-day request vs first part of overnight item: [checkStart, checkEnd] vs [itemStart, 1440]
                            overlapStart = Math.max(checkStart, itemStart);
                            overlapEnd = Math.min(checkEnd, 1440);
                        } else if (item.day === (day - 1 + 7) % 7) {
                            // Same-day request vs second part of overnight item: [checkStart, checkEnd] vs [0, itemEnd]
                            overlapStart = Math.max(checkStart, 0);
                            overlapEnd = Math.min(checkEnd, itemEnd);
                        }
                    } else {
                        // Neither overnight: standard same-day
                        overlapStart = Math.max(checkStart, itemStart);
                        overlapEnd = Math.min(checkEnd, itemEnd);
                    }
                    const overlapMinutes = (overlapEnd ?? 0) - (overlapStart ?? 0);

                    // Only report conflicts with actual time overlap (more than 0 minutes)
                    if (overlapMinutes > 0) {
                        conflicts.push({
                            type: 'aircraft',
                            aircraft: aircraftReg,
                            description: item.description || item.type,
                            conflictingTime: `${item.startTime}-${item.endTime}`,
                            overlapMinutes: overlapMinutes,
                            phase: item.phase || 'unknown',
                            day: item.day,
                            flightNumber: item.flightNumber || 'N/A',
                            conflictType: conflictDetails
                        });

                        console.log(`   ❌ CONFLICT: ${overlapMinutes} minute overlap with ${aircraftReg} (${item.phase || 'unknown'}) - ${conflictDetails}`);
                    } else {
                        console.log(`   ✅ NO CONFLICT: Zero-minute overlap with ${aircraftReg} (acceptable)`);
                    }
                }
            }
        });
    });

    // 1.5. Check for logical conflicts: same aircraft using same gate consecutively
    // This prevents aircraft from disembarking and boarding simultaneously
    if (excludeAircraft && aircraftSchedules[excludeAircraft]) {
        const currentAircraftSchedule = aircraftSchedules[excludeAircraft];
        currentAircraftSchedule.forEach((item, index) => {
            if (excludeIndex === -1) return;
            if (excludeIndex != null && index === excludeIndex) {
                return;
            }

            // Skip if airport doesn't match
            if (item.airport !== airportName) {
                return;
            }

            // Skip if gate is null (flight phases)
            if (!item.gate) {
                return;
            }

            // Check if this item uses the same gate at the same airport
            const normalizedItemGate = normalizeGateName(item.gate);
            const normalizedCheckGate = normalizeGateName(gateName);
            
            if (normalizedItemGate === normalizedCheckGate) {
                const itemStart = timeToMinutes(item.startTime);
                const itemEnd = timeToMinutes(item.endTime);
                const checkStart = timeToMinutes(startTime);
                const checkEnd = timeToMinutes(endTime);

                // Note: Zero-minute overlaps (consecutive operations) are permitted
                // e.g., Aircraft 1 boarding 12:00-12:15, Aircraft 2 disembarking 12:15-12:30 is allowed
            }
        });
    }

    // 2. Check gate blocks for conflicts across ALL aircraft (not just current aircraft)
    Object.keys(gateBlocks).forEach(aircraftReg => {
        const aircraftBlocks = gateBlocks[aircraftReg];
        if (!aircraftBlocks || !aircraftBlocks[airportName]) return;

        const airportBlocks = aircraftBlocks[airportName];
        airportBlocks.forEach((block, index) => {
            // Use normalized gate names for comparison to handle variations
            const normalizedBlockGate = normalizeGateName(block.gate);
            const normalizedCheckGate = normalizeGateName(gateName);
            
            // Only log gate block comparisons when debugging is enabled
            if (window.debugGateConflicts) {
                console.log(`   🔍 Comparing gate blocks: "${block.gate}" (normalized: "${normalizedBlockGate}") vs "${gateName}" (normalized: "${normalizedCheckGate}")`);
            }
            
            if (normalizedBlockGate === normalizedCheckGate) {
                // Skip if this is the gate block we're trying to exclude (for gate change functionality)
                if (excludeGateBlock && 
                    excludeGateBlock.aircraft === aircraftReg && 
                    excludeGateBlock.airport === airportName && 
                    excludeGateBlock.blockIndex === index) {
                    console.log(`   ⏭️ SKIPPING: Excluding gate block from ${aircraftReg} (index ${index})`);
                    return;
                }

                // Hypothetical auto gap check (excludeIndex -1): this aircraft already "owns" that window via its blocks
                if (excludeAircraft && excludeIndex === -1 && aircraftReg === excludeAircraft) {
                    return;
                }
                
                const blockStart = timeToMinutes(block.startTime);
                const blockEnd = timeToMinutes(block.endTime);
                const isBlockOvernight = blockEnd < blockStart;

                console.log(`   Checking against gate block from ${aircraftReg}: ${block.startTime}-${block.endTime} (${blockStart}-${blockEnd} min) - Overnight: ${isBlockOvernight}`);

                let hasConflict = false;
                let conflictDetails = '';

                if (isOvernightRequest && isBlockOvernight) {
                    // Both request and block are overnight
                    if (block.day === day) {
                        // Block starts on same day as request
                        hasConflict = (checkStart < 1440 && blockStart < 1440 && checkStart < 1440 && blockStart < 1440);
                        if (hasConflict) {
                            const overlapStart = Math.max(checkStart, blockStart);
                            const overlapEnd = Math.min(1440, 1440);
                            const overlapMinutes = overlapEnd - overlapStart;
                            hasConflict = overlapMinutes > 0;
                            conflictDetails = `overnight block overlap on day ${day}`;
                        }
                    } else if (block.day === (day + 1) % 7) {
                        // Block starts on next day after request
                        hasConflict = (checkEnd > 0 && blockStart < 1440 && checkEnd > blockStart);
                        if (hasConflict) {
                            const overlapStart = Math.max(0, blockStart);
                            const overlapEnd = Math.min(checkEnd, 1440);
                            const overlapMinutes = overlapEnd - overlapStart;
                            hasConflict = overlapMinutes > 0;
                            conflictDetails = `overnight block overlap on day ${(day + 1) % 7}`;
                        }
                    }
                } else if (isOvernightRequest && !isBlockOvernight) {
                    // Request is overnight, block is not
                    if (block.day === day) {
                        hasConflict = (checkStart < blockEnd && 1440 > blockStart);
                        conflictDetails = `overnight request overlaps with same-day block`;
                    } else if (block.day === (day + 1) % 7) {
                        hasConflict = (checkEnd > blockStart && 0 < blockEnd);
                        conflictDetails = `overnight request overlaps with next-day block`;
                    }
                } else if (!isOvernightRequest && isBlockOvernight) {
                    // Request is not overnight, block is overnight
                    if (block.day === day) {
                        hasConflict = (checkStart < 1440 && checkEnd > blockStart);
                        conflictDetails = `request overlaps with overnight block's first part`;
                    } else if (block.day === (day - 1 + 7) % 7) {
                        hasConflict = (checkStart < blockEnd && checkEnd > 0);
                        conflictDetails = `request overlaps with overnight block's second part`;
                    }
                } else {
                    // Neither is overnight - standard same-day check
                    if (block.day === day) {
                        hasConflict = (checkStart < blockEnd && checkEnd > blockStart);
                        conflictDetails = `same-day block overlap`;
                    }
                }

                // Check for overlap (excluding zero-minute overlaps)
                if (hasConflict) {
                    // Compute accurate overlap minutes across day boundaries
                    let overlapStart;
                    let overlapEnd;
                    if (isOvernightRequest && isBlockOvernight) {
                        if (block.day === day) {
                            // Overlap on day X: [checkStart, 1440] vs [blockStart, 1440]
                            overlapStart = Math.max(checkStart, blockStart);
                            overlapEnd = 1440;
                        } else if (block.day === (day + 1) % 7) {
                            // Overlap on day Y: [0, checkEnd] vs [blockStart, 1440]
                            overlapStart = Math.max(0, blockStart);
                            overlapEnd = Math.min(checkEnd, 1440);
                        }
                    } else if (isOvernightRequest && !isBlockOvernight) {
                        if (block.day === day) {
                            // Request first part vs same-day block: [checkStart, 1440] vs [blockStart, blockEnd]
                            overlapStart = Math.max(checkStart, blockStart);
                            overlapEnd = Math.min(1440, blockEnd);
                        } else if (block.day === (day + 1) % 7) {
                            // Request second part vs next-day block: [0, checkEnd] vs [blockStart, blockEnd]
                            overlapStart = Math.max(0, blockStart);
                            overlapEnd = Math.min(checkEnd, blockEnd);
                        }
                    } else if (!isOvernightRequest && isBlockOvernight) {
                        if (block.day === day) {
                            // Same-day request vs first part of overnight block: [checkStart, checkEnd] vs [blockStart, 1440]
                            overlapStart = Math.max(checkStart, blockStart);
                            overlapEnd = Math.min(checkEnd, 1440);
                        } else if (block.day === (day - 1 + 7) % 7) {
                            // Same-day request vs second part of overnight block: [checkStart, checkEnd] vs [0, blockEnd]
                            overlapStart = Math.max(checkStart, 0);
                            overlapEnd = Math.min(checkEnd, blockEnd);
                        }
                    } else {
                        // Neither overnight: standard same-day
                        overlapStart = Math.max(checkStart, blockStart);
                        overlapEnd = Math.min(checkEnd, blockEnd);
                    }
                    const overlapMinutes = (overlapEnd ?? 0) - (overlapStart ?? 0);
                    
                    // Only report conflicts with actual time overlap (more than 0 minutes)
                    // Zero-minute overlaps are acceptable - gate blocks can end exactly when another starts
                    if (overlapMinutes > 0) {
                        conflicts.push({
                            type: 'block',
                            reason: block.reason,
                            conflictingTime: `${block.startTime}-${block.endTime}`,
                            overlapMinutes: overlapMinutes,
                            blockingAircraft: aircraftReg,
                            blockType: block.type || 'gate-block',
                            conflictType: conflictDetails
                        });

                        console.log(`   ❌ CONFLICT: ${overlapMinutes} minute overlap with gate block from ${aircraftReg} - ${conflictDetails}`);
                    } else {
                        console.log(`   ✅ NO CONFLICT: Zero-minute overlap with gate block from ${aircraftReg} (acceptable - no actual conflict)`);
                    }
                }
            }
        });
    });

    // 3. Check for multi-day gate blocks that might conflict
    Object.keys(gateBlocks).forEach(aircraftReg => {
        const aircraftBlocks = gateBlocks[aircraftReg];
        if (!aircraftBlocks || !aircraftBlocks[airportName]) return;

        const airportBlocks = aircraftBlocks[airportName];
        airportBlocks.forEach((block, index) => {
            // Use normalized gate names for comparison
            const normalizedBlockGate = normalizeGateName(block.gate);
            const normalizedCheckGate = normalizeGateName(gateName);
            
            if (normalizedBlockGate === normalizedCheckGate) {
                // Skip if this is the gate block we're trying to exclude (for gate change functionality)
                if (excludeGateBlock && 
                    excludeGateBlock.aircraft === aircraftReg && 
                    excludeGateBlock.airport === airportName && 
                    excludeGateBlock.blockIndex === index) {
                    console.log(`   ⏭️ SKIPPING: Excluding multi-day gate block from ${aircraftReg} (index ${index})`);
                    return;
                }

                if (excludeAircraft && excludeIndex === -1 && aircraftReg === excludeAircraft) {
                    return;
                }

                const blockStart = timeToMinutes(block.startTime);
                const blockEnd = timeToMinutes(block.endTime);

                // Check if block spans across days
                if (blockEnd < blockStart) {
                    // Block spans to next day
                    const nextDay = (block.day + 1) % 7;

                    // Check if our requested time conflicts with the next day portion
                    if (nextDay === day && checkStart < blockEnd) {
                        const overlapMinutes = blockEnd - checkStart;

                        // Only report conflicts with actual time overlap (more than 0 minutes)
                        if (overlapMinutes > 0) {
                            conflicts.push({
                                type: 'block',
                                reason: block.reason,
                                conflictingTime: `${block.startTime}-${block.endTime} (spans to next day)`,
                                overlapMinutes: overlapMinutes,
                                blockingAircraft: aircraftReg,
                                blockType: block.type || 'gate-block',
                                multiDay: true
                            });

                            console.log(`   ❌ CONFLICT: ${overlapMinutes} minute overlap with multi-day gate block from ${aircraftReg}`);
                        } else {
                            console.log(`   ✅ NO CONFLICT: Zero-minute overlap with multi-day gate block from ${aircraftReg} (acceptable)`);
                        }
                    }
                }
            }
        });
    });

    // 4. Summary and return results
    if (conflicts.length === 0) {
        console.log(`   ✅ NO CONFLICTS FOUND`);
    } else {
        console.log(`   ❌ ${conflicts.length} CONFLICT(S) FOUND:`);
        conflicts.forEach((conflict, index) => {
            const conflictInfo = conflict.type === 'aircraft' ?
                `${conflict.aircraft} (${conflict.phase})` :
                `Gate block from ${conflict.blockingAircraft}: ${conflict.reason}`;
            console.log(`      ${index + 1}. ${conflictInfo} (${conflict.overlapMinutes} min overlap)`);
        });
    }

    // 3. Check for auto gate blocks that WILL BE CREATED when this flight is scheduled (only if enabled)
    if (autoGateBlocksEnabled) {
        console.log('🔍 Checking for auto gate blocks that will be created...');
        const autoGateBlockResult = checkAutoGateBlocksThatWillBeCreated(airportName, gateName, day, startTime, endTime, excludeAircraft);
        if (autoGateBlockResult && autoGateBlockResult.conflicts) {
            conflicts.push(...autoGateBlockResult.conflicts);
        }
    } else {
        console.log('🔍 Auto gate blocks disabled - skipping auto gate block conflict check');
    }

    return {
        conflict: conflicts.length > 0,
        conflicts: conflicts,
        totalConflicts: conflicts.length,
        summary: {
            aircraftConflicts: conflicts.filter(c => c.type === 'aircraft').length,
            blockConflicts: conflicts.filter(c => c.type === 'block').length,
            autoBlockConflicts: conflicts.filter(c => c.type === 'auto-block').length,
            multiDayConflicts: conflicts.filter(c => c.multiDay).length
        }
    };
}

// Check for auto gate blocks that will be created when a flight is scheduled
function checkAutoGateBlocksThatWillBeCreated(airportName, gateName, day, startTime, endTime, excludeAircraft) {
    console.log('🔍 AUTO GATE BLOCKS: Checking for auto gate blocks that will be created...');
    console.log(`   Requested: ${airportName} gate ${gateName} on day ${day} from ${startTime}-${endTime}`);
    console.log(`   Current aircraft: ${currentAircraftForSchedule}`);
    console.log(`   Exclude aircraft: ${excludeAircraft}`);
    
    const conflicts = [];
    
    if (!currentAircraftForSchedule) {
        console.log('   ⏭️ SKIPPING: No aircraft selected');
        return conflicts;
    }
    
    // We should ALWAYS check the current aircraft's auto gate blocks when scheduling a new flight
    // The excludeAircraft parameter is only used when checking conflicts for other aircraft
    console.log('   ✅ Proceeding with auto gate block check for current aircraft');
    
    const schedule = aircraftSchedules[currentAircraftForSchedule];
    if (!schedule || schedule.length === 0) {
        console.log('   ⏭️ SKIPPING: No existing flights for auto gate block prediction');
        return conflicts;
    }
    
    console.log(`   📋 Current aircraft schedule has ${schedule.length} flights:`);
    schedule.forEach((flight, index) => {
        console.log(`     ${index + 1}. Day ${flight.day} ${flight.startTime}-${flight.endTime} at ${flight.airport} gate ${flight.gate} (${flight.phase})`);
    });
    
    // Find the last flight that ends before the new flight starts
    const lastFlight = findLastFlightBeforeNewFlight(schedule, day, startTime);
    
    if (!lastFlight) {
        console.log('   ⏭️ SKIPPING: No previous flight found for auto gate block prediction');
        return conflicts;
    }
    
    console.log('   🔍 AUTO GATE BLOCKS: Found previous flight:', lastFlight);
    console.log(`   Previous flight: Day ${lastFlight.endDay} ${lastFlight.endTime} at ${lastFlight.arrivalAirport} gate ${lastFlight.arrivalGate}`);
    
    // Calculate the gap between the last flight and the new flight
    const gapInfo = calculateFlightGap(lastFlight, day, startTime);
    
    console.log('   🔍 AUTO GATE BLOCKS: Gap calculation result:', gapInfo);
    
    if (!gapInfo.needsGateBlock) {
        console.log('   ⏭️ SKIPPING: No gap detected - no auto gate blocks will be created');
        return conflicts;
    }
    
    console.log('   🔍 AUTO GATE BLOCKS: Gap detected, checking for conflicts...');
    console.log(`   Auto gate block will be: Day ${gapInfo.startDay} ${gapInfo.startTime} to Day ${gapInfo.endDay} ${gapInfo.endTime}`);
    
    // Check if the auto gate block will conflict with the requested time
    const autoBlockStart = timeToMinutes(gapInfo.startTime);
    const autoBlockEnd = timeToMinutes(gapInfo.endTime);
    const checkStart = timeToMinutes(startTime);
    const checkEnd = timeToMinutes(endTime);
    
    console.log(`   Time comparison: Auto block ${autoBlockStart}-${autoBlockEnd} vs Requested ${checkStart}-${checkEnd}`);
    
    // Check if the auto gate block will be at the same airport and gate
    const willBeAtSameAirport = (lastFlight.arrivalAirport === airportName);
    
    // Determine which gate the auto gate block will use
    // If both flights are at the same airport, use the new flight's departure gate
    // If different airports, use the last flight's arrival gate
    let autoBlockGate;
    if (willBeAtSameAirport) {
        // Same airport: auto gate block will be at the new flight's departure gate
        // We need to get this from the form or context
        const departureGateSelect = document.getElementById('departureGate');
        autoBlockGate = departureGateSelect ? departureGateSelect.value : null;
        console.log(`   🔧 AUTO GATE BLOCKS: Same airport detected, auto block will use departure gate: ${autoBlockGate}`);
    } else {
        // Different airport: auto gate block will be at the last flight's arrival gate
        autoBlockGate = lastFlight.arrivalGate;
        console.log(`   🔧 AUTO GATE BLOCKS: Different airport, auto block will use arrival gate: ${autoBlockGate}`);
    }
    
    // Extract just the gate number from the full gate name for comparison
    const autoBlockGateNumber = autoBlockGate ? autoBlockGate.split(' (')[0] : null;
    const requestedGateNumber = gateName ? gateName.split(' (')[0] : null;
    const willBeAtSameGate = (autoBlockGateNumber === requestedGateNumber);
    
    console.log(`   Location check: Same airport? ${willBeAtSameAirport} (${lastFlight.arrivalAirport} vs ${airportName})`);
    console.log(`   Location check: Same gate? ${willBeAtSameGate} (${autoBlockGateNumber} vs ${requestedGateNumber})`);
    
    // Check for auto gate block conflicts if we're at the same airport and gate
    if (willBeAtSameAirport && willBeAtSameGate) {
        console.log('   🔍 AUTO GATE BLOCKS: Auto gate block will be at same airport and gate');
        
        // Check for overlap with the requested time
        if ((checkStart < autoBlockEnd && checkEnd > autoBlockStart)) {
            const overlapStart = Math.max(checkStart, autoBlockStart);
            const overlapEnd = Math.min(checkEnd, autoBlockEnd);
            const overlapMinutes = overlapEnd - overlapStart;
            
            // Only report conflicts with actual time overlap (more than 0 minutes)
            // Zero-minute overlaps are acceptable - auto gate blocks can end exactly when another starts
            if (overlapMinutes > 0) {
                conflicts.push({
                    type: 'auto-block',
                    reason: 'Auto-block between flights',
                    conflictingTime: `${gapInfo.startTime}-${gapInfo.endTime}`,
                    overlapMinutes: overlapMinutes,
                    blockingAircraft: currentAircraftForSchedule,
                    blockType: 'auto-gate-block',
                    details: `Auto gate block will be created between ${lastFlight.flightNumber || 'previous flight'} and new flight`
                });
                
                console.log(`   ❌ AUTO GATE BLOCK CONFLICT: ${overlapMinutes} minute overlap with auto gate block`);
            } else {
                console.log(`   ✅ NO AUTO GATE BLOCK CONFLICT: Zero-minute overlap with auto gate block (acceptable - no actual conflict)`);
            }
        } else {
            console.log('   ✅ AUTO GATE BLOCKS: No time overlap detected');
        }
    } else {
        console.log('   ⏭️ SKIPPING: Auto gate block will be at different airport or gate');
    }
    
    return {
        conflict: conflicts.length > 0,
        totalConflicts: conflicts.length,
        conflicts: conflicts
    };
}

// When auto gate blocks are enabled, the gap between the previous flight and this one must be
// clear for the same segments buildAutoGateBlockSegments would reserve (same comprehensive
// gate check as createGateBlockBetweenFlights; autoGateBlocksEnabled false avoids treating
// the block window as a flight for hypothetical-auto-block prediction).
function getProposedAutoGateBlockGateConflictErrors(route, newDay, newStartTime, newDepartureGate, newFlightNumber, autoGateBlocksEnabled) {
    const errors = [];
    if (!autoGateBlocksEnabled || !currentAircraftForSchedule) {
        return errors;
    }

    const schedule = aircraftSchedules[currentAircraftForSchedule];
    if (!schedule || schedule.length === 0) {
        return errors;
    }

    const newRouteStr = `${route.departure} → ${route.arrival}`;
    const excludeNewFlight =
        newFlightNumber && String(newFlightNumber).trim()
            ? {
                  route: newRouteStr,
                  flightNumber: String(newFlightNumber).trim(),
                  boardingDay: parseInt(newDay, 10),
                  boardingStartTime: newStartTime
              }
            : null;

    const lastFlight = findLastFlightBeforeNewFlight(schedule, newDay, newStartTime, excludeNewFlight);
    if (!lastFlight) {
        return errors;
    }

    const gapInfo = calculateFlightGap(lastFlight, newDay, newStartTime);
    if (!gapInfo.needsGateBlock) {
        return errors;
    }

    const departureAirport = route.departure;
    const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

    const gapSegments = buildAutoGateBlockSegments(
        gapInfo.startDay,
        gapInfo.startTime,
        gapInfo.endDay,
        gapInfo.endTime
    );
    const placements = mapAutoGateBlockSegmentPlacements(
        lastFlight.arrivalAirport,
        lastFlight.arrivalGate,
        departureAirport,
        newDepartureGate,
        gapInfo.startDay,
        gapInfo.endDay,
        gapSegments
    );

    placements.forEach(({ airport, gate, seg }) => {
        if (!gate) {
            return;
        }
        const result = comprehensiveGateConflictCheck(
            airport,
            gate,
            seg.day,
            seg.startTime,
            seg.endTime,
            currentAircraftForSchedule,
            -1,
            null,
            false
        );
        if (!result.conflict || !result.conflicts || result.conflicts.length === 0) {
            return;
        }
        const dayLabel = dayNames[parseInt(seg.day, 10)] || `Day ${seg.day}`;
        const overnightGap = parseInt(gapInfo.startDay, 10) !== parseInt(gapInfo.endDay, 10);
        const isOvernightBoardingDayTail =
            overnightGap && parseInt(seg.day, 10) === parseInt(gapInfo.endDay, 10) && seg.startTime === '00:00';
        const scheduleNote =
            (isOvernightBoardingDayTail
                ? ' Overnight gap: this segment reserves the gate from 00:00 UTC on the boarding day through your boarding start (not only the boarding duration).'
                : '') + ' All schedule times are UTC.';
        result.conflicts.forEach(conflict => {
            let enhancedDetails = '';
            if (conflict.type === 'aircraft') {
                enhancedDetails = `Aircraft ${conflict.aircraft} (${conflict.phase}) - ${conflict.overlapMinutes} minute overlap\n\n${conflict.aircraft} ${conflict.phase} from ${conflict.conflictingTime}`;
            } else if (conflict.type === 'block') {
                enhancedDetails = `Gate block from ${conflict.blockingAircraft}: ${conflict.reason} - ${conflict.overlapMinutes} minute overlap\n\nGate blocked from ${conflict.conflictingTime}`;
            } else if (conflict.type === 'auto-block') {
                enhancedDetails = `Auto gate block: ${conflict.reason || ''} (${conflict.conflictingTime})`;
            } else {
                enhancedDetails = `${conflict.type || 'conflict'} (${conflict.conflictingTime || ''})`;
            }
            errors.push({
                type: 'gate_conflict',
                message: `Auto gate block required (${airport}, ${gate}) conflicts: ${dayLabel} ${seg.startTime}-${seg.endTime} UTC.${scheduleNote}`,
                details: enhancedDetails,
                conflictingTime: conflict.conflictingTime,
                overlapMinutes: conflict.overlapMinutes,
                phase: 'auto_gate_block',
                gate,
                airport,
                blockingAircraftTime: conflict.conflictingTime
            });
        });
    });

    return errors;
}

// Enhanced flight validation function that uses comprehensive gate conflict checking
function enhancedValidateFlightSchedule(route, day, startTime, boardingTime, flightDuration, disembarkingTime, departureGate, arrivalGate, flightNumber, autoGateBlocksEnabled = true) {
    console.log(`🔍 ENHANCED FLIGHT VALIDATION`);
    console.log(`   Route: ${route.departure} → ${route.arrival}`);
    console.log(`   Flight: ${flightNumber}`);
    
    const errors = [];
    
    // Calculate all flight times
    const boardingStartTime = startTime;
    const boardingEndTime = addMinutesToTime(startTime, boardingTime);
    const flightStartTime = boardingEndTime;
    const flightEndTime = addMinutesToTime(startTime, boardingTime + timeToMinutes(flightDuration));
    const disembarkingStartTime = flightEndTime;
    const disembarkingEndTime = addMinutesToTime(startTime, boardingTime + timeToMinutes(flightDuration) + disembarkingTime);
    
    // Calculate the correct day for each phase (same logic as flight scheduling)
    const startDay = parseInt(day);
    let boardingDay = startDay;
    let flightDay = startDay;
    let disembarkingDay = startDay;
    
    // Check if boarding spans to next day
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        boardingDay = getNextDay(startDay);
    }
    
    // FIXED: Flight and disembarking days should be calculated based on when they actually occur
    // If boarding crosses midnight, flight starts on the day after boarding ends
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        // Boarding crossed midnight, so flight starts on the day after boarding ends
        flightDay = getNextDay(day); // Flight starts on the day after boarding ends
    } else {
        // Boarding is on the same day, flight starts on the same day
        flightDay = startDay;
    }
    
    // Check if disembarking occurs on next day (if flight spans overnight)
    if (timeToMinutes(flightEndTime) < timeToMinutes(flightStartTime)) {
        disembarkingDay = getNextDay(flightDay);
    } else {
        disembarkingDay = flightDay;
    }
    
    console.log(`   Flight phases: Boarding day ${boardingDay}, Flight day ${flightDay}, Disembarking day ${disembarkingDay}`);
    console.log(`   📝 NOTE: Only boarding and disembarking phases are checked for gate conflicts - flight phase (in-air) is ignored`);
    
    // Note: Overnight disembarking is allowed as a single segment
    // FIXED: disembarkingStartTime is already a time string, not minutes
    const disembarkingStartTimeMinutes = timeToMinutes(disembarkingStartTime);
    const disembarkingEndTimeMinutes = disembarkingStartTimeMinutes + disembarkingTime;
    if (disembarkingEndTimeMinutes >= 1440) {
        const invalidEndTime = minutesToTimeString(disembarkingEndTimeMinutes);
        console.log(`   🌙 OVERNIGHT DISEMBARKING: ${disembarkingStartTime} to ${invalidEndTime} (spans to next day)`);
    }
    
    // 1. Check departure gate conflicts (boarding phase only - NOT flight phase)
    console.log(`   🚪 CHECKING DEPARTURE GATE: ${departureGate} at ${route.departure}`);
    console.log(`   📅 Departure Day: ${boardingDay} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][boardingDay]})`);
    console.log(`   ⏰ Boarding Time: ${boardingStartTime} - ${boardingEndTime}`);
    // Use full gate name for conflict checking (includes terminal information)
    console.log(`   🔍 Using full departure gate name: ${departureGate}`);
    
    // Check for overnight boarding conflicts
    let departureConflict;
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        // Boarding crosses midnight - check conflicts on both days
        console.log(`   🌙 Checking overnight boarding conflicts on both days`);
        
        // Check current day (where boarding starts)
        const currentDayConflict = comprehensiveGateConflictCheck(route.departure, departureGate, startDay, boardingStartTime, '24:00', currentAircraftForSchedule, null, null, autoGateBlocksEnabled);
        
        // Check next day (where boarding ends)
        const nextDayEndTime = minutesToTimeString(timeToMinutes(boardingEndTime));
        const nextDay = getNextDay(startDay);
        const nextDayConflict = comprehensiveGateConflictCheck(route.departure, departureGate, nextDay, '00:00', nextDayEndTime, currentAircraftForSchedule, null, null, autoGateBlocksEnabled);
        
        console.log(`   Current day (${startDay}) conflict: ${currentDayConflict.totalConflicts} conflicts`);
        console.log(`   Next day (${nextDay}) conflict: ${nextDayConflict.totalConflicts} conflicts`);
        
        // Combine conflicts from both days
        const allConflicts = [...(currentDayConflict.conflicts || []), ...(nextDayConflict.conflicts || [])];
        departureConflict = {
            totalConflicts: allConflicts.length,
            conflicts: allConflicts
        };
    } else {
        // Boarding is on the same day - standard check
        departureConflict = comprehensiveGateConflictCheck(route.departure, departureGate, boardingDay, boardingStartTime, boardingEndTime, currentAircraftForSchedule, null, null, autoGateBlocksEnabled);
    }
    
    if (departureConflict.totalConflicts > 0) {
        console.log(`   ❌ DEPARTURE GATE CONFLICT DETECTED: ${departureConflict.totalConflicts} conflicts`);
        departureConflict.conflicts.forEach(conflict => {
            // Enhanced details to show specific aircraft times
            let enhancedDetails = '';
            if (conflict.type === 'aircraft') {
                enhancedDetails = `Aircraft ${conflict.aircraft} (${conflict.phase}) - ${conflict.overlapMinutes} minute overlap\n\n${conflict.aircraft} ${conflict.phase} from ${conflict.conflictingTime}`;
            } else {
                enhancedDetails = `Gate block from ${conflict.blockingAircraft}: ${conflict.reason} - ${conflict.overlapMinutes} minute overlap\n\nGate blocked from ${conflict.conflictingTime}`;
            }
            
            errors.push({
                type: 'gate_conflict',
                message: `Gate ${departureGate} at ${route.departure} is not available during boarding (${boardingStartTime}-${boardingEndTime})`,
                details: enhancedDetails,
                conflictingTime: conflict.conflictingTime,
                overlapMinutes: conflict.overlapMinutes,
                phase: 'boarding',
                gate: departureGate,
                airport: route.departure,
                blockingAircraftTime: conflict.conflictingTime
            });
        });
    } else {
        console.log(`   ✅ Departure gate ${departureGate} is available`);
    }
    
    // 2. Check arrival gate conflicts (disembarking phase only - NOT flight phase)
    console.log(`   🛬 CHECKING ARRIVAL GATE: ${arrivalGate} at ${route.arrival}`);
    console.log(`   📅 Arrival Day: ${disembarkingDay} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][disembarkingDay]})`);
    console.log(`   ⏰ Disembarking Time: ${disembarkingStartTime} - ${disembarkingEndTime}`);
    // Use full gate name for conflict checking (includes terminal information)
    console.log(`   🔍 Using full arrival gate name: ${arrivalGate}`);
    
    // Check for overnight disembarking conflicts
    if (disembarkingEndTimeMinutes >= 1440) {
        // Disembarking spans overnight - check conflicts on both days
        console.log(`   🌙 Checking overnight disembarking conflicts on both days`);
        
        // Check current day (where disembarking starts)
        const currentDayConflict = comprehensiveGateConflictCheck(route.arrival, arrivalGate, disembarkingDay, disembarkingStartTime, '24:00', currentAircraftForSchedule, null, null, autoGateBlocksEnabled);
        
        // Check next day (where disembarking ends)
        const nextDayEndTime = minutesToTimeString(disembarkingEndTimeMinutes - 1440);
        const nextDay = getNextDay(disembarkingDay);
        const nextDayConflict = comprehensiveGateConflictCheck(route.arrival, arrivalGate, nextDay, '00:00', nextDayEndTime, currentAircraftForSchedule, null, null, autoGateBlocksEnabled);
        
        console.log(`   Current day (${disembarkingDay}) conflict: ${currentDayConflict.totalConflicts} conflicts`);
        console.log(`   Next day (${nextDay}) conflict: ${nextDayConflict.totalConflicts} conflicts`);
        
        // Combine conflicts from both days
        const allConflicts = [...(currentDayConflict.conflicts || []), ...(nextDayConflict.conflicts || [])];
        const totalConflicts = allConflicts.length;
        
        if (totalConflicts > 0) {
            console.log(`   ❌ OVERNIGHT ARRIVAL GATE CONFLICT DETECTED: ${totalConflicts} conflicts across both days`);
            allConflicts.forEach(conflict => {
                // Enhanced details to show specific aircraft times
                let enhancedDetails = '';
                if (conflict.type === 'aircraft') {
                    enhancedDetails = `Aircraft ${conflict.aircraft} (${conflict.phase}) - ${conflict.overlapMinutes} minute overlap\n\n${conflict.aircraft} ${conflict.phase} from ${conflict.conflictingTime}`;
                } else {
                    enhancedDetails = `Gate block from ${conflict.blockingAircraft}: ${conflict.reason} - ${conflict.overlapMinutes} minute overlap\n\nGate blocked from ${conflict.conflictingTime}`;
                }
                
                errors.push({
                    type: 'gate_conflict',
                    message: `Gate ${arrivalGate} at ${route.arrival} is not available during overnight disembarking (${disembarkingStartTime}-${disembarkingEndTime})`,
                    details: enhancedDetails,
                    conflictingTime: conflict.conflictingTime,
                    overlapMinutes: conflict.overlapMinutes,
                    phase: 'disembarking',
                    gate: arrivalGate,
                    airport: route.arrival,
                    blockingAircraftTime: conflict.conflictingTime
                });
            });
        } else {
            console.log(`   ✅ Arrival gate ${arrivalGate} is available for overnight disembarking`);
        }
    } else {
        // Normal same-day disembarking
        const arrivalConflict = comprehensiveGateConflictCheck(route.arrival, arrivalGate, disembarkingDay, disembarkingStartTime, disembarkingEndTime, currentAircraftForSchedule, null, null, autoGateBlocksEnabled);
        
        if (arrivalConflict.totalConflicts > 0) {
            console.log(`   ❌ ARRIVAL GATE CONFLICT DETECTED: ${arrivalConflict.totalConflicts} conflicts`);
            arrivalConflict.conflicts.forEach(conflict => {
                // Enhanced details to show specific aircraft times
                let enhancedDetails = '';
                if (conflict.type === 'aircraft') {
                    enhancedDetails = `Aircraft ${conflict.aircraft} (${conflict.phase}) - ${conflict.overlapMinutes} minute overlap\n\n${conflict.aircraft} ${conflict.phase} from ${conflict.conflictingTime}`;
                } else {
                    enhancedDetails = `Gate block from ${conflict.blockingAircraft}: ${conflict.reason} - ${conflict.overlapMinutes} minute overlap\n\nGate blocked from ${conflict.conflictingTime}`;
                }
                
                errors.push({
                    type: 'gate_conflict',
                    message: `Gate ${arrivalGate} at ${route.arrival} is not available during disembarking (${disembarkingStartTime}-${disembarkingEndTime})`,
                    details: enhancedDetails,
                    conflictingTime: conflict.conflictingTime,
                    overlapMinutes: conflict.overlapMinutes,
                    phase: 'disembarking',
                    gate: arrivalGate,
                    airport: route.arrival,
                    blockingAircraftTime: conflict.conflictingTime
                });
            });
        } else {
            console.log(`   ✅ Arrival gate ${arrivalGate} is available`);
        }
    }

    // 2b. Auto gate blocks: same comprehensive gate occupancy check as placement (must clear or flight cannot be scheduled)
    if (autoGateBlocksEnabled) {
        const autoBlockErrors = getProposedAutoGateBlockGateConflictErrors(
            route,
            day,
            startTime,
            departureGate,
            flightNumber,
            autoGateBlocksEnabled
        );
        autoBlockErrors.forEach(err => errors.push(err));
        if (autoBlockErrors.length > 0) {
            console.log(`   ❌ PROPOSED AUTO GATE BLOCK(S) CONFLICT: ${autoBlockErrors.length} issue(s)`);
        }
    }
    
    // 3. Check airport operating hours
    const departureHoursCheck = evaluateAirportHoursAtUtcTime(route.departure, flightStartTime);
    const arrivalHoursCheck = evaluateAirportHoursAtUtcTime(route.arrival, flightEndTime);
    
    if (!departureHoursCheck.isWithinHours) {
        errors.push({
            type: 'airport_hours',
            message: `Flight departure time ${flightStartTime} UTC is outside ${route.departure} operating hours`,
            details: `Airport hours (UTC): ${departureHoursCheck.opening} - ${departureHoursCheck.closing}`
        });
    }
    
    if (!arrivalHoursCheck.isWithinHours) {
        errors.push({
            type: 'airport_hours',
            message: `Flight arrival time ${flightEndTime} UTC is outside ${route.arrival} operating hours`,
            details: `Airport hours (UTC): ${arrivalHoursCheck.opening} - ${arrivalHoursCheck.closing}`
        });
    }
    
    // 4. Check for same-aircraft schedule overlaps
    const schedule = aircraftSchedules[currentAircraftForSchedule] || [];
    const flightItems = [
        { startTime: boardingStartTime, endTime: boardingEndTime, phase: 'boarding', day: boardingDay },
        { startTime: flightStartTime, endTime: flightEndTime, phase: 'flight', day: flightDay },
        { startTime: disembarkingStartTime, endTime: disembarkingEndTime, phase: 'disembarking', day: disembarkingDay }
    ];
    
    flightItems.forEach(flightItem => {
        console.log(`   Checking ${flightItem.phase} overlap on day ${flightItem.day} (${flightItem.startTime}-${flightItem.endTime})`);
        const overlap = checkScheduleOverlap(schedule, flightItem.day, flightItem.startTime, flightItem.endTime);
        if (overlap.conflict) {
            console.log(`   ❌ ${flightItem.phase} conflict found on day ${flightItem.day}`);
            const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
            const dayName = dayNames[flightItem.day] || `Day ${flightItem.day}`;
            errors.push({
                type: 'schedule_overlap',
                message: `${flightItem.phase.charAt(0).toUpperCase() + flightItem.phase.slice(1)} time (${dayName} ${flightItem.startTime}-${flightItem.endTime}) conflicts with existing schedule`,
                details: `Conflicts with: ${getDetailedConflictInfo(overlap.conflictingItem)}`
            });
        } else {
            console.log(`   ✅ No ${flightItem.phase} conflicts on day ${flightItem.day}`);
        }
    });
    
    console.log(`   Validation result: ${errors.length === 0 ? 'VALID' : `${errors.length} ERROR(S)`}`);
    
    return {
        valid: errors.length === 0,
        errors: errors
    };
}

