// Test function to verify calendar day calculation for overnight boarding
function testCalendarDayCalculation() {
    console.log('🧪 TESTING CALENDAR DAY CALCULATION');
    console.log('===================================');
    
    // Test case: Flight that boards overnight from Saturday to Sunday
    // startDay = 5 (Saturday)
    // boardingStartTime = 23:50 (Saturday evening)
    // boardingEndTime = 00:20 (Sunday morning)
    // Expected calendar display:
    // - Boarding: Day 5 (Saturday) 23:50-00:20
    // - Flight: Day 6 (Sunday) 00:20-01:20
    // - Disembarking: Day 6 (Sunday) 01:20-01:35
    
    console.log('Testing calendar day calculation for overnight boarding:');
    console.log('  Start Day: 5 (Saturday)');
    console.log('  Boarding: 23:50-00:20 (overnight to Sunday)');
    console.log('  Expected: boardingDay=5, flightDay=6, disembarkingDay=6');
    
    // Simulate the day calculation logic from addFlightToSchedule
    const day = 5; // Saturday
    const startTime = '23:50';
    const boardingTime = 30; // 30 minutes
    const flightDuration = '01:00'; // 1 hour
    const disembarkingTime = 15; // 15 minutes
    
    // Calculate flight times
    const boardingStartTime = startTime;
    const boardingEndTime = addMinutesToTime(startTime, boardingTime);
    const flightStartTime = boardingEndTime;
    const flightEndTime = addMinutesToTime(startTime, boardingTime + timeToMinutes(flightDuration));
    const disembarkingStartTime = flightEndTime;
    
    // Calculate the correct day for each phase
    let boardingDay = day;
    let flightDay = day;
    let disembarkingDay = day;
    
    // Check if boarding spans to next day
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        // Boarding crosses midnight, but it should still be displayed on the start day
        // The boarding segment will be handled as an overnight segment in the calendar
        console.log(`   🌙 Boarding crosses midnight but stays on day ${boardingDay} (start day)`);
    }
    
    // FIXED: Flight and disembarking days should be calculated based on when they actually occur
    // If boarding crosses midnight, flight starts on the day after boarding ends
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        // Boarding crossed midnight, so flight starts on the day after boarding ends
        flightDay = getNextDay(day); // Flight starts on the day after boarding ends
    } else {
        // Boarding is on the same day, flight starts on the same day
        flightDay = day;
    }
    
    // Check if disembarking occurs on next day (if flight spans overnight)
    if (timeToMinutes(flightEndTime) < timeToMinutes(flightStartTime)) {
        disembarkingDay = getNextDay(flightDay);
    } else {
        disembarkingDay = flightDay;
    }
    
    console.log(`\nResults:`);
    console.log(`  Boarding: Day ${boardingDay} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][boardingDay]}) ${boardingStartTime}-${boardingEndTime}`);
    console.log(`  Flight: Day ${flightDay} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][flightDay]}) ${flightStartTime}-${flightEndTime}`);
    console.log(`  Disembarking: Day ${disembarkingDay} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][disembarkingDay]}) ${disembarkingStartTime}-${addMinutesToTime(disembarkingStartTime, disembarkingTime)}`);
    
    // Verify the results
    const expectedBoardingDay = 5; // Saturday (should stay on start day)
    const expectedFlightDay = 6; // Sunday (should move to next day)
    const expectedDisembarkingDay = 6; // Sunday (should be same as flight day)
    
    if (boardingDay === expectedBoardingDay && flightDay === expectedFlightDay && disembarkingDay === expectedDisembarkingDay) {
        console.log('✅ SUCCESS: Calendar day calculation is correct!');
    } else {
        console.log('❌ FAILURE: Calendar day calculation is incorrect');
        console.log(`  Expected: boardingDay=${expectedBoardingDay}, flightDay=${expectedFlightDay}, disembarkingDay=${expectedDisembarkingDay}`);
        console.log(`  Actual: boardingDay=${boardingDay}, flightDay=${flightDay}, disembarkingDay=${disembarkingDay}`);
    }
    
    console.log('\n=== CALENDAR DAY CALCULATION TEST COMPLETE ===');
}

// Test function to verify boarding segment display in calendar
function testBoardingSegmentDisplay() {
    console.log('🧪 TESTING BOARDING SEGMENT DISPLAY');
    console.log('===================================');
    
    // Test case: Flight that boards overnight from Saturday to Sunday
    // startDay = 5 (Saturday)
    // boardingStartTime = 23:50 (Saturday evening)
    // boardingEndTime = 00:20 (Sunday morning)
    // Expected: Boarding segment should show on Saturday (startDay), not Sunday (boardingDay)
    
    console.log('Testing boarding segment display for overnight boarding:');
    console.log('  Start Day: 5 (Saturday)');
    console.log('  Boarding: 23:50-00:20 (overnight to Sunday)');
    console.log('  Expected: Boarding segment should show on Saturday (day 5) - the day where boarding starts');
    
    // Simulate the form submission logic
    const day = 5; // Saturday
    const startTime = '23:50';
    const boardingTime = 30; // 30 minutes
    const flightDuration = '01:00'; // 1 hour
    const disembarkingTime = 15; // 15 minutes
    
    // Calculate flight times
    const boardingStartTime = startTime;
    const boardingEndTime = addMinutesToTime(startTime, boardingTime);
    const flightStartTime = boardingEndTime;
    const flightEndTime = addMinutesToTime(startTime, boardingTime + timeToMinutes(flightDuration));
    const disembarkingStartTime = flightEndTime;
    
    // Calculate the correct day for each phase
    const startDay = parseInt(day);
    let boardingDay = startDay;
    let flightDay = startDay;
    let disembarkingDay = startDay;
    
    // Check if boarding spans to next day
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        boardingDay = getNextDay(startDay);
    }
    
    // FIXED: Flight and disembarking days should be calculated based on when they actually occur
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        flightDay = boardingDay;
    } else {
        flightDay = startDay;
    }
    
    if (timeToMinutes(flightEndTime) < timeToMinutes(flightStartTime)) {
        disembarkingDay = getNextDay(flightDay);
    } else {
        disembarkingDay = flightDay;
    }
    
    // Simulate the flight item creation logic
    const flightItems = [];
    
    // Boarding phase - always on the start day
    flightItems.push({
        day: startDay, // Boarding always starts on the original day
        startTime: boardingStartTime,
        endTime: boardingEndTime,
        phase: 'boarding'
    });
    
    console.log(`\nResults:`);
    console.log(`  Boarding segment: Day ${flightItems[0].day} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][flightItems[0].day]}) ${flightItems[0].startTime}-${flightItems[0].endTime}`);
    
    // Verify the results
    const expectedBoardingDay = 5; // Saturday (should be on startDay, not boardingDay)
    
    if (flightItems[0].day === expectedBoardingDay) {
        console.log('✅ SUCCESS: Boarding segment is displayed on the correct day!');
    } else {
        console.log('❌ FAILURE: Boarding segment is displayed on the wrong day');
        console.log(`  Expected: Day ${expectedBoardingDay} (Saturday)`);
        console.log(`  Actual: Day ${flightItems[0].day} (${['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][flightItems[0].day]})`);
    }
    
    console.log('\n=== BOARDING SEGMENT DISPLAY TEST COMPLETE ===');
}

