// Quick conflict scan function to check existing schedules for conflicts
function quickConflictScan() {
    console.log('🔍 QUICK CONFLICT SCAN');
    console.log('======================');
    
    let totalConflicts = 0;
    const allConflicts = [];
    
    // Scan all aircraft schedules for conflicts
    Object.keys(aircraftSchedules).forEach(aircraftReg => {
        const schedule = aircraftSchedules[aircraftReg];
        if (!Array.isArray(schedule)) return;
        
        // Check for conflicts between different aircraft
        schedule.forEach((item, index) => {
            if (!item.gate || !item.airport) return;
            
            // Check for conflicts with OTHER aircraft
            const conflicts = comprehensiveGateConflictCheck(
                item.airport,
                item.gate,
                item.day,
                item.startTime,
                item.endTime,
                aircraftReg, // Exclude the current aircraft
                index // Exclude the current schedule item
            );
            
            if (conflicts.conflict) {
                totalConflicts += conflicts.totalConflicts;
                allConflicts.push({
                    aircraft: aircraftReg,
                    scheduleItem: item,
                    conflicts: conflicts.conflicts
                });
                
                console.log(`❌ INTER-AIRCRAFT CONFLICT FOUND: ${aircraftReg} - ${item.description || item.type || 'Unknown'}`);
                console.log(`   Gate: ${item.gate} at ${item.airport}`);
                console.log(`   Time: ${item.startTime}-${item.endTime} (Day ${item.day})`);
                console.log(`   Conflicts: ${conflicts.totalConflicts}`);
            }
        });
        
        // Check for conflicts within the same aircraft's schedule (consecutive operations)
        schedule.forEach((item, index) => {
            if (!item.gate || !item.airport) return;
            
            // Check if this item conflicts with other items in the same aircraft's schedule
            for (let i = 0; i < schedule.length; i++) {
                if (i === index) continue; // Skip self
                
                const otherItem = schedule[i];
                if (!otherItem.gate || !otherItem.airport) continue;
                
                // Check if same gate, same airport, same day
                if (item.airport === otherItem.airport && 
                    item.gate === otherItem.gate && 
                    item.day === otherItem.day) {
                    
                    const itemStart = timeToMinutes(item.startTime);
                    const itemEnd = timeToMinutes(item.endTime);
                    const otherStart = timeToMinutes(otherItem.startTime);
                    const otherEnd = timeToMinutes(otherItem.endTime);
                    
                    // Check for time overlap only (consecutive operations are permitted)
                    const hasOverlap = (itemStart < otherEnd && itemEnd > otherStart);
                    
                    if (hasOverlap) {
                        const overlapStart = Math.max(itemStart, otherStart);
                        const overlapEnd = Math.min(itemEnd, otherEnd);
                        const overlapMinutes = overlapEnd - overlapStart;
                        
                        // Only report conflicts with actual time overlap (more than 0 minutes)
                        // Zero-minute overlaps (consecutive operations) are permitted
                        if (overlapMinutes > 0) {
                            totalConflicts++;
                            allConflicts.push({
                                aircraft: aircraftReg,
                                scheduleItem: item,
                                conflicts: [{
                                    type: 'aircraft',
                                    aircraft: aircraftReg,
                                    description: otherItem.description || otherItem.type,
                                    conflictingTime: `${otherItem.startTime}-${otherItem.endTime}`,
                                    overlapMinutes: overlapMinutes,
                                    phase: otherItem.phase || 'unknown',
                                    day: otherItem.day,
                                    flightNumber: otherItem.flightNumber || 'N/A',
                                    conflictType: 'same aircraft schedule overlap'
                                }]
                            });
                            
                            console.log(`❌ INTRA-AIRCRAFT CONFLICT FOUND: ${aircraftReg} - ${item.description || item.type || 'Unknown'}`);
                            console.log(`   Gate: ${item.gate} at ${item.airport}`);
                            console.log(`   Time: ${item.startTime}-${item.endTime} (Day ${item.day})`);
                            console.log(`   Conflicts with: ${otherItem.description || otherItem.type || 'Unknown'} (${otherItem.startTime}-${otherItem.endTime})`);
                            console.log(`   Conflict Type: Time Overlap`);
                            console.log(`   Overlap: ${overlapMinutes} minutes`);
                        }
                    }
                }
            }
        });
    });
    
    // Scan all gate blocks
    Object.keys(gateBlocks).forEach(aircraftReg => {
        const aircraftBlocks = gateBlocks[aircraftReg];
        if (!aircraftBlocks) return;
        
        Object.keys(aircraftBlocks).forEach(airportName => {
            const airportBlocks = aircraftBlocks[airportName];
            if (!Array.isArray(airportBlocks)) return;
            
            airportBlocks.forEach((block, index) => {
                if (!block.gate) return;
                
                // Check for conflicts with this gate block
                const conflicts = comprehensiveGateConflictCheck(
                    airportName,
                    block.gate,
                    block.day,
                    block.startTime,
                    block.endTime,
                    aircraftReg, // Exclude the current aircraft
                    null, // No schedule item to exclude
                    {
                        aircraft: aircraftReg,
                        airport: airportName,
                        blockIndex: index // Exclude the current gate block
                    }
                );
                
                if (conflicts.conflict) {
                    totalConflicts += conflicts.totalConflicts;
                    allConflicts.push({
                        aircraft: aircraftReg,
                        gateBlock: block,
                        conflicts: conflicts.conflicts
                    });
                    
                    console.log(`❌ GATE BLOCK CONFLICT FOUND: ${aircraftReg} - ${block.reason}`);
                    console.log(`   Gate: ${block.gate} at ${airportName}`);
                    console.log(`   Time: ${block.startTime}-${block.endTime} (Day ${block.day})`);
                    console.log(`   Conflicts: ${conflicts.totalConflicts}`);
                }
            });
        });
    });
    
    // Summary
    if (totalConflicts === 0) {
        console.log('✅ NO CONFLICTS FOUND - All schedules are conflict-free!');
    } else {
        console.log(`❌ TOTAL CONFLICTS FOUND: ${totalConflicts}`);
        console.log(`   Affected items: ${allConflicts.length}`);
        console.log('\n📋 CONFLICT SUMMARY:');
        allConflicts.forEach((item, index) => {
            const itemInfo = item.scheduleItem ? 
                `${item.aircraft} - ${item.scheduleItem.description || item.scheduleItem.type || 'Unknown'}` :
                `${item.aircraft} - Gate Block: ${item.gateBlock.reason}`;
            console.log(`   ${index + 1}. ${itemInfo} (${item.conflicts.length} conflicts)`);
        });
    }
    
    return {
        totalConflicts: totalConflicts,
        conflicts: allConflicts,
        hasConflicts: totalConflicts > 0
    };
}

// Function to integrate enhanced validation with existing flight scheduling
function integrateEnhancedValidation() {
    console.log('🔧 INTEGRATING ENHANCED VALIDATION WITH EXISTING SYSTEM');
    
    // Find the existing validateFlightSchedule function and replace it
    if (typeof validateFlightSchedule === 'function') {
        console.log('✅ Found existing validateFlightSchedule function');
        
        // Store the original function
        window.originalValidateFlightSchedule = validateFlightSchedule;
        
        // Replace with enhanced version
        window.validateFlightSchedule = function(route, day, startTime, boardingTime, flightDuration, disembarkingTime, departureGate, arrivalGate, flightNumber, autoGateBlocksEnabled = true) {
            console.log('🚀 Using enhanced flight validation...');
            return enhancedValidateFlightSchedule(route, day, startTime, boardingTime, flightDuration, disembarkingTime, departureGate, arrivalGate, flightNumber, autoGateBlocksEnabled);
        };
        
        console.log('✅ Enhanced validation integrated successfully');
        console.log('   Original function preserved as: originalValidateFlightSchedule');
    } else {
        console.log('⚠️  validateFlightSchedule function not found - may need manual integration');
    }
    
    // Also check for checkGateConflicts function
    if (typeof checkGateConflicts === 'function') {
        console.log('✅ Found existing checkGateConflicts function');
        
        // Store the original function
        window.originalCheckGateConflicts = checkGateConflicts;
        
        // Replace with enhanced version
        window.checkGateConflicts = function(airportName, gateName, day, startTime, endTime, excludeAircraft = null, excludeIndex = null) {
            console.log('🚀 Using enhanced gate conflict checking...');
            return comprehensiveGateConflictCheck(airportName, gateName, day, startTime, endTime, excludeAircraft, excludeIndex);
        };
        
        console.log('✅ Enhanced gate conflict checking integrated successfully');
        console.log('   Original function preserved as: originalCheckGateConflicts');
    } else {
        console.log('⚠️  checkGateConflicts function not found - may need manual integration');
    }
}

