// Global variable to store validation result
window.flightValidationResult = null;

// Function to update Schedule Flight button state based on validation
function updateScheduleFlightButtonState() {
    const flightForm = document.getElementById('flightSchedulingFormElement');
    const submitButton = flightForm ? flightForm.querySelector('button[type="submit"]') : null;
    
    if (submitButton) {
        if (window.flightValidationResult && window.flightValidationResult.valid) {
            // Validation passed - enable button
            submitButton.disabled = false;
            submitButton.style.opacity = '1';
            submitButton.style.cursor = 'pointer';
            submitButton.title = 'Click to schedule the flight';
        } else {
            // No validation or validation failed - disable button
            submitButton.disabled = true;
            submitButton.style.opacity = '0.6';
            submitButton.style.cursor = 'not-allowed';
            submitButton.title = 'Please check for conflicts first';
        }
    }
}

// CRITICAL: Override the flight scheduling form submission to add automatic validation
function overrideScheduleFlightFunction() {
    console.log('🔧 OVERRIDING FLIGHT SCHEDULING FORM SUBMISSION FOR AUTOMATIC VALIDATION');
    
    // Find the flight scheduling form and override its submission
    const flightForm = document.getElementById('flightSchedulingFormElement');
    if (flightForm) {
        console.log('✅ Found flight scheduling form');
        
        // Initialize: Disable submit button by default
        updateScheduleFlightButtonState();
        
        // Reset validation state when form fields change
        const formFields = ['flightDay', 'flightRoute', 'flightStartTime', 'boardingTime', 'flightDuration', 'disembarkingTime', 'departureGate', 'arrivalGate', 'flightNumber', 'isPositioningFlight', 'autoGateBlocks'];
        formFields.forEach(fieldId => {
            const field = document.getElementById(fieldId);
            if (field) {
                field.addEventListener('change', function() {
                    // Reset validation state when form changes
                    window.flightValidationResult = null;
                    updateScheduleFlightButtonState();
                    
                    // Reset check conflicts button
                    const checkBtn = document.getElementById('checkConflictsBtn');
                    if (checkBtn) {
                        checkBtn.textContent = '🔍 Check for Conflicts';
                        checkBtn.style.backgroundColor = '#17a2b8';
                    }

                    // Keep flight-number duplicate warning in sync with form values.
                    updateFlightNumberDuplicateWarning();
                    if (fieldId === 'flightStartTime' && isOnScheduleFlightPage() && typeof refreshScheduleRoutePopupFromForm === 'function') {
                        refreshScheduleRoutePopupFromForm();
                    }
                });
            }
        });

        const flightNumberField = document.getElementById('flightNumber');
        if (flightNumberField) {
            flightNumberField.addEventListener('input', updateFlightNumberDuplicateWarning);
            flightNumberField.addEventListener('blur', updateFlightNumberDuplicateWarning);
        }
        
        // Add the enhanced validation event listener
        flightForm.addEventListener('submit', function(e) {
            e.preventDefault();
            e.stopPropagation();
            
            // CRITICAL: Check if validation has been performed and passed
            if (!window.flightValidationResult || !window.flightValidationResult.valid) {
                showNonBlockingNotification('❌ Please check for conflicts first before scheduling the flight.', 'error');
                return;
            }
            
            logger('🚀 FLIGHT FORM SUBMISSION - VALIDATION ALREADY CONFIRMED');
            
            // Get form values
            const routeValue = document.getElementById('flightRoute').value;
            const day = document.getElementById('flightDay').value;
            const startTime = document.getElementById('flightStartTime').value;
            const boardingTime = parseInt(document.getElementById('boardingTime').value) || 30;
            const flightDuration = document.getElementById('flightDuration').value;
            const disembarkingTime = parseInt(document.getElementById('disembarkingTime').value) || 15;
            const departureGate = document.getElementById('departureGate').value;
            const arrivalGate = document.getElementById('arrivalGate').value;
            let flightNumber = document.getElementById('flightNumber').value;
            const autoGateBlocksEnabled = document.getElementById('autoGateBlocks').checked;
            
            // Check if this is a positioning flight
            const isPositioningFlight = document.getElementById('isPositioningFlight') ? document.getElementById('isPositioningFlight').checked : false;
            
            const dayFromForm = parseInt(day, 10);
            const localSuffixDay = getFlightFormLocalDepartureDayForSuffix();
            const daySuffixIndex = localSuffixDay !== null ? localSuffixDay : dayFromForm;

            // Auto-format flight number
            if (!flightNumber.trim()) {
                // If empty, generate complete flight number
                flightNumber = generateFlightNumber(currentAircraftForSchedule, dayFromForm, isPositioningFlight, daySuffixIndex);
                console.log(`🔢 Auto-generated flight number: ${flightNumber}`);
            } else if (!isValidFlightNumberFormat(flightNumber)) {
                // If manual input, check if it's just a number and add prefix/suffix
                const numberMatch = flightNumber.match(/^(\d{1,4})$/);
                if (numberMatch) {
                    const numberPart = numberMatch[1]; // Keep original number without padding
                    const airlineCode = getAirlineCodeForAircraft(currentAircraftForSchedule);
                    const daySuffixes = ['A', 'B', 'C', 'D', 'E', 'F', 'G'];
                    const daySuffix = daySuffixes[daySuffixIndex] || 'A';
                    const positioningSuffix = isPositioningFlight ? 'P' : '';
                    const originalInput = flightNumber;
                    flightNumber = `${airlineCode}${numberPart}${daySuffix}${positioningSuffix}`;
                    console.log(`🔢 Formatted manual input "${originalInput}" to: ${flightNumber}`);
                } else {
                    console.log(`⚠️ Manual flight number "${flightNumber}" doesn't match expected format, but preserving user input`);
                }
            }

            const duplicateCheck = checkFlightNumberSuffixDuplicateForCurrentForm();
            if (duplicateCheck.hasDuplicate) {
                updateFlightNumberDuplicateWarning();
                alert(`⚠️ Flight number conflict detected.\n\n${duplicateCheck.message}\n\nPlease choose a different flight number.`);
                return;
            }
            
            // Parse route data
            let departureAirport, arrivalAirport;
            if (routeValue) {
                try {
                    const route = JSON.parse(routeValue);
                    departureAirport = route.departure;
                    arrivalAirport = route.arrival;
                } catch (e) {
                    console.error('Error parsing route:', e);
                    alert('❌ Invalid route selection. Please select a valid route.');
                    return;
                }
            }
            
            console.log('🔍 FORM VALUES:');
            console.log(`   Departure: ${departureAirport}`);
            console.log(`   Arrival: ${arrivalAirport}`);
            console.log(`   Day: ${day}`);
            console.log(`   Start Time: ${startTime}`);
            console.log(`   Departure Gate: ${departureGate}`);
            console.log(`   Arrival Gate: ${arrivalGate}`);
            console.log(`   Flight Number: ${flightNumber}`);
            
            // Check if boardingTime and disembarkingTime are valid (they have defaults, so check for NaN)
            if (!routeValue || !departureAirport || !arrivalAirport || !day || !startTime || isNaN(boardingTime) || !flightDuration || isNaN(disembarkingTime) || !departureGate || !arrivalGate || !flightNumber) {
                console.log('❌ OVERRIDE VALIDATION FAILED - Missing fields detected');
                console.log('   routeValue:', routeValue, '(type:', typeof routeValue, ')');
                console.log('   departureAirport:', departureAirport, '(type:', typeof departureAirport, ')');
                console.log('   arrivalAirport:', arrivalAirport, '(type:', typeof arrivalAirport, ')');
                console.log('   day:', day, '(type:', typeof day, ')');
                console.log('   startTime:', startTime, '(type:', typeof startTime, ')');
                console.log('   boardingTime:', boardingTime, '(isNaN:', isNaN(boardingTime), ')');
                console.log('   flightDuration:', flightDuration, '(type:', typeof flightDuration, ')');
                console.log('   disembarkingTime:', disembarkingTime, '(isNaN:', isNaN(disembarkingTime), ')');
                console.log('   departureGate:', departureGate, '(type:', typeof departureGate, ')');
                console.log('   arrivalGate:', arrivalGate, '(type:', typeof arrivalGate, ')');
                console.log('   flightNumber:', flightNumber, '(type:', typeof flightNumber, ')');
                showNonBlockingNotification('❌ Please fill in all required fields before scheduling the flight.', 'error');
                return;
            }
            
            const route = {
                departure: departureAirport,
                arrival: arrivalAirport
            };
            
            console.log('🔍 VALIDATING FLIGHT SCHEDULE:');
            console.log(`   Route: ${route.departure} → ${route.arrival}`);
            console.log(`   Flight: ${flightNumber}`);
            console.log(`   Day: ${day}`);
            console.log(`   Start Time: ${startTime}`);
            console.log(`   Departure Gate: ${departureGate}`);
            console.log(`   Arrival Gate: ${arrivalGate}`);
            
            const validationResult = enhancedValidateFlightSchedule(
                route,
                parseInt(day),
                startTime,
                boardingTime,
                flightDuration,
                disembarkingTime,
                departureGate,
                arrivalGate,
                flightNumber,
                autoGateBlocksEnabled
            );
            
            if (!validationResult.valid) {
                console.log('❌ VALIDATION FAILED - PREVENTING SCHEDULE');
                
                let errorMessage = '❌ FLIGHT SCHEDULING BLOCKED - GATE CONFLICTS DETECTED\n\n';
                
                validationResult.errors.forEach((error, index) => {
                    if (error.type === 'gate_conflict') {
                        errorMessage += `${index + 1}. ${error.message}\n`;
                        errorMessage += `   Details: ${error.details}\n\n`;
                    } else {
                        errorMessage += `${index + 1}. ${error.message}\n`;
                        if (error.details) {
                            errorMessage += `   Details: ${error.details}\n\n`;
                        }
                    }
                });
                
                errorMessage += 'Please choose different gates or adjust flight times to resolve conflicts.';
                
                alert(errorMessage);
                return;
            }
            
            logger('✅ VALIDATION PASSED - PROCEEDING WITH FORM SUBMISSION');

            // Persist route scheduling templates for future prefill.
            updateRouteTemplateFromScheduledFlight(
                route,
                parseInt(day, 10),
                currentAircraftForSchedule,
                flightNumber,
                flightDuration
            );
            
            // CRITICAL: Add flight to schedule (validation already passed - no gate checking here)
            const result = addFlightToSchedule(
                currentAircraftForSchedule, 
                route, 
                parseInt(day), 
                startTime, 
                boardingTime, 
                flightDuration, 
                disembarkingTime, 
                departureGate, 
                arrivalGate, 
                flightNumber
            );
            
            // OPTIMIZATION: Defer expensive operations to prevent blocking UI
            // Do immediate UI updates first
            // Reset validation state and form
            window.flightValidationResult = null;
            safeResetForm('flightSchedulingFormElement');
            updateFlightNumberDuplicateWarning();
            const autoGateAfterReset = document.getElementById('autoGateBlocks');
            if (autoGateAfterReset) {
                autoGateAfterReset.checked = autoGateBlocksEnabled;
            }
            updateScheduleFlightButtonState();
            
            // Reset check conflicts button
            const checkBtn = document.getElementById('checkConflictsBtn');
            if (checkBtn) {
                checkBtn.textContent = '🔍 Check for Conflicts';
                checkBtn.style.backgroundColor = '#17a2b8';
            }
            
            showNonBlockingNotification('✅ Flight scheduled successfully!', 'success');
            
            // Return to schedule view immediately
            const scheduleMenu = document.getElementById('aircraftScheduleContent');
            const flightForm = document.getElementById('flightSchedulingForm');
            
            if (scheduleMenu) scheduleMenu.style.display = 'block';
            if (flightForm) flightForm.style.display = 'none';
            
            // OPTIMIZATION: Incrementally update calendar instead of full rebuild
            const calendarBody = document.getElementById('calendarBody');
            const hasCalendarGrid = calendarBody && calendarBody.querySelector('.time-slot');
            
            if (hasCalendarGrid) {
                // Calendar grid exists - incrementally add new flight items
                addScheduleItemsToCalendar(result.flightItems, aircraftSchedules[currentAircraftForSchedule].length - result.flightItems.length);
            } else {
                // Calendar grid doesn't exist - do full rebuild (defer to avoid blocking)
                setTimeout(() => generateCalendar(), 0);
            }
            
            // OPTIMIZATION: Defer expensive operations
            // 1. Save to localStorage (defer with requestIdleCallback)
            if (window.requestIdleCallback) {
                requestIdleCallback(() => {
                    saveAircraftSchedules();
                }, { timeout: 1000 });
            } else {
                setTimeout(() => saveAircraftSchedules(), 100);
            }
            
            // 2. Update route utilization incrementally (only update affected route)
            setTimeout(() => {
                updateRouteUtilizationForRoute(result.route);
            }, 50);
            
            // 3. Auto gate blocks (if enabled) - defer, then refresh calendar (incremental path does not paint new gate blocks)
            if (autoGateBlocksEnabled) {
                setTimeout(() => {
                    createAutomaticGateBlocksBetweenFlights(result.route, parseInt(day), startTime, departureGate, arrivalGate, flightNumber);
                    generateCalendar();
                }, 150);
            }
            
            // 4. Defer non-critical UI updates
            setTimeout(() => {
                restoreAllForSchedulePage();
            }, 200);
            
            setTimeout(() => {
                updateAirportMarkersForSchedulePage();
            }, 300);
            
            setTimeout(() => {
                updateRoutePopupsForSchedulePage();
            }, 400);
        });
        
        console.log('✅ Flight scheduling form submission overridden with enhanced validation');
        updateFlightNumberDuplicateWarning();
    } else {
        console.log('⚠️  Flight scheduling form not found - may need manual integration');
    }
}

// 🔍 PERFORM CONFLICT CHECK FUNCTION - NOW USES UNIFIED VALIDATION
function performConflictCheck() {
    logger('🔍 PERFORMING CONFLICT CHECK...');
    
    // Show loading state
    const checkBtn = document.getElementById('checkConflictsBtn');
    const originalText = checkBtn ? checkBtn.textContent : '';
    if (checkBtn) {
        checkBtn.disabled = true;
        checkBtn.textContent = 'Checking...';
    }
    
    const validationResult = performUnifiedValidation(); // Use the unified validation system
    
    // Store validation result globally
    window.flightValidationResult = validationResult;
    
    // Restore button state
    if (checkBtn) {
        checkBtn.disabled = false;
    }
    
    if (!validationResult.valid) {
        logger('❌ CONFLICTS DETECTED');
        
        let errorMessage = '❌ CONFLICTS DETECTED - FLIGHT CANNOT BE SCHEDULED\n\n';
        
        validationResult.errors.forEach((error, index) => {
            errorMessage += `${index + 1}. ${error.message}\n`;
            if (error.details) {
                errorMessage += `   Details: ${error.details}\n\n`;
            }
        });
        
        errorMessage += 'Please choose different gates or adjust flight times to resolve conflicts.';
        
        showNonBlockingNotification(errorMessage, 'error');
        
        // Update button to show conflict status
        if (checkBtn) {
            checkBtn.textContent = '❌ Conflicts Found';
            checkBtn.style.backgroundColor = '#dc3545';
            setTimeout(() => {
                checkBtn.textContent = originalText;
                checkBtn.style.backgroundColor = '#17a2b8';
            }, 3000);
        }
        
        // Disable Schedule Flight button
        updateScheduleFlightButtonState();
        
        // Gate borders are already updated by performUnifiedValidation
    } else {
        logger('✅ NO CONFLICTS FOUND');
        showNonBlockingNotification('✅ NO CONFLICTS DETECTED - Flight can be scheduled!', 'success');
        
        if (checkBtn) {
            checkBtn.textContent = '✅ No Conflicts';
            checkBtn.style.backgroundColor = '#28a745';
            setTimeout(() => {
                checkBtn.textContent = originalText;
                checkBtn.style.backgroundColor = '#17a2b8';
            }, 3000);
        }
        
        // Enable Schedule Flight button since validation passed
        updateScheduleFlightButtonState();
        
        // Gate borders are already updated by performUnifiedValidation
    }
}

// 🔍 PERFORM GATE BLOCK CONFLICT CHECK FUNCTION - USES SAME SYSTEM AS FLIGHTS
function performGateBlockConflictCheck() {
    console.log('🔍 PERFORMING GATE BLOCK CONFLICT CHECK...');
    
    // Get form values
    const day = document.getElementById('blockDay').value;
    const airport = document.getElementById('blockAirport').value;
    const gate = document.getElementById('blockGate').value;
    const startTime = document.getElementById('blockStartTime').value;
    const endTime = document.getElementById('blockEndTime').value;
    const reason = document.getElementById('blockReason').value;
    
    // Validate required fields
    if (!day || !airport || !gate || !startTime || !endTime) {
        showNonBlockingNotification('❌ Please fill in all required fields before checking for conflicts!', 'error');
        return;
    }
    
    // Validate time range (allow overnight blocks)
    if (startTime >= endTime && !isOvernightBlock(startTime, endTime)) {
        showNonBlockingNotification('❌ End time must be after start time!', 'error');
        return;
    }
    
    // Use the same comprehensive conflict detection system as flights
    const conflictResult = comprehensiveGateConflictCheck(airport, gate, parseInt(day), startTime, endTime);
    
    if (conflictResult.conflict && conflictResult.conflicts.length > 0) {
        console.log('❌ GATE BLOCK CONFLICTS DETECTED');
        
        let errorMessage = '❌ CONFLICTS DETECTED - GATE BLOCK CANNOT BE CREATED\n\n';
        
        conflictResult.conflicts.forEach((conflict, index) => {
            const conflictInfo = conflict.type === 'aircraft' ?
                `Aircraft ${conflict.aircraft} (${conflict.phase})` :
                `Gate block from ${conflict.blockingAircraft}: ${conflict.reason}`;
            
            errorMessage += `${index + 1}. ${conflictInfo}\n`;
            errorMessage += `   Time: ${conflict.conflictingTime}\n`;
            errorMessage += `   Overlap: ${conflict.overlapMinutes} minutes\n\n`;
        });
        
        errorMessage += 'Please choose a different gate or adjust the time range to resolve conflicts.';
        
        showNonBlockingNotification(errorMessage, 'error');
        
        // Update button to show conflict status
        const checkBtn = document.getElementById('checkGateBlockConflictsBtn');
        if (checkBtn) {
            checkBtn.textContent = '❌ Conflicts Found';
            checkBtn.style.backgroundColor = '#dc3545';
            setTimeout(() => {
                checkBtn.textContent = '🔍 Check for Conflicts';
                checkBtn.style.backgroundColor = '#17a2b8';
            }, 3000);
        }
        
        // Add visual conflict indicators to gate dropdown
        addGateBlockConflictVisualIndicators(airport, gate, conflictResult.conflicts);
        
    } else {
        console.log('✅ NO GATE BLOCK CONFLICTS FOUND');
        showNonBlockingNotification('✅ NO CONFLICTS DETECTED - Gate block can be created!', 'success');
        
        const checkBtn = document.getElementById('checkGateBlockConflictsBtn');
        if (checkBtn) {
            checkBtn.textContent = '✅ No Conflicts';
            checkBtn.style.backgroundColor = '#28a745';
            setTimeout(() => {
                checkBtn.textContent = '🔍 Check for Conflicts';
                checkBtn.style.backgroundColor = '#17a2b8';
            }, 3000);
        }
        
        // Remove any existing conflict visual indicators
        removeGateBlockConflictVisualIndicators();
    }
}

