// Remove visual conflict indicators for gate block form
function removeGateBlockConflictVisualIndicators() {
    console.log('🎨 Removing gate block conflict visual indicators...');
    
    // Remove conflict indicators from all form elements
    const elementsToClean = [
        'blockGate', 'blockAirport', 'blockStartTime', 'blockEndTime', 'blockDay'
    ];
    
    elementsToClean.forEach(elementId => {
        const element = document.getElementById(elementId);
        if (element) {
            element.style.border = '';
            element.style.boxShadow = '';
            element.classList.remove('conflict-indicator');
            element.classList.remove('no-conflict-indicator');
        }
    });
    
    console.log('🎨 Gate block conflict visual indicators removed');
}

