// Add flight to schedule function
function addFlightToSchedule(aircraft, route, day, startTime, boardingTime, flightDuration, disembarkingTime, departureGate, arrivalGate, flightNumber) {
    console.log('🔧 ADDING FLIGHT TO SCHEDULE');
    console.log('  Aircraft:', aircraft);
    console.log('  Route:', route);
    console.log('  Day:', day, 'Start Time:', startTime);
    console.log('  Departure Gate:', departureGate, 'Arrival Gate:', arrivalGate);
    console.log('  Flight Number:', flightNumber);
    
    // Calculate flight times
    const boardingStartTime = startTime;
    const boardingEndTime = addMinutesToTime(startTime, boardingTime);
    const flightStartTime = boardingEndTime;
    const flightEndTime = addMinutesToTime(startTime, boardingTime + timeToMinutes(flightDuration));
    const disembarkingStartTime = flightEndTime;
    
    // Calculate disembarking end time - handle overnight case
    const disembarkingEndTimeMinutes = timeToMinutes(disembarkingStartTime) + disembarkingTime;
    let disembarkingEndTime;
    if (disembarkingEndTimeMinutes >= 1440) { // 1440 minutes = 24:00
        // Disembarking spans to next day
        const nextDayMinutes = disembarkingEndTimeMinutes - 1440;
        disembarkingEndTime = minutesToTimeString(nextDayMinutes);
        console.log(`   🌙 Disembarking spans overnight: ${disembarkingStartTime} to ${disembarkingEndTime} (next day)`);
    } else {
        // Disembarking stays on same day
        disembarkingEndTime = minutesToTimeString(disembarkingEndTimeMinutes);
        console.log(`   ☀️ Disembarking same day: ${disembarkingStartTime} to ${disembarkingEndTime}`);
    }
    
    // Calculate the correct day for each phase
    let boardingDay = day;
    let flightDay = day;
    let disembarkingDay = day;
    
    // Check if boarding spans to next day
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        // Boarding crosses midnight, but it should still be displayed on the start day
        // The boarding segment will be handled as an overnight segment in the calendar
        console.log(`   🌙 Boarding crosses midnight but stays on day ${boardingDay} (start day)`);
    }
    
    // FIXED: Flight and disembarking days should be calculated based on when they actually occur
    // If boarding crosses midnight, flight starts on the day after boarding ends
    if (timeToMinutes(boardingEndTime) < timeToMinutes(boardingStartTime)) {
        // Boarding crossed midnight, so flight starts on the day after boarding ends
        flightDay = getNextDay(day); // Flight starts on the day after boarding ends
    } else {
        // Boarding is on the same day, flight starts on the same day
        flightDay = day;
    }
    
    // Check if disembarking occurs on next day (if flight spans overnight)
    if (timeToMinutes(flightEndTime) < timeToMinutes(flightStartTime)) {
        disembarkingDay = getNextDay(flightDay);
        console.log(`   🌙 Disembarking moved to day ${disembarkingDay} (flight spans overnight)`);
    } else {
        disembarkingDay = flightDay;
        console.log(`   ☀️ Disembarking stays on day ${disembarkingDay} (flight same day, disembarking may span overnight)`);
    }
    
    console.log(`   📅 Final schedule: Boarding Day ${boardingDay}, Flight Day ${flightDay}, Disembarking Day ${disembarkingDay}`);
    console.log(`   🕐 Final times: Boarding ${boardingStartTime}-${boardingEndTime}, Flight ${flightStartTime}-${flightEndTime}, Disembarking ${disembarkingStartTime}-${disembarkingEndTime}`);
    
    // Create flight items
    const flightItems = [
        {
            type: 'flight',
            route: `${route.departure} → ${route.arrival}`,
            flightNumber: flightNumber,
            departureAirport: route.departure,
            arrivalAirport: route.arrival,
            day: day, // Boarding always starts on the original day
            startTime: boardingStartTime,
            endTime: boardingEndTime,
            phase: 'boarding',
            airport: route.departure,
            gate: departureGate
        },
        {
            type: 'flight',
            route: `${route.departure} → ${route.arrival}`,
            flightNumber: flightNumber,
            departureAirport: route.departure,
            arrivalAirport: route.arrival,
            day: flightDay,
            startTime: flightStartTime,
            endTime: flightEndTime,
            phase: 'flight',
            airport: null,
            gate: null
        }
    ];
    
    // Handle disembarking as a single segment (even if it spans overnight)
    flightItems.push({
        type: 'flight',
        route: `${route.departure} → ${route.arrival}`,
        flightNumber: flightNumber,
        departureAirport: route.departure,
        arrivalAirport: route.arrival,
        day: disembarkingDay,
        startTime: disembarkingStartTime,
        endTime: disembarkingEndTime,
        phase: 'disembarking',
        airport: route.arrival,
        gate: arrivalGate
    });
    
    if (disembarkingEndTimeMinutes >= 1440) {
        console.log(`   🌙 Created overnight disembarking: Day ${disembarkingDay} ${disembarkingStartTime}-${disembarkingEndTime} (spans to next day)`);
    } else {
        console.log(`   ☀️ Created same-day disembarking: Day ${disembarkingDay} ${disembarkingStartTime}-${disembarkingEndTime}`);
    }
    
    // Initialize schedule array if it doesn't exist for this aircraft
    if (!aircraftSchedules[aircraft]) {
        aircraftSchedules[aircraft] = [];
        console.log(`Initialized schedule for aircraft: ${aircraft}`);
    }
    
    // Add flight items to schedule
    flightItems.forEach(item => {
        aircraftSchedules[aircraft].push(item);
        scheduleIndexDirty = true; // Mark index as dirty for conflict checking
        logger(`   ➕ Added: ${item.phase} - Day ${item.day} ${item.startTime}-${item.endTime} at ${item.airport} gate ${item.gate}`);
    });
    markRouteFlightsLookupDirty();
    
    logger(`Added ${flightItems.length} flight items to aircraft: ${aircraft}`);
    
    // Return result for deferred operations
    return {
        flightItems: flightItems,
        route: route
    };
}

