// Populate gate options for the selected airport
function populateGateOptions(airport, currentGate) {
    const gateSelect = document.getElementById('newGate');
    if (!gateSelect) return;
    
    // Clear existing options
    gateSelect.innerHTML = '<option value="">Select new gate...</option>';
    
    // Get gates for the airport
    const airportGates = gatesData[airport] || [];
    
    // Sort gates alphabetically by terminal first, then by gate number
    const sortedGates = [...airportGates].sort((a, b) => {
        // First sort by terminal
        const terminalComparison = a.terminal.localeCompare(b.terminal);
        if (terminalComparison !== 0) {
            return terminalComparison;
        }
        // Then sort by gate number alphabetically
        return a.number.localeCompare(b.number, undefined, { numeric: true, sensitivity: 'base' });
    });
    
    sortedGates.forEach(gate => {
        const option = document.createElement('option');
        option.value = `${gate.number} (${gate.terminal})`;
        option.textContent = `${gate.number} (${gate.terminal})`;
        
        // Mark current gate as selected
        if (option.value === currentGate) {
            option.selected = true;
        }
        
        gateSelect.appendChild(option);
    });
    
    console.log(`   Populated ${airportGates.length} gate options for ${airport}`);
}

