// Save the gate change
function saveGateChange(aircraft, scheduleIndex, newGate, airport, day, startTime, endTime) {
    console.log(`💾 Saving gate change for ${aircraft}: ${newGate}`);
    
    // Check for conflicts with the new gate before saving
    console.log(`🔍 Checking for conflicts with new gate ${newGate}...`);
    
    const conflictResult = comprehensiveGateConflictCheck(
        airport, 
        newGate, 
        day, 
        startTime, 
        endTime, 
        aircraft // Exclude current aircraft from conflict check
    );
    
    if (conflictResult && conflictResult.conflict) {
        console.log(`❌ Conflict detected with new gate ${newGate}`);
        console.log(`   Conflicts found: ${conflictResult.totalConflicts}`);
        
        // Show detailed conflict information
        let conflictMessage = `❌ Cannot change gate to ${newGate}!\n\n`;
        conflictMessage += `Conflicts detected:\n`;
        
        conflictResult.conflicts.forEach((conflict, index) => {
            conflictMessage += formatComprehensiveGateConflictForUi(conflict, index);
        });
        
        conflictMessage += `Please select a different gate or adjust the flight time.`;
        
        showNonBlockingNotification(conflictMessage, 'error');
        return; // Don't save the change
    }
    
    console.log(`✅ No conflicts found with new gate ${newGate}`);
    
    // Update the schedule
    if (aircraftSchedules[aircraft] && aircraftSchedules[aircraft][scheduleIndex]) {
        aircraftSchedules[aircraft][scheduleIndex].gate = newGate;
        
        // Save to localStorage
        saveAircraftSchedules();
        
        // Update UI
        updateRouteUtilizationFromSchedules();
        generateCalendar();
        updateAirportMarkersForSchedulePage();
        updateRoutePopupsForSchedulePage();
        
        // Show success message
        showNonBlockingNotification(`✅ Gate changed successfully!\n\n${aircraft} now uses ${newGate}`, 'success');
        
        console.log(`✅ Gate change saved for ${aircraft}`);
    } else {
        console.error(`❌ Could not find schedule item for ${aircraft} at index ${scheduleIndex}`);
        showNonBlockingNotification('❌ Error: Could not find the flight to update', 'error');
    }
}

