// Get airline code for a specific aircraft
function getAirlineCodeForAircraft(aircraftRegistration) {
    for (const airline of airlinesList) {
        if (airline.aircraft) {
            const foundAircraft = airline.aircraft.find(ac => ac.registration === aircraftRegistration);
            if (foundAircraft) {
                return airline.code;
            }
        }
    }
    return 'KTC'; // Default fallback
}

// Check if flight number has proper format (airline code + number + day suffix)
function isValidFlightNumberFormat(flightNumber) {
    if (!flightNumber) return false;
    
    // Check if it matches the pattern: [AIRLINE_CODE][NUMBER][DAY_SUFFIX][P?]
    // Examples: KTC1A, KTA123B, NH4567C, KTC1AP (positioning flight)
    const pattern = /^[A-Z]{2,3}\d{1,4}[A-G]P?$/;
    return pattern.test(flightNumber);
}

function getAllFlightNumbersForAirline(airlineCode) {
    const airlineFlightNumbers = new Set();
    if (!airlineCode) return airlineFlightNumbers;

    const normalizedAirlineCode = String(airlineCode).toUpperCase();

    Object.values(aircraftSchedules).forEach(schedule => {
        if (!Array.isArray(schedule)) return;

        schedule.forEach(item => {
            if (!item || item.type !== 'flight' || item.phase !== 'flight' || !item.flightNumber) return;
            const normalizedFlightNumber = String(item.flightNumber).trim().toUpperCase();
            if (normalizedFlightNumber.startsWith(normalizedAirlineCode)) {
                airlineFlightNumbers.add(normalizedFlightNumber);
            }
        });
    });

    return airlineFlightNumbers;
}

function normalizeCurrentFormFlightNumberForDuplicateCheck() {
    const flightNumberInput = document.getElementById('flightNumber');
    const daySelect = document.getElementById('flightDay');
    const isPositioningFlight = document.getElementById('isPositioningFlight') ? document.getElementById('isPositioningFlight').checked : false;
    const airlineCode = getAirlineCodeForAircraft(currentAircraftForSchedule);

    if (!flightNumberInput || !daySelect || !airlineCode) {
        return null;
    }

    const rawInput = String(flightNumberInput.value || '').trim().toUpperCase();
    const dayValue = daySelect.value;
    if (!rawInput || dayValue === '') {
        return null;
    }

    const daySuffixes = ['A', 'B', 'C', 'D', 'E', 'F', 'G'];
    const utcDay = parseInt(dayValue, 10);
    const localDay = getFlightFormLocalDepartureDayForSuffix();
    const suffixIdx = localDay !== null ? localDay : utcDay;
    const daySuffix = daySuffixes[suffixIdx] || 'A';
    const positioningSuffix = isPositioningFlight ? 'P' : '';

    // User entered only number -> this is what scheduler auto-formats on submit.
    const numberMatch = rawInput.match(/^(\d{1,4})$/);
    if (numberMatch) {
        return `${airlineCode}${numberMatch[1]}${daySuffix}${positioningSuffix}`;
    }

    // User entered full flight number already.
    if (isValidFlightNumberFormat(rawInput)) {
        return rawInput;
    }

    return null;
}

function checkFlightNumberSuffixDuplicateForCurrentForm() {
    const normalizedFlightNumber = normalizeCurrentFormFlightNumberForDuplicateCheck();
    const airlineCode = getAirlineCodeForAircraft(currentAircraftForSchedule);

    if (!normalizedFlightNumber || !airlineCode) {
        return { hasDuplicate: false, normalizedFlightNumber: null, message: '' };
    }

    const airlineFlightNumbers = getAllFlightNumbersForAirline(airlineCode);
    const hasDuplicate = airlineFlightNumbers.has(normalizedFlightNumber);
    const message = hasDuplicate
        ? `Flight number ${normalizedFlightNumber} already exists for airline ${airlineCode}.`
        : '';

    return { hasDuplicate, normalizedFlightNumber, message };
}

function updateFlightNumberDuplicateWarning() {
    const flightNumberInput = document.getElementById('flightNumber');
    if (!flightNumberInput) return;

    const duplicateCheck = checkFlightNumberSuffixDuplicateForCurrentForm();
    if (duplicateCheck.hasDuplicate) {
        flightNumberInput.style.borderColor = '#dc3545';
        flightNumberInput.style.boxShadow = '0 0 0 2px rgba(220, 53, 69, 0.18)';
        flightNumberInput.title = duplicateCheck.message;
        return;
    }

    flightNumberInput.style.borderColor = '';
    flightNumberInput.style.boxShadow = '';
    flightNumberInput.title = '';
}

// Auto-generate flight number based on airline route allocation (or positioning fallback).
function generateFlightNumber(aircraftRegistration, day, isPositioningFlight = false, suffixDayIndex = null, routeOverride = null) {
    console.log(`🔢 Generating flight number for ${aircraftRegistration} on day ${day}${isPositioningFlight ? ' (positioning flight)' : ''}`);

    const airlineCode = getAirlineCodeForAircraft(aircraftRegistration);

    if (!isPositioningFlight) {
        let route = routeOverride;
        if (!route) {
            const routeValue = document.getElementById('flightRoute')?.value;
            if (routeValue) {
                try {
                    route = JSON.parse(routeValue);
                } catch (error) {
                    route = null;
                }
            }
        }
        if (route) {
            const serviceOrdinal = getRouteServiceOrdinalForForm(route, day, aircraftRegistration);
            const numberCore = getOrAllocateRouteFlightNumberCore(airlineCode, route, serviceOrdinal);
            if (numberCore != null) {
                const flightNumber = formatFlightNumberFromCore(
                    airlineCode,
                    numberCore,
                    day,
                    false,
                    suffixDayIndex
                );
                console.log(`   Generated route-based flight number: ${flightNumber}`);
                return flightNumber;
            }
        }
    }

    const daySuffixes = ['A', 'B', 'C', 'D', 'E', 'F', 'G'];
    const suffixIdx = Number.isInteger(suffixDayIndex) && suffixDayIndex >= 0 && suffixDayIndex <= 6 ? suffixDayIndex : day;
    const daySuffix = daySuffixes[suffixIdx] || 'A';
    const finalSuffix = isPositioningFlight ? `${daySuffix}P` : daySuffix;

    const existingFlights = [];
    if (aircraftSchedules[aircraftRegistration]) {
        aircraftSchedules[aircraftRegistration].forEach(item => {
            if (item.type === 'flight' && item.phase === 'flight' && item.day === day && item.flightNumber) {
                existingFlights.push(item.flightNumber);
            }
        });
    }

    let nextNumber = FLIGHT_NUMBER_CORE_MIN;
    const usedNumbers = existingFlights.map(flightNum => {
        const match = flightNum.match(new RegExp(`${airlineCode}(\\d+)${daySuffix}(P)?`));
        return match ? parseInt(match[1], 10) : 0;
    }).filter(num => num > 0);

    if (usedNumbers.length > 0) {
        nextNumber = Math.max(...usedNumbers) + 1;
    }

    const airlineUsedCores = collectUsedFlightNumberCoresForAirline(airlineCode);
    nextNumber = findNextAvailableFlightNumberCore(nextNumber, airlineUsedCores) || nextNumber;

    const flightNumber = `${airlineCode}${nextNumber}${finalSuffix}`;
    console.log(`   Generated fallback flight number: ${flightNumber}`);
    return flightNumber;
}

