// Setup auto-fill event listeners for flight scheduling form
function setupFlightNumberAutoFill() {
    const daySelect = document.getElementById('flightDay');
    const routeSelect = document.getElementById('flightRoute');
    const flightNumberInput = document.getElementById('flightNumber');
    const flightDurationInput = document.getElementById('flightDuration');
    
    if (!daySelect || !flightNumberInput) {
        console.log('❌ Flight number auto-fill elements not found');
        return;
    }
    
    // Clear any existing data attributes
    daySelect.removeAttribute('data-auto-fill-disabled');
    flightNumberInput.removeAttribute('data-manual-input');
    if (flightDurationInput) {
        flightDurationInput.removeAttribute('data-manual-input');
    }
    
    // Add event listener to day dropdown - only auto-fill if field is empty
    daySelect.addEventListener('change', function() {
        console.log('📅 Day selection changed');
        updateFlightNumberAutoFill();
    });

    if (routeSelect) {
        routeSelect.addEventListener('change', function() {
            updateFlightNumberAutoFill();
        });
    }
    
    // Add event listener to flight number input to track manual entry
    flightNumberInput.addEventListener('input', function() {
        if (this.value.trim()) {
            this.setAttribute('data-manual-input', 'true');
            console.log(`✏️ User manually entered: ${this.value}`);
        } else {
            this.removeAttribute('data-manual-input');
            console.log('✏️ Flight number field cleared, auto-fill re-enabled');
        }
    });

    if (flightDurationInput) {
        flightDurationInput.addEventListener('input', function() {
            if (this.value.trim()) {
                this.setAttribute('data-manual-input', 'true');
            } else {
                this.removeAttribute('data-manual-input');
            }
        });
    }
    
    // Add event listener to positioning flight checkbox
    const positioningFlightCheckbox = document.getElementById('isPositioningFlight');
    if (positioningFlightCheckbox) {
        positioningFlightCheckbox.addEventListener('change', function() {
            console.log(`🔄 Positioning flight checkbox changed: ${this.checked}`);
            const hasManualInput = flightNumberInput.getAttribute('data-manual-input') === 'true';
            if (!hasManualInput && daySelect.value) {
                console.log('🔄 Auto-updating flight number for positioning flight change');
                updateFlightNumberAutoFill();
            } else {
                console.log('🔄 Preserving manual input, not auto-updating');
            }
            refreshScheduleRoutePopupFromForm();
        });
    }
    
    console.log('✅ Flight number auto-fill event listeners set up');
}

// Fix flight numbers in export data to use proper sequential format
function fixExportDataFlightNumbers() {
    console.log('🔧 FIXING FLIGHT NUMBERS IN EXPORT DATA...');
    
    // Get the current export data
    const exportData = {
        version: "1.0",
        exportDate: new Date().toISOString(),
        data: {
            airports: JSON.parse(localStorage.getItem('savedAirports') || '[]'),
            routes: JSON.parse(localStorage.getItem('savedRoutes') || '[]'),
            aircraftTypes: JSON.parse(localStorage.getItem('savedAircraft') || '[]'),
            registeredAircraft: JSON.parse(localStorage.getItem('savedRegisteredAircraft') || '[]'),
            airlines: JSON.parse(localStorage.getItem('savedAirlines') || '[]'),
            gates: JSON.parse(localStorage.getItem('savedGates') || '{}'),
            gateBlocks: JSON.parse(localStorage.getItem('savedGateBlocks') || '{}'),
            schedule: JSON.parse(localStorage.getItem('savedSchedule') || '[]'),
            aircraftSchedules: JSON.parse(localStorage.getItem('savedAircraftSchedules') || '{}')
        }
    };
    
    let totalFixed = 0;
    
    // Process each aircraft's schedule
    Object.keys(exportData.data.aircraftSchedules).forEach(aircraftRegistration => {
        const schedule = exportData.data.aircraftSchedules[aircraftRegistration];
        if (!schedule || !Array.isArray(schedule)) return;
        
        console.log(`\n🔧 Processing aircraft: ${aircraftRegistration}`);
        
        // Find the airline for this aircraft
        let airlineCode = 'KTC'; // Default fallback
        for (const airline of exportData.data.airlines) {
            if (airline.aircraft) {
                const foundAircraft = airline.aircraft.find(ac => ac.registration === aircraftRegistration);
                if (foundAircraft) {
                    airlineCode = airline.code;
                    console.log(`   Found airline: ${airline.name} (${airlineCode})`);
                    break;
                }
            }
        }
        
        // Group flights by day and create sequential numbers
        const flightsByDay = {};
        
        schedule.forEach(item => {
            if (item.type === 'flight' && item.phase === 'flight' && item.flightNumber) {
                const day = item.day;
                if (!flightsByDay[day]) {
                    flightsByDay[day] = [];
                }
                flightsByDay[day].push(item);
            }
        });
        
        // Process each day's flights
        Object.keys(flightsByDay).forEach(day => {
            const dayFlights = flightsByDay[day];
            const daySuffixes = ['A', 'B', 'C', 'D', 'E', 'F', 'G'];
            const daySuffix = daySuffixes[parseInt(day)] || 'A';
            
            console.log(`   Day ${day} (${daySuffix}): ${dayFlights.length} flights`);
            
            // Sort flights by start time
            dayFlights.sort((a, b) => a.startTime.localeCompare(b.startTime));
            
            // Assign sequential flight numbers
            dayFlights.forEach((flight, index) => {
                const sequentialNumber = (index + 1).toString().padStart(4, '0'); // 0001, 0002, 0003, etc.
                const newFlightNumber = `${airlineCode}${sequentialNumber}${daySuffix}`;
                
                if (flight.flightNumber !== newFlightNumber) {
                    console.log(`     ${flight.flightNumber} → ${newFlightNumber}`);
                    
                    // Update all related items (boarding, flight, disembarking) with the same flight number
                    schedule.forEach(scheduleItem => {
                        if (scheduleItem.flightNumber === flight.flightNumber) {
                            scheduleItem.flightNumber = newFlightNumber;
                            totalFixed++;
                        }
                    });
                }
            });
        });
    });
    
    // Save the fixed data back to localStorage
    localStorage.setItem('savedAircraftSchedules', JSON.stringify(exportData.data.aircraftSchedules));
    
    console.log(`\n✅ FIXED ${totalFixed} FLIGHT NUMBERS IN EXPORT DATA`);
    console.log('📁 Updated data saved to localStorage');
    
    return exportData;
}

