// Export the fixed data
function exportFixedData() {
    console.log('📤 EXPORTING FIXED DATA...');
    
    const fixedData = fixExportDataFlightNumbers();
    
    // Create download link
    const dataStr = JSON.stringify(fixedData, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    
    const link = document.createElement('a');
    link.href = url;
    link.download = `kohben-travel-data-fixed-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    
    console.log('✅ Fixed data exported successfully!');
}

