function normalizeClockMinutes(totalMinutes) {
    const minutesPerDay = 24 * 60;
    return ((totalMinutes % minutesPerDay) + minutesPerDay) % minutesPerDay;
}

function formatAbsoluteMinutesToClock(totalMinutes) {
    return minutesToTimeString(normalizeClockMinutes(totalMinutes));
}

// Validates a continuous [start, end] interval against airport daily operating hours,
// including airports whose hours cross midnight (e.g. 10:30-02:00).
function isIntervalWithinAirportHours(startAbsMinutes, endAbsMinutes, openingTime, closingTime) {
    const openingMinutes = timeToMinutes(openingTime);
    const closingMinutes = timeToMinutes(closingTime);

    // 00:00-00:00 / same open-close means 24-hour operations in this app.
    if (openingMinutes === closingMinutes) {
        return true;
    }

    let start = startAbsMinutes;
    let end = endAbsMinutes;
    if (end < start) {
        end += 24 * 60;
    }

    const startDay = Math.floor(start / (24 * 60));
    const candidateAnchors = [startDay - 1, startDay, startDay + 1];

    for (const dayAnchor of candidateAnchors) {
        let windowStart;
        let windowEnd;

        if (openingMinutes < closingMinutes) {
            // Same-day window, e.g. 08:00-22:00
            windowStart = dayAnchor * 24 * 60 + openingMinutes;
            windowEnd = dayAnchor * 24 * 60 + closingMinutes;
        } else {
            // Overnight window, e.g. 10:30-02:00
            windowStart = dayAnchor * 24 * 60 + openingMinutes;
            windowEnd = (dayAnchor + 1) * 24 * 60 + closingMinutes;
        }

        if (start >= windowStart && end <= windowEnd) {
            return true;
        }
    }

    return false;
}

// Check if gate usage is outside airport operating hours
function checkAirportOperatingHours(gateType, gateValue) {
    console.log(`🕐 Checking airport operating hours for ${gateType} gate ${gateValue}...`);
    
    // Get flight details
    const day = document.getElementById('flightDay').value;
    const startTime = document.getElementById('flightStartTime').value;
    const boardingTime = parseInt(document.getElementById('boardingTime').value) || 30;
    const flightDuration = document.getElementById('flightDuration').value;
    const disembarkingTime = parseInt(document.getElementById('disembarkingTime').value) || 15;
    
    if (!day || !startTime || !flightDuration) {
        return { isOutsideHours: false, message: '' };
    }
    
    // Get airport from route selection
    const routeValue = document.getElementById('flightRoute').value;
    let airport;
    if (routeValue) {
        try {
            const route = JSON.parse(routeValue);
            airport = gateType === 'departure' ? route.departure : route.arrival;
        } catch (e) {
            console.error('Error parsing route for operating hours check:', e);
            return { isOutsideHours: false, message: '' };
        }
    } else {
        return { isOutsideHours: false, message: '' };
    }
    
    if (!airport) return { isOutsideHours: false, message: '' };
    
    // Calculate time ranges
    const startTimeMinutes = timeToMinutes(startTime);
    const flightDurationMinutes = timeToMinutes(flightDuration);
    
    let checkStartTime, checkEndTime, checkDay;
    
    if (gateType === 'departure') {
        // Validate against the flight segment timing (takeoff), not full boarding window.
        // This keeps gate-hours highlighting aligned with flight-hours validation.
        checkStartTime = startTimeMinutes + boardingTime;
        checkEndTime = checkStartTime;
        checkDay = parseInt(day);
    } else {
        // Validate against the flight segment timing (landing), not full disembarking window.
        checkStartTime = startTimeMinutes + boardingTime + flightDurationMinutes;
        checkEndTime = checkStartTime;
        checkDay = parseInt(day);
    }
    
    const checkStartTimeStr = formatAbsoluteMinutesToClock(checkStartTime);
    const checkEndTimeStr = formatAbsoluteMinutesToClock(checkEndTime);
    
    console.log(`🕐 Operating hours check: ${airport} gate ${gateValue}`);
    console.log(`   Time: ${checkStartTimeStr} - ${checkEndTimeStr} (Day ${checkDay})`);
    
    // Get airport operating hours
    const airportHours = getAirportOperatingHours(airport);
    
    if (!airportHours) {
        console.log(`   No operating hours data for ${airport}`);
        return { isOutsideHours: false, message: '' };
    }
    
    console.log(`   Airport hours: ${airportHours.openingTime} - ${airportHours.closingTime}`);
    
    // For 24-hour airports (00:00-23:59), allow overnight usage
    if (airportHours.openingTime === '00:00' && airportHours.closingTime === '23:59') {
        console.log(`   ✅ 24-hour airport - gate usage allowed at any time (including overnight)`);
        console.log(`   🕐 Gate usage: ${checkStartTimeStr}-${checkEndTimeStr} on day ${checkDay}`);
        return { isOutsideHours: false, message: '' };
    }
    
    // Check if the full gate-usage interval is within airport operating hours.
    const isWithinHours = isIntervalWithinAirportHours(
        checkStartTime,
        checkEndTime,
        airportHours.openingTime,
        airportHours.closingTime
    );
    
    if (!isWithinHours) {
        const segmentLabel = gateType === 'departure' ? 'Takeoff time' : 'Landing time';
        const message = `${segmentLabel} (${checkStartTimeStr}) is outside ${airport} operating hours (${airportHours.openingTime}-${airportHours.closingTime})`;
        console.log(`   ❌ ${message}`);
        return { isOutsideHours: true, message: message };
    }
    
    console.log(`   ✅ Gate usage is within operating hours`);
    return { isOutsideHours: false, message: '' };
}

// Get airport operating hours
function getAirportOperatingHours(airportName) {
    // Default operating hours if not specified
    // Most airports operate 24/7, but some have restrictions
    const defaultHours = {
        openingTime: '00:00',
        closingTime: '23:59'
    };

    // Prefer the actual airport data from markers/export when available.
    // This keeps validation aligned with the loaded dataset.
    const marker = userMarkers.find(m => m?.airportData?.name === airportName);
    const rawHours = marker?.airportData?.hours;
    if (rawHours) {
        if (typeof rawHours === 'string') {
            const [openingRaw, closingRaw] = rawHours.split('-');
            const openingTime = (openingRaw || '00:00').trim();
            const closingTime = (closingRaw || '00:00').trim();

            // In this app, 00:00-00:00 means 24-hour operations.
            if (openingTime === '00:00' && closingTime === '00:00') {
                return { openingTime: '00:00', closingTime: '23:59' };
            }
            return { openingTime, closingTime };
        }

        if (typeof rawHours === 'object') {
            const openingTime = (rawHours.opening || rawHours.openingTime || '00:00').trim();
            const closingTime = (rawHours.closing || rawHours.closingTime || '00:00').trim();

            if (openingTime === '00:00' && closingTime === '00:00') {
                return { openingTime: '00:00', closingTime: '23:59' };
            }
            return { openingTime, closingTime };
        }
    }
    
    // Some airports with known restrictions
    const restrictedAirports = {
        'Hacaritama Airport': { openingTime: '11:00', closingTime: '23:00' },
        'Germán Olano Airport': { openingTime: '06:00', closingTime: '22:00' }
    };
    
    return restrictedAirports[airportName] || defaultHours;
}

