// UNIFIED CONFLICT DETECTION SYSTEM - ALL THREE VALIDATION SYSTEMS USE THIS
function performUnifiedValidation() {
    console.log('🔍 PERFORMING UNIFIED CONFLICT CHECK...');
    
    // Get all form values
    const day = parseInt(document.getElementById('flightDay').value);
    const startTime = document.getElementById('flightStartTime').value;
    const boardingTime = parseInt(document.getElementById('boardingTime').value) || 30;
    const flightDuration = document.getElementById('flightDuration').value;
    const disembarkingTime = parseInt(document.getElementById('disembarkingTime').value) || 15;
    const departureGate = document.getElementById('departureGate').value;
    const arrivalGate = document.getElementById('arrivalGate').value;
    
    // Check if boardingTime and disembarkingTime are valid (they have defaults, so check for NaN)
    // Note: day can be 0 (Monday), so check for null/undefined instead of falsy
    if (day === null || day === undefined || !startTime || isNaN(boardingTime) || !flightDuration || isNaN(disembarkingTime) || !departureGate || !arrivalGate) {
        console.log('❌ UNIFIED VALIDATION FAILED - Missing required form data');
        console.log('   day:', day, '(type:', typeof day, ')');
        console.log('   startTime:', startTime, '(type:', typeof startTime, ')');
        console.log('   boardingTime:', boardingTime, '(isNaN:', isNaN(boardingTime), ')');
        console.log('   flightDuration:', flightDuration, '(type:', typeof flightDuration, ')');
        console.log('   disembarkingTime:', disembarkingTime, '(isNaN:', isNaN(disembarkingTime), ')');
        console.log('   departureGate:', departureGate, '(type:', typeof departureGate, ')');
        console.log('   arrivalGate:', arrivalGate, '(type:', typeof arrivalGate, ')');
        return { valid: false, errors: [{ type: 'missing_data', message: 'Missing required form data' }] };
    }
    
    // Get route (if available)
    const routeValue = document.getElementById('flightRoute').value;
    let route = null;
    let departureAirport = null;
    let arrivalAirport = null;
    
    if (routeValue) {
        try {
            route = JSON.parse(routeValue);
            departureAirport = route.departure;
            arrivalAirport = route.arrival;
        } catch (e) {
            console.log('❌ Invalid route data');
            return { valid: false, errors: [{ type: 'invalid_data', message: 'Invalid route data' }] };
        }
    } else {
        console.log('⚠️ No route selected - will check gate conflicts without full route context');
        // Try to infer airports from gate names if possible
        if (departureGate && departureGate.includes('Terminal')) {
            departureAirport = 'El Dorado International Airport'; // Default assumption for Terminal gates
        }
        if (arrivalGate && arrivalGate.includes('Terminal')) {
            arrivalAirport = 'Gustavo Rojas Pinilla International Airport'; // Default assumption for Terminal gates
        }
    }
    
    // CRITICAL FIX: Ensure currentAircraftForSchedule is set for validation
    // If not set, try to determine from the current context
    if (!currentAircraftForSchedule) {
        console.log('⚠️ currentAircraftForSchedule not set, attempting to determine from context...');
        
        // Try to get from aircraft selection dropdown if it exists
        const aircraftSelect = document.getElementById('aircraftSelect');
        if (aircraftSelect && aircraftSelect.value) {
            currentAircraftForSchedule = aircraftSelect.value;
            console.log(`✅ Set currentAircraftForSchedule from dropdown: ${currentAircraftForSchedule}`);
        } else {
            // Fallback: use the first available aircraft
            const availableAircraft = Object.keys(aircraftSchedules);
            if (availableAircraft.length > 0) {
                currentAircraftForSchedule = availableAircraft[0];
                console.log(`⚠️ Set currentAircraftForSchedule to first available: ${currentAircraftForSchedule}`);
            } else {
                console.log('❌ No aircraft available for validation');
                return { valid: false, errors: [{ type: 'no_aircraft', message: 'No aircraft selected or available' }] };
            }
        }
    }
    
    console.log(`🔍 Using aircraft for validation: ${currentAircraftForSchedule}`);
    
    // Use the SAME validation logic as the schedule button
    // If no route is available, create a temporary route for validation
    const validationRoute = route || {
        departure: departureAirport || 'Unknown Departure',
        arrival: arrivalAirport || 'Unknown Arrival'
    };
    
    const flightNumberField = document.getElementById('flightNumber');
    let validationFlightNumber = flightNumberField && flightNumberField.value.trim() ? flightNumberField.value.trim() : 'TEMP-FLIGHT';
    const autoGateBlocksToggle = document.getElementById('autoGateBlocks');
    const autoGateBlocksEnabled = autoGateBlocksToggle ? autoGateBlocksToggle.checked : false;
    const validationResult = enhancedValidateFlightSchedule(
        validationRoute,
        day,
        startTime,
        boardingTime,
        flightDuration,
        disembarkingTime,
        departureGate,
        arrivalGate,
        validationFlightNumber,
        autoGateBlocksEnabled
    );
    
    console.log(`🔍 UNIFIED VALIDATION RESULT: ${validationResult.valid ? 'VALID' : `${validationResult.errors.length} CONFLICTS`}`);
    
    // Update gate borders based on the validation results
    // Check which specific gates have conflicts
    let departureHasConflict = false;
    let arrivalHasConflict = false;
    
    if (!validationResult.valid && validationResult.errors) {
        validationResult.errors.forEach(error => {
            // Check for departure gate conflicts (boarding phase)
            if (error.phase === 'boarding' || 
                (error.gate && error.gate === departureGate) ||
                (error.airport && error.airport === validationRoute.departure && error.phase === 'boarding')) {
                departureHasConflict = true;
                console.log(`   🎯 DEPARTURE GATE CONFLICT IDENTIFIED: ${error.message}`);
            }
            
            // Check for arrival gate conflicts (disembarking phase)
            if (error.phase === 'disembarking' || 
                (error.gate && error.gate === arrivalGate) ||
                (error.airport && error.airport === validationRoute.arrival && error.phase === 'disembarking')) {
                arrivalHasConflict = true;
                console.log(`   🎯 ARRIVAL GATE CONFLICT IDENTIFIED: ${error.message}`);
            }
        });
    }
    
    // Check operating hours violations FIRST (takes priority over conflicts)
    const departureHoursViolation = checkAirportOperatingHours('departure', departureGate);
    const arrivalHoursViolation = checkAirportOperatingHours('arrival', arrivalGate);
    
    // Set gate colors based on operating hours violations or conflicts
    if (departureHoursViolation.isOutsideHours) {
        console.log('🚫 DEPARTURE GATE OUTSIDE OPERATING HOURS - Setting departure gate to red');
        setGateBorderColor('departure', 'red', 'hours-violation', departureHoursViolation.message);
    } else if (departureHasConflict) {
        console.log('❌ DEPARTURE GATE CONFLICT - Setting departure gate to red');
        setGateBorderColor('departure', 'red', 'conflict');
    } else {
        console.log('✅ DEPARTURE GATE AVAILABLE - Setting departure gate to green');
        setGateBorderColor('departure', 'green');
    }
    
    if (arrivalHoursViolation.isOutsideHours) {
        console.log('🚫 ARRIVAL GATE OUTSIDE OPERATING HOURS - Setting arrival gate to red');
        setGateBorderColor('arrival', 'red', 'hours-violation', arrivalHoursViolation.message);
    } else if (arrivalHasConflict) {
        console.log('❌ ARRIVAL GATE CONFLICT - Setting arrival gate to red');
        setGateBorderColor('arrival', 'red', 'conflict');
    } else {
        console.log('✅ ARRIVAL GATE AVAILABLE - Setting arrival gate to green');
        setGateBorderColor('arrival', 'green');
    }
    
    return validationResult;
}

