// Helper function to set gate border color
function setGateBorderColor(gateType, color, violationType = null, message = '') {
    const gateSelect = document.getElementById(gateType + 'Gate');
    const gateContainer = gateSelect ? gateSelect.parentElement : null;
    
    if (!gateContainer) return;
    
    // Remove existing validation classes
    gateContainer.classList.remove('gate-available', 'gate-conflict', 'gate-warning', 'gate-hours-violation');
    
    if (color === 'green') {
        gateContainer.classList.add('gate-available');
        gateContainer.title = '✅ Gate is available during the selected time';
    } else if (color === 'red') {
        if (violationType === 'hours-violation') {
            gateContainer.classList.add('gate-hours-violation');
            gateContainer.title = `🚫 OUTSIDE OPERATING HOURS: ${message || 'Gate usage is outside airport operating hours'}`;
        } else {
            gateContainer.classList.add('gate-conflict');
            gateContainer.title = '⚠️ CONFLICT: Gate is not available during the selected time';
        }
    }
    
    console.log(`🎨 Set ${gateType} gate border to ${color}${violationType ? ` (${violationType})` : ''}`);
}

