// Show non-blocking notification
function showNonBlockingNotification(message, type = 'error') {
    // Remove any existing notifications
    const existingNotifications = document.querySelectorAll('.notification-toast');
    existingNotifications.forEach(notification => notification.remove());
    
    // Create notification element
    const notification = document.createElement('div');
    notification.className = `notification-toast ${type}`;
    
    // Add close button
    const closeBtn = document.createElement('button');
    closeBtn.className = 'close-btn';
    closeBtn.innerHTML = '×';
    closeBtn.onclick = () => notification.remove();
    
    // Add message
    notification.innerHTML = message;
    notification.appendChild(closeBtn);
    
    // Add to page
    document.body.appendChild(notification);
    
    // Auto-remove after 10 seconds
    setTimeout(() => {
        if (notification.parentNode) {
            notification.remove();
        }
    }, 10000);
    
    console.log(`📢 Non-blocking notification shown: ${type}`);
}

// 📊 CONFLICT MONITORING SYSTEM
function setupConflictMonitoring() {
    console.log('📊 Setting up conflict monitoring...');
    
    // Monitor for changes in schedule data
    const originalSaveData = window.saveData;
    if (originalSaveData) {
        window.saveData = function() {
            const result = originalSaveData.apply(this, arguments);
            
            // Run conflict check after data changes
            setTimeout(() => {
                console.log('🔄 Data changed - running conflict check...');
                quickConflictScan();
            }, 100);
            
            return result;
        };
    }
    
    // OPTIMIZATION: Throttle periodic conflict monitoring to prevent blocking
    // Set up periodic conflict monitoring (every 30 seconds) - deferred to avoid blocking
    setInterval(() => {
        // Defer to next idle period to avoid blocking setInterval handler
        if (window.requestIdleCallback) {
            requestIdleCallback(() => {
                logger('🔄 Periodic conflict monitoring...');
                const conflicts = quickConflictScan();
                if (conflicts.totalConflicts > 0) {
                    logger(`ℹ️ ${conflicts.totalConflicts} existing conflicts detected in schedules (informational)`);
                }
            }, { timeout: 5000 });
        } else {
            setTimeout(() => {
                logger('🔄 Periodic conflict monitoring...');
                const conflicts = quickConflictScan();
                if (conflicts.totalConflicts > 0) {
                    logger(`ℹ️ ${conflicts.totalConflicts} existing conflicts detected in schedules (informational)`);
                }
            }, 100);
        }
    }, 30000);
    
    console.log('✅ Conflict monitoring system active');
}

// Function to find and preserve the original schedule flight function
function preserveOriginalScheduleFlight() {
    console.log('🔍 SEARCHING FOR ORIGINAL SCHEDULE FLIGHT FUNCTION');
    
    // Look for common function names
    const possibleNames = ['scheduleFlight', 'addFlight', 'createFlight', 'submitFlight'];
    
    for (const name of possibleNames) {
        if (typeof window[name] === 'function') {
            console.log(`✅ Found original function: ${name}`);
            window[`original${name.charAt(0).toUpperCase() + name.slice(1)}`] = window[name];
            return name;
        }
    }
    
    console.log('⚠️  Original schedule flight function not found');
    return null;
}

