// Debug function to test conflict detection
function debugConflictDetection() {
    console.log('🔍 DEBUGGING CONFLICT DETECTION');
    
    const day = document.getElementById('flightDay').value;
    const startTime = document.getElementById('flightStartTime').value;
    const boardingTime = parseInt(document.getElementById('boardingTime').value) || 30;
    const flightDuration = document.getElementById('flightDuration').value;
    const disembarkingTime = parseInt(document.getElementById('disembarkingTime').value) || 15;
    const departureGate = document.getElementById('departureGate').value;
    const arrivalGate = document.getElementById('arrivalGate').value;
    
    console.log('Flight parameters:', { day, startTime, boardingTime, flightDuration, disembarkingTime, departureGate, arrivalGate });
    
    // Get route
    const routeValue = document.getElementById('flightRoute').value;
    if (routeValue) {
        const route = JSON.parse(routeValue);
        console.log('Route:', route);
        
        // Calculate times
        const startTimeMinutes = timeToMinutes(startTime);
        const flightDurationMinutes = timeToMinutes(flightDuration);
        
        // Boarding times
        const boardingStartTime = startTime;
        const boardingEndTime = addMinutesToTime(startTime, boardingTime);
        
        // Flight times
        const flightStartTime = boardingEndTime;
        const flightEndTime = addMinutesToTime(startTime, boardingTime + flightDurationMinutes);
        
        // Disembarking times
        const disembarkingStartTime = flightEndTime;
        const disembarkingEndTimeMinutes = timeToMinutes(disembarkingStartTime) + disembarkingTime;
        let disembarkingEndTime;
        if (disembarkingEndTimeMinutes >= 1440) {
            const nextDayMinutes = disembarkingEndTimeMinutes - 1440;
            disembarkingEndTime = minutesToTimeString(nextDayMinutes);
        } else {
            disembarkingEndTime = minutesToTimeString(disembarkingEndTimeMinutes);
        }
        
        console.log('Calculated times:');
        console.log(`  Boarding: ${boardingStartTime} - ${boardingEndTime}`);
        console.log(`  Flight: ${flightStartTime} - ${flightEndTime}`);
        console.log(`  Disembarking: ${disembarkingStartTime} - ${disembarkingEndTime}`);
        
        // Check if disembarking spans overnight
        if (disembarkingEndTimeMinutes >= 1440) {
            console.log('⚠️ DISEMBARKING SPANS OVERNIGHT - This should be rejected or split!');
        }
        
        // Test conflict detection for departure gate
        console.log('🔍 Testing departure gate conflict detection...');
        const departureConflict = comprehensiveGateConflictCheck(
            route.departure,
            departureGate,
            parseInt(day),
            boardingStartTime,
            boardingEndTime,
            currentAircraftForSchedule,
            null,
            null
        );
        console.log('Departure gate conflict result:', departureConflict);
        
        // Test conflict detection for arrival gate
        console.log('🔍 Testing arrival gate conflict detection...');
        const arrivalConflict = comprehensiveGateConflictCheck(
            route.arrival,
            arrivalGate,
            parseInt(day),
            disembarkingStartTime,
            disembarkingEndTime,
            currentAircraftForSchedule,
            null,
            null
        );
        console.log('Arrival gate conflict result:', arrivalConflict);
    }
    
    console.log('🔍 Conflict detection debug completed');
}

// 🧪 COMPREHENSIVE SHOW/HIDE ROUTES TESTING
function testShowHideRoutesFunctionality() {
    console.log('🧪 === TESTING SHOW/HIDE ROUTES FUNCTIONALITY ===');
    
    let testResults = {
        basicToggle: false,
        filteringReset: false,
        focusMode: false,
        edgeCases: false,
        stateConsistency: false
    };
    
    // Test 1: Basic Toggle Functionality
    console.log('🧪 Test 1: Basic Toggle Functionality');
    try {
        const initialRoutesVisible = routesVisible;
        const toggleButton = document.getElementById('toggleRoutes');
        
        if (!toggleButton) {
            console.log('❌ Test 1 FAILED: Toggle button not found');
        } else {
            // Test showing routes
            if (!initialRoutesVisible) {
                toggleRoutesVisibility();
                if (routesVisible && toggleButton.textContent === 'Hide Routes') {
                    console.log('✅ Test 1a PASSED: Routes shown correctly');
                } else {
                    console.log('❌ Test 1a FAILED: Routes not shown correctly');
                }
            }
            
            // Test hiding routes
            toggleRoutesVisibility();
            if (!routesVisible && toggleButton.textContent === 'Show Routes') {
                console.log('✅ Test 1b PASSED: Routes hidden correctly');
                testResults.basicToggle = true;
            } else {
                console.log('❌ Test 1b FAILED: Routes not hidden correctly');
            }
            
            // Restore initial state
            if (initialRoutesVisible) {
                toggleRoutesVisibility();
            }
        }
    } catch (error) {
        console.log('❌ Test 1 FAILED with error:', error);
    }
    
    // Test 2: Filtering Reset Functionality
    console.log('🧪 Test 2: Filtering Reset Functionality');
    try {
        // Simulate filtered state
        window.airportsFilteredForRoutes = true;
        window.filteredAirportName = 'Test Airport';
        
        const toggleButton = document.getElementById('toggleRoutes');
        if (toggleButton) {
            // Set button to show it's in filtered state
            toggleButton.textContent = 'Show All Routes';
            
            // Click should reset filtering
            toggleButton.click();
            
            if (!window.airportsFilteredForRoutes && toggleButton.textContent === 'Hide Routes') {
                console.log('✅ Test 2 PASSED: Filtering reset correctly');
                testResults.filteringReset = true;
            } else {
                console.log('❌ Test 2 FAILED: Filtering not reset correctly');
            }
        } else {
            console.log('❌ Test 2 FAILED: Toggle button not found');
        }
    } catch (error) {
        console.log('❌ Test 2 FAILED with error:', error);
    }
    
    // Test 3: Focus Mode Protection
    console.log('🧪 Test 3: Focus Mode Protection');
    try {
        // Set focus mode
        focusedRouteIndex = 0;
        const initialRoutesVisible = routesVisible;
        
        // Try to toggle routes while in focus mode
        toggleRoutesVisibility();
        
        // Routes should not change when in focus mode
        if (routesVisible === initialRoutesVisible) {
            console.log('✅ Test 3 PASSED: Focus mode protection works');
            testResults.focusMode = true;
        } else {
            console.log('❌ Test 3 FAILED: Focus mode protection failed');
        }
        
        // Clear focus mode
        focusedRouteIndex = null;
    } catch (error) {
        console.log('❌ Test 3 FAILED with error:', error);
    }
    
    // Test 4: Edge Cases
    console.log('🧪 Test 4: Edge Cases');
    try {
        // Test with empty routeLines array
        const originalRouteLines = routeLines;
        routeLines = [];
        
        toggleRoutesVisibility();
        toggleRoutesVisibility(); // Toggle back
        
        // Should not crash
        console.log('✅ Test 4a PASSED: Empty routeLines handled');
        
        // Test with invalid polylines
        routeLines = [null, undefined, {}];
        toggleRoutesVisibility();
        toggleRoutesVisibility(); // Toggle back
        
        // Should not crash
        console.log('✅ Test 4b PASSED: Invalid polylines handled');
        
        // Restore original routeLines
        routeLines = originalRouteLines;
        testResults.edgeCases = true;
    } catch (error) {
        console.log('❌ Test 4 FAILED with error:', error);
    }
    
    // Test 5: State Consistency
    console.log('🧪 Test 5: State Consistency');
    try {
        // Test that all route polylines have consistent _isClickable state
        const initialRoutesVisible = routesVisible;
        
        // Show routes
        if (!initialRoutesVisible) {
            toggleRoutesVisibility();
        }
        
        let allClickable = true;
        routeLines.forEach((polyline, index) => {
            if (polyline && polyline._isClickable !== true) {
                console.log(`❌ Route ${index} not marked as clickable when routes are visible`);
                allClickable = false;
            }
        });
        
        if (allClickable) {
            console.log('✅ Test 5a PASSED: All routes clickable when visible');
        }
        
        // Hide routes
        toggleRoutesVisibility();
        
        let allNotClickable = true;
        routeLines.forEach((polyline, index) => {
            if (polyline && polyline._isClickable !== false) {
                console.log(`❌ Route ${index} not marked as not clickable when routes are hidden`);
                allNotClickable = false;
            }
        });
        
        if (allNotClickable) {
            console.log('✅ Test 5b PASSED: All routes not clickable when hidden');
            testResults.stateConsistency = true;
        }
        
        // Restore initial state
        if (initialRoutesVisible) {
            toggleRoutesVisibility();
        }
    } catch (error) {
        console.log('❌ Test 5 FAILED with error:', error);
    }
    
    // Summary
    console.log('🧪 === TEST RESULTS SUMMARY ===');
    console.log(`Basic Toggle: ${testResults.basicToggle ? '✅ PASS' : '❌ FAIL'}`);
    console.log(`Filtering Reset: ${testResults.filteringReset ? '✅ PASS' : '❌ FAIL'}`);
    console.log(`Focus Mode: ${testResults.focusMode ? '✅ PASS' : '❌ FAIL'}`);
    console.log(`Edge Cases: ${testResults.edgeCases ? '✅ PASS' : '❌ FAIL'}`);
    console.log(`State Consistency: ${testResults.stateConsistency ? '✅ PASS' : '❌ FAIL'}`);
    
    const allPassed = Object.values(testResults).every(result => result === true);
    console.log(`Overall Result: ${allPassed ? '✅ ALL TESTS PASSED' : '❌ SOME TESTS FAILED'}`);
    
    return testResults;
}

