// Test function to verify real-time gate validation is working
function testRealTimeGateValidation() {
    console.log('🧪 TESTING REAL-TIME GATE VALIDATION...');
    console.log('=====================================');
    
    // Test 1: Set up a known conflict scenario
    console.log('📋 Test 1: Setting up conflict scenario...');
    
    // Set aircraft to one with known conflicts
    setCurrentAircraftForTesting('HK-KCC');
    
    // Check if we have the flight scheduling form
    const form = document.getElementById('flightSchedulingForm');
    if (!form || form.style.display === 'none') {
        console.log('❌ Flight scheduling form not visible. Please open the flight scheduling form first.');
        return;
    }
    
    // Set up form with known conflict data
    const daySelect = document.getElementById('flightDay');
    const startTimeSelect = document.getElementById('flightStartTime');
    const departureGateSelect = document.getElementById('departureGate');
    const arrivalGateSelect = document.getElementById('arrivalGate');
    const routeSelect = document.getElementById('flightRoute');
    
    if (!daySelect || !startTimeSelect || !departureGateSelect || !arrivalGateSelect || !routeSelect) {
        console.log('❌ Required form elements not found');
        return;
    }
    
    // Set up a scenario that should have conflicts
    // Based on the previous test, HK-KCC has conflicts at Mandinga Airport
    daySelect.value = '1'; // Day 1
    startTimeSelect.value = '12:00'; // 12:00 PM
    departureGateSelect.value = 'Gate 1'; // Gate 1 at departure airport
    arrivalGateSelect.value = 'Gate 1'; // Gate 1 at arrival airport
    
    // Try to find a route that goes to Mandinga Airport
    const routeOptions = routeSelect.options;
    let mandingaRoute = null;
    for (let i = 0; i < routeOptions.length; i++) {
        try {
            const route = JSON.parse(routeOptions[i].value);
            if (route.arrival && route.arrival.includes('Mandinga')) {
                mandingaRoute = route;
                routeSelect.value = routeOptions[i].value;
                break;
            }
        } catch (e) {
            // Skip invalid routes
        }
    }
    
    if (!mandingaRoute) {
        console.log('⚠️ No route to Mandinga Airport found, using first available route');
        if (routeOptions.length > 0) {
            routeSelect.value = routeOptions[0].value;
        }
    }
    
    console.log('✅ Form set up with conflict scenario');
    console.log(`   Aircraft: ${currentAircraftForSchedule}`);
    console.log(`   Day: ${daySelect.value}`);
    console.log(`   Start Time: ${startTimeSelect.value}`);
    console.log(`   Departure Gate: ${departureGateSelect.value}`);
    console.log(`   Arrival Gate: ${arrivalGateSelect.value}`);
    
    // Test 2: Trigger validation and check results
    console.log('\n📋 Test 2: Triggering validation...');
    
    const validationResult = performUnifiedValidation();
    
    console.log('📊 Validation Result:', validationResult);
    
    // Test 3: Check gate border colors
    console.log('\n📋 Test 3: Checking gate border colors...');
    
    const departureGateContainer = departureGateSelect.parentElement;
    const arrivalGateContainer = arrivalGateSelect.parentElement;
    
    const departureClasses = departureGateContainer ? departureGateContainer.className : 'not found';
    const arrivalClasses = arrivalGateContainer ? arrivalGateContainer.className : 'not found';
    
    console.log(`Departure Gate Classes: ${departureClasses}`);
    console.log(`Arrival Gate Classes: ${arrivalClasses}`);
    
    // Check if gates show conflicts (red borders)
    const departureHasConflict = departureClasses.includes('gate-conflict');
    const arrivalHasConflict = arrivalClasses.includes('gate-conflict');
    
    console.log(`Departure Gate Conflict: ${departureHasConflict ? '✅ RED (Conflict detected)' : '❌ GREEN (No conflict - this might be wrong)'}`);
    console.log(`Arrival Gate Conflict: ${arrivalHasConflict ? '✅ RED (Conflict detected)' : '❌ GREEN (No conflict - this might be wrong)'}`);
    
    // Test 4: Summary
    console.log('\n📋 Test 4: Summary');
    console.log('==================');
    
    if (validationResult && !validationResult.valid && validationResult.errors.length > 0) {
        console.log('✅ CONFLICT DETECTION: Working correctly');
        console.log(`   Found ${validationResult.errors.length} conflicts`);
        validationResult.errors.forEach((error, index) => {
            console.log(`   ${index + 1}. ${error.type}: ${error.message}`);
        });
    } else {
        console.log('❌ CONFLICT DETECTION: Not working - no conflicts found when they should exist');
    }
    
    if (departureHasConflict || arrivalHasConflict) {
        console.log('✅ UI VALIDATION: Working correctly - gates show red borders for conflicts');
    } else {
        console.log('❌ UI VALIDATION: Not working - gates should show red borders but are showing green');
    }
    
    console.log('\n🎯 RECOMMENDATION:');
    if (validationResult && !validationResult.valid && (departureHasConflict || arrivalHasConflict)) {
        console.log('✅ Both conflict detection and UI validation are working correctly!');
    } else {
        console.log('⚠️ There may still be issues with the validation system.');
        console.log('   Try manually changing the gate selection to trigger validation.');
    }
    
    return {
        conflictDetectionWorking: validationResult && !validationResult.valid,
        uiValidationWorking: departureHasConflict || arrivalHasConflict,
        validationResult: validationResult
    };
}

