        const departureClasses = departureContainer ? departureContainer.className : 'not found';
        const departureHasConflict = departureClasses.includes('gate-conflict');
        const departureHasAvailable = departureClasses.includes('gate-available');
        
        console.log(`   Departure Gate Classes: ${departureClasses}`);
        console.log(`   Departure Gate Status: ${departureHasConflict ? '❌ RED (Conflict)' : departureHasAvailable ? '✅ GREEN (Available)' : '⚠️ UNKNOWN'}`);
